def _hex_to_rgb(hexstr):
    s = hexstr.strip().lstrip("#")
    if len(s) != 6:
        return None
    r = int(s[0:2], 16) / 255.0
    g = int(s[2:4], 16) / 255.0
    b = int(s[4:6], 16) / 255.0
    return (r, g, b)
