# ABFE calibration/pocket descriptor helpers are provided by abfe_runtime.py.
def distance(a, b):
    """Euclidean distance between two 3D points."""
    return np.linalg.norm(np.array(a) - np.array(b))
def get_centroid(coords):
    """Compute centroid of a list of 3D coordinates."""
    return np.mean(np.array(coords), axis=0)
def get_ring_radius(coords, centroid=None):
    c = centroid if centroid is not None else get_centroid(coords)
    return float(max(distance(p, c) for p in coords))
def get_normal(coords):
    """Compute normal vector of a ring plane defined by coords."""
    pts = np.array(coords)
    if pts.shape[0] < 3:
        return np.array([0.0, 0.0, 1.0])
    centroid = get_centroid(pts)
    _, _, vh = np.linalg.svd(pts - centroid)
    normal = vh[2]
    n = np.linalg.norm(normal)
    if n == 0:
        return np.array([0.0, 0.0, 1.0])
    return normal / n
def angle_between_vectors(v1, v2):
    """Calculate the angle in degrees between two vectors."""
    n1 = np.linalg.norm(v1)
    n2 = np.linalg.norm(v2)
    if n1 == 0 or n2 == 0:
        return 0.0
    v1_u = v1 / n1
    v2_u = v2 / n2
    return np.degrees(np.arccos(np.clip(np.dot(v1_u, v2_u), -1.0, 1.0)))
def ring_plane_offset(center_a, normal_a, center_b):
    """
    Lateral (in-plane) displacement from ring A center to ring B center.
    Used to avoid classifying highly shifted ring pairs as pi-stacking.
    """
    v = np.array(center_b, dtype=float) - np.array(center_a, dtype=float)
    n = np.array(normal_a, dtype=float)
    nn = np.linalg.norm(n)
    if nn == 0.0:
        return float(np.linalg.norm(v))
    n = n / nn
    perp = float(np.dot(v, n))
    lateral = v - perp * n
    return float(np.linalg.norm(lateral))
OPENMM_PEPTIDE_CAPS = frozenset({"ACE", "NME", "NMA", "NH2", "NHE"})
