    def _project_save_state(self, silent=False):
        root = str(getattr(self, "_project_root", "") or "").strip()
        if not root:
            return False
        root = self._project_make_structure(root)
        state_file = self._project_state_file()
        session_file = self._project_session_file_path()
        session_rel = self._project_relpath(session_file)
        scene_saved = False
        try:
            if session_file:
                names = list(cmd.get_names("objects"))
                if names:
                    cmd.save(session_file)
                    scene_saved = bool(os.path.isfile(session_file))
        except Exception as e:
            self._append_debug_log(f"Project save warning (session): {e}")
        try:
            ui_settings = dict(getattr(self, "_settings", {}) or {})
        except Exception:
            ui_settings = {}
        try:
            ui_settings.update(self._collect_settings_from_ui())
        except Exception:
            pass
        vals = {
            "pdb_path": self._project_relpath(str(getattr(self, "pdb_path", "") or "")),
            "loaded_object": str(getattr(self, "loaded_object", "") or ""),
            "traj_topology_object": str(getattr(self, "_traj_topology_object", "") or ""),
            "ligand_info": list(getattr(self, "ligand_info", []) or []),
            "ligand_charge_source": str(getattr(self, "_ligand_charge_source", "") or ""),
            "ligand_charge_details": str(getattr(self, "_ligand_charge_details", "") or ""),
            "ligand_pdbqt_charge_mode": str(getattr(self, "_ligand_pdbqt_charge_mode", "preserve") or "preserve"),
            "project_name": str(getattr(self, "_project_name", "") or os.path.basename(root) or "project"),
        }
        payload = {
            "version": int(getattr(self, "_project_state_version", 1) or 1),
            "saved_at": datetime.datetime.now().isoformat(timespec="seconds"),
            "project_root": str(root),
            "session_file": str(session_rel),
            "scene_saved": bool(scene_saved),
            "paths": self._project_runtime_paths_state(),
            "values": vals,
            "ui_settings": ui_settings,
            "widget_state": self._project_collect_widget_state(),
        }
        try:
            with open(state_file, "w", encoding="utf-8") as fh:
                json.dump(payload, fh, indent=2)
        except Exception as e:
            if not bool(silent):
                QtWidgets.QMessageBox.warning(self, "Project", f"Failed to save project state:\n{e}")
            return False
        try:
            master_file = self._project_write_master_file(root=root, state_payload=payload)
        except Exception as e:
            master_file = self._project_master_file(root)
            self._append_debug_log(f"Project save warning (master file): {e}")
        self._project_session_file = str(session_file)
        try:
            if not hasattr(self, "_settings") or self._settings is None:
                self._settings = {}
            self._settings["last_project_root"] = str(root)
            self._settings["last_project_parent"] = str(os.path.dirname(root) or root)
            self._save_settings()
        except Exception:
            pass
        self._project_update_status_label()
        if not bool(silent):
            QtWidgets.QMessageBox.information(
                self,
                "Project",
                f"Project saved.\n\nProject file:\n{master_file}\n\nInternal state:\n{state_file}",
            )
        return True
    def _project_load_state(self, show_errors=False):
        state_file = self._project_state_file()
        if (not state_file) or (not os.path.isfile(state_file)):
            return False
        try:
            with open(state_file, "r", encoding="utf-8") as fh:
                data = json.load(fh)
        except Exception as e:
            if bool(show_errors):
                QtWidgets.QMessageBox.warning(self, "Project", f"Failed to read project state:\n{e}")
            return False
        if not isinstance(data, dict):
            return False
        try:
            sess_rel = str(data.get("session_file", "") or "").strip()
            sess_abs = self._project_abspath(sess_rel)
            if sess_abs and os.path.isfile(sess_abs):
                try:
                    cmd.reinitialize()
                except Exception:
                    pass
                try:
                    cmd.load(sess_abs)
                    self._project_session_file = str(sess_abs)
                except Exception as e:
                    self._append_debug_log(f"Project load warning (session load): {e}")
        except Exception:
            pass
        self._project_apply_paths_state(data.get("paths", {}))
        vals = dict(data.get("values", {}) or {})
        self.pdb_path = self._project_abspath(str(vals.get("pdb_path", "") or ""))
        self.loaded_object = str(vals.get("loaded_object", "") or "") or None
        self._traj_topology_object = str(vals.get("traj_topology_object", "") or "") or None
        lig = vals.get("ligand_info")
        if isinstance(lig, (list, tuple)) and len(lig) >= 3:
            try:
                self.ligand_info = (str(lig[0]), int(lig[1]), str(lig[2]))
            except Exception:
                self.ligand_info = (str(lig[0]), str(lig[1]), str(lig[2]))
        self._ligand_charge_source = str(vals.get("ligand_charge_source", getattr(self, "_ligand_charge_source", "none")) or "none")
        self._ligand_charge_details = str(vals.get("ligand_charge_details", getattr(self, "_ligand_charge_details", "")) or "")
        self._ligand_pdbqt_charge_mode = str(vals.get("ligand_pdbqt_charge_mode", getattr(self, "_ligand_pdbqt_charge_mode", "preserve")) or "preserve")
        self._project_name = str(vals.get("project_name", getattr(self, "_project_name", "project")) or "project")
        ui_settings = data.get("ui_settings", {})
        if isinstance(ui_settings, dict):
            try:
                if not hasattr(self, "_settings") or self._settings is None:
                    self._settings = {}
                self._settings.update(ui_settings)
                self._apply_settings_to_ui()
            except Exception:
                pass
        try:
            self._refresh_docking_object_combo()
        except Exception:
            pass
        try:
            self._refresh_redocking_object_combos()
        except Exception:
            pass
        try:
            self._populate_limit_combo()
        except Exception:
            pass
        self._project_apply_widget_state(data.get("widget_state", {}))
        try:
            names = list(cmd.get_names("objects"))
        except Exception:
            names = []
        if self.loaded_object and self.loaded_object not in names:
            self.loaded_object = names[0] if names else None
        if (not self._traj_topology_object) and self.loaded_object:
            self._traj_topology_object = self.loaded_object
        try:
            if self.loaded_object and (self.loaded_object in names):
                self._redock_apply_scene_actions(
                    [{"action": "enable", "object": str(self.loaded_object)}],
                    known_objects=set(names or []),
                    default_action="disable",
                )
        except Exception:
            pass
        try:
            if self.ligand_info and len(self.ligand_info) >= 3:
                if hasattr(self, "ligand_chain"):
                    self.ligand_chain.setText(str(self.ligand_info[0]))
                if hasattr(self, "ligand_resi"):
                    self.ligand_resi.setText(str(self.ligand_info[1]))
                if hasattr(self, "ligand_resn"):
                    self.ligand_resn.setText(str(self.ligand_info[2]))
        except Exception:
            pass
        try:
            if hasattr(self, "file_edit"):
                self.file_edit.setText(str(self.pdb_path or ""))
        except Exception:
            pass
        try:
            self._update_ligand_prep_outputs_label()
            self._update_active_docking_ligand_label()
            self._update_redock_ligand_status_label()
            self._update_docking_hub_status()
            self._update_main_workspace_summary()
        except Exception:
            pass
        self._project_state_loaded = True
        self._project_update_status_label()
        return True
    def _project_activate(self, project_root, load_state=True, clear_scene=False):
        root = os.path.abspath(str(project_root or "").strip())
        if not root:
            return False
        self._project_make_structure(root)
        self._project_root = str(root)
        self._project_name = os.path.basename(root) or "project"
        self._project_state_loaded = False
        if bool(clear_scene):
            try:
                cmd.reinitialize()
            except Exception:
                pass
            self._project_reset_runtime_state()
        loaded = False
        if bool(load_state):
            loaded = bool(self._project_load_state(show_errors=False))
        if not loaded:
            self._project_state_loaded = False
            self._project_update_status_label()
        try:
            if not hasattr(self, "_settings") or self._settings is None:
                self._settings = {}
            self._settings["last_project_root"] = str(root)
            self._settings["last_project_parent"] = str(os.path.dirname(root) or root)
            self._save_settings()
        except Exception:
            pass
        self._project_update_status_label()
        return True
    def _project_reset_to_scratch(self, clear_scene=True, clear_autoload=True):
        if bool(clear_scene):
            try:
                cmd.reinitialize()
            except Exception:
                pass
        self._project_root = ""
        self._project_name = "scratch"
        self._project_state_loaded = False
        self._project_session_file = ""
        self._project_reset_runtime_state()
        try:
            if hasattr(self, "_settings") and self._settings is not None:
                self._settings["last_project_root"] = ""
                self._settings["last_file"] = ""
                self._settings["last_ligand_chain"] = ""
                self._settings["last_ligand_resi"] = ""
                self._settings["last_ligand_resn"] = ""
                if bool(clear_autoload):
                    self._save_settings()
        except Exception:
            pass
        try:
            self._refresh_docking_object_combo()
        except Exception:
            pass
        try:
            self._refresh_redocking_object_combos()
        except Exception:
            pass
        try:
            self._refresh_modeler_object_combo()
        except Exception:
            pass
        try:
            self._populate_limit_combo()
        except Exception:
            pass
        try:
            self._update_modeler_hub_status()
        except Exception:
            pass
        try:
            self._project_update_status_label()
            self._update_main_workspace_summary()
        except Exception:
            pass
        return True
    def _on_project_reset(self):
        ans = QtWidgets.QMessageBox.question(
            self,
            "Reset Leonardo",
            (
                "Start a fresh scratch project and clear the current PyMOL scene?\n\n"
                "This also clears the saved last-project autoload, so restarting PyMOL will not reopen the current project."
            ),
            QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.No,
            QtWidgets.QMessageBox.No,
        )
        if ans != QtWidgets.QMessageBox.Yes:
            return
        self._project_reset_to_scratch(clear_scene=True, clear_autoload=True)
        QtWidgets.QMessageBox.information(
            self,
            "Reset Leonardo",
            "Leonardo was reset to a fresh scratch project.",
        )
    def _on_project_new(self):
        try:
            base_dir = str(getattr(self, "_settings", {}).get("last_project_parent", "") or "").strip()
        except Exception:
            base_dir = ""
        if not base_dir:
            base_dir = os.path.expanduser("~")
        parent = QtWidgets.QFileDialog.getExistingDirectory(self, "Select Parent Directory for New Project", base_dir)
        if not parent:
            return
        name, ok = QtWidgets.QInputDialog.getText(self, "New Project", "Project name:")
        if not ok:
            return
        raw = str(name or "").strip()
        if not raw:
            QtWidgets.QMessageBox.warning(self, "Project", "Project name cannot be empty.")
            return
        safe = re.sub(r"[^A-Za-z0-9._-]+", "_", raw).strip("._-") or "project"
        root = os.path.join(parent, safe)
        if os.path.isdir(root):
            try:
                has_files = bool(os.listdir(root))
            except Exception:
                has_files = False
            if has_files:
                ans = QtWidgets.QMessageBox.question(
                    self,
                    "Project",
                    f"Directory already exists and is not empty:\n{root}\n\nUse it as project root?",
                    QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.No,
                    QtWidgets.QMessageBox.No,
                )
                if ans != QtWidgets.QMessageBox.Yes:
                    return
        try:
            os.makedirs(root, exist_ok=True)
        except Exception as e:
            QtWidgets.QMessageBox.warning(self, "Project", f"Failed to create project directory:\n{e}")
            return
        self._project_activate(root, load_state=False, clear_scene=True)
        self._project_reset_runtime_state()
        self._project_save_state(silent=True)
        QtWidgets.QMessageBox.information(
            self,
            "Project",
            f"New project ready:\n{root}\n\nOpen later with:\n{self._project_master_file(root)}",
        )
    def _on_project_open(self):
        try:
            base_dir = str(getattr(self, "_settings", {}).get("last_project_parent", "") or "").strip()
        except Exception:
            base_dir = ""
        if not base_dir:
            base_dir = os.path.expanduser("~")
        target, _selected_filter = QtWidgets.QFileDialog.getOpenFileName(
            self,
            "Open Leonardo Project",
            base_dir,
            f"Leonardo Project Files ({PROJECT_MASTER_FILE_NAME} {PROJECT_STATE_FILE_NAME});;JSON Files (*.json);;All Files (*)",
        )
        if not target:
            return
        resolved = self._project_resolve_open_target(target)
        if not bool(resolved.get("ok", False)):
            QtWidgets.QMessageBox.warning(self, "Project", str(resolved.get("error", "Could not open project.")))
            return
        root = str(resolved.get("root", "") or "").strip()
        self._project_activate(root, load_state=True, clear_scene=False)
        if not bool(getattr(self, "_project_state_loaded", False)):
            self._project_save_state(silent=True)
            QtWidgets.QMessageBox.information(
                self,
                "Project",
                (
                    f"Opened project root without previous state.\nInitialized a new project file in:\n"
                    f"{self._project_master_file(root)}"
                ),
            )
    def _on_project_save(self):
        if not str(getattr(self, "_project_root", "") or "").strip():
            QtWidgets.QMessageBox.warning(
                self,
                "Project",
                "No project is active. Click 'New Project' or 'Open Project' first.",
            )
            return
        self._project_save_state(silent=False)
    def _project_try_autoload_from_settings(self):
        try:
            s = getattr(self, "_settings", {}) or {}
            root = str(s.get("last_project_root", "") or "").strip()
            if root and os.path.isdir(root):
                ok = bool(self._project_activate(root, load_state=True, clear_scene=False))
                return bool(ok and getattr(self, "_project_state_loaded", False))
        except Exception:
            pass
        self._project_update_status_label()
        return False
    def _setup_project_ui(self):
        try:
            if not hasattr(self, "verticalLayout"):
                return
            box = QtWidgets.QGroupBox("Project")
            box.setObjectName("pliProjectBox")
            vbox = QtWidgets.QVBoxLayout(box)
            vbox.setContentsMargins(10, 8, 10, 8)
            vbox.setSpacing(7)
            actions = QtWidgets.QGridLayout()
            actions.setHorizontalSpacing(8)
            actions.setVerticalSpacing(8)
            self.btn_project_new = QtWidgets.QPushButton("New Project")
            self.btn_project_new.clicked.connect(self._on_project_new)
            actions.addWidget(self.btn_project_new, 0, 0)
            self.btn_project_open = QtWidgets.QPushButton("Open Project")
            self.btn_project_open.setToolTip(
                f"Choose {PROJECT_MASTER_FILE_NAME} (or legacy {PROJECT_STATE_FILE_NAME})"
            )
            self.btn_project_open.clicked.connect(self._on_project_open)
            actions.addWidget(self.btn_project_open, 0, 1)
            self.btn_project_save = QtWidgets.QPushButton("Save Project")
            self.btn_project_save.setToolTip(
                f"Updates both {PROJECT_MASTER_FILE_NAME} and {PROJECT_STATE_FILE_NAME}"
            )
            self.btn_project_save.clicked.connect(self._on_project_save)
            actions.addWidget(self.btn_project_save, 1, 0)
            self.btn_project_reset = QtWidgets.QPushButton("Reset Leonardo")
            self.btn_project_reset.clicked.connect(self._on_project_reset)
            actions.addWidget(self.btn_project_reset, 1, 1)
            actions.setColumnStretch(0, 1)
            actions.setColumnStretch(1, 1)
            vbox.addLayout(actions)
            self.lbl_project_status = QtWidgets.QLabel("")
            self.lbl_project_status.setWordWrap(True)
            vbox.addWidget(self.lbl_project_status)
            self.lbl_project_entry_file = QtWidgets.QLabel("")
            self.lbl_project_entry_file.setWordWrap(True)
            vbox.addWidget(self.lbl_project_entry_file)
            self.verticalLayout.insertWidget(0, box)
            self._project_update_status_label()
        except Exception as e:
            print(f"Project UI setup warning: {e}")
    def _setup_launcher_hub(self):
        """
        Build the workflow launcher of the main window: the AI assistant on top, then one titled group of
        cards per area (``ui_layout_runtime.LAUNCHER_SECTIONS``), so every workflow window is one click away.
        """
        try:
            if not hasattr(self, "verticalLayout"):
                return

            def _button(name):
                w = getattr(self, name, None)
                return w if isinstance(w, QtWidgets.QPushButton) else None

            def _detach(btn):
                # some buttons were first inserted straight into the main layout; take them out of it
                parent = btn.parentWidget()
                layout = parent.layout() if parent is not None else None
                if layout is not None:
                    layout.removeWidget(btn)

            available = [n for n, _ in vars(self).items() if n.startswith("btn_open_") and _button(n) is not None]
            plan = launcher_plan(available)
            top = [b for b in (_button(n) for n in LAUNCHER_TOP) if b is not None]
            if not plan and not top:
                return
            hub = QtWidgets.QGroupBox("Workflow Launcher")
            hub.setObjectName("pliLauncherHub")
            hub_layout = QtWidgets.QVBoxLayout(hub)
            hub_layout.setContentsMargins(16, 14, 16, 14)
            hub_layout.setSpacing(10)
            desc = QtWidgets.QLabel(
                "Ask the AI assistant, or open a workflow window directly. Advanced Tools runs any assistant tool "
                "from a form, including those without a window of their own (membranes, materials, design...)."
            )
            desc.setObjectName("pliLauncherDesc")
            desc.setWordWrap(True)
            hub_layout.addWidget(desc)
            if top:
                top_row = QtWidgets.QHBoxLayout()
                top_row.setSpacing(8)
                for idx, btn in enumerate(top):
                    _detach(btn)
                    if idx == 0:
                        btn.setProperty("leonardoRole", "primary")
                    else:
                        btn.setObjectName("pliLauncherButton")
                    btn.setMinimumHeight(44)
                    btn.setMinimumWidth(0)
                    btn.setSizePolicy(QtWidgets.QSizePolicy.Expanding, QtWidgets.QSizePolicy.Fixed)
                    top_row.addWidget(btn, 2 if idx == 0 else 1)
                hub_layout.addLayout(top_row)
            self._launcher_sections = []
            buttons = []
            for title, names in plan:
                header = QtWidgets.QLabel(title.upper())
                header.setObjectName("pliLauncherSection")
                header.setStyleSheet(
                    "QLabel#pliLauncherSection { color: #5B626B; font-size: 11px; font-weight: 700;"
                    " letter-spacing: 1px; padding-top: 6px; }"
                )
                hub_layout.addWidget(header)
                grid = QtWidgets.QGridLayout()
                grid.setHorizontalSpacing(8)
                grid.setVerticalSpacing(8)
                section_buttons = []
                for name in names:
                    btn = _button(name)
                    _detach(btn)
                    btn.setObjectName("pliLauncherButton")
                    btn.setVisible(True)
                    btn.setMinimumHeight(44)
                    btn.setMaximumHeight(64)
                    btn.setMinimumWidth(0)
                    btn.setSizePolicy(QtWidgets.QSizePolicy.Expanding, QtWidgets.QSizePolicy.Fixed)
                    section_buttons.append(btn)
                hub_layout.addLayout(grid)
                self._launcher_sections.append((grid, section_buttons))
                buttons.extend(section_buttons)
            self._launcher_buttons = top + buttons
            self._launcher_column_count = 0
            self._reflow_launcher_grid()
            self.lbl_compute_hardware = QtWidgets.QLabel("Compute: detecting CPU/GPU...")
            self.lbl_compute_hardware.setObjectName("pliLauncherDesc")
            self.lbl_compute_hardware.setWordWrap(True)
            hub_layout.addWidget(self.lbl_compute_hardware)
            insert_idx = 2 if self.verticalLayout.count() >= 2 else self.verticalLayout.count()
            self.verticalLayout.insertWidget(insert_idx, hub)
        except Exception as e:
            print(f"Launcher hub setup warning: {e}")
    def _reflow_launcher_grid(self):
        """Rearrange launcher cards when the main window crosses width breakpoints."""
        sections = list(getattr(self, "_launcher_sections", []) or [])
        if not sections:
            return
        try:
            viewport = getattr(self, "_main_scroll_area", None)
            if viewport is not None:
                available_width = int(viewport.viewport().width()) - 40
            else:
                available_width = int(self.width()) - 60
            ncols = responsive_grid_columns(available_width, card_min_width=240, maximum_columns=3)
            if int(getattr(self, "_launcher_column_count", 0) or 0) == int(ncols):
                return
            for grid, buttons in sections:
                while grid.count():
                    grid.takeAt(0)
                for idx, button in enumerate(buttons):
                    grid.addWidget(button, idx // ncols, idx % ncols)
                for col in range(3):
                    grid.setColumnStretch(col, 1 if col < ncols else 0)
            self._launcher_column_count = int(ncols)
        except Exception:
            pass
