    def _append_debug_log(self, message):
        ts = datetime.datetime.now().strftime("%H:%M:%S")
        line = f"[{ts}] {message}"
        self._debug_log_lines.append(line)
        # keep memory bounded
        if len(self._debug_log_lines) > 800:
            self._debug_log_lines = self._debug_log_lines[-800:]
        print(f"ProtLigInteract DEBUG: {line}")
        self._refresh_debug_text()
    def _refresh_debug_text(self):
        try:
            if hasattr(self, "_debug_text"):
                self._debug_text.setPlainText("\n".join(self._debug_log_lines))
                self._debug_text.verticalScrollBar().setValue(self._debug_text.verticalScrollBar().maximum())
        except Exception:
            pass
    def _clear_debug_log(self):
        self._debug_log_lines = []
        self._refresh_debug_text()
