    def _show_task_monitor_dialog(self):
        try:
            self._normalize_task_monitor_storage()
            if self._task_monitor_dialog is None:
                self._setup_task_monitor_ui()
            self._ensure_task_monitor_timer()
            self._on_task_monitor_tick()
            self._fit_dialog_to_screen(self._task_monitor_dialog)
            self._task_monitor_dialog.show()
            self._task_monitor_dialog.raise_()
            self._task_monitor_dialog.activateWindow()
        except Exception as e:
            try:
                self._append_debug_log(f"Task monitor open failed: {e}")
            except Exception:
                pass
            QtWidgets.QMessageBox.warning(self, "Task Monitor", f"Could not open task monitor: {e}")
    def _ensure_task_monitor_timer(self):
        try:
            if self._task_monitor_timer is None:
                self._task_monitor_timer = QtCore.QTimer(self)
                self._task_monitor_timer.setInterval(700)
                self._task_monitor_timer.timeout.connect(self._on_task_monitor_tick)
            if not self._task_monitor_timer.isActive():
                self._task_monitor_timer.start()
        except Exception as e:
            print(f"Task monitor timer warning: {e}")
    def _normalize_task_monitor_storage(self):
        """
        Keep task-monitor internals in the expected dict shape.

        Older transient states and some failed UI rebuilds could leave the
        monitor state as a list of row payloads.  The monitor tick uses
        `.items()`, so normalize defensively before every public monitor path.
        """
        raw_rows = getattr(self, "_task_monitor_rows", {})
        if not isinstance(raw_rows, dict):
            raw_rows = {}
        rows = {}
        for key, val in dict(raw_rows or {}).items():
            jid = str(key or "").strip()
            if not jid:
                continue
            try:
                rows[jid] = int(val)
            except Exception:
                continue

        raw_state = getattr(self, "_task_monitor_state", {})
        state = {}
        if isinstance(raw_state, dict):
            iterable = list(raw_state.items())
        elif isinstance(raw_state, list):
            iterable = []
            for idx, meta in enumerate(list(raw_state or [])):
                if not isinstance(meta, dict):
                    continue
                jid = str(meta.get("job_id", meta.get("id", meta.get("jid", ""))) or "").strip()
                if not jid:
                    jid = f"J{int(idx) + 1:04d}"
                iterable.append((jid, meta))
        else:
            iterable = []
        for jid_raw, meta_raw in iterable:
            jid = str(jid_raw or "").strip()
            if not jid or not isinstance(meta_raw, dict):
                continue
            meta = dict(meta_raw or {})
            try:
                row = int(meta.get("row", rows.get(jid, -1)))
            except Exception:
                row = int(rows.get(jid, -1)) if jid in rows else -1
            table = getattr(self, "_task_monitor_table", None)
            if row < 0 and table is not None:
                # Try to recover row mapping from the visible table ID column.
                try:
                    for r in range(int(table.rowCount())):
                        it = table.item(r, 0)
                        if str(it.text() if it is not None else "").strip() == jid:
                            row = int(r)
                            break
                except Exception:
                    pass
            if row >= 0:
                rows[jid] = int(row)
            meta["row"] = int(row)
            meta.setdefault("tool_label", "")
            meta.setdefault("task_label", "")
            meta.setdefault("status", "Running")
            meta.setdefault("progress", 0.0)
            meta.setdefault("message", "")
            meta.setdefault("job_dir", "")
            meta.setdefault("last_probe_signature", "")
            meta.setdefault("last_probe_mtime", 0.0)
            state[jid] = meta
        self._task_monitor_rows = rows
        self._task_monitor_state = state
        try:
            numeric = [
                int(str(k).lstrip("Jj"))
                for k in list(state.keys()) + list(rows.keys())
                if str(k).lstrip("Jj").isdigit()
            ]
            if numeric:
                self._task_monitor_counter = max(int(getattr(self, "_task_monitor_counter", 0)), max(numeric))
        except Exception:
            pass
    def _on_task_monitor_tick(self):
        if self._task_monitor_table is None:
            return
        self._normalize_task_monitor_storage()
        active = False
        state_map = getattr(self, "_task_monitor_state", {}) or {}
        if not isinstance(state_map, dict):
            state_map = {}
            self._task_monitor_state = {}
        row_map = getattr(self, "_task_monitor_rows", {}) or {}
        if not isinstance(row_map, dict):
            row_map = {}
            self._task_monitor_rows = {}
        for jid, meta in list(state_map.items()):
            if str(jid or "").strip() not in row_map:
                continue
            status = str((meta or {}).get("status", "Running") or "Running").strip().lower()
            if status in ("completed", "failed", "canceled", "cancelled"):
                continue
            active = True
            tool_label = str((meta or {}).get("tool_label", "") or "").strip()
            job_dir = str((meta or {}).get("job_dir", "") or "").strip()
            if (not tool_label) or (not job_dir):
                continue
            try:
                probe = dict(task_monitor_probe_job(tool_label, job_dir) or {})
            except Exception:
                probe = {}
            signature = str(probe.get("signature", "") or "").strip()
            if (not signature) or (signature == str((meta or {}).get("last_probe_signature", "") or "").strip()):
                continue
            meta["last_probe_signature"] = str(signature)
            if probe.get("mtime") is not None:
                try:
                    meta["last_probe_mtime"] = float(probe.get("mtime", 0.0) or 0.0)
                except Exception:
                    meta["last_probe_mtime"] = 0.0
            self._task_monitor_update_row(
                jid,
                message=str(probe.get("message", "") or "").strip() or None,
                job_dir=str(probe.get("job_dir", "") or "").strip() or None,
            )
        try:
            self._task_monitor_table.viewport().update()
        except Exception:
            pass
        if (not active) and (self._task_monitor_timer is not None):
            try:
                self._task_monitor_timer.stop()
            except Exception:
                pass
    def _task_monitor_set_cell(self, row, col, text):
        if self._task_monitor_table is None:
            return
        item = self._task_monitor_table.item(int(row), int(col))
        if item is None:
            item = QtWidgets.QTableWidgetItem("")
            self._task_monitor_table.setItem(int(row), int(col), item)
        item.setText(str(text or ""))
    def _task_monitor_add_row(self, tool_label, task_label, job_dir=""):
        if self._task_monitor_table is None:
            return ""
        self._normalize_task_monitor_storage()
        self._ensure_task_monitor_timer()
        self._task_monitor_counter = int(self._task_monitor_counter) + 1
        job_id = f"J{int(self._task_monitor_counter):04d}"
        row = int(self._task_monitor_table.rowCount())
        self._task_monitor_table.insertRow(row)
        now = datetime.datetime.now().strftime("%H:%M:%S")
        self._task_monitor_set_cell(row, 0, job_id)
        self._task_monitor_set_cell(row, 1, tool_label)
        self._task_monitor_set_cell(row, 2, task_label)
        self._task_monitor_set_cell(row, 3, "Running")
        self._task_monitor_set_cell(row, 4, "0%")
        self._task_monitor_set_cell(row, 5, now)
        self._task_monitor_set_cell(row, 6, now)
        self._task_monitor_set_cell(row, 7, str(job_dir or ""))
        self._task_monitor_set_cell(row, 8, "Queued")
        self._task_monitor_rows[str(job_id)] = row
        self._task_monitor_state[str(job_id)] = {
            "row": int(row),
            "tool_label": str(tool_label or ""),
            "task_label": str(task_label or ""),
            "status": "Running",
            "progress": 0.0,
            "message": "Queued",
            "job_dir": str(job_dir or ""),
            "started_at": float(time.time()),
            "updated_at": float(time.time()),
            "last_probe_signature": "",
            "last_probe_mtime": 0.0,
        }
        return str(job_id)
    def _task_monitor_update_row(self, job_id, status=None, progress=None, message=None, job_dir=None):
        if self._task_monitor_table is None:
            return
        self._normalize_task_monitor_storage()
        jid = str(job_id or "").strip()
        if not jid or jid not in self._task_monitor_rows:
            return
        row = int(self._task_monitor_rows[jid])
        meta = dict(getattr(self, "_task_monitor_state", {}).get(jid, {}) or {})
        if status is not None:
            self._task_monitor_set_cell(row, 3, str(status))
            meta["status"] = str(status)
        if progress is not None:
            try:
                p = int(max(0, min(100, round(float(progress)))))
                self._task_monitor_set_cell(row, 4, f"{p}%")
                meta["progress"] = float(p)
            except Exception:
                self._task_monitor_set_cell(row, 4, str(progress))
                meta["progress"] = progress
        if message is not None:
            self._task_monitor_set_cell(row, 8, str(message))
            meta["message"] = str(message)
        if job_dir is not None:
            self._task_monitor_set_cell(row, 7, str(job_dir))
            meta["job_dir"] = str(job_dir)
        self._task_monitor_set_cell(row, 6, datetime.datetime.now().strftime("%H:%M:%S"))
        meta["row"] = int(row)
        meta["updated_at"] = float(time.time())
        self._task_monitor_state[str(jid)] = dict(meta)
        try:
            self._task_monitor_table.viewport().update()
        except Exception:
            pass
    def _task_monitor_consume_progress_payload(self, job_id, payload):
        status = None
        progress = None
        message = None
        job_dir = None
        if isinstance(payload, dict):
            status = payload.get("status", None)
            progress = payload.get("progress", None)
            message = payload.get("message", None)
            job_dir = payload.get("job_dir", None)
        elif isinstance(payload, (int, float)):
            progress = float(payload)
        else:
            message = str(payload or "")
        self._task_monitor_update_row(
            job_id=job_id,
            status=status,
            progress=progress,
            message=message,
            job_dir=job_dir,
        )
    def _task_monitor_finish_row(self, job_id, ok=True, message="", job_dir=None):
        status = "Completed" if bool(ok) else "Failed"
        prog = 100 if bool(ok) else None
        self._task_monitor_update_row(job_id, status=status, progress=prog, message=message, job_dir=job_dir)
    def _on_task_monitor_clear_finished(self):
        if self._task_monitor_table is None:
            return
        self._normalize_task_monitor_storage()
        keep_rows = []
        for row in range(int(self._task_monitor_table.rowCount())):
            st_item = self._task_monitor_table.item(row, 3)
            st = str(st_item.text() if st_item is not None else "").strip().lower()
            if st in ("completed", "failed", "canceled", "cancelled"):
                continue
            keep_rows.append(row)
        if len(keep_rows) == int(self._task_monitor_table.rowCount()):
            return
        new_rows = {}
        new_table = []
        for row in keep_rows:
            vals = []
            for col in range(9):
                it = self._task_monitor_table.item(row, col)
                vals.append(str(it.text() if it is not None else ""))
            new_table.append(vals)
        self._task_monitor_table.setRowCount(0)
        for vals in new_table:
            r = int(self._task_monitor_table.rowCount())
            self._task_monitor_table.insertRow(r)
            for c, v in enumerate(vals):
                self._task_monitor_set_cell(r, c, v)
            if vals and vals[0]:
                new_rows[str(vals[0])] = r
        new_state = {}
        old_state_map = getattr(self, "_task_monitor_state", {}) or {}
        old_state = dict(old_state_map) if isinstance(old_state_map, dict) else {}
        for vals in new_table:
            jid = str(vals[0] if vals else "").strip()
            if not jid:
                continue
            meta = dict(old_state.get(jid, {}) or {})
            meta["row"] = int(new_rows.get(jid, 0))
            if len(vals) > 3:
                meta["status"] = str(vals[3] or "")
            if len(vals) > 4:
                meta["progress"] = str(vals[4] or "")
            if len(vals) > 7:
                meta["job_dir"] = str(vals[7] or "")
            if len(vals) > 8:
                meta["message"] = str(vals[8] or "")
            new_state[jid] = meta
        self._task_monitor_rows = new_rows
        self._task_monitor_state = new_state
    def _on_task_monitor_open_selected_dir(self):
        if self._task_monitor_table is None:
            return
        row = int(self._task_monitor_table.currentRow())
        if row < 0:
            return
        it = self._task_monitor_table.item(row, 7)
        path = str(it.text() if it is not None else "").strip()
        if (not path) or (not os.path.isdir(path)):
            QtWidgets.QMessageBox.information(self, "Task Monitor", "Selected row does not have a valid job folder.")
            return
        try:
            QtGui.QDesktopServices.openUrl(QtCore.QUrl.fromLocalFile(path))
        except Exception as e:
            QtWidgets.QMessageBox.warning(self, "Task Monitor", f"Could not open folder:\n{e}")
    def _submit_monitored_background_task(
        self,
        task_fn,
        tool_label="Task",
        task_label="task",
        on_success=None,
        on_error=None,
        on_finished=None,
        on_progress=None,
        with_progress=False,
        job_dir="",
    ):
        jid = self._task_monitor_add_row(tool_label, task_label, job_dir=job_dir)
        try:
            self._show_task_monitor_dialog()
        except Exception:
            pass

        def _on_progress(payload):
            self._task_monitor_consume_progress_payload(jid, payload)
            if callable(on_progress):
                try:
                    on_progress(payload)
                except Exception:
                    pass

        def _on_success_monitored(payload):
            try:
                if callable(on_success):
                    on_success(payload)
                self._task_monitor_finish_row(jid, ok=True, message="Completed")
            except Exception as e:
                msg = str(e or "").strip()
                self._task_monitor_finish_row(jid, ok=False, message=msg[:500])
                QtWidgets.QMessageBox.critical(
                    self,
                    "Background Task Error",
                    f"{task_label} post-processing failed:\n{msg[:3000]}",
                )

        def _on_error_monitored(err_text):
            msg = str(err_text or "").strip()
            self._task_monitor_finish_row(jid, ok=False, message=msg[:500])
            if callable(on_error):
                on_error(msg)
            else:
                QtWidgets.QMessageBox.critical(self, "Background Task Error", f"{task_label} failed:\n{msg[:3000]}")

        def _on_finished_monitored():
            if callable(on_finished):
                on_finished()

        return self._submit_background_task(
            task_fn=task_fn,
            on_success=_on_success_monitored,
            on_error=_on_error_monitored,
            on_finished=_on_finished_monitored,
            on_progress=_on_progress,
            with_progress=bool(with_progress),
            task_name=f"{tool_label}: {task_label}",
        )
    def _submit_background_task(
        self,
        task_fn,
        on_success=None,
        on_error=None,
        on_finished=None,
        on_progress=None,
        with_progress=False,
        task_name="task",
    ):
        """Run a blocking callable on a worker thread and marshal callbacks back to UI."""
        if not callable(task_fn):
            raise TypeError("task_fn must be callable")

        holder = {}

        def _wrapped_error(err_text):
            txt = str(err_text or "").strip()
            if callable(on_error):
                on_error(txt)
                return
            self._append_debug_log(f"{task_name} failed: {txt[:800]}")
            QtWidgets.QMessageBox.critical(
                self,
                "Background Task Error",
                f"{task_name} failed:\n{txt[:3000]}",
            )

        def _wrapped_finished():
            task = holder.get("task")
            if task in self._background_tasks:
                self._background_tasks.discard(task)
            if callable(on_finished):
                on_finished()

        task = submit_background_task(
            self._thread_pool,
            task_fn,
            on_success=on_success,
            on_error=_wrapped_error,
            on_finished=_wrapped_finished,
            on_progress=on_progress,
            with_progress=bool(with_progress),
        )
        holder["task"] = task
        self._background_tasks.add(task)
        return task
    def _setup_live_updates(self):
        """
        Poll current state and refresh selected interaction distance dashes/labels
        in trajectory mode so values are frame-resolved while playing.
        """
        try:
            self._live_update_timer = QtCore.QTimer(self)
            self._live_update_timer.setInterval(180)
            self._live_update_timer.timeout.connect(self._on_live_update_tick)
            self._live_update_timer.start()
        except Exception as e:
            print(f"Live-update timer setup warning: {e}")
    def _on_live_update_tick(self):
        # Keep this lightweight and skip while another trajectory compute is running.
        if self._live_update_busy or getattr(self, "_traj_mode", False):
            return
        if not self._selected_ids or not self.loaded_object:
            return
        try:
            if int(cmd.count_states(self.loaded_object)) < 2:
                return
        except Exception:
            return
        try:
            state_idx = int(cmd.get_state())
        except Exception:
            return
        if state_idx <= 0 or state_idx == int(getattr(self, "_last_live_state", -1)):
            return
        self._last_live_state = int(state_idx)
        self._refresh_selected_distance_visuals(state_idx)
    def _refresh_selected_distance_visuals(self, state_idx):
        """
        Recompute interactions at `state_idx` and update only currently selected
        dash objects so distance labels and line geometry track frame motion.
        """
        if not self._selected_ids or self._live_update_busy:
            return
        self._live_update_busy = True
        try:
            current = []
            self._traj_state = int(state_idx)
            self._traj_mode = True
            try:
                current = self._calculate_all_interactions()
            finally:
                self._traj_mode = False
                self._traj_state = 0
            by_key = {self._interaction_key(x): x for x in current}
            for rid in list(self._selected_ids):
                try:
                    if rid < 0 or rid >= len(self.interactions):
                        continue
                    ref = self.interactions[rid]
                    hit = by_key.get(self._interaction_key(ref))
                    if hit is None:
                        occ_key = self._interaction_occ_key(ref, coarse=True)
                        relaxed = [x for x in current if self._interaction_occ_key(x, coarse=True) == occ_key]
                        if relaxed:
                            try:
                                ref_d = float(ref.get("distance", np.nan))
                            except Exception:
                                ref_d = np.nan
                            if np.isfinite(ref_d):
                                hit = min(relaxed, key=lambda y: abs(float(y.get("distance", 1e9)) - ref_d))
                            else:
                                hit = min(relaxed, key=lambda y: float(y.get("distance", 1e9)))
                    if hit is None:
                        p_fallback, l_fallback = self._fallback_frame_coords_from_reference(ref, state_idx)
                        if p_fallback is not None and l_fallback is not None:
                            hit = dict(ref)
                            hit["prot_coord"] = tuple(p_fallback)
                            hit["lig_coord"] = tuple(l_fallback)
                            hit["distance"] = float(distance(p_fallback, l_fallback))
                    if hit is not None:
                        self._update_distance_dash_for_selected(rid, hit, state_idx=state_idx, ref_inter=ref)
                except Exception as rid_e:
                    print(f"Live-update warning (rid={rid}, state={state_idx}): {rid_e}")
        finally:
            self._live_update_busy = False
    def _fallback_frame_coords_from_reference(self, ref_inter, state_idx):
        """
        Compute frame-specific coordinates directly from selectors when interaction
        matching fails in a frame. This keeps dash distances dynamic even if the
        interaction no longer satisfies geometric criteria in that frame.
        """
        try:
            prot_atoms = [a.strip() for a in str(ref_inter.get("prot_atom", "")).split(",") if a.strip()]
            lig_atoms = [a.strip() for a in str(ref_inter.get("lig_atom", "")).split(",") if a.strip()]
            if not prot_atoms or not lig_atoms:
                return None, None
            if prot_atoms == ["Ring"] or lig_atoms == ["Ring"]:
                return None, None
            prot_chain = ref_inter.get("prot_chain")
            prot_resi = ref_inter.get("prot_resi")
            prot_resn = ref_inter.get("prot_resn")
            if prot_chain is None or prot_resi is None:
                toks = str(ref_inter.get("prot_res", "")).split()
                pr = toks[1] if len(toks) > 1 else ""
                if pr:
                    prot_chain = pr[0]
                    prot_resi = pr[1:] if len(pr) > 1 else pr
                if not prot_resn and toks:
                    prot_resn = toks[0]
            if prot_chain is None or prot_resi is None:
                return None, None
            chain_clause = 'chain ""' if str(prot_chain).strip() == "" else f'chain "{str(prot_chain).strip()}"'
            prot_res_sel = f"{self.loaded_object} and {chain_clause} and resi {prot_resi}"
            if prot_resn:
                prot_res_sel += f" and resn {prot_resn}"
            prot_sel = f"({prot_res_sel}) and name {'+'.join(prot_atoms)}"
            lig_chain, lig_resi, lig_resn = self.ligand_info
            lig_res_sel = self._pymol_residue_selection(self.loaded_object, lig_chain, lig_resi, lig_resn, wrap=True)
            lig_sel = f"({lig_res_sel}) and name {'+'.join(lig_atoms)}"
            pm = cmd.get_model(prot_sel, state=int(state_idx))
            lm = cmd.get_model(lig_sel, state=int(state_idx))
            if not pm.atom or not lm.atom:
                return None, None
            p_coords = np.array([np.array(a.coord, dtype=float) for a in pm.atom], dtype=float)
            l_coords = np.array([np.array(a.coord, dtype=float) for a in lm.atom], dtype=float)
            p_cent = np.mean(p_coords, axis=0)
            l_cent = np.mean(l_coords, axis=0)
            return p_cent, l_cent
        except Exception:
            return None, None
    def _update_distance_dash_for_selected(self, rid, inter, state_idx=0, ref_inter=None):
        """
        Refresh distance dash for one already-selected interaction using frame-specific
        interaction coordinates.
        """
        dash_name = f"int_dash_{rid}"
        p1_name = f"pseudo_p_{rid}"
        p2_name = f"pseudo_l_{rid}"
        p1 = inter.get("prot_coord")
        p2 = inter.get("lig_coord")
        if p1 is None or p2 is None:
            return
        try:
            try:
                st = int(state_idx)
            except Exception:
                st = 0
            if st <= 0:
                try:
                    st = int(cmd.get_state())
                except Exception:
                    st = 1
            cmd.delete(p1_name)
            cmd.delete(p2_name)
            cmd.pseudoatom(p1_name, pos=list(p1), state=st)
            cmd.pseudoatom(p2_name, pos=list(p2), state=st)
            cmd.distance(dash_name, p1_name, p2_name, reset=1, state=st, state1=st, state2=st)
            itype = str(inter.get("type", ""))
            c_name = f"c_{itype.replace(' ', '_')}"
            c_rgb = _hex_to_rgb(COLOR_MAP.get(itype, "#FFFFFF"))
            if c_rgb:
                cmd.set_color(c_name, list(c_rgb))
            cmd.set("dash_color", c_name, dash_name)
            cmd.set("label_color", c_name, dash_name)
            self._apply_dash_style(dash_name, itype)
            cmd.group(f"Interactions.{itype.replace(' ', '_')}", dash_name)
            self._update_live_labels_for_selected(
                rid=rid,
                inter=inter,
                ref_inter=(ref_inter or inter),
                state_idx=st,
            )
        except Exception:
            pass
    def _update_live_labels_for_selected(self, rid, inter, ref_inter, state_idx):
        """
        Keep protein/ligand labels attached to the frame-resolved coordinates used by
        the selected interaction dash.
        """
        p = inter.get("prot_coord")
        lig_xyz = inter.get("lig_coord")
        if p is None or lig_xyz is None:
            return
        try:
            st = int(state_idx)
        except Exception:
            st = 1
        if st <= 0:
            st = 1
        lbl_prot = f"lbl_prot_{rid}"
        lbl_lig = f"lbl_lig_{rid}"
        itype = str((ref_inter or inter).get("type", "")).replace(" ", "_")
        gname = f"Interactions.{itype}"
        prot_atom_name = str((ref_inter or inter).get("prot_atom", ""))
        lig_atom_name = str((ref_inter or inter).get("lig_atom", ""))
        p_resn = str((ref_inter or inter).get("prot_resn") or "").strip()
        p_resi = (ref_inter or inter).get("prot_resi")
        if (not p_resn) or (p_resi is None):
            toks = str((ref_inter or inter).get("prot_res", "")).split()
            if toks and not p_resn:
                p_resn = toks[0]
            if (p_resi is None) and len(toks) > 1:
                p_resi = toks[1]
        if prot_atom_name == "Ring":
            prot_label = f"{p_resn} {p_resi} Ring".strip()
        else:
            prot_label = f"{p_resn} {p_resi} {prot_atom_name}".strip()
        lig_label = "Ring" if lig_atom_name == "Ring" else lig_atom_name
        try:
            cmd.delete(lbl_prot)
            cmd.delete(lbl_lig)
        except Exception:
            pass
        cmd.pseudoatom(lbl_prot, pos=list(p), state=st)
        cmd.pseudoatom(lbl_lig, pos=list(lig_xyz), state=st)
        cmd.label(lbl_prot, f'"{prot_label}"')
        cmd.label(lbl_lig, f'"{lig_label}"')
        cmd.set("label_color", "green", lbl_prot)
        cmd.set("label_color", "green", lbl_lig)
        cmd.group(gname, lbl_prot)
        cmd.group(gname, lbl_lig)
