    def _apply_leonardo_branding(self):
        logo_path = resource_string("logo.png")
        self.setWindowTitle(f"{SUITE_NAME} [{PLUGIN_BUILD}]")
        if os.path.isfile(logo_path):
            try:
                self.setWindowIcon(QtGui.QIcon(logo_path))
            except Exception:
                pass
        self._apply_global_stylesheet()
        if not hasattr(self, "verticalLayout"):
            return
        try:
            header = QtWidgets.QFrame(self)
            header.setObjectName("leonardo_brand_header")
            header.setMinimumHeight(100)
            header.setMaximumHeight(116)
            row = QtWidgets.QHBoxLayout(header)
            row.setContentsMargins(18, 12, 20, 12)
            row.setSpacing(16)
            if os.path.isfile(logo_path):
                pix = QtGui.QPixmap(logo_path)
                if not pix.isNull():
                    lbl_logo = QtWidgets.QLabel(header)
                    lbl_logo.setObjectName("leonardo_brand_logo")
                    lbl_logo.setAlignment(QtCore.Qt.AlignVCenter | QtCore.Qt.AlignLeft)
                    lbl_logo.setPixmap(
                        pix.scaled(68, 68, QtCore.Qt.KeepAspectRatio, QtCore.Qt.SmoothTransformation)
                    )
                    row.addWidget(lbl_logo, 0)
            title_col = QtWidgets.QVBoxLayout()
            title_col.setSpacing(0)
            title_col.setContentsMargins(0, 0, 0, 0)
            lbl_name = QtWidgets.QLabel(SUITE_NAME, header)
            lbl_name.setObjectName("leonardo_brand_name")
            lbl_tag = QtWidgets.QLabel(SUITE_SUBTITLE.upper(), header)
            lbl_tag.setObjectName("leonardo_brand_tagline")
            lbl_tag.setToolTip(SUITE_TAGLINE)
            title_col.addStretch(1)
            title_col.addWidget(lbl_name)
            title_col.addWidget(lbl_tag)
            title_col.addStretch(1)
            row.addLayout(title_col, 1)
            side_col = QtWidgets.QVBoxLayout()
            side_col.setSpacing(4)
            side_col.setContentsMargins(0, 0, 0, 0)
            lbl_ver = QtWidgets.QLabel(f"Version {PLUGIN_VERSION}  ·  Build {PLUGIN_BUILD}", header)
            lbl_ver.setObjectName("leonardo_brand_version")
            lbl_ver.setAlignment(QtCore.Qt.AlignRight | QtCore.Qt.AlignVCenter)
            lbl_contact = QtWidgets.QLabel(
                f'Bugs &amp; feedback: <a href="mailto:{SUITE_CONTACT_EMAIL}?subject=Leonardo%20{PLUGIN_VERSION}" style="color:#FFFFFF; text-decoration:none;">'
                f"{SUITE_CONTACT_EMAIL}</a>",
                header,
            )
            lbl_contact.setObjectName("leonardo_brand_contact")
            lbl_contact.setTextFormat(QtCore.Qt.RichText)
            lbl_contact.setOpenExternalLinks(True)
            lbl_contact.setAlignment(QtCore.Qt.AlignRight | QtCore.Qt.AlignVCenter)
            lbl_contact.setToolTip("Write to report a bug or send a comment")
            # Open-Source PyMOL: the slogan its trademark notice allows, and its copyright notice one click away
            lbl_credit = QtWidgets.QLabel(
                'Built using PyMOL\u2122 &middot; <a href="about" style="color:#FFFFFF; text-decoration:none;">'
                "About &amp; licenses</a>",
                header,
            )
            lbl_credit.setObjectName("leonardo_brand_contact")
            lbl_credit.setTextFormat(QtCore.Qt.RichText)
            lbl_credit.setAlignment(QtCore.Qt.AlignRight | QtCore.Qt.AlignVCenter)
            lbl_credit.setToolTip("Open-Source PyMOL is Copyright (C) Schrodinger, LLC. "
                                  "PyMOL is a trademark of Schrodinger, LLC.")
            lbl_credit.linkActivated.connect(lambda _link: self._show_about_dialog())
            side_col.addStretch(1)
            side_col.addWidget(lbl_ver)
            side_col.addWidget(lbl_credit)
            side_col.addWidget(lbl_contact)
            side_col.addStretch(1)
            row.addLayout(side_col, 0)
            self.verticalLayout.insertWidget(0, header)
        except Exception as e:
            print(f"{SUITE_NAME}: branding header warning: {e}")
    def _show_about_dialog(self):
        """About & licenses: Leonardo's license and the Open-Source PyMOL copyright and trademark notices."""
        try:
            from .about import show_about
        except ImportError:
            from leonardo.about import show_about
        self._about_dialog = show_about(self)
        return self._about_dialog
    def _connect_signals(self):
        self.file_btn.clicked.connect(self._on_load_pdb)
        if hasattr(self, "fetch_structure_btn"):
            self.fetch_structure_btn.clicked.connect(self._on_fetch_structure_dialog)
        self.detect_ligand_btn.clicked.connect(self._on_detect_ligand)
        if hasattr(self, "choose_ligand_btn"):
            self.choose_ligand_btn.clicked.connect(self._on_choose_ligand)
        self.calc_btn.clicked.connect(self._on_calc_interactions)
        self.table.cellClicked.connect(self._on_table_clicked)
        self.render_btn.clicked.connect(self._on_render_export)
        # Optional tools if present in UI
        if hasattr(self, "clear_btn"):
            self.clear_btn.clicked.connect(self._on_clear)
        if hasattr(self, "export_csv_btn"):
            self.export_csv_btn.clicked.connect(self._on_export_csv)
        if hasattr(self, "redraw_btn"):
            self.redraw_btn.clicked.connect(self._on_redraw_all)
        if hasattr(self, "redraw_visible_btn"):
            self.redraw_visible_btn.clicked.connect(self._on_redraw_visible_types)
        if hasattr(self, "reset_defaults_btn"):
            self.reset_defaults_btn.clicked.connect(self._on_reset_defaults)
        if hasattr(self, "hist_btn"):
            self.hist_btn.setVisible(False) # User request: move functionality to Trajectory only
            
        # User Request: Remove "Max Distance" labels and "Legend/Types" groups from main UI
        # (Since they were moved to Trajectory Analysis panel)
        if hasattr(self, "maxDistLabel"):
             self.maxDistLabel.setVisible(False)
        if hasattr(self, "types_group"):
             self.types_group.setVisible(False)
        if hasattr(self, "legend_group"):
             self.legend_group.setVisible(False)
        # Add 2D Map button programmatically if not in UI
        if not hasattr(self, "show_2d_btn"):
            self.show_2d_btn = QtWidgets.QPushButton("Show 2D Map")
            self.show_2d_btn.clicked.connect(self._on_show_2d_map)
            # Try to add to the tools layout or near render button
            # Assuming 'tools_group' or similar exists, or add to main layout
            # For robustness, we'll try to find a suitable layout
            if hasattr(self, "verticalLayout"): # Common top layout name
                self.verticalLayout.addWidget(self.show_2d_btn)
            else:
                self.layout().addWidget(self.show_2d_btn)
            self.show_2d_btn.setEnabled(False) # Enable after calculation
    def _on_load_pdb(self):
        path, _ = QtWidgets.QFileDialog.getOpenFileName(self, "Open PDB File", "", "PDB/CIF Files (*.pdb *.ent *.cif)")
        if not path:
            return
        try:
            self._load_structure_file_into_session(path)
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "Error", f"Failed to load structure: {e}")
    def _structure_fetch_workspace_dir(self):
        root = os.path.join(self._dock_workspace_dir(), "structures")
        try:
            os.makedirs(root, exist_ok=True)
        except Exception:
            pass
        return root
    def _on_fetch_structure_dialog(self):
        dlg = QtWidgets.QDialog(self)
        dlg.setWindowTitle("Fetch Structure")
        vbox = QtWidgets.QVBoxLayout(dlg)
        form = QtWidgets.QFormLayout()
        cmb_source = QtWidgets.QComboBox(dlg)
        source_order = ["rcsb", "alphafold", "esmatlas"]
        for key in source_order:
            spec = dict(STRUCTURE_FETCH_SOURCES.get(key, {}) or {})
            cmb_source.addItem(str(spec.get("label", key)), key)
        form.addRow("Source", cmb_source)
        edit_id = QtWidgets.QLineEdit(dlg)
        form.addRow("Identifier", edit_id)
        cmb_format = QtWidgets.QComboBox(dlg)
        form.addRow("Format", cmb_format)
        vbox.addLayout(form)
        status = QtWidgets.QLabel("", dlg)
        status.setWordWrap(True)
        vbox.addWidget(status)
        buttons = QtWidgets.QDialogButtonBox(
            QtWidgets.QDialogButtonBox.Ok | QtWidgets.QDialogButtonBox.Cancel,
            parent=dlg,
        )
        try:
            buttons.button(QtWidgets.QDialogButtonBox.Ok).setText("Fetch")
        except Exception:
            pass
        vbox.addWidget(buttons)

        def _refresh_source_fields():
            key = str(cmb_source.currentData() or "rcsb")
            spec = dict(STRUCTURE_FETCH_SOURCES.get(key, {}) or {})
            edit_id.setPlaceholderText(str(spec.get("id_hint", "") or ""))
            cmb_format.blockSignals(True)
            cmb_format.clear()
            for fmt in list(spec.get("formats", ("pdb",)) or ("pdb",)):
                label = "mmCIF" if str(fmt).lower() == "cif" else "PDB"
                cmb_format.addItem(label, str(fmt))
            default_fmt = str(spec.get("default_format", "") or "")
            idx = cmb_format.findData(default_fmt)
            if idx >= 0:
                cmb_format.setCurrentIndex(idx)
            cmb_format.blockSignals(False)
            status.setText(str(spec.get("id_hint", "") or ""))

        cmb_source.currentIndexChanged.connect(lambda _i: _refresh_source_fields())
        _refresh_source_fields()

        def _accept():
            source = str(cmb_source.currentData() or "rcsb")
            identifier = str(edit_id.text() or "").strip()
            fmt = str(cmb_format.currentData() or "")
            try:
                req = build_structure_fetch_request(source, identifier, file_format=fmt)
            except Exception as e:
                QtWidgets.QMessageBox.warning(dlg, "Fetch Structure", str(e))
                return
            try:
                QtWidgets.QApplication.setOverrideCursor(QtCore.Qt.WaitCursor)
                result = download_structure_file(req, self._structure_fetch_workspace_dir(), timeout=60)
                self._load_structure_file_into_session(
                    str(result.get("path", "")),
                    object_name=str(result.get("object_name", "") or ""),
                    source_label=f"{result.get('source_label', 'Database')} {result.get('identifier', '')}",
                )
                try:
                    self._settings["last_structure_fetch_source"] = str(result.get("source", "") or "")
                    self._settings["last_structure_fetch_identifier"] = str(result.get("identifier", "") or "")
                    self._settings["last_structure_fetch_format"] = str(result.get("format", "") or "")
                    self._save_settings()
                except Exception:
                    pass
                try:
                    self._append_debug_log(
                        "Fetched structure: "
                        f"source={result.get('source')}, id={result.get('identifier')}, "
                        f"path={result.get('path')}, url={result.get('resolved_url')}"
                    )
                except Exception:
                    pass
                QtWidgets.QMessageBox.information(
                    self,
                    "Fetch Structure",
                    f"Loaded {result.get('source_label', 'structure')} {result.get('identifier', '')}.\n\n"
                    f"File:\n{result.get('path', '')}",
                )
                dlg.accept()
            except Exception as e:
                QtWidgets.QMessageBox.critical(dlg, "Fetch Structure", f"Failed to fetch structure:\n{e}")
            finally:
                try:
                    QtWidgets.QApplication.restoreOverrideCursor()
                except Exception:
                    pass

        buttons.accepted.connect(_accept)
        buttons.rejected.connect(dlg.reject)
        try:
            last_source = str(self._settings.get("last_structure_fetch_source", "") or "")
            if last_source:
                idx = cmb_source.findData(last_source)
                if idx >= 0:
                    cmb_source.setCurrentIndex(idx)
            last_id = str(self._settings.get("last_structure_fetch_identifier", "") or "")
            if last_id:
                edit_id.setText(last_id)
        except Exception:
            pass
        dlg.resize(460, 170)
        dlg.exec_()
    def _load_structure_file_into_session(self, path, object_name=None, source_label=""):
        path = os.path.abspath(str(path or ""))
        if not path or not os.path.isfile(path):
            raise FileNotFoundError(path or "No structure file selected.")
        self.pdb_path = path
        if hasattr(self, "file_edit"):
            self.file_edit.setText(path)
        self._load_structure(path)
        base = str(object_name or os.path.splitext(os.path.basename(path))[0] or "structure")
        try:
            base = self._dock_safe_obj_name(base)
        except Exception:
            base = re.sub(r"[^A-Za-z0-9_]+", "_", base).strip("_") or "structure"
        cmd.reinitialize()
        self.loaded_object = base
        self._traj_topology_object = base
        try:
            cmd.load(path, base)
        except Exception as e:
            raise RuntimeError(f"Failed to load in PyMOL: {e}")
        self._populate_limit_combo()
        # persist last file
        try:
            self._settings["last_file"] = path
            if source_label:
                self._settings["last_file_source"] = str(source_label)
            self._save_settings()
        except Exception:
            pass
        self.ligand_info = None
        for widget_name in ("ligand_chain", "ligand_resi", "ligand_resn"):
            try:
                getattr(self, widget_name).clear()
            except Exception:
                pass
        ligand = self._auto_detect_ligand()
        if ligand:
            self.ligand_info = ligand
            self.ligand_chain.setText(ligand[0])
            self.ligand_resi.setText(str(ligand[1]))
            self.ligand_resn.setText(ligand[2])
            # persist last ligand
            try:
                self._settings.update(
                    {"last_ligand_chain": ligand[0], "last_ligand_resi": int(ligand[1]), "last_ligand_resn": ligand[2]}
                )
                self._save_settings()
            except Exception:
                pass
        self._beautify_scene()
        self.interactions.clear()
        self.table.setRowCount(0)
        self._selected_ids.clear()
        self._ligand_refined_mol = None
        self._update_main_workspace_summary()
    def _load_structure(self, path):
        ext = os.path.splitext(path)[1].lower()
        if ext in (".cif", ".mmcif"):
            parser = MMCIFParser(QUIET=True)
        else:
            parser = PDBParser(QUIET=True)
        self.structure = parser.get_structure("X", path)
    def _on_detect_ligand(self):
        if not self.structure:
            QtWidgets.QMessageBox.warning(self, "Error", "Load a PDB file first.")
            return
        ligand = self._auto_detect_ligand()
        if not ligand:
            QtWidgets.QMessageBox.warning(self, "Error", "No ligand detected.")
            return
        self.ligand_info = ligand
        self.ligand_chain.setText(ligand[0])
        self.ligand_resi.setText(str(ligand[1]))
        self.ligand_resn.setText(ligand[2])
        try:
            self._settings.update(
                {"last_ligand_chain": ligand[0], "last_ligand_resi": int(ligand[1]), "last_ligand_resn": ligand[2]}
            )
            self._save_settings()
        except Exception:
            pass
        self._beautify_scene()
        self._update_main_workspace_summary()
    def _auto_detect_ligand_in_object(self, obj_name):
        # Prefer PyMOL topology when available: it preserves duplicate atom names
        # that are frequently present in docking outputs (e.g., many atoms named "C").
        obj = str(obj_name or "").strip()
        try:
            if obj and cmd.count_atoms(obj) > 0:
                model = cmd.get_model(f"({obj}) and not polymer and not (solvent and resn HOH+WAT+H2O+DOD+TIP+TIP3+TIP4+TP3+T3P+SOL+SPC)")
                by_res = defaultdict(int)
                for a in model.atom:
                    try:
                        resn = str(a.resn).strip()
                        if not resn or resn in ATOM_DEFS["metals"] or resn == "HOH":
                            continue
                        if resn.upper() in OPENMM_PEPTIDE_CAPS:
                            continue          # ACE/NME caps are backbone, not ligands
                        ch = self._normalize_chain_id(a.chain)
                        ri = self._resi_to_int(a.resi)
                        el = str(getattr(a, "symbol", "")).strip().upper()
                        if not el:
                            nm = str(a.name).strip().upper()
                            if nm.startswith("CL"):
                                el = "CL"
                            elif nm.startswith("BR"):
                                el = "BR"
                            elif nm:
                                el = nm[0]
                        if el == "H":
                            continue
                        by_res[(ch, int(ri), resn)] += 1
                    except Exception:
                        continue
                if by_res:
                    best_key, _ = max(by_res.items(), key=lambda kv: kv[1])
                    return best_key
        except Exception:
            pass
        return None
    def _auto_detect_ligand(self):
        lig = self._auto_detect_ligand_in_object(self.loaded_object)
        if lig:
            return lig
        if self.structure is None:
            return None
        max_atoms = 0
        best = None
        for res in self.structure.get_residues():
            if (
                not is_aa(res)
                and res.get_resname() not in ATOM_DEFS["metals"]
                and res.get_resname() != "HOH"
                and res.get_resname().upper() not in OPENMM_PEPTIDE_CAPS
            ):
                heavy_atoms = [a for a in res if a.element != "H"]
                if len(heavy_atoms) > max_atoms:
                    max_atoms = len(heavy_atoms)
                    best = (res.parent.id, res.id[1], res.get_resname())
        return best
    def _discover_ligands(self):
        # Return a list of potential ligands with metadata
        ligands = []
        if not self.structure:
            return ligands
        seen = set()
        for res in self.structure.get_residues():
            resn = res.get_resname()
            if is_aa(res) or resn in ATOM_DEFS["metals"] or resn == "HOH" or resn.upper() in OPENMM_PEPTIDE_CAPS:
                continue
            chain_id = res.parent.id
            resi = res.id[1]
            key = (chain_id, resi, resn)
            if key in seen:
                continue
            seen.add(key)
            heavy_atoms = [a for a in res if getattr(a, "element", "") != "H"]
            ligands.append(
                {
                    "chain": chain_id,
                    "resi": int(resi),
                    "resn": resn,
                    "heavy_count": len(heavy_atoms),
                    "class": "nucleotide" if resn.upper() in NUCLEOTIDE_RESN else "small_molecule",
                }
            )
        # Sort nucleotides first, then by heavy atoms desc, then chain/resi
        ligands.sort(key=lambda x: (0 if x["class"] == "nucleotide" else 1, -x["heavy_count"], x["chain"], x["resi"]))
        return ligands
    def _on_choose_ligand(self):
        if not self.structure:
            QtWidgets.QMessageBox.warning(self, "Error", "Load a structure first.")
            return
        items = self._discover_ligands()
        if not items:
            QtWidgets.QMessageBox.information(
                self, "No ligands", "No non-polymer, non-water, non-metal residues detected."
            )
            return
        # Build chooser dialog
        dlg = QtWidgets.QDialog(self)
        dlg.setWindowTitle("Choose Ligand")
        v = QtWidgets.QVBoxLayout(dlg)
        # Filter row
        filt_row = QtWidgets.QHBoxLayout()
        filt_row.addWidget(QtWidgets.QLabel("Show:"))
        filt_combo = QtWidgets.QComboBox(dlg)
        filt_combo.addItems(["All", "Ligands", "DNA/RNA"])
        filt_row.addSpacing(12)
        near_cb = QtWidgets.QCheckBox("Within")
        near_spin = QtWidgets.QDoubleSpinBox()
        near_spin.setDecimals(1)
        near_spin.setRange(1.0, 20.0)
        near_spin.setSingleStep(0.5)
        near_spin.setValue(6.0)
        near_cb.setChecked(False)
        unit_lbl = QtWidgets.QLabel("Å of")
        ref_combo = QtWidgets.QComboBox(dlg)
        ref_combo.addItem("Protein")
        # populate chains
        chains = []
        try:
            chains = sorted({ch.id for ch in self.structure.get_chains()})
        except Exception:
            chains = []
        ref_combo.addItem("Chain")
        if self.ligand_info:
            ref_combo.addItem("Current Ligand")
        chain_combo = QtWidgets.QComboBox(dlg)
        chain_combo.addItems([str(c) for c in chains] if chains else [])
        chain_combo.setEnabled(False)
        near_spin.setEnabled(False)
        def on_near_toggle(on):
            near_spin.setEnabled(on)
            unit_lbl.setEnabled(on)
            ref_combo.setEnabled(on)
            chain_combo.setEnabled(on and ref_combo.currentText() == "Chain")
        near_cb.toggled.connect(on_near_toggle)
        def on_ref_change(_):
            chain_combo.setEnabled(near_cb.isChecked() and ref_combo.currentText() == "Chain")
        ref_combo.currentTextChanged.connect(on_ref_change)
        for w in (near_cb, near_spin, unit_lbl, ref_combo, chain_combo):
            filt_row.addWidget(w)
        # Search box
        filt_row.addSpacing(12)
        search_edit = QtWidgets.QLineEdit(dlg)
        search_edit.setPlaceholderText("Search (chain/resn/resi)")
        filt_row.addWidget(search_edit)
        filt_row.addStretch(1)
        v.addLayout(filt_row)
        table = QtWidgets.QTableWidget(dlg)
        table.setColumnCount(6)
        table.setHorizontalHeaderLabels(["Chain", "Resi", "Resn", "Heavy atoms", "Class", "Min Dist (Å)"])
        table.setSortingEnabled(True)
        def populate(rows):
            table.setRowCount(0)
            table.setRowCount(len(rows))
            for i, it in enumerate(rows):
                table.setItem(i, 0, QtWidgets.QTableWidgetItem(str(it["chain"])))
                table.setItem(i, 1, QtWidgets.QTableWidgetItem(str(it["resi"])))
                table.setItem(i, 2, QtWidgets.QTableWidgetItem(str(it["resn"])))
                table.setItem(i, 3, QtWidgets.QTableWidgetItem(str(it["heavy_count"])))
                table.setItem(i, 4, QtWidgets.QTableWidgetItem("DNA/RNA" if it["class"] == "nucleotide" else "Ligand"))
                # Min distance to current reference when proximity filter is enabled
                mind_txt = ""
                if near_cb.isChecked():
                    md = min_dist_reference(it)
                    if md is not None:
                        mind_txt = f"{md:.2f}"
                item = QtWidgets.QTableWidgetItem(mind_txt)
                # Make numeric sort work even if empty by setting data role
                try:
                    item.setData(QtCore.Qt.UserRole, float(mind_txt) if mind_txt else 1e9)
                except Exception:
                    pass
                table.setItem(i, 5, item)
            table.resizeColumnsToContents()
        items_full = items[:]
        populate(items_full)
        table.setSelectionBehavior(QtWidgets.QAbstractItemView.SelectRows)
        table.setSelectionMode(QtWidgets.QAbstractItemView.SingleSelection)
        v.addWidget(table)
        # Preview checkbox and behavior
        preview_row = QtWidgets.QHBoxLayout()
        preview_cb = QtWidgets.QCheckBox("Preview zoom on hover/selection", dlg)
        preview_cb.setChecked(True)
        preview_row.addWidget(preview_cb)
        preview_row.addStretch(1)
        v.addLayout(preview_row)
        # Build reference coordinate caches
        prot_coords = []
        chain_coords = {c: [] for c in chains}
        try:
            for res in self.structure.get_residues():
                ch = res.parent.id
                # protein heavy atoms for protein reference
                if is_aa(res):
                    for a in res:
                        if getattr(a, "element", "") != "H":
                            prot_coords.append(np.array(a.coord))
                # chain coords: include all heavy atoms (protein + nucleic acid + others)
                if ch in chain_coords:
                    for a in res:
                        if getattr(a, "element", "") != "H":
                            chain_coords[ch].append(np.array(a.coord))
            prot_coords = np.array(prot_coords) if prot_coords else np.zeros((0, 3))
            for ch in list(chain_coords.keys()):
                arr = np.array(chain_coords[ch]) if chain_coords[ch] else np.zeros((0, 3))
                chain_coords[ch] = arr
        except Exception:
            prot_coords = np.zeros((0, 3))
            chain_coords = {c: np.zeros((0, 3)) for c in chains}
        def residue_atoms(chain, resi, resn):
            try:
                for res in self.structure.get_residues():
                    if res.parent.id == chain and res.id[1] == resi and res.get_resname() == resn:
                        return [np.array(a.coord) for a in res if getattr(a, "element", "") != "H"]
            except Exception:
                pass
            return []
        def near_reference(it, thr):
            # Determine reference coords
            ref = ref_combo.currentText()
            if ref == "Protein":
                rc = prot_coords
            elif ref == "Chain":
                ch = chain_combo.currentText()
                rc = chain_coords.get(ch, np.zeros((0, 3)))
            else:  # Current Ligand
                rc_list = []
                try:
                    if self.ligand_info:
                        c, i, r = self.ligand_info
                        rc_list = residue_atoms(c, int(i), r)
                except Exception:
                    rc_list = []
                rc = np.array(rc_list) if rc_list else np.zeros((0, 3))
            if rc.shape[0] == 0:
                return False
            lig = residue_atoms(it["chain"], it["resi"], it["resn"])
            if not lig:
                return False
            for la in lig:
                d = np.linalg.norm(rc - la, axis=1).min()
                if d <= thr:
                    return True
            return False
        def min_dist_reference(it):
            # Returns minimal heavy-atom distance to current reference or None
            ref = ref_combo.currentText()
            if ref == "Protein":
                rc = prot_coords
            elif ref == "Chain":
                ch = chain_combo.currentText()
                rc = chain_coords.get(ch, np.zeros((0, 3)))
            else:
                rc_list = []
                try:
                    if self.ligand_info:
                        c, i, r = self.ligand_info
                        rc_list = residue_atoms(c, int(i), r)
                except Exception:
                    rc_list = []
                rc = np.array(rc_list) if rc_list else np.zeros((0, 3))
            if rc.shape[0] == 0:
                return None
            lig = residue_atoms(it["chain"], it["resi"], it["resn"])
            if not lig:
                return None
            best = None
            for la in lig:
                d = float(np.linalg.norm(rc - la, axis=1).min())
                if best is None or d < best:
                    best = d
            return best
        def apply_filter():
            mode = filt_combo.currentText()
            if mode == "All":
                rows = items_full
            elif mode == "Ligands":
                rows = [x for x in items_full if x["class"] == "small_molecule"]
            else:
                rows = [x for x in items_full if x["class"] == "nucleotide"]
            if near_cb.isChecked():
                thr = float(near_spin.value())
                rows = [x for x in rows if near_reference(x, thr)]
            q = search_edit.text().strip().lower()
            if q:
                def match(rec):
                    blob = f"{rec['chain']} {rec['resn']} {rec['resi']} {rec['class']}".lower()
                    return q in blob
                rows = [r for r in rows if match(r)]
            populate(rows)
            try:
                if near_cb.isChecked():
                    table.sortItems(5, QtCore.Qt.AscendingOrder)
            except Exception:
                pass
        filt_combo.currentTextChanged.connect(lambda _t: (apply_filter(), _save_chooser_settings()))
        near_cb.toggled.connect(lambda _on: (apply_filter(), _save_chooser_settings()))
        near_spin.valueChanged.connect(lambda _v: (apply_filter(), _save_chooser_settings()))
        ref_combo.currentTextChanged.connect(lambda _t: (apply_filter(), _save_chooser_settings()))
        chain_combo.currentTextChanged.connect(lambda _t: (apply_filter(), _save_chooser_settings()))
        search_edit.textChanged.connect(lambda _t: (apply_filter(), _save_chooser_settings()))
        def zoom_to_row(row):
            if row < 0 or row >= table.rowCount():
                return
            if not preview_cb.isChecked():
                return
            try:
                ch = table.item(row, 0).text()
                ri = table.item(row, 1).text()
                rn = table.item(row, 2).text()
                sel = f"{self.loaded_object} and chain {ch} and resi {ri} and resn {rn}"
                cmd.zoom(sel, 8)
            except Exception:
                pass
        table.setMouseTracking(True)
        table.cellEntered.connect(lambda r, c: zoom_to_row(r))
        table.itemSelectionChanged.connect(lambda: zoom_to_row(table.currentRow()))
        # Restore chooser settings
        try:
            cs = self._settings
            # show mode
            if cs.get("chooser_show") in ["All", "Ligands", "DNA/RNA"]:
                filt_combo.setCurrentText(cs.get("chooser_show"))
            # near filter
            near_cb.setChecked(bool(cs.get("chooser_near", False)))
            near_spin.setValue(float(cs.get("chooser_near_dist", 6.0)))
            if cs.get("chooser_ref") in ["Protein", "Chain", "Current Ligand"]:
                ref_combo.setCurrentText(cs.get("chooser_ref"))
            # chain selection
            ch_pref = cs.get("chooser_ref_chain", "")
            if ch_pref and ch_pref in [chain_combo.itemText(i) for i in range(chain_combo.count())]:
                chain_combo.setCurrentText(ch_pref)
            search_edit.setText(cs.get("chooser_search", ""))
            apply_filter()
        except Exception:
            apply_filter()
        h = QtWidgets.QHBoxLayout()
        export_btn = QtWidgets.QPushButton("Export CSV", dlg)
        select_btn = QtWidgets.QPushButton("Select", dlg)
        cancel_btn = QtWidgets.QPushButton("Cancel", dlg)
        h.addWidget(export_btn)
        h.addStretch(1)
        h.addWidget(select_btn)
        h.addWidget(cancel_btn)
        v.addLayout(h)
        def do_select():
            idx = table.currentRow()
            if idx < 0:
                QtWidgets.QMessageBox.warning(dlg, "Select", "Please select a row.")
                return
            # read back from table to find selected ligand
            chain = table.item(idx, 0).text()
            resi = int(table.item(idx, 1).text())
            resn = table.item(idx, 2).text()
            if chain == "":
                chain = " "
            it = next(
                (
                    x
                    for x in items_full
                    if str(x["chain"]) == chain and int(x["resi"]) == resi and str(x["resn"]) == resn
                ),
                None,
            )
            if it is None:
                QtWidgets.QMessageBox.warning(dlg, "Select", "Could not resolve selection.")
                return
            self.ligand_info = (it["chain"], int(it["resi"]), it["resn"])
            self.ligand_chain.setText(str(it["chain"]))
            self.ligand_resi.setText(str(it["resi"]))
            self.ligand_resn.setText(str(it["resn"]))
            try:
                self._settings.update(
                    {
                        "last_ligand_chain": it["chain"],
                        "last_ligand_resi": int(it["resi"]),
                        "last_ligand_resn": it["resn"],
                    }
                )
                self._save_settings()
            except Exception:
                pass
            self._update_main_workspace_summary()
            dlg.accept()
        select_btn.clicked.connect(do_select)
        cancel_btn.clicked.connect(dlg.reject)
        table.itemDoubleClicked.connect(lambda *_: do_select())
        def do_export():
            path, _ = QtWidgets.QFileDialog.getSaveFileName(dlg, "Export Ligands CSV", "ligands.csv", "CSV (*.csv)")
            if not path:
                return
            try:
                import csv
                with open(path, "w", newline="") as f:
                    w = csv.writer(f)
                    headers = ["Chain", "Resi", "Resn", "Heavy atoms", "Class"]
                    if table.columnCount() >= 6:
                        headers.append("Min Dist (Å)")
                    w.writerow(headers)
                    for row in range(table.rowCount()):
                        vals = [
                            table.item(row, 0).text() if table.item(row, 0) else "",
                            table.item(row, 1).text() if table.item(row, 1) else "",
                            table.item(row, 2).text() if table.item(row, 2) else "",
                            table.item(row, 3).text() if table.item(row, 3) else "",
                            table.item(row, 4).text() if table.item(row, 4) else "",
                        ]
                        if table.columnCount() >= 6:
                            vals.append(table.item(row, 5).text() if table.item(row, 5) else "")
                        w.writerow(vals)
                QtWidgets.QMessageBox.information(dlg, "Exported", f"Ligand list saved to {path}")
            except Exception as e:
                QtWidgets.QMessageBox.critical(dlg, "Error", f"Failed to export CSV: {e}")
        export_btn.clicked.connect(do_export)
        def _save_chooser_settings():
            try:
                self._settings.update(
                    {
                        "chooser_show": filt_combo.currentText(),
                        "chooser_near": bool(near_cb.isChecked()),
                        "chooser_near_dist": float(near_spin.value()),
                        "chooser_ref": ref_combo.currentText(),
                        "chooser_ref_chain": (
                            chain_combo.currentText() if chain_combo.isEnabled() and chain_combo.count() > 0 else ""
                        ),
                        "chooser_search": search_edit.text(),
                    }
                )
                self._save_settings()
            except Exception:
                pass
        dlg.resize(540, 360)
        dlg.exec_()
    def _normalize_chain_id(self, chain_id):
        """
        Normalize chain IDs across Bio.PDB/PyMOL conventions.
        Blank chain is represented as a single space for Bio.PDB matching.
        """
        s = "" if chain_id is None else str(chain_id)
        return " " if s.strip() == "" else s.strip()
    def _resi_to_int(self, resi):
        """
        Parse PyMOL/Bio.PDB residue ids like '184', '184A', '-3B' to integer part.
        """
        if isinstance(resi, int):
            return int(resi)
        s = str(resi).strip()
        if not s:
            raise ValueError("empty residue id")
        try:
            return int(s)
        except Exception:
            m = re.match(r"^(-?\d+)", s)
            if m:
                return int(m.group(1))
            m = re.search(r"(-?\d+)", s)
            if m:
                return int(m.group(1))
            raise ValueError(f"invalid residue id: {resi}")
    def _pymol_residue_selection(self, obj_name, chain, resi, resn, wrap=False):
        """Build a robust PyMOL residue selector (quoted model + blank-chain safe)."""
        if not obj_name:
            return ""
        try:
            ri = int(resi)
        except Exception:
            ri = str(resi).strip()
        ch = "" if chain is None else str(chain)
        if ch.strip() == "":
            chain_clause = 'chain ""'
        else:
            chain_clause = f'chain "{ch.strip()}"'
        try:
            model_clause = self._pymol_model_selection(obj_name, wrap=True)
        except Exception:
            model_clause = ""
        if not model_clause:
            safe = str(obj_name).replace("\\", "\\\\").replace('"', '\\"')
            model_clause = f'(model "{safe}")'
        rn = str(resn).strip().upper()
        sel = f"{model_clause} and {chain_clause} and resi {ri} and resn {rn}"
        return f"({sel})" if wrap else sel
    def _pymol_model_selection(self, obj_name, wrap=False):
        """
        Build a robust PyMOL selector for object names.
        For names with punctuation (e.g. grouped names like Docking.Ligand),
        prefer exact-name `%name` selectors over `model "..."` to avoid
        parser errors in some PyMOL builds.
        """
        name = "" if obj_name is None else str(obj_name).strip()
        if not name:
            return ""
        safe = name.replace("\\", "\\\\").replace('"', '\\"')
        if re.match(r"^[A-Za-z0-9_]+$", name):
            sel = f'model "{safe}"'
        else:
            if re.search(r"\s", name):
                sel = f'%"{safe}"'
            else:
                sel = f'%{name}'
        return f"({sel})" if wrap else sel
    def _pymol_object_names(self):
        """Return current PyMOL object names as a string set."""
        try:
            return {str(n) for n in cmd.get_names("objects")}
        except Exception:
            return set()
    def _pymol_object_exists(self, obj_name, known_objects=None):
        """Check object existence without raising selection parser errors."""
        name = "" if obj_name is None else str(obj_name).strip()
        if not name:
            return False
        names = known_objects if isinstance(known_objects, set) else self._pymol_object_names()
        return name in names
    def _pymol_object_atom_count(self, obj_name, polymer_only=False):
        """
        Count atoms for a PyMOL object name using robust quoted selections.
        Returns 0 on any selection/parser failure.
        """
        name = "" if obj_name is None else str(obj_name).strip()
        if not name:
            return 0
        try:
            sel = self._pymol_model_selection(name, wrap=True)
        except Exception:
            sel = ""
        if not sel:
            return 0
        expr = f"{sel} and polymer" if bool(polymer_only) else sel
        try:
            return int(max(0, int(cmd.count_atoms(expr))))
        except Exception:
            return 0
    def _is_generated_docking_object(self, obj_name):
        """Internal/transient docking/ABFE objects that should not be used as receptor sources."""
        name = str(obj_name or "").strip().lower()
        if not name:
            return False
        transient_prefixes = (
            "dock_pose_mode",
            "dock_complex_mode",
            "dock_selected_pose_preview",
            "dock_receptor_poly_mode",
            "vs_selected_pose_preview",
            "vs_complex_rank",
            "abfe_local_md_view",
            "abfe_context_protein",
        )
        return any(name.startswith(pfx) for pfx in transient_prefixes)
    def _resolve_ligand_residue_in_structure(self, chain, resi, resn):
        """
        Resolve ligand residue against current structure and repair stale chain IDs.
        """
        if self.structure is None:
            return None
        target_resn = str(resn).strip() if resn is not None else ""
        if not target_resn:
            return None
        try:
            target_resi = int(resi)
        except Exception:
            target_resi = None
        target_chain = self._normalize_chain_id(chain)
        candidates = []
        for res in self.structure.get_residues():
            r_resn = str(res.get_resname()).strip()
            if r_resn != target_resn:
                continue
            try:
                r_resi = int(res.id[1])
            except Exception:
                continue
            r_chain = self._normalize_chain_id(res.parent.id)
            heavy = sum(
                1
                for a in res
                if str(getattr(a, "element", "")).strip().upper() != "H"
            )
            score = float(heavy)
            if target_resi is not None and r_resi == target_resi:
                score += 10000.0
            if r_chain == target_chain:
                score += 5000.0
            try:
                if self.loaded_object and cmd.count_atoms(self.loaded_object) > 0:
                    rsel = self._pymol_residue_selection(
                        self.loaded_object, r_chain, r_resi, r_resn, wrap=True
                    )
                    present = int(cmd.count_atoms(rsel))
                    near = int(
                        cmd.count_atoms(
                            f"({self.loaded_object}) and polymer within 6.0 of {rsel}"
                        )
                    )
                    score += (100.0 * present) + near
            except Exception:
                pass
            candidates.append((score, r_chain, r_resi, r_resn))
        if not candidates:
            return None
        candidates.sort(key=lambda x: x[0], reverse=True)
        best = candidates[0]
        return (str(best[1]), int(best[2]), str(best[3]))
    def _resolve_ligand_inputs(self):
        """
        Resolve ligand tuple as (chain, resi, resn) from UI fields, cached selection,
        or auto-detection. Chain may be blank in some PDBs.
        """
        c = self.ligand_chain.text().strip() if hasattr(self, "ligand_chain") else ""
        i = self.ligand_resi.text().strip() if hasattr(self, "ligand_resi") else ""
        r = self.ligand_resn.text().strip() if hasattr(self, "ligand_resn") else ""
        # Prefer explicit fields; otherwise detect directly from the active PyMOL object.
        if not i or not r:
            try:
                obj = self._resolve_analysis_object(prefer_combo=True) or self.loaded_object
            except Exception:
                obj = self.loaded_object
            try:
                lig = self._auto_detect_ligand_in_object(obj)
                if lig:
                    c = str(lig[0]) if lig[0] is not None else ""
                    i = str(int(lig[1]))
                    r = str(lig[2])
            except Exception:
                pass
        # Fallback to previously selected ligand.
        if (not i or not r) and self.ligand_info:
            try:
                c0, i0, r0 = self.ligand_info
                if not c:
                    c = str(c0) if c0 is not None else ""
                if not i:
                    i = str(int(i0))
                if not r:
                    r = str(r0)
            except Exception:
                pass
        # Final fallback: auto-detect from structure.
        if (not i or not r) and self.structure is not None:
            try:
                lig = self._auto_detect_ligand()
                if lig:
                    c = str(lig[0]) if lig[0] is not None else ""
                    i = str(int(lig[1]))
                    r = str(lig[2])
            except Exception:
                pass
        try:
            ii = int(i)
        except Exception:
            return None
        if not r:
            return None
        # Normalize then resolve against the current structure.
        c = self._normalize_chain_id(c)
        try:
            resolved = self._resolve_ligand_residue_in_structure(c, ii, r)
            if resolved is not None:
                c, ii, r = resolved
            elif self.structure is not None:
                lig = self._auto_detect_ligand_in_object(self.loaded_object) or self._auto_detect_ligand()
                if lig:
                    c = self._normalize_chain_id(lig[0])
                    ii = int(lig[1])
                    r = str(lig[2])
        except Exception:
            pass
        c = self._normalize_chain_id(c)
        # Sync UI + cache (chain may legitimately be blank).
        try:
            self.ligand_chain.setText("" if str(c).strip() == "" else str(c))
            self.ligand_resi.setText(str(ii))
            self.ligand_resn.setText(str(r))
        except Exception:
            pass
        self.ligand_info = (str(c), int(ii), str(r))
        return self.ligand_info
    def _reset_table_filters_to_all(self):
        """Avoid stale hidden filters masking interaction rows after a new compute."""
        try:
            if hasattr(self, "filter_combo"):
                self.filter_combo.blockSignals(True)
                if self.filter_combo.findText("All") >= 0:
                    self.filter_combo.setCurrentText("All")
                self.filter_combo.blockSignals(False)
        except Exception:
            pass
        try:
            if hasattr(self, "max_distance_spin"):
                self.max_distance_spin.blockSignals(True)
                self.max_distance_spin.setValue(0.0)
                self.max_distance_spin.blockSignals(False)
        except Exception:
            pass
    def _on_calc_interactions(self):
        # Always run a fresh reference-frame compute here.
        self._traj_mode = False
        self._last_live_state = -1
        self._cached_features = None
        self._ensure_valid_analysis_context()
        lig = self._resolve_ligand_inputs()
        if lig is None:
            QtWidgets.QMessageBox.warning(self, "Error", "Specify ligand info.")
            return
        obj = self._resolve_analysis_object(prefer_combo=True)
        if obj:
            self.loaded_object = obj
            if hasattr(self, "structure_combo"):
                idx = self.structure_combo.findText(obj)
                if idx >= 0:
                    self.structure_combo.setCurrentIndex(idx)
        if not self.loaded_object:
            QtWidgets.QMessageBox.warning(self, "Error", "No structure object selected.")
            return
        # Keep topology object pinned when available (prevents drift to ligand-only objects).
        topo_obj = getattr(self, "_traj_topology_object", None)
        try:
            if topo_obj and cmd.count_atoms(topo_obj) > 0:
                topo_poly = cmd.count_atoms(f"({topo_obj}) and polymer")
                curr_poly = cmd.count_atoms(f"({self.loaded_object}) and polymer")
                if topo_poly > 0 and curr_poly <= 0:
                    self.loaded_object = topo_obj
                    if hasattr(self, "structure_combo"):
                        idx = self.structure_combo.findText(topo_obj)
                        if idx >= 0:
                            self.structure_combo.setCurrentIndex(idx)
        except Exception:
            pass
        if not self._sync_structure_from_pymol() and self.structure is None:
            QtWidgets.QMessageBox.warning(
                self, "Error", "Could not parse topology. Load a PDB/CIF topology first."
            )
            return
        # Re-resolve ligand after structure sync to avoid stale chain/residue context.
        lig = self._resolve_ligand_inputs()
        if lig is None:
            QtWidgets.QMessageBox.warning(self, "Error", "Specify ligand info.")
            return
        self._ligand_refined_mol = None
        self._ligand_refined_keep_input_h = False
        self.ligand_info = lig
        try:
            self._append_debug_log(
                f"Compute started | object='{self.loaded_object}' | ligand={self.ligand_info[2]} "
                f"{self.ligand_info[0]}:{self.ligand_info[1]}"
            )
        except Exception:
            pass
        # Absolute fallback: if current object has no polymer, locate an object with polymer+ligand.
        try:
            curr_poly = int(cmd.count_atoms(f"({self.loaded_object}) and polymer"))
            if curr_poly <= 0:
                l_c, l_i, l_n = self.ligand_info
                obj2 = self._find_object_with_ligand_and_polymer(l_c, l_i, l_n)
                if obj2:
                    self.loaded_object = obj2
                    self._traj_topology_object = obj2
                    if hasattr(self, "structure_combo"):
                        idx = self.structure_combo.findText(obj2)
                        if idx >= 0:
                            self.structure_combo.setCurrentIndex(idx)
        except Exception:
            pass
        # Validate ligand protonation/charge setup before interaction classification.
        self._target_ph = None
        try:
            is_traj = self._is_trajectory_object()
            l_c, l_i, l_n = self.ligand_info
            target_res = None
            for res in self.structure.get_residues():
                if res.parent.id == l_c and int(res.id[1]) == int(l_i) and res.get_resname() == l_n:
                    target_res = res
                    break
            has_ligand_h = False
            if target_res is not None:
                has_ligand_h = any(getattr(a, "element", "").upper() == "H" for a in target_res)
            if is_traj:
                # Trajectories are expected to already carry correct hydrogens from topology prep.
                print("ProtLigInteract: Trajectory context detected; skipping ligand protonation/repair.")
                self._append_debug_log(
                    "Trajectory context detected (multi-state object): skipped ligand protonation/refinement."
                )
            elif target_res is not None and HAS_RDKIT:
                default_ph = 7.4
                try:
                    default_ph = float(self._settings.get("target_ph", 7.4))
                except Exception:
                    default_ph = 7.4
                assess = self._assess_ligand_hydrogen_quality(target_ph=default_ph)
                do_refine = False
                status = str(assess.get("status", "unknown"))
                reason = str(assess.get("reason", "")).strip()
                self._append_debug_log(
                    "Single-PDB hydrogen assessment: "
                    f"status={status}, "
                    f"has_h={bool(assess.get('has_h', False))}, "
                    f"h_count={int(assess.get('hydrogen_count', 0))}, "
                    f"needs_refine={bool(assess.get('needs_refine', False))}, "
                    f"reason='{reason or 'OK'}'."
                )
                if bool(assess.get("needs_refine", False)):
                    ph, ok = QtWidgets.QInputDialog.getDouble(
                        self,
                        "Ligand Refactoring Required",
                        (
                            f"{reason or 'Ligand hydrogens are missing or inconsistent.'}\n"
                            "Refinement is required for accurate single-PDB interactions.\n"
                            "Enter target pH for protonation/charge repair.\n"
                            "Tip: install dimorphite-dl for better pH-aware protonation."
                        ),
                        default_ph,
                        0.0,
                        14.0,
                        1,
                    )
                    if ok:
                        self._target_ph = float(ph)
                        self._append_debug_log(
                            f"User selected pH {self._target_ph:.2f} for mandatory single-PDB refinement."
                        )
                    else:
                        # Keep mandatory refinement but fallback to configured/default pH.
                        self._target_ph = float(default_ph)
                        self._append_debug_log(
                            f"pH dialog canceled; using default pH {self._target_ph:.2f} for mandatory refinement."
                        )
                    do_refine = True
                else:
                    self._append_debug_log("Single-PDB ligand hydrogens/chemistry look valid; no refinement needed.")
                    # still type the ligand from a model with bond orders (groups, rings, donor/acceptor
                    # roles); the input hydrogens are kept for the geometry
                    try:
                        self._refine_ligand_geometry(target_ph=default_ph, update_scene=False)
                        self._ligand_refined_keep_input_h = True
                    except Exception as chem_e:
                        self._ligand_refined_mol = None
                        self._append_debug_log(f"Ligand chemistry model unavailable ({chem_e}); typing from the input.")
                if do_refine:
                    try:
                        self._settings["target_ph"] = float(self._target_ph)
                        self._save_settings()
                    except Exception:
                        pass
                    try:
                        self._refine_ligand_geometry(target_ph=self._target_ph, update_scene=False)
                        self._append_debug_log("Ligand chemistry refinement completed successfully.")
                    except Exception as ref_e:
                        # not fatal: the ligand is typed from its input atoms or the topology rules
                        self._append_debug_log(
                            f"Ligand chemistry refinement failed ({ref_e}); typing the ligand from its input atoms."
                        )
            elif target_res is not None:
                if not has_ligand_h:
                    self._append_debug_log(
                        "Single-PDB ligand has no hydrogens and RDKit is unavailable; cannot perform required refinement."
                    )
                    QtWidgets.QMessageBox.warning(
                        self,
                        "Missing RDKit",
                        "Ligand has no hydrogens and RDKit is unavailable.\n"
                        "Single-PDB refinement is required for best accuracy in this case.",
                    )
                else:
                    self._append_debug_log(
                        "RDKit unavailable: hydrogens detected but wrong-hydrogen validation/refinement is unavailable."
                    )
            elif target_res is None:
                self._append_debug_log("Ligand residue could not be resolved in parsed structure; skipped refinement checks.")
        except Exception as e:
            self._append_debug_log(f"Pre-calc hydrogen/refinement check failed: {e}")
            print(f"Pre-calc Check Error: {e}")
        # Refresh structure from the selected object/state after optional chemistry repair.
        try:
            print("ProtLigInteract: Synchronizing structure from PyMOL...")
            if not self._sync_structure_from_pymol():
                print("ProtLigInteract: Warning - Empty/invalid PDB string from PyMOL.")
        except Exception as e:
            print(f"ProtLigInteract: Structure Sync Failed: {e}")
             
        # Remove previous visual artifacts before rebuilding interactions.
        try:
            self._on_clear()
        except Exception:
            pass
        try:
            self.interactions = self._calculate_all_interactions()
        except Exception as e:
            error_text = (
                "The interaction calculation could not be completed.\n\n"
                f"{e}\n\n"
                "Verify the selected structure, ligand chain, residue number, and residue name. "
                "The complete diagnostic is also recorded in Leonardo's debug log."
            )
            try:
                self._append_debug_log(f"Interaction calculation failed: {e}")
            except Exception:
                pass
            QtWidgets.QMessageBox.critical(self, "Interaction Calculation Error", error_text)
            return
        # Safety retry: if a non-topology object was analyzed and yielded zero, retry on topology.
        try:
            topo_obj = getattr(self, "_traj_topology_object", None)
            if (
                len(self.interactions) == 0
                and topo_obj
                and topo_obj != self.loaded_object
                and cmd.count_atoms(topo_obj) > 0
                and cmd.count_atoms(f"({topo_obj}) and polymer") > 0
            ):
                prev_obj = self.loaded_object
                self.loaded_object = topo_obj
                if self._sync_structure_from_pymol():
                    self._cached_features = None
                    retry = self._calculate_all_interactions()
                    if retry:
                        self.interactions = retry
                        print(
                            f"ProtLigInteract: Recovered from 0-interaction context "
                            f"({prev_obj} -> {topo_obj})."
                        )
                        if hasattr(self, "structure_combo"):
                            idx = self.structure_combo.findText(topo_obj)
                            if idx >= 0:
                                self.structure_combo.setCurrentIndex(idx)
        except Exception:
            pass
        try:
            tcounts = collections.Counter(str(i.get("type", "")) for i in self.interactions)
            if tcounts:
                top_txt = ", ".join(f"{k}:{v}" for k, v in tcounts.most_common())
            else:
                top_txt = "none"
            self._append_debug_log(f"Interactions computed: {len(self.interactions)} | types: {top_txt}")
        except Exception:
            pass
        # Always show full fresh results after compute.
        self._reset_table_filters_to_all()
        self._populate_table()
        self._beautify_scene()
        self._apply_publication_view()
        # If there are no contacts in this frame, force a protein-centered view so
        # the user does not end up with a ligand-only framing.
        try:
            if len(self.interactions) == 0 and self.ligand_info and self.loaded_object:
                l_c, l_i, l_n = self.ligand_info
                lig_sel = self._pymol_residue_selection(self.loaded_object, l_c, l_i, l_n, wrap=True)
                near6 = cmd.count_atoms(f"({self.loaded_object}) and polymer within 6.0 of ({lig_sel})")
                if near6 == 0:
                    prot_only = f"({self.loaded_object}) and polymer"
                    if cmd.count_atoms(prot_only) > 0:
                        cmd.show("cartoon", prot_only)
                        cmd.set("cartoon_color", "white", prot_only)
                        cmd.set("cartoon_transparency", 0.0, prot_only)
                        cmd.orient(prot_only)
                        cmd.zoom(prot_only, 8)
        except Exception:
            pass
        
        # Calculate SASA
        sasa_info = self._calc_sasa()
        msg_extra = ""
        if sasa_info:
            buried = float(sasa_info.get("buried", sasa_info.get("free", 0.0) - sasa_info.get("bound", 0.0)))
            buried_pct = float(sasa_info.get("buried_pct", sasa_info.get("buried_percent", 0.0)))
            msg_extra = (
                f"\n\nSASA (Ligand):\n"
                f"  Bound: {sasa_info['bound']:.1f} Å²\n"
                f"  Free:  {sasa_info['free']:.1f} Å²\n"
                f"  Buried: {buried:.1f} Å² ({buried_pct:.1f}%)"
            )
        if len(self.interactions) == 0 and self.ligand_info and self.loaded_object:
            try:
                l_c, l_i, l_n = self.ligand_info
                lig_sel = self._pymol_residue_selection(self.loaded_object, l_c, l_i, l_n, wrap=True)
                near6 = cmd.count_atoms(f"({self.loaded_object}) and polymer within 6.0 of ({lig_sel})")
                if near6 == 0:
                    msg_extra += (
                        "\n\nNo protein atoms are within 6.0 Å of the ligand in the current frame."
                        "\nIf this is a trajectory, try another frame or a re-imaged/restrained trajectory."
                    )
            except Exception:
                pass
        try:
            ref_frame = int(getattr(self, "_reference_frame", 1))
            if ref_frame > 1:
                msg_extra += f"\n\nReference frame used: {ref_frame}"
        except Exception:
            pass
        
        if hasattr(self, "show_2d_btn"):
             self.show_2d_btn.setEnabled(HAS_RDKIT_MPL)
             
        # --- VISUAL CORROBORATION (DEBUG LABELS) ---
        # Label ligand ionic atoms by coordinate-specific pseudoatoms.
        try:
            cmd.hide("labels")
            cmd.delete("ion_dbg_*")
        except Exception:
            pass
        for i, a in enumerate(self._cached_features.get("ligand_atoms", [])):
            lbl = []
            if a.get("is_anion"):
                lbl.append("ANION")
            if a.get("is_cation"):
                lbl.append("CATION")
            if not lbl:
                continue
            c = a.get("coord")
            if c is None:
                continue
            try:
                dbg = f"ion_dbg_{i}"
                cmd.pseudoatom(dbg, pos=[float(c[0]), float(c[1]), float(c[2])], label="+".join(lbl))
                cmd.set("label_color", "green", dbg)
                cmd.set("label_font_id", 2, dbg)
                cmd.hide("nonbonded", dbg)
            except Exception:
                continue
        
        try:
            poly_n = int(cmd.count_atoms(f"({self.loaded_object}) and polymer")) if self.loaded_object else 0
        except Exception:
            poly_n = -1
        try:
            poly_cartoon_n = int(cmd.count_atoms(f"({self.loaded_object}) and polymer and rep cartoon")) if self.loaded_object else 0
        except Exception:
            poly_cartoon_n = -1
        try:
            poly_lines_n = int(cmd.count_atoms(f"({self.loaded_object}) and polymer and rep lines")) if self.loaded_object else 0
        except Exception:
            poly_lines_n = -1
        try:
            l_c, l_i, l_n = self.ligand_info if self.ligand_info else ("", "", "")
            lig_n = (
                int(
                    cmd.count_atoms(
                        self._pymol_residue_selection(self.loaded_object, l_c, l_i, l_n, wrap=True)
                    )
                )
                if self.loaded_object
                else 0
            )
        except Exception:
            lig_n = -1
        try:
            state_id = int(cmd.get_state())
        except Exception:
            state_id = -1
        debug_info = (
            f"\n\nPlugin: {PLUGIN_VERSION} ({PLUGIN_BUILD})"
            f"\nModule: {__file__}"
            f"\nObject: {self.loaded_object}"
            f"\nState: {state_id}"
            f"\nPolymer atoms in object: {poly_n}"
            f"\nPolymer atoms shown as cartoon: {poly_cartoon_n}"
            f"\nPolymer atoms shown as lines: {poly_lines_n}"
            f"\nLigand atoms in object: {lig_n}"
        )
        QtWidgets.QMessageBox.information(
            self,
            "Done",
            f"Found {len(self.interactions)} interactions.{msg_extra}\n\nCheck 3D View: Labeled ANION/CATION atoms.{debug_info}",
        )
        # Ensure toggles reflect group visibility
        try:
            for t, cb in getattr(self, "_type_checkboxes", {}).items():
                self._on_type_toggle(t, cb.isChecked())
        except Exception:
            pass
        # persist ligand fields
        try:
            self._settings.update(
                {
                    "last_ligand_chain": self.ligand_info[0],
                    "last_ligand_resi": int(self.ligand_info[1]),
                    "last_ligand_resn": self.ligand_info[2],
                }
            )
            self._save_settings()
        except Exception:
            pass
