    def _openmm_gray_stylesheet(self):
        """Shared neutral style for OpenMM dialogs and subpanels."""
        return """
        QDialog { background: #f7f7f7; }
        QScrollArea { background: #f7f7f7; border: 0; }
        QWidget { color: #2f2f2f; }
        QGroupBox {
            background: #ffffff;
            border: 1px solid #d0d0d0;
            border-radius: 6px;
            margin-top: 12px;
            padding-top: 8px;
        }
        QGroupBox::title {
            subcontrol-origin: margin;
            left: 10px;
            padding: 0 4px;
            color: #2f2f2f;
            font-weight: 600;
        }
        QPushButton {
            background: #eeeeee;
            border: 1px solid #bdbdbd;
            border-radius: 4px;
            padding: 5px 10px;
        }
        QPushButton:hover { background: #e2e2e2; }
        QPushButton:pressed { background: #d6d6d6; }
        QLineEdit, QComboBox, QSpinBox, QDoubleSpinBox, QPlainTextEdit {
            background: #ffffff;
            border: 1px solid #c8c8c8;
            border-radius: 4px;
            padding: 3px;
        }
        QTableWidget {
            background: #ffffff;
            gridline-color: #dddddd;
            alternate-background-color: #f5f5f5;
            selection-background-color: #d9d9d9;
            selection-color: #1f1f1f;
        }
        """
    def _openmm_current_ligand_selection_text(self, obj_name=""):
        """Return a PyMOL selection for the active ligand when Leonardo knows one."""
        obj = str(obj_name or "").strip()
        try:
            lig = tuple(getattr(self, "ligand_info", None) or ())
        except Exception:
            lig = ()
        if len(lig) >= 3:
            chain = str(lig[0] or "").strip()
            resi = str(lig[1] or "").strip()
            resn = str(lig[2] or "").strip()
            parts = []
            if obj:
                parts.append(str(obj))
            if chain:
                parts.append(f"chain {chain}")
            if resi:
                parts.append(f"resi {resi}")
            if resn:
                parts.append(f"resn {resn}")
            if parts:
                return "(" + " and ".join(parts) + ")"
        if obj:
            return f"({obj} and organic)"
        return "(organic)"
    def _openmm_cv_context(self, obj_name=""):
        """
        Build placeholder values for built-in CV presets.

        PyMOL selections are still editable in the popup.  This helper only
        supplies sensible first guesses based on the currently selected object,
        ligand metadata, and any active selection named `sele`.
        """
        obj = str(obj_name or self._openmm_current_object() or "").strip()
        ligand_sel = self._openmm_current_ligand_selection_text(obj_name=obj)
        if obj:
            binding_site = f"({obj} and polymer within 6 of {ligand_sel})"
        else:
            binding_site = f"((polymer) within 6 of {ligand_sel})"
        try:
            active = str(self._openmm_current_pymol_selection() or "").strip()
        except Exception:
            active = ""
        return openmm_default_cv_context(
            object_name=obj,
            ligand_selection=ligand_sel,
            binding_site_selection=binding_site,
            active_selection=active,
        )
    def _openmm_selected_cv_preset_id(self):
        try:
            if hasattr(self, "cmb_openmm_cv_preset"):
                return str(self.cmb_openmm_cv_preset.currentData() or "protein_ligand_distance")
        except Exception:
            pass
        return str(getattr(self, "_openmm_cv_preset_id", "protein_ligand_distance") or "protein_ligand_distance")
    def _openmm_cv_from_selected_preset(self, workflow="umbrella", preset_id=None, obj_name=""):
        """Resolve the selected preset into a normalized CV dictionary."""
        pid = str(preset_id or self._openmm_selected_cv_preset_id() or "protein_ligand_distance")
        obj = str(obj_name or self._openmm_current_object() or "").strip()
        return apply_openmm_cv_preset(pid, context=self._openmm_cv_context(obj), workflow=workflow)
    def _openmm_update_cv_preset_summary(self):
        lbl = getattr(self, "lbl_openmm_cv_preset_summary", None)
        if lbl is None:
            return
        try:
            cv = self._openmm_cv_from_selected_preset(workflow="umbrella")
            lbl.setText(summarize_openmm_cv_definitions([cv]))
        except Exception as e:
            lbl.setText(f"CVs: preset unavailable ({e})")
