    def _openmm_create_panel_dialog(self, title, widgets):
        dlg = QtWidgets.QDialog(self)
        dlg.setWindowTitle(str(title or "OpenMM Panel"))
        dlg._leonardo_scroll_checked = True
        dlg.resize(1080, 880)
        dlg.setMinimumSize(920, 720)
        try:
            dlg.setStyleSheet(self._openmm_gray_stylesheet())
        except Exception:
            pass
        self._fit_dialog_to_screen(
            dlg,
            preferred_w=1080,
            preferred_h=880,
            min_w=900,
            min_h=700,
        )
        vbox = QtWidgets.QVBoxLayout(dlg)
        scroll = QtWidgets.QScrollArea(dlg)
        scroll.setObjectName("openmmPanelScrollArea")
        scroll.setProperty("leonardoVerticalOnly", True)
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QtWidgets.QFrame.NoFrame)
        scroll.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarAlwaysOff)
        scroll.setVerticalScrollBarPolicy(QtCore.Qt.ScrollBarAsNeeded)
        panel = QtWidgets.QWidget(scroll)
        panel_v = QtWidgets.QVBoxLayout(panel)
        for w in list(widgets or []):
            if w is not None:
                panel_v.addWidget(w)
        panel_v.addStretch(1)
        scroll.setWidget(panel)
        vbox.addWidget(scroll, 1)
        row = QtWidgets.QHBoxLayout()
        row.addStretch(1)
        btn_close = QtWidgets.QPushButton("Close")
        btn_close.clicked.connect(dlg.close)
        row.addWidget(btn_close)
        vbox.addLayout(row)
        return dlg
    def _update_openmm_tool_status(self):
        """Refresh OpenMM runtime status without requiring a simulation launch."""
        lbl = getattr(self, "lbl_openmm_tools", None)
        if lbl is None:
            return
        try:
            report = build_openmm_capability_report(OMM if HAS_OPENMM else None, OMM_APP if HAS_OPENMM else None)
            lbl.setText(str(report.get("message", "OpenMM status unavailable")))
        except Exception as e:
            lbl.setText(f"OpenMM status unavailable: {e}")
    def _openmm_show_panel_dialog(self, attr_name, refresh=False):
        try:
            if bool(refresh):
                self._refresh_openmm_object_combo()
                self._openmm_sync_xml_from_global()
                self._openmm_update_component_summary()
                self._openmm_update_ligand_status()
                self._update_openmm_tool_status()
            dlg = getattr(self, str(attr_name), None)
            if dlg is None:
                return
            self._fit_dialog_to_screen(
                dlg,
                preferred_w=980,
                preferred_h=760,
                min_w=620,
                min_h=420,
            )
            dlg.show()
            dlg.raise_()
            dlg.activateWindow()
        except Exception as e:
            QtWidgets.QMessageBox.warning(self, "OpenMM", f"Failed to open panel:\n{e}")
    def _show_openmm_system_panel(self):
        self._openmm_show_panel_dialog("_openmm_system_dialog", refresh=True)
    def _show_openmm_protocol_panel(self):
        self._openmm_show_panel_dialog("_openmm_protocol_dialog", refresh=False)
    def _show_openmm_analysis_panel(self):
        self._openmm_show_panel_dialog("_openmm_analysis_dialog", refresh=False)
    def _openmm_reset_minimization_energy_live_view(self, title="Minimization Energy"):
        self._openmm_min_energy_history = []
        try:
            self._openmm_min_energy_job_id = ""
        except Exception:
            pass
        lbl = getattr(self, "lbl_openmm_min_energy_status", None)
        if lbl is not None:
            try:
                lbl.setText("Live minimization energy: waiting for updates")
            except Exception:
                pass
        txt = getattr(self, "txt_openmm_min_energy_fallback", None)
        if txt is not None:
            try:
                txt.clear()
            except Exception:
                pass
        ax = getattr(self, "_openmm_min_energy_ax", None)
        canvas = getattr(self, "_openmm_min_energy_canvas", None)
        if ax is None or canvas is None:
            return
        try:
            ax.clear()
            ax.set_title(str(title or "Minimization Energy"))
            ax.set_xlabel("Iteration")
            ax.set_ylabel("Potential Energy (kJ/mol)")
            ax.grid(True, alpha=0.25)
            canvas.draw_idle()
        except Exception:
            pass
    def _openmm_append_minimization_energy_point(self, iteration, energy_kj_mol):
        try:
            it = int(iteration)
            e = float(energy_kj_mol)
        except Exception:
            return
        self._openmm_min_energy_history.append((it, e))
        self._openmm_min_energy_history = self._openmm_min_energy_history[-4000:]
        lbl = getattr(self, "lbl_openmm_min_energy_status", None)
        if lbl is not None:
            try:
                lbl.setText(f"Live minimization energy: iter={it} | E={e:.4f} kJ/mol")
            except Exception:
                pass
        txt = getattr(self, "txt_openmm_min_energy_fallback", None)
        if txt is not None:
            try:
                txt.appendPlainText(f"{it},{e:.6f}")
                sb = txt.verticalScrollBar()
                if sb is not None:
                    sb.setValue(sb.maximum())
            except Exception:
                pass
        ax = getattr(self, "_openmm_min_energy_ax", None)
        canvas = getattr(self, "_openmm_min_energy_canvas", None)
        if ax is None or canvas is None:
            return
        try:
            xs = [p[0] for p in self._openmm_min_energy_history]
            ys = [p[1] for p in self._openmm_min_energy_history]
            ax.clear()
            ax.plot(xs, ys, color="#1f77b4", linewidth=1.6)
            ax.scatter([xs[-1]], [ys[-1]], color="#d62728", s=22, zorder=5)
            ax.set_title("Minimization Energy")
            ax.set_xlabel("Iteration")
            ax.set_ylabel("Potential Energy (kJ/mol)")
            ax.grid(True, alpha=0.25)
            canvas.draw_idle()
        except Exception:
            pass
    def _openmm_update_minimization_live_visual(self, preview_pdb, object_name=""):
        p = str(preview_pdb or "").strip()
        if (not p) or (not os.path.isfile(p)):
            return
        now_ts = float(time.time())
        try:
            last_ts = float(self._openmm_min_live_last_update or 0.0)
        except Exception:
            last_ts = 0.0
        if (now_ts - last_ts) < 0.45:
            return
        self._openmm_min_live_last_update = now_ts
        live_obj = str(object_name or self._openmm_min_live_object or "").strip()
        if not live_obj:
            live_obj = "openmm_minimization_live"
        try:
            if self._pymol_object_exists(live_obj):
                try:
                    nst = int(cmd.count_states(live_obj))
                except Exception:
                    nst = 0
                cmd.load(p, live_obj, state=max(1, int(nst) + 1))
            else:
                cmd.load(p, live_obj, state=1)
                cmd.show("cartoon", f"({live_obj}) and polymer")
                self._apply_ball_and_stick_style(f"({live_obj}) and not polymer", sphere_scale=0.22, stick_radius=0.16)
            try:
                cmd.frame(int(max(1, cmd.count_states(live_obj))))
            except Exception:
                pass
            self._openmm_min_live_object = str(live_obj)
        except Exception as e:
            self._append_debug_log(f"OpenMM minimization live visualization warning: {e}")
    def _openmm_handle_runtime_progress(self, payload):
        if not isinstance(payload, dict):
            return
        msg = str(payload.get("message", "") or "").strip()
        if msg and hasattr(self, "lbl_openmm_status"):
            try:
                self.lbl_openmm_status.setText(f"OpenMM running: {msg}")
            except Exception:
                pass
        if msg and hasattr(self, "lbl_qmmm_status"):
            try:
                if isinstance(payload.get("qmmm_probe", None), dict) or ("QM/MM" in msg.upper()):
                    self.lbl_qmmm_status.setText(f"QM/MM running: {msg}")
            except Exception:
                pass
        is_min_only = bool(payload.get("minimize_only", False))
        if not is_min_only:
            return
        min_point = payload.get("minimization_point", None)
        if isinstance(min_point, dict):
            self._openmm_append_minimization_energy_point(
                min_point.get("iteration", 0),
                min_point.get("energy_kj_mol", 0.0),
            )
        preview_pdb = str(payload.get("minimization_preview_pdb", "") or "").strip()
        if preview_pdb:
            self._openmm_update_minimization_live_visual(
                preview_pdb=preview_pdb,
                object_name=str(payload.get("live_object", "") or ""),
            )
    def _openmm_current_pymol_selection(self):
        try:
            nat = int(cmd.count_atoms("sele"))
        except Exception:
            nat = 0
        if nat > 0:
            return "(sele)"
        return ""
    def _openmm_collect_object_atoms_for_picker(self, obj_name, max_atoms=120000):
        obj = str(obj_name or "").strip()
        if not obj:
            return []
        try:
            nat = int(cmd.count_atoms(f"({obj})"))
        except Exception:
            nat = 0
        if nat <= 0:
            return []
        max_keep = int(max(1000, max_atoms))
        sel = f"({obj})"
        truncated = False
        if nat > max_keep:
            sel = f"first {max_keep} of ({obj})"
            truncated = True
        rows = []
        space = {"rows": rows}
        try:
            cmd.iterate(
                sel,
                "rows.append((int(index),str(chain),str(resi),str(resn),str(name),str(elem)))",
                space=space,
            )
        except Exception:
            return []
        out = []
        for idx, ch, resi, resn, name, elem in rows:
            out.append(
                {
                    "index": int(idx),
                    "chain": str(ch or ""),
                    "resi": str(resi or ""),
                    "resn": str(resn or ""),
                    "name": str(name or ""),
                    "elem": str(elem or ""),
                }
            )
        return {
            "atoms": out,
            "total_atoms": int(nat),
            "truncated": bool(truncated),
            "max_atoms": int(max_keep),
        }
    def _openmm_prompt_selection_from_object(self, obj_name, title="Choose atoms for CV"):
        obj = str(obj_name or "").strip()
        if (not obj) or (not self._pymol_object_exists(obj)):
            QtWidgets.QMessageBox.warning(self, "OpenMM CV", "Select a valid structure object first.")
            return ""
        pack = self._openmm_collect_object_atoms_for_picker(obj)
        if not isinstance(pack, dict):
            pack = {}
        atoms = list(pack.get("atoms", []) or [])
        if not atoms:
            QtWidgets.QMessageBox.warning(self, "OpenMM CV", f"No atoms found in object '{obj}'.")
            return ""
        for a in atoms:
            a["search"] = " ".join(
                [
                    str(a.get("index", "")),
                    str(a.get("chain", "")),
                    str(a.get("resi", "")),
                    str(a.get("resn", "")),
                    str(a.get("name", "")),
                    str(a.get("elem", "")),
                ]
            ).lower()
        dlg = QtWidgets.QDialog(self)
        dlg.setWindowTitle(str(title or "Choose atoms"))
        dlg.resize(1020, 780)
        dlg.setMinimumSize(880, 660)
        self._fit_dialog_to_screen(dlg, preferred_w=1020, preferred_h=780, min_w=860, min_h=640)
        vbox = QtWidgets.QVBoxLayout(dlg)
        lbl_info = QtWidgets.QLabel(
            "Filter and select one or more atoms, then press Use Selection.\n"
            f"Object: {obj} | atoms: {int(pack.get('total_atoms', len(atoms)))}"
        )
        if bool(pack.get("truncated", False)):
            lbl_info.setText(
                lbl_info.text()
                + f"\nNote: showing first {int(pack.get('max_atoms', len(atoms)))} atoms only."
            )
        lbl_info.setWordWrap(True)
        vbox.addWidget(lbl_info)
        row_filter = QtWidgets.QHBoxLayout()
        row_filter.addWidget(QtWidgets.QLabel("Filter"))
        edit_filter = QtWidgets.QLineEdit()
        edit_filter.setPlaceholderText("chain A resi 100 name CA, LIG, etc.")
        row_filter.addWidget(edit_filter, 1)
        vbox.addLayout(row_filter)
        tbl = QtWidgets.QTableWidget(0, 6)
        tbl.setHorizontalHeaderLabels(["index", "chain", "resi", "resn", "name", "elem"])
        tbl.setSelectionBehavior(QtWidgets.QAbstractItemView.SelectRows)
        tbl.setSelectionMode(QtWidgets.QAbstractItemView.ExtendedSelection)
        tbl.setEditTriggers(QtWidgets.QAbstractItemView.NoEditTriggers)
        tbl.verticalHeader().setVisible(False)
        try:
            hdr = tbl.horizontalHeader()
            hdr.setSectionResizeMode(0, QtWidgets.QHeaderView.ResizeToContents)
            hdr.setSectionResizeMode(1, QtWidgets.QHeaderView.ResizeToContents)
            hdr.setSectionResizeMode(2, QtWidgets.QHeaderView.ResizeToContents)
            hdr.setSectionResizeMode(3, QtWidgets.QHeaderView.ResizeToContents)
            hdr.setSectionResizeMode(4, QtWidgets.QHeaderView.ResizeToContents)
            hdr.setSectionResizeMode(5, QtWidgets.QHeaderView.ResizeToContents)
        except Exception:
            pass
        vbox.addWidget(tbl, 1)
        lbl_count = QtWidgets.QLabel("")
        vbox.addWidget(lbl_count)
        shown_rows = []
        max_show = 5000
        def _refresh_table():
            q = str(edit_filter.text() or "").strip().lower()
            if q:
                filtered = [a for a in atoms if q in str(a.get("search", ""))]
            else:
                filtered = list(atoms)
            shown = filtered[:max_show]
            shown_rows.clear()
            shown_rows.extend(shown)
            tbl.setRowCount(0)
            for a in shown:
                r = int(tbl.rowCount())
                tbl.insertRow(r)
                vals = [
                    str(a.get("index", "")),
                    str(a.get("chain", "")),
                    str(a.get("resi", "")),
                    str(a.get("resn", "")),
                    str(a.get("name", "")),
                    str(a.get("elem", "")),
                ]
                for c, v in enumerate(vals):
                    it = QtWidgets.QTableWidgetItem(v)
                    tbl.setItem(r, c, it)
            extra = ""
            if len(filtered) > max_show:
                extra = f" (showing first {max_show})"
            lbl_count.setText(f"Rows: {len(filtered)}{extra}")
        edit_filter.textChanged.connect(_refresh_table)
        _refresh_table()
        row_btn = QtWidgets.QHBoxLayout()
        row_btn.addStretch(1)
        btn_use = QtWidgets.QPushButton("Use Selection")
        btn_cancel = QtWidgets.QPushButton("Cancel")
        row_btn.addWidget(btn_use)
        row_btn.addWidget(btn_cancel)
        vbox.addLayout(row_btn)
        holder = {"selection": ""}
        def _accept_selected():
            rows = sorted({int(ix.row()) for ix in tbl.selectionModel().selectedRows()})
            if not rows:
                QtWidgets.QMessageBox.information(self, "OpenMM CV", "Select at least one atom row.")
                return
            idxs = []
            for r in rows:
                if r < 0 or r >= len(shown_rows):
                    continue
                try:
                    idxs.append(int(shown_rows[r].get("index", 0)))
                except Exception:
                    pass
            idxs = sorted({i for i in idxs if i > 0})
            if not idxs:
                QtWidgets.QMessageBox.information(self, "OpenMM CV", "No valid atom indices selected.")
                return
            sel = f"({obj} and index {'+'.join(str(i) for i in idxs)})"
            holder["selection"] = sel
            dlg.accept()
        btn_use.clicked.connect(_accept_selected)
        btn_cancel.clicked.connect(dlg.reject)
        if dlg.exec_() != QtWidgets.QDialog.Accepted:
            return ""
        return str(holder.get("selection", "") or "")
    def _openmm_capture_selection_into_edit(self, edit_widget, fallback_text=""):
        if edit_widget is None:
            return
        sel = str(self._openmm_current_pymol_selection() or "").strip()
        if not sel:
            if fallback_text:
                sel = str(fallback_text)
            else:
                QtWidgets.QMessageBox.information(
                    self,
                    "OpenMM CV",
                    "No active PyMOL selection named 'sele'.\nSelect atoms first, then capture.",
                )
                return
        try:
            edit_widget.setText(sel)
        except Exception:
            pass
    def _openmm_insert_advanced_widget_full_width(self, dlg, widget):
        if dlg is None or widget is None:
            return
        layout = dlg.layout()
        if layout is None:
            return
        idx = max(0, int(layout.count()) - 2)
        try:
            layout.insertWidget(idx, widget)
        except Exception:
            try:
                layout.addWidget(widget)
            except Exception:
                pass
    def _openmm_add_advanced_object_picker(self, form, label="Structure object", default_obj=""):
        row_widget = QtWidgets.QWidget()
        row = QtWidgets.QHBoxLayout(row_widget)
        row.setContentsMargins(0, 0, 0, 0)
        row.setSpacing(6)
        cmb_obj = QtWidgets.QComboBox()
        cmb_obj.setEditable(True)
        row.addWidget(cmb_obj, 1)
        btn_refresh = QtWidgets.QPushButton("Refresh")
        row.addWidget(btn_refresh)
        form.addRow(str(label or "Structure object"), row_widget)
        seed = str(default_obj or self._openmm_current_object() or "").strip()
        def _refresh_obj_combo():
            names = list(self._candidate_structure_objects() or [])
            current_txt = str(cmb_obj.currentText() or "").strip()
            chosen = current_txt or seed
            cmb_obj.blockSignals(True)
            cmb_obj.clear()
            if names:
                cmb_obj.addItems(names)
            if chosen and chosen not in names:
                cmb_obj.addItem(chosen)
            if chosen:
                cmb_obj.setCurrentText(chosen)
            elif names:
                cmb_obj.setCurrentText(str(names[0]))
            cmb_obj.blockSignals(False)
        btn_refresh.clicked.connect(_refresh_obj_combo)
        _refresh_obj_combo()
        return cmb_obj
    def _show_openmm_dialog(self):
        try:
            self._refresh_openmm_object_combo()
            self._openmm_sync_xml_from_global()
            self._openmm_update_component_summary()
            self._openmm_update_ligand_status()
            self._update_openmm_tool_status()
            self._fit_dialog_to_screen(self._openmm_dialog)
            self._openmm_dialog.show()
            self._openmm_dialog.raise_()
            self._openmm_dialog.activateWindow()
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "Error", f"Failed to open OpenMM dialog: {e}")
