    def _qmmm_sync_from_openmm_defaults(self):
        try:
            self._refresh_openmm_object_combo()
        except Exception:
            pass
        try:
            if hasattr(self, "cmb_openmm_object") and hasattr(self, "cmb_qmmm_object"):
                obj = str(self.cmb_openmm_object.currentText() or "").strip()
                if obj:
                    self.cmb_qmmm_object.setCurrentText(obj)
        except Exception:
            pass
        try:
            if hasattr(self, "cmb_openmm_ff_family") and hasattr(self, "cmb_qmmm_ff"):
                ff = str(self.cmb_openmm_ff_family.currentData() or "").strip().lower()
                for i in range(int(self.cmb_qmmm_ff.count())):
                    if str(self.cmb_qmmm_ff.itemData(i) or "").strip().lower() == ff:
                        self.cmb_qmmm_ff.setCurrentIndex(i)
                        break
        except Exception:
            pass
        try:
            if hasattr(self, "cmb_openmm_solvent_mode") and hasattr(self, "cmb_qmmm_mode"):
                md = str(self.cmb_openmm_solvent_mode.currentData() or "").strip().lower()
                for i in range(int(self.cmb_qmmm_mode.count())):
                    if str(self.cmb_qmmm_mode.itemData(i) or "").strip().lower() == md:
                        self.cmb_qmmm_mode.setCurrentIndex(i)
                        break
        except Exception:
            pass
        try:
            if hasattr(self, "spin_openmm_ph") and hasattr(self, "spin_qmmm_ph"):
                self.spin_qmmm_ph.setValue(float(self.spin_openmm_ph.value()))
        except Exception:
            pass
    def _qmmm_refresh_object_combo(self):
        if not hasattr(self, "cmb_qmmm_object"):
            return
        try:
            current = str(self.cmb_qmmm_object.currentText() or "").strip()
            names = list(self._candidate_structure_objects() or [])
            self.cmb_qmmm_object.blockSignals(True)
            self.cmb_qmmm_object.clear()
            if names:
                self.cmb_qmmm_object.addItems(names)
            preferred = current if current in names else ""
            if not preferred:
                preferred = str(self._resolve_analysis_object(prefer_combo=True) or "").strip()
            if preferred and preferred not in names:
                self.cmb_qmmm_object.addItem(preferred)
            if preferred:
                self.cmb_qmmm_object.setCurrentText(preferred)
            elif names:
                self.cmb_qmmm_object.setCurrentText(str(names[0]))
            self.cmb_qmmm_object.blockSignals(False)
        except Exception as e:
            print(f"QM/MM object refresh warning: {e}")
    def _on_qmmm_use_analysis_object(self):
        obj = str(self._resolve_analysis_object(prefer_combo=True) or "").strip()
        if not obj:
            return
        try:
            self._qmmm_refresh_object_combo()
            self.cmb_qmmm_object.setCurrentText(obj)
        except Exception:
            pass
    def _on_qmmm_pick_selection_for_edit(self, edit_widget, title="Pick atoms"):
        if edit_widget is None:
            return
        obj = str(self.cmb_qmmm_object.currentText() or "").strip() if hasattr(self, "cmb_qmmm_object") else ""
        if (not obj) or (not self._pymol_object_exists(obj)):
            QtWidgets.QMessageBox.warning(self, "QM/MM", "Select a valid structure object first.")
            return
        sel = str(self._openmm_prompt_selection_from_object(obj, title=str(title or "Pick atoms")) or "").strip()
        if not sel:
            return
        try:
            edit_widget.setText(sel)
        except Exception:
            pass
    def _qmmm_operation_code(self):
        try:
            if hasattr(self, "cmb_qmmm_operation"):
                return str(self.cmb_qmmm_operation.currentData() or "probe").strip().lower()
        except Exception:
            pass
        return "probe"
    def _qmmm_recommended_keywords(self, op=None):
        key = str(op or self._qmmm_operation_code() or "probe").strip().lower()
        fallback = {
            "probe": "PM7 1SCF GRAD AUX QMMM",
            "single_point": "PM7 1SCF GRAD AUX QMMM",
            "electrostatic": "PM7 1SCF GRAD AUX QMMM",
            "optimization": "PM7 EF AUX QMMM",
            "opt": "PM7 EF AUX QMMM",
            "thermochemistry": "PM7 FORCE THERMO AUX QMMM",
            "thermo": "PM7 FORCE THERMO AUX QMMM",
            "reaction_scan": "PM7 1SCF GRAD AUX QMMM",
            "reaction_path": "PM7 1SCF GRAD AUX QMMM",
            "transition_state": "PM7 TS AUX QMMM",
            "mopac_qst2": "PM7 SADDLE AUX XYZ",
            "mopac_qst3": "PM7 TS AUX XYZ",
            "mopac_ts_frequency": "PM7 FORCE AUX XYZ",
            "mopac_irc": "PM7 FORCE IRC=1* AUX XYZ",
            "mopac_reaction_path": "PM7 AUX XYZ",
            "md_periodic": "PM7 1SCF GRAD AUX QMMM",
            "md_coupled": "PM7 1SCF GRAD AUX QMMM",
            "redock_rescore": "PM7 1SCF GRAD AUX QMMM",
        }
        try:
            mod = self._openmm_qmmm_runtime_mod()
            return str(mod.build_mopac_keywords_for_operation(operation=key, base_keywords="") or fallback.get(key, fallback["probe"]))
        except Exception:
            return str(fallback.get(key, fallback["probe"]))
    def _qmmm_apply_recommended_keywords(self):
        if not hasattr(self, "edit_qmmm_mopac_keywords"):
            return
        kw = str(self._qmmm_recommended_keywords(self._qmmm_operation_code()) or "").strip()
        self.edit_qmmm_mopac_keywords.setText(kw)
        self._qmmm_last_auto_keywords = str(kw)
