    def _show_qmmm_dialog(self):
        try:
            self._qmmm_sync_from_openmm_defaults()
            self._qmmm_refresh_object_combo()
            self._on_qmmm_operation_changed()
            self._fit_dialog_to_screen(self._qmmm_dialog)
            self._qmmm_dialog.show()
            self._qmmm_dialog.raise_()
            self._qmmm_dialog.activateWindow()
        except Exception as e:
            QtWidgets.QMessageBox.warning(self, "QM/MM", f"Failed to open QM/MM panel:\n{e}")
    def _qmmm_parse_indices_text(self, text):
        toks = re.split(r"[\s,;:]+", str(text or "").strip())
        out = []
        seen = set()
        for t in toks:
            if not t:
                continue
            try:
                i = int(t)
            except Exception:
                raise ValueError(f"Invalid atom index token: '{t}'")
            if i in seen:
                continue
            seen.add(i)
            out.append(i)
        return out
    def _qmmm_collect_probe_config(self):
        try:
            mode = str(self.cmb_qmmm_region_mode.currentData() or "auto_ligand_pocket")
        except Exception:
            mode = "auto_ligand_pocket"
        operation = self._qmmm_operation_code()
        exe = "mopac"
        kws = "PM7 1SCF GRAD AUX QMMM"
        charge = 0
        mult = 1
        dielectric = 1.0
        timeout_s = 180
        strict = False
        try:
            if hasattr(self, "edit_qmmm_mopac_exe"):
                exe = str(self.edit_qmmm_mopac_exe.text() or "mopac").strip()
        except Exception:
            exe = "mopac"
        try:
            if hasattr(self, "edit_qmmm_mopac_keywords"):
                kws = str(self.edit_qmmm_mopac_keywords.text() or kws).strip()
        except Exception:
            pass
        try:
            if hasattr(self, "spin_qmmm_charge"):
                charge = int(self.spin_qmmm_charge.value())
        except Exception:
            charge = 0
        try:
            if hasattr(self, "spin_qmmm_mult"):
                mult = int(self.spin_qmmm_mult.value())
        except Exception:
            mult = 1
        try:
            if hasattr(self, "spin_qmmm_dielectric"):
                dielectric = float(self.spin_qmmm_dielectric.value())
        except Exception:
            dielectric = 1.0
        try:
            if hasattr(self, "spin_qmmm_timeout"):
                timeout_s = int(self.spin_qmmm_timeout.value())
        except Exception:
            timeout_s = 180
        try:
            if hasattr(self, "cb_qmmm_strict"):
                strict = bool(self.cb_qmmm_strict.isChecked())
        except Exception:
            strict = False
        cfg = {
            "enabled": True,
            "mopac_executable": str(exe or "mopac").strip(),
            "mopac_keywords": str(kws or "PM7 1SCF GRAD AUX QMMM").strip(),
            "qm_total_charge": int(charge),
            "qm_multiplicity": int(max(1, mult)),
            "dielectric": float(max(1.0e-8, dielectric)),
            "timeout_s": int(max(1, timeout_s)),
            "strict": bool(strict),
            "operation": str(operation),
        }
        try:
            mod = self._openmm_qmmm_runtime_mod()
            cfg["mopac_keywords"] = str(
                mod.build_mopac_keywords_for_operation(
                    operation=str(operation),
                    base_keywords=str(cfg.get("mopac_keywords", "") or ""),
                )
            )
        except Exception:
            pass
        if not str(cfg.get("mopac_executable", "") or "").strip():
            return {"ok": False, "error": "MOPAC executable is required."}
        obj = str(self.cmb_qmmm_object.currentText() or "").strip() if hasattr(self, "cmb_qmmm_object") else ""
        if mode in ("auto_ligand", "auto_ligand_pocket"):
            cfg["auto_include_pocket"] = bool(mode == "auto_ligand_pocket")
            try:
                cfg["qm_pocket_cutoff_ang"] = float(self.spin_qmmm_qm_cutoff.value())
            except Exception:
                cfg["qm_pocket_cutoff_ang"] = 4.0
            try:
                cfg["max_qm_atoms"] = int(self.spin_qmmm_max_qm_atoms.value())
            except Exception:
                cfg["max_qm_atoms"] = 180
            try:
                cfg["include_metals"] = bool(self.cb_qmmm_include_metals.isChecked())
            except Exception:
                cfg["include_metals"] = True
        elif mode == "pymol_selection":
            raw_qm_sel = str(self.edit_qmmm_qm_selection.text() or "").strip() if hasattr(self, "edit_qmmm_qm_selection") else ""
            if not raw_qm_sel:
                return {"ok": False, "error": "QM PyMOL selection is required."}
            try:
                qm_atoms = list(self._qmmm_atom_descriptors_from_selection(obj, raw_qm_sel) or [])
            except Exception as e:
                return {"ok": False, "error": f"QM selection: {e}"}
            if not qm_atoms:
                return {"ok": False, "error": "QM selection matched no atoms."}
            cfg["qm_atom_descriptors"] = list(qm_atoms)
            cfg["qm_selection_expr"] = str(raw_qm_sel)
            raw_mm_sel = str(self.edit_qmmm_mm_selection.text() or "").strip() if hasattr(self, "edit_qmmm_mm_selection") else ""
            if raw_mm_sel:
                try:
                    mm_atoms = list(self._qmmm_atom_descriptors_from_selection(obj, raw_mm_sel) or [])
                except Exception as e:
                    return {"ok": False, "error": f"MM selection: {e}"}
                if not mm_atoms:
                    return {"ok": False, "error": "MM selection matched no atoms."}
                qm_keys = {
                    (
                        str(a.get("chain", "") or "").strip(),
                        str(a.get("resi", "") or "").strip(),
                        str(a.get("resn", "") or "").strip().upper(),
                        str(a.get("name", "") or "").strip(),
                    )
                    for a in qm_atoms
                }
                mm_keys = {
                    (
                        str(a.get("chain", "") or "").strip(),
                        str(a.get("resi", "") or "").strip(),
                        str(a.get("resn", "") or "").strip().upper(),
                        str(a.get("name", "") or "").strip(),
                    )
                    for a in mm_atoms
                }
                if qm_keys.intersection(mm_keys):
                    return {"ok": False, "error": "QM and MM PyMOL selections overlap. Remove the shared atoms or leave MM empty for complement mode."}
                cfg["mm_atom_descriptors"] = list(mm_atoms)
                cfg["mm_selection_expr"] = str(raw_mm_sel)
        elif mode == "qm_resnames":
            raw = str(self.edit_qmmm_qm_resnames.text() or "").strip() if hasattr(self, "edit_qmmm_qm_resnames") else ""
            names = [x.strip().upper() for x in re.split(r"[\s,;]+", raw) if x.strip()]
            if not names:
                return {"ok": False, "error": "Enter at least one QM residue name."}
            cfg["qm_resnames"] = list(dict.fromkeys(names))
        elif mode == "explicit_indices":
            raw_qm = str(self.edit_qmmm_qm_indices.text() or "").strip() if hasattr(self, "edit_qmmm_qm_indices") else ""
            if not raw_qm:
                return {"ok": False, "error": "QM atom indices are required in explicit mode."}
            try:
                cfg["qm_indices"] = list(self._qmmm_parse_indices_text(raw_qm))
            except Exception as e:
                return {"ok": False, "error": str(e)}
            raw_mm = str(self.edit_qmmm_mm_indices.text() or "").strip() if hasattr(self, "edit_qmmm_mm_indices") else ""
            if raw_mm:
                try:
                    cfg["mm_indices"] = list(self._qmmm_parse_indices_text(raw_mm))
                except Exception as e:
                    return {"ok": False, "error": f"MM indices: {e}"}
        op_params = dict(self._qmmm_get_operation_params(operation) or {})
        if operation == "reaction_path":
            # bonds formed / broken by the reaction: [[sel_a, sel_b], ...] -> atom descriptors, all forced into QM
            try:
                for key in ("form", "break"):
                    cfg[f"path_{key}_atoms"] = [
                        [dict(self._qmmm_first_atom_descriptor_from_selection(obj, str(a))),
                         dict(self._qmmm_first_atom_descriptor_from_selection(obj, str(b)))]
                        for a, b in list(op_params.get(f"{key}_bonds", []) or [])]
            except Exception as e:
                return {"ok": False, "error": str(e)}
            if not cfg["path_form_atoms"] and not cfg["path_break_atoms"]:
                return {"ok": False, "error": "A reaction path needs at least one bond that forms or breaks."}
            pairs = cfg["path_form_atoms"] + cfg["path_break_atoms"]
            forced = list(cfg.get("force_qm_atom_descriptors", []) or [])
            forced_res = list(cfg.get("force_qm_residue_keys", []) or [])
            for pair in pairs:
                for atom_desc in pair:
                    forced.append(dict(atom_desc))
                    forced_res.append({"chain": str(atom_desc.get("chain", "") or "").strip(),
                                       "resi": str(atom_desc.get("resi", "") or "").strip(),
                                       "resn": str(atom_desc.get("resn", "") or "").strip().upper()})
            cfg["force_qm_atom_descriptors"] = forced
            cfg["force_qm_residue_keys"] = forced_res
            cfg["path_n_images"] = int(op_params.get("n_images", 9) or 9)
        if operation == "reaction_scan":
            sel_a = str(op_params.get("sel_a", "") or "").strip()
            sel_b = str(op_params.get("sel_b", "") or "").strip()
            if not sel_a or not sel_b:
                return {"ok": False, "error": "Configure reaction scan atom selections first."}
            # optional third atom: transfer coordinate xi = d(A-B) - d(B-C) (B moves from A to C; SN2, proton
            # transfers), with the maximum refined to the transition state
            sel_c = str(op_params.get("sel_c", "") or "").strip()
            try:
                cfg["scan_atom_a"] = dict(self._qmmm_first_atom_descriptor_from_selection(obj, sel_a))
                cfg["scan_atom_b"] = dict(self._qmmm_first_atom_descriptor_from_selection(obj, sel_b))
                if sel_c:
                    cfg["scan_atom_c"] = dict(self._qmmm_first_atom_descriptor_from_selection(obj, sel_c))
                else:
                    cfg.pop("scan_atom_c", None)
            except Exception as e:
                return {"ok": False, "error": str(e)}
            scan_keys = ("scan_atom_a", "scan_atom_b") + (("scan_atom_c",) if sel_c else ())
            forced = list(cfg.get("force_qm_atom_descriptors", []) or [])
            for scan_key in scan_keys:
                forced.append(dict(cfg[scan_key]))
            cfg["force_qm_atom_descriptors"] = list(forced)
            forced_res = list(cfg.get("force_qm_residue_keys", []) or [])
            for scan_key in scan_keys:
                atom_desc = dict(cfg.get(scan_key, {}) or {})
                forced_res.append(
                    {
                        "chain": str(atom_desc.get("chain", "") or "").strip(),
                        "resi": str(atom_desc.get("resi", "") or "").strip(),
                        "resn": str(atom_desc.get("resn", "") or "").strip().upper(),
                    }
                )
            cfg["force_qm_residue_keys"] = list(forced_res)
            if (
                str(cfg["scan_atom_a"].get("chain", "") or "").strip() == str(cfg["scan_atom_b"].get("chain", "") or "").strip()
                and str(cfg["scan_atom_a"].get("resi", "") or "").strip() == str(cfg["scan_atom_b"].get("resi", "") or "").strip()
                and str(cfg["scan_atom_a"].get("resn", "") or "").strip().upper() == str(cfg["scan_atom_b"].get("resn", "") or "").strip().upper()
                and str(cfg["scan_atom_a"].get("name", "") or "").strip() == str(cfg["scan_atom_b"].get("name", "") or "").strip()
            ):
                return {"ok": False, "error": "Reaction scan atom A and atom B must be different atoms."}
            start_ang = float(op_params.get("start_ang", 1.2))
            end_ang = float(op_params.get("end_ang", 2.8))
            if (not np.isfinite(start_ang)) or (not np.isfinite(end_ang)):
                return {"ok": False, "error": "Reaction scan start and end must be finite numbers."}
            # a distance scan needs positive distances; the transfer coordinate xi = d(A-B) - d(B-C) (third atom)
            # is negative on the reactant side
            if (not sel_c) and (start_ang <= 0.0 or end_ang <= 0.0):
                return {"ok": False, "error": "Reaction scan distances must be positive finite numbers."}
            if abs(start_ang - end_ang) < 1.0e-8:
                return {"ok": False, "error": "Reaction scan start and end distances must differ."}
            cfg["scan_start_ang"] = float(min(start_ang, end_ang))
            cfg["scan_end_ang"] = float(max(start_ang, end_ang))
            cfg["scan_n_points"] = int(max(3, int(op_params.get("n_points", 9))))
            cfg["scan_selection_a"] = str(sel_a)
            cfg["scan_selection_b"] = str(sel_b)
        elif operation == "md_periodic":
            cfg["probe_interval_steps"] = int(max(50, int(op_params.get("interval_steps", 1000))))
        elif operation == "md_coupled":
            cfg["force_update_interval"] = int(max(1, int(op_params.get("force_update_interval", 1))))
        return {"ok": True, "config": cfg}
    def _qmmm_direct_mopac_reaction_operations(self):
        return {"mopac_qst2", "mopac_qst3", "mopac_ts_frequency", "mopac_irc", "mopac_reaction_path"}
    def _qmmm_atoms_from_object_indices_for_mopac(self, obj_name, indices):
        obj = str(obj_name or "").strip()
        rows, _bonds = self._qmmm_pymol_atom_rows_and_bonds(obj)
        by_idx = {int(row.get("index")): dict(row) for row in list(rows or [])}
        atoms = []
        missing = []
        for idx in [int(i) for i in list(indices or [])]:
            row = by_idx.get(int(idx))
            if row is None:
                missing.append(int(idx))
                continue
            atoms.append(
                {
                    "element": str(row.get("element", "C") or "C"),
                    "name": str(row.get("name", "") or ""),
                    "resn": str(row.get("resn", "") or ""),
                    "chain": str(row.get("chain", "") or ""),
                    "resi": str(row.get("resi", "") or ""),
                    "x": float(row.get("x", 0.0)),
                    "y": float(row.get("y", 0.0)),
                    "z": float(row.get("z", 0.0)),
                }
            )
        if missing:
            raise ValueError(f"Object '{obj}' is missing selected atom indices: {missing[:8]}")
        if not atoms:
            raise ValueError(f"No atoms were selected from object '{obj}'.")
        return atoms
    def _qmmm_selected_indices_for_direct_mopac(self, obj_name, operation):
        obj = str(obj_name or "").strip()
        rows, bonds = self._qmmm_pymol_atom_rows_and_bonds(obj)
        if not rows:
            return {"ok": False, "error": "No atoms were found in the selected object."}
        try:
            mode = str(self.cmb_qmmm_region_mode.currentData() or "auto_ligand_pocket")
        except Exception:
            mode = "auto_ligand_pocket"
        if mode in ("auto_ligand", "auto_ligand_pocket"):
            try:
                mod = self._qmmm_mopac_runtime_mod()
                rec = dict(
                    mod.qmmm_recommend_region(
                        atom_rows=rows,
                        operation=str(operation),
                        ligand_resnames=[],
                        qm_pocket_cutoff_ang=float(self.spin_qmmm_qm_cutoff.value()) if hasattr(self, "spin_qmmm_qm_cutoff") else 4.0,
                        include_pocket=bool(mode == "auto_ligand_pocket"),
                        include_metals=bool(self.cb_qmmm_include_metals.isChecked()) if hasattr(self, "cb_qmmm_include_metals") else True,
                        max_qm_atoms=int(self.spin_qmmm_max_qm_atoms.value()) if hasattr(self, "spin_qmmm_max_qm_atoms") else 180,
                    )
                    or {}
                )
            except Exception as e:
                return {"ok": False, "error": f"Automatic QM region failed: {e}"}
            if not bool(rec.get("ok", False)):
                return {"ok": False, "error": str(rec.get("error", "Automatic QM region failed."))}
            return {
                "ok": True,
                "indices": list(rec.get("qm_indices", []) or []),
                "selection_hint": str(rec.get("selection_hint", "") or "automatic QM region"),
                "region": rec,
            }
        if mode == "pymol_selection":
            raw_qm_sel = str(self.edit_qmmm_qm_selection.text() or "").strip() if hasattr(self, "edit_qmmm_qm_selection") else ""
            if not raw_qm_sel:
                return {"ok": False, "error": "QM PyMOL selection is required."}
            pidx = []
            space = {"pidx": pidx}
            try:
                cmd.iterate(f"({obj}) and ({raw_qm_sel})", "pidx.append(int(index))", space=space)
            except Exception as e:
                return {"ok": False, "error": f"QM selection failed: {e}"}
            pset = {int(x) for x in pidx}
            indices = [int(row.get("index")) for row in rows if int(row.get("pymol_index", -1)) in pset]
            return {"ok": bool(indices), "indices": indices, "selection_hint": str(raw_qm_sel), "region": {"bonds": bonds}}
        if mode == "qm_resnames":
            raw = str(self.edit_qmmm_qm_resnames.text() or "").strip() if hasattr(self, "edit_qmmm_qm_resnames") else ""
            names = {x.strip().upper() for x in re.split(r"[\s,;]+", raw) if x.strip()}
            if not names:
                return {"ok": False, "error": "Enter at least one QM residue name."}
            indices = [int(row.get("index")) for row in rows if str(row.get("resn", "") or "").strip().upper() in names]
            return {"ok": bool(indices), "indices": indices, "selection_hint": ",".join(sorted(names)), "region": {"bonds": bonds}}
        if mode == "explicit_indices":
            raw_qm = str(self.edit_qmmm_qm_indices.text() or "").strip() if hasattr(self, "edit_qmmm_qm_indices") else ""
            if not raw_qm:
                return {"ok": False, "error": "QM atom indices are required in explicit mode."}
            try:
                indices = list(self._qmmm_parse_indices_text(raw_qm))
            except Exception as e:
                return {"ok": False, "error": str(e)}
            return {"ok": bool(indices), "indices": indices, "selection_hint": "explicit atom indices", "region": {"bonds": bonds}}
        return {"ok": False, "error": f"Unsupported region mode for MOPAC reaction workflow: {mode}"}
    def _qmmm_collect_mopac_reaction_payload(self, operation):
        obj = str(self.cmb_qmmm_object.currentText() or "").strip() if hasattr(self, "cmb_qmmm_object") else ""
        if (not obj) or (not self._pymol_object_exists(obj)):
            return {"ok": False, "error": "Select a valid reactant/TS object for the MOPAC reaction workflow."}
        cfg_pack = self._qmmm_collect_probe_config()
        if not bool(cfg_pack.get("ok", False)):
            return cfg_pack
        cfg = dict(cfg_pack.get("config", {}) or {})
        sel_pack = self._qmmm_selected_indices_for_direct_mopac(obj, operation)
        if not bool(sel_pack.get("ok", False)):
            return {"ok": False, "error": str(sel_pack.get("error", "Could not resolve selected atoms."))}
        indices = [int(i) for i in list(sel_pack.get("indices", []) or [])]
        try:
            reactant_atoms = self._qmmm_atoms_from_object_indices_for_mopac(obj, indices)
        except Exception as e:
            return {"ok": False, "error": str(e)}
        params = dict(self._qmmm_get_operation_params(operation) or {})
        product_atoms = None
        product_obj = str(params.get("product_object", "") or "").strip()
        if operation in {"mopac_qst2", "mopac_qst3", "mopac_reaction_path"}:
            if (not product_obj) or (not self._pymol_object_exists(product_obj)):
                return {"ok": False, "error": "Configure a valid product object with the same atom order as the reactant."}
            try:
                product_atoms = self._qmmm_atoms_from_object_indices_for_mopac(product_obj, indices)
            except Exception as e:
                return {"ok": False, "error": f"Product object: {e}"}
        ts_guess_atoms = None
        ts_guess_obj = str(params.get("ts_guess_object", "") or "").strip()
        if ts_guess_obj:
            if not self._pymol_object_exists(ts_guess_obj):
                return {"ok": False, "error": "Configured TS guess object does not exist."}
            try:
                ts_guess_atoms = self._qmmm_atoms_from_object_indices_for_mopac(ts_guess_obj, indices)
            except Exception as e:
                return {"ok": False, "error": f"TS guess object: {e}"}
        if operation == "mopac_qst3" and not ts_guess_atoms:
            return {"ok": False, "error": "MOPAC QST3 requires a TS guess object."}
        safe = self._dock_safe_obj_name(obj) if hasattr(self, "_dock_safe_obj_name") else re.sub(r"[^A-Za-z0-9_.-]+", "_", obj)
        job_dir = tempfile.mkdtemp(prefix=f"leonardo_mopac_reaction_{safe}_")
        payload = {
            "ok": True,
            "mopac_reaction_job": True,
            "qmmm_operation": str(operation),
            "object_name": str(obj),
            "product_object": str(product_obj),
            "ts_guess_object": str(ts_guess_obj),
            "job_dir": str(job_dir),
            "reactant_atoms": list(reactant_atoms),
            "product_atoms": list(product_atoms or []),
            "ts_guess_atoms": list(ts_guess_atoms or []),
            "selected_indices": list(indices),
            "selection_hint": str(sel_pack.get("selection_hint", "") or ""),
            "qmmm_probe": dict(cfg),
            "mopac_reaction_params": dict(params),
        }
        return {"ok": True, "payload": payload}
    def _qmmm_collect_run_payload(self):
        operation = self._qmmm_operation_code()
        if operation in self._qmmm_direct_mopac_reaction_operations():
            return self._qmmm_collect_mopac_reaction_payload(operation)
        if not HAS_OPENMM or OMM is None or OMM_APP is None or OMM_UNIT is None:
            return {"ok": False, "error": "OpenMM is not available in this environment."}
        obj = str(self.cmb_qmmm_object.currentText() or "").strip() if hasattr(self, "cmb_qmmm_object") else ""
        if (not obj) or (not self._pymol_object_exists(obj)):
            return {"ok": False, "error": "Select a valid structure object for QM/MM."}
        cfg_pack = self._qmmm_collect_probe_config()
        if not bool(cfg_pack.get("ok", False)):
            return cfg_pack
        try:
            self._refresh_openmm_object_combo()
            if hasattr(self, "cmb_openmm_object"):
                self.cmb_openmm_object.setCurrentText(obj)
        except Exception:
            pass
        payload = dict(self._collect_openmm_run_payload(minimize_only=bool(operation not in ("md_periodic", "md_coupled"))) or {})
        if not bool(payload.get("ok", False)):
            return payload
        ff_family = str(self.cmb_qmmm_ff.currentData() or payload.get("ff_family", "amber14")).strip().lower() if hasattr(self, "cmb_qmmm_ff") else str(payload.get("ff_family", "amber14")).strip().lower()
        mode = str(self.cmb_qmmm_mode.currentData() or payload.get("mode", "gas")).strip().lower() if hasattr(self, "cmb_qmmm_mode") else str(payload.get("mode", "gas")).strip().lower()
        ph = float(self.spin_qmmm_ph.value()) if hasattr(self, "spin_qmmm_ph") else float(payload.get("ph", 7.4))
        payload.update({"object_name": str(obj), "ff_family": str(ff_family), "mode": str(mode), "ph": float(ph)})
        probe_cfg = dict(cfg_pack.get("config", {}) or {})
        payload["qmmm_probe"] = dict(probe_cfg)
        payload["qmmm_operation"] = str(operation)
        if operation == "md_periodic":
            mdp = dict(self._qmmm_get_operation_params(operation) or {})
            payload["qmmm_probe_only"] = False
            payload["qmmm_pose_state_rescore"] = False
            payload["qmmm_force_coupled"] = False
            payload["minimize_only"] = False
            payload["run_min"] = bool(mdp.get("run_min", True))
            payload["run_heat"] = bool(mdp.get("run_heat", True))
            payload["run_equil"] = bool(mdp.get("run_equil", True))
            payload["run_prod"] = bool(mdp.get("run_prod", True))
            payload["min_iters"] = int(max(0, int(mdp.get("min_iters", payload.get("min_iters", 2000)))))
            payload["heat_steps"] = int(max(0, int(mdp.get("heat_steps", payload.get("heat_steps", 5000)))))
            payload["equil_steps"] = int(max(0, int(mdp.get("equil_steps", payload.get("equil_steps", 20000)))))
            payload["prod_steps"] = int(max(0, int(mdp.get("prod_steps", payload.get("prod_steps", 100000)))))
            if not bool(payload.get("run_prod", False)):
                return {"ok": False, "error": "MD periodic mode requires production stage enabled."}
        elif operation == "md_coupled":
            mdp = dict(self._qmmm_get_operation_params(operation) or {})
            payload["qmmm_probe_only"] = False
            payload["qmmm_pose_state_rescore"] = False
            payload["qmmm_force_coupled"] = True
            payload["qmmm_force_update_interval"] = int(max(1, int(mdp.get("force_update_interval", 1))))
            payload["minimize_only"] = False
            payload["run_min"] = bool(mdp.get("run_min", True))
            payload["run_heat"] = bool(mdp.get("run_heat", True))
            payload["run_equil"] = bool(mdp.get("run_equil", True))
            payload["run_prod"] = bool(mdp.get("run_prod", True))
            payload["min_iters"] = int(max(0, int(mdp.get("min_iters", payload.get("min_iters", 2000)))))
            payload["heat_steps"] = int(max(0, int(mdp.get("heat_steps", payload.get("heat_steps", 5000)))))
            payload["equil_steps"] = int(max(0, int(mdp.get("equil_steps", payload.get("equil_steps", 20000)))))
            payload["prod_steps"] = int(max(0, int(mdp.get("prod_steps", payload.get("prod_steps", 100000)))))
            if not (bool(payload.get("run_heat", False)) or bool(payload.get("run_equil", False)) or bool(payload.get("run_prod", False))):
                return {"ok": False, "error": "Force-coupled QM/MM MD requires at least one dynamics stage (heat/equil/prod)."}
        elif operation == "redock_rescore":
            try:
                nst = int(max(1, int(cmd.count_states(obj))))
            except Exception:
                nst = 1
            rs = dict(self._qmmm_get_operation_params(operation) or {})
            max_states = int(max(1, int(rs.get("max_states", 50))))
            n_pick = int(min(nst, max_states))
            pose_dir = os.path.join(str(payload.get("job_dir", "") or ""), "pose_states")
            try:
                os.makedirs(pose_dir, exist_ok=True)
            except Exception:
                pass
            inputs = []
            for st in range(1, n_pick + 1):
                pdb_state = os.path.join(pose_dir, f"{self._dock_safe_obj_name(obj)}_state_{st:04d}.pdb")
                try:
                    cmd.save(pdb_state, f"({obj})", state=int(st), format="pdb")
                except Exception as e:
                    return {"ok": False, "error": f"Could not export state {st}: {e}"}
                if not os.path.isfile(pdb_state):
                    return {"ok": False, "error": f"Missing exported PDB for state {st}."}
                inputs.append({"state": int(st), "input_pdb": str(pdb_state)})
            if not inputs:
                return {"ok": False, "error": "No pose states found for rescoring."}
            payload["qmmm_probe_only"] = True
            payload["qmmm_pose_state_rescore"] = True
            payload["qmmm_pose_strict"] = bool(rs.get("strict_per_pose", False))
            payload["pose_state_inputs"] = list(inputs)
            payload["run_min"] = True
            payload["min_iters"] = 0
            payload["run_heat"] = False
            payload["run_equil"] = False
            payload["run_prod"] = False
            payload["minimize_only"] = True
            payload["result_object"] = ""
        else:
            payload.update(
                {
                    "run_min": True,
                    "min_iters": 0,
                    "run_heat": False,
                    "run_equil": False,
                    "run_prod": False,
                    "minimize_only": True,
                    "qmmm_probe_only": True,
                    "qmmm_pose_state_rescore": False,
                    "qmmm_force_coupled": False,
                }
            )
        return {"ok": True, "payload": payload}
    def _on_qmmm_run_probe(self):
        pack = self._qmmm_collect_run_payload()
        if not bool(pack.get("ok", False)):
            QtWidgets.QMessageBox.warning(self, "QM/MM", str(pack.get("error", "QM/MM setup failed.")))
            return
        payload = dict(pack.get("payload", {}) or {})
        obj = str(payload.get("object_name", "") or "")
        mode = str(payload.get("mode", "") or "")
        ff = str(payload.get("ff_family", "") or "")
        op = str(payload.get("qmmm_operation", self._qmmm_operation_code()) or self._qmmm_operation_code())
        if hasattr(self, "lbl_qmmm_status"):
            self.lbl_qmmm_status.setText(
                f"QM/MM job queued in background | operation={op} | object={obj} | mode={mode} | ff={ff}"
            )
        try:
            if hasattr(self, "btn_qmmm_run_probe"):
                self.btn_qmmm_run_probe.setEnabled(False)
        except Exception:
            pass
        self._append_debug_log(
            f"QM/MM job queued: operation={op}, object={obj}, mode={mode}, ff={ff}, job_dir={payload.get('job_dir','')}"
        )
        def _job(progress_cb):
            if bool(payload.get("mopac_reaction_job", False)):
                return self._run_mopac_reaction_worker(payload, progress_cb=progress_cb)
            if bool(payload.get("qmmm_pose_state_rescore", False)):
                return self._run_qmmm_pose_state_rescore_worker(payload, progress_cb=progress_cb)
            return self._run_openmm_worker_job(payload, progress_cb=progress_cb)
        def _on_success(result_payload):
            self._qmmm_last_probe_result = dict(result_payload or {})
            self._openmm_finalize_worker_result(payload, result_payload)
        def _on_error(err_text):
            msg = str(err_text or "").strip()
            if hasattr(self, "lbl_qmmm_status"):
                self.lbl_qmmm_status.setText(f"QM/MM probe failed: {msg[:300]}")
            QtWidgets.QMessageBox.warning(self, "QM/MM", f"QM/MM background task failed:\n{msg[:3000]}")
        def _on_finished():
            try:
                if hasattr(self, "btn_qmmm_run_probe"):
                    self.btn_qmmm_run_probe.setEnabled(True)
            except Exception:
                pass
        self._submit_monitored_background_task(
            _job,
            tool_label="QM/MM",
            task_label=f"{op} {obj}",
            on_success=_on_success,
            on_error=_on_error,
            on_finished=_on_finished,
            on_progress=self._openmm_handle_runtime_progress,
            with_progress=True,
            job_dir=str(payload.get("job_dir", "") or ""),
        )
    def _run_mopac_reaction_worker(self, payload, progress_cb=None):
        data = dict(payload or {})
        out = {
            "ok": False,
            "operation": str(data.get("qmmm_operation", "mopac_reaction_path") or "mopac_reaction_path"),
            "job_dir": str(data.get("job_dir", "") or ""),
            "error": "",
        }
        def _emit(progress, message="", status="Running", extra=None):
            if callable(progress_cb):
                try:
                    msg = {
                        "progress": float(progress),
                        "message": str(message or ""),
                        "status": str(status or "Running"),
                        "job_dir": str(out.get("job_dir", "") or ""),
                    }
                    if isinstance(extra, dict):
                        msg.update(extra)
                    progress_cb(msg)
                except Exception:
                    pass
        try:
            _emit(5, "Preparing MOPAC reaction workflow")
            mod = self._qmmm_mopac_runtime_mod()
            cfg = dict(data.get("qmmm_probe", {}) or {})
            params = dict(data.get("mopac_reaction_params", {}) or {})
            op = str(data.get("qmmm_operation", "mopac_reaction_path") or "mopac_reaction_path")
            _emit(15, f"Running {op} with MOPAC")
            res = dict(
                mod.run_mopac_reaction_workflow(
                    reactant_atoms=list(data.get("reactant_atoms", []) or []),
                    product_atoms=list(data.get("product_atoms", []) or []) or None,
                    ts_guess_atoms=list(data.get("ts_guess_atoms", []) or []) or None,
                    operation=str(op),
                    base_keywords=str(cfg.get("mopac_keywords", "") or ""),
                    charge=int(cfg.get("qm_total_charge", 0) or 0),
                    multiplicity=int(max(1, int(cfg.get("qm_multiplicity", 1) or 1))),
                    mopac_executable=str(cfg.get("mopac_executable", "mopac") or "mopac"),
                    workdir=str(out.get("job_dir", "") or ""),
                    timeout_s=int(max(1, int(cfg.get("timeout_s", 3600) or 3600))),
                    use_forcets=bool(params.get("use_forcets", False)),
                    irc_direction=str(params.get("irc_direction", "both") or "both"),
                    irc_x_priority_ang=float(params.get("irc_x_priority_ang", 0.05) or 0.05),
                    irc_max_points=int(max(2, int(params.get("irc_max_points", 25) or 25))),
                    frequency_threshold_cm=float(params.get("frequency_threshold_cm", 10.0) or 10.0),
                )
                or {}
            )
            res["job_dir"] = str(out.get("job_dir", res.get("workdir", "")) or "")
            _emit(100, "MOPAC reaction workflow completed" if bool(res.get("ok", False)) else "MOPAC reaction workflow finished with warnings", status="Completed" if bool(res.get("ok", False)) else "Failed")
            return res
        except Exception as e:
            out["error"] = str(e)
            _emit(100, f"MOPAC reaction workflow failed: {e}", status="Failed")
            return out
    def _run_qmmm_pose_state_rescore_worker(self, payload, progress_cb=None):
        data = dict(payload or {})
        out = {
            "ok": False,
            "error": "",
            "operation": "redock_rescore",
            "job_dir": str(data.get("job_dir", "") or ""),
            "rows": [],
            "csv_path": "",
            "best_state": None,
        }
        inputs = list(data.get("pose_state_inputs", []) or [])
        if not inputs:
            out["error"] = "No pose states provided for QM/MM rescoring."
            return out
        strict_pose = bool(data.get("qmmm_pose_strict", False))
        n_total = len(inputs)
        rows = []
        def _emit(progress, message="", status="Running", extra=None):
            if callable(progress_cb):
                try:
                    payload_emit = {
                        "progress": float(progress),
                        "message": str(message or ""),
                        "status": str(status or "Running"),
                        "job_dir": str(out.get("job_dir", "") or ""),
                    }
                    if isinstance(extra, dict):
                        payload_emit.update(extra)
                    progress_cb(payload_emit)
                except Exception:
                    pass
        for i, item in enumerate(inputs, start=1):
            st = int(item.get("state", i))
            p_pdb = str(item.get("input_pdb", "") or "").strip()
            one = dict(data)
            one["input_pdb"] = str(p_pdb)
            one["qmmm_pose_state_rescore"] = False
            one["qmmm_probe_only"] = True
            one["run_min"] = True
            one["min_iters"] = 0
            one["run_heat"] = False
            one["run_equil"] = False
            one["run_prod"] = False
            try:
                _emit(5.0 + 90.0 * (float(i - 1) / float(max(1, n_total))), f"QM/MM rescoring state {st}/{n_total}")
                res = dict(self._run_openmm_worker_job(one, progress_cb=None) or {})
            except Exception as e:
                res = {"ok": False, "error": str(e)}
            qprobe = dict(res.get("qmmm_probe", {}) or {})
            qdict = dict(qprobe.get("qmmm", {}) or {})
            diag = dict(qprobe.get("diagnostics", {}) or {})
            row = {
                "state": int(st),
                "ok": bool(res.get("ok", False) and qprobe.get("ok", False)),
                "error": str(res.get("error", "") or qprobe.get("error", "") or ""),
                "energy_qm_hartree": float(qdict.get("energy_qm_hartree", np.nan)),
                "energy_qmmm_elec_kj_mol": float(qdict.get("energy_qmmm_elec_kj_mol", np.nan)),
                "third_law_ok": bool(diag.get("third_law_ok", False)),
                "input_pdb": str(p_pdb),
                "probe_workdir": str(qdict.get("workdir", "") or ""),
            }
            rows.append(row)
            if strict_pose and (not row["ok"]):
                out["error"] = f"State {st} failed in strict mode: {row['error']}"
                out["rows"] = list(rows)
                return out
        out["rows"] = list(rows)
        best = None
        for r in rows:
            if not bool(r.get("ok", False)):
                continue
            if best is None:
                best = r
                continue
            try:
                if float(r.get("energy_qm_hartree", np.nan)) < float(best.get("energy_qm_hartree", np.nan)):
                    best = r
            except Exception:
                pass
        out["best_state"] = int(best.get("state")) if isinstance(best, dict) else None
        csvf = os.path.join(str(out.get("job_dir", "") or ""), "qmmm_pose_rescore_summary.csv")
        try:
            with open(csvf, "w", encoding="utf-8") as fh:
                fh.write("state,ok,energy_qm_hartree,energy_qmmm_elec_kj_mol,third_law_ok,error,input_pdb,probe_workdir\n")
                for r in rows:
                    err_txt = str(r.get("error", "") or "").replace('"', '""')
                    inp_txt = str(r.get("input_pdb", "") or "").replace('"', '""')
                    wd_txt = str(r.get("probe_workdir", "") or "").replace('"', '""')
                    fh.write(
                        f"{int(r.get('state',0))},{int(bool(r.get('ok',False)))},"
                        f"{float(r.get('energy_qm_hartree', np.nan)):.10f},"
                        f"{float(r.get('energy_qmmm_elec_kj_mol', np.nan)):.6f},"
                        f"{int(bool(r.get('third_law_ok', False)))},"
                        f"\"{err_txt}\","
                        f"\"{inp_txt}\","
                        f"\"{wd_txt}\"\n"
                    )
            out["csv_path"] = str(csvf)
        except Exception:
            out["csv_path"] = ""
        out["ok"] = True
        _emit(100, "QM/MM pose rescoring completed", status="Completed")
        return out
    def _openmm_workspace_dir(self):
        root = os.path.join(self._dock_workspace_dir(), "openmm")
        try:
            os.makedirs(root, exist_ok=True)
        except Exception:
            pass
        return root
    def _openmm_current_object(self):
        obj = ""
        try:
            if hasattr(self, "cmb_openmm_object"):
                obj = str(self.cmb_openmm_object.currentText() or "").strip()
        except Exception:
            obj = ""
        if obj:
            return obj
        try:
            obj = str(self._resolve_analysis_object(prefer_combo=True) or "").strip()
        except Exception:
            obj = ""
        return obj
    def _refresh_openmm_object_combo(self):
        if not hasattr(self, "cmb_openmm_object"):
            return
        try:
            current = str(self.cmb_openmm_object.currentText() or "").strip()
            names = self._candidate_structure_objects()
            self.cmb_openmm_object.blockSignals(True)
            self.cmb_openmm_object.clear()
            self.cmb_openmm_object.addItems(names)
            preferred = ""
            if current in names:
                preferred = current
            else:
                obj = self._openmm_current_object()
                if obj in names:
                    preferred = obj
                elif names:
                    preferred = names[0]
            if preferred:
                self.cmb_openmm_object.setCurrentText(preferred)
            self.cmb_openmm_object.blockSignals(False)
        except Exception as e:
            print(f"OpenMM object refresh warning: {e}")
    def _on_openmm_object_changed(self, _obj_name):
        self._openmm_update_component_summary()
        self._openmm_update_ligand_status()
    def _on_openmm_use_analysis_object(self):
        obj = str(self._resolve_analysis_object(prefer_combo=True) or "").strip()
        if not obj:
            return
        self._refresh_openmm_object_combo()
        try:
            if hasattr(self, "cmb_openmm_object"):
                self.cmb_openmm_object.setCurrentText(obj)
        except Exception:
            pass
        try:
            if hasattr(self, "cmb_qmmm_object"):
                self._qmmm_refresh_object_combo()
                self.cmb_qmmm_object.setCurrentText(obj)
        except Exception:
            pass
        self._openmm_update_component_summary()
        self._openmm_update_ligand_status()
    def _openmm_sync_xml_from_global(self):
        paths = list(self._resolve_openmm_ligand_xml_paths(self._openmm_current_object()) or [])
        xmlf = "; ".join(paths)
        try:
            if hasattr(self, "edit_openmm_ligand_xml"):
                self.edit_openmm_ligand_xml.setText(xmlf)
        except Exception:
            pass
    def _on_openmm_pick_ligand_xml(self):
        fnames, _ = QtWidgets.QFileDialog.getOpenFileNames(
            self,
            "Select Ligand OpenMM XML(s)",
            "",
            "OpenMM XML (*.xml);;All Files (*)",
        )
        if not fnames:
            return
        existing = list(self._resolve_openmm_ligand_xml_paths(self._openmm_current_object()) or [])
        merged = list(existing)
        seen = set(str(x) for x in merged)
        for f in list(fnames or []):
            sf = str(f or "").strip()
            if (not sf) or (sf in seen):
                continue
            merged.append(sf)
            seen.add(sf)
        self._openmm_set_ligand_xml_paths(merged)
        self._openmm_update_ligand_status()
    def _on_openmm_use_current_ligand_xml(self):
        self._on_set_abfe_xml_from_current_ligand()
        self._openmm_sync_xml_from_global()
        self._openmm_update_ligand_status()
    def _openmm_parameterize_ligand_source_to_xml(
        self,
        source_file,
        out_dir,
        charge_method="bcc",
        atom_type="gaff2",
        net_charge=0,
        residue_name_hint="",
        smiles_hint="",
        skip_smiles_source_rebuild=False,
        target_ph=None,
    ):
        src = str(source_file or "").strip()
        work = str(out_dir or "").strip()
        if (not src) or (not os.path.isfile(src)):
            return {"ok": False, "error": "Ligand source file not found."}
        try:
            os.makedirs(work, exist_ok=True)
        except Exception:
            pass
        antechamber_bin = self._dock_tool_path("antechamber")
        parmchk2_bin = self._dock_tool_path("parmchk2")
        if (not antechamber_bin) or (not parmchk2_bin):
            return {"ok": False, "error": "antechamber/parmchk2 not found in PATH."}
        fi = self._dock_input_format_from_ext(src)
        if not fi:
            return {"ok": False, "error": f"Unsupported ligand format for parameterization: {src}"}
        out_mol2 = os.path.join(work, "ligand_gaff2.mol2")
        out_frcmod = os.path.join(work, "ligand_gaff2.frcmod")
        cm_req = str(charge_method or "bcc").strip().lower()
        if cm_req not in ("bcc", "gas", "rc"):
            cm_req = "bcc"
        try:
            use_target_ph = float(self._current_small_molecule_target_ph() if target_ph is None else target_ph)
        except Exception:
            use_target_ph = 7.4
        charge_candidates = [cm_req]
        if cm_req == "bcc":
            charge_candidates.append("gas")
        elif cm_req == "gas":
            charge_candidates.append("bcc")
        else:
            charge_candidates.append("gas")
        source_candidates = [(str(src), str(fi), "input")]
        attempt_log = []
        notes = []
        smiles_hint = str(smiles_hint or "").strip()
        expected_sig = self._rdkit_topology_signature_from_smiles(smiles_hint)
        if (
            (not bool(skip_smiles_source_rebuild))
            and
            str(fi).lower() == "pdb"
            and bool(expected_sig.get("ok", False))
            and HAS_RDKIT
        ):
            clean_sdf = os.path.join(work, "ligand_template_3d.sdf")
            try:
                if self._prepare_ligand_3d_from_source(
                    src,
                    clean_sdf,
                    smiles_hint=smiles_hint,
                    target_ph=float(use_target_ph),
                ):
                    source_candidates.insert(0, (str(clean_sdf), "sdf", "rdkit_template_sdf"))
                    notes.append("rdkit_template_sdf_prepared")
            except Exception as prep_e:
                notes.append(f"rdkit_template_sdf_failed:{prep_e}")
        prepared_single_unit = False
        ok1 = False
        used_charge_method = ""
        used_source_desc = ""
        while source_candidates and (not ok1):
            src_i, fi_i, src_desc = source_candidates.pop(0)
            for cm_try in list(charge_candidates):
                try:
                    if os.path.isfile(out_mol2):
                        os.remove(out_mol2)
                except Exception:
                    pass
                cmd1 = self._psi4_build_antechamber_cmd_runtime(
                    antechamber_bin=antechamber_bin,
                    source_file=src_i,
                    source_format=fi_i,
                    out_mol2=out_mol2,
                    charge_method=str(cm_try),
                    net_charge=int(net_charge),
                    atom_type=str(atom_type or "gaff2"),
                )
                ok_try, out_try, err_try, rc_try = self._dock_run_command(cmd1, cwd=work, timeout=2400)
                msg_try = str(err_try or out_try or "")
                attempt_log.append(
                    {
                        "src": str(src_desc),
                        "fi": str(fi_i),
                        "charge": str(cm_try),
                        "rc": int(rc_try),
                        "ok": bool(ok_try and os.path.isfile(out_mol2)),
                        "msg_tail": str(msg_try[-320:]),
                    }
                )
                if bool(ok_try) and os.path.isfile(out_mol2):
                    topo_qc = {}
                    if bool(expected_sig.get("ok", False)):
                        observed_sig = dict(self._dock_expected_rotatable_info(out_mol2, smiles_hint="") or {})
                        topo_qc = assess_ligand_topology_signature_compatibility(expected_sig, observed_sig)
                        attempt_log[-1]["topology_qc"] = dict(topo_qc)
                        if not bool(topo_qc.get("ok", False)):
                            issues = ", ".join(str(x) for x in list(topo_qc.get("issues", []) or [])[:3])
                            notes.append(
                                f"topology_reject:{src_desc}:{issues or 'signature_mismatch'}"
                            )
                            try:
                                os.remove(out_mol2)
                            except Exception:
                                pass
                            continue
                    ok1 = True
                    str(out_try or "")
                    str(err_try or "")
                    int(rc_try)
                    used_charge_method = str(cm_try)
                    used_source_desc = str(src_desc)
                    if str(cm_try) != str(cm_req):
                        notes.append(f"antechamber_charge_fallback:{cm_req}->{cm_try}")
                    if str(src_desc) != "input":
                        notes.append(f"antechamber_source_fallback:{src_desc}")
                    break
                low_msg = str(msg_try or "").lower()
                if (not prepared_single_unit) and (
                    ("more than one unit" in low_msg)
                    or ("connectivity is wrong" in low_msg)
                ):
                    prepared_single_unit = True
                    fixed_mol2 = os.path.join(work, "ligand_single_unit.mol2")
                    cmd_fix = [
                        str(antechamber_bin),
                        "-i",
                        str(src_i),
                        "-fi",
                        str(fi_i),
                        "-o",
                        str(fixed_mol2),
                        "-fo",
                        "mol2",
                        "-j",
                        "5",
                        "-at",
                        "sybyl",
                        "-dr",
                        "no",
                        "-c",
                        "gas",
                        "-nc",
                        str(int(net_charge)),
                        "-s",
                        "2",
                    ]
                    ok_fix, out_fix, err_fix, rc_fix = self._dock_run_command(cmd_fix, cwd=work, timeout=2400)
                    if bool(ok_fix) and os.path.isfile(fixed_mol2):
                        source_candidates.append((str(fixed_mol2), "mol2", "single_unit_mol2"))
                        notes.append("single_unit_mol2_prepared")
                    else:
                        msg_fix = str(err_fix or out_fix or "")
                        attempt_log.append(
                            {
                                "src": "single_unit_prepare",
                                "fi": str(fi_i),
                                "charge": "gas",
                                "rc": int(rc_fix),
                                "ok": False,
                                "msg_tail": str(msg_fix[-320:]),
                            }
                        )
            if ok1:
                break
        if (not ok1) or (not os.path.isfile(out_mol2)):
            attempts_txt = "; ".join(
                f"{a.get('src','?')}/{a.get('charge','?')}:rc={int(a.get('rc', 1))}"
                for a in list(attempt_log or [])[-6:]
            )
            last_msg = ""
            if attempt_log:
                last_msg = str((attempt_log[-1] or {}).get("msg_tail", "") or "")
            return {
                "ok": False,
                "error": (
                    f"antechamber failed after {len(attempt_log)} attempt(s) [{attempts_txt}]. "
                    f"{last_msg}"
                ).strip(),
            }
        cmd2 = self._psi4_build_parmchk2_cmd_runtime(
            parmchk2_bin=parmchk2_bin,
            in_mol2=out_mol2,
            out_frcmod=out_frcmod,
        )
        ok2, out2, err2, rc2 = self._dock_run_command(cmd2, cwd=work, timeout=1200)
        if (not ok2) or (not os.path.isfile(out_frcmod)):
            return {
                "ok": False,
                "error": f"parmchk2 failed (rc={rc2}): {(err2 or out2 or '')[-800:]}",
            }
        ok_ff, msg_ff, out_prmtop, out_inpcrd = self._build_ligand_amber_files_with_tleap(
            out_mol2,
            out_frcmod,
            atom_type=str(atom_type or "gaff2"),
            out_dir=work,
        )
        if not ok_ff:
            return {"ok": False, "error": f"tleap build failed: {msg_ff}"}
        out_xml = os.path.join(work, "ligand_openmm_system.xml")
        ok_xml, msg_xml = self._export_ligand_openmm_xml_from_prmtop(out_prmtop, out_xml)
        out_ffxml = os.path.join(work, "ligand_openmm_ff.xml")
        ok_ffxml, msg_ffxml = self._export_ligand_forcefield_xml_from_prmtop(
            out_prmtop,
            out_ffxml,
            residue_name_hint=str(residue_name_hint or ""),
        )
        if (not ok_xml) and (not ok_ffxml):
            return {
                "ok": False,
                "error": f"OpenMM XML export failed: system={msg_xml}; ffxml={msg_ffxml}",
            }
        preferred_xml = out_ffxml if ok_ffxml else out_xml
        if used_charge_method:
            notes.append(f"antechamber_charge_method:{used_charge_method}")
        if used_source_desc:
            notes.append(f"antechamber_source:{used_source_desc}")
        if bool(expected_sig.get("ok", False)):
            obs_sig = dict(self._dock_expected_rotatable_info(out_mol2, smiles_hint="") or {})
            topo_qc = assess_ligand_topology_signature_compatibility(expected_sig, obs_sig)
            notes.append(
                "topology_qc:"
                f"rotb={int(obs_sig.get('rotb', -1) or -1)},"
                f"aromatic_bonds={int(obs_sig.get('aromatic_bonds', -1) or -1)},"
                f"status={'ok' if bool(topo_qc.get('ok', False)) else 'failed'}"
            )
        audit_path = out_ffxml + ".audit.json"
        if ok_ffxml and os.path.isfile(audit_path):
            try:
                with open(audit_path, "r", encoding="utf-8") as fh:
                    audit = json.load(fh)
                counts = dict(audit.get("counts", {}) or {})
                chg = dict(audit.get("charge", {}) or {})
                roundtrip = dict(audit.get("roundtrip", {}) or {})
                notes.append(
                    "ffxml_audit:"
                    f"atoms={int(counts.get('atoms', 0) or 0)},"
                    f"bonds={int(counts.get('bond_terms', 0) or 0)},"
                    f"angles={int(counts.get('angle_terms', 0) or 0)},"
                    f"torsion_terms={int(counts.get('torsion_terms', 0) or 0)},"
                    f"charge_sum={float(chg.get('sum_e', 0.0) or 0.0):.4f}e,"
                    f"roundtrip={'ok' if bool(roundtrip.get('ok', False)) else 'failed'}"
                )
            except Exception:
                pass
        if (not ok_ffxml) and ok_xml:
            notes.append(f"forcefield_xml_unavailable: {msg_ffxml}")
        if (not ok_xml) and ok_ffxml:
            notes.append(f"system_xml_unavailable: {msg_xml}")
        notes.append(f"prep_target_ph:{float(use_target_ph):.2f}")
        return {
            "ok": True,
            "mol2": out_mol2,
            "frcmod": out_frcmod,
            "prmtop": out_prmtop,
            "inpcrd": out_inpcrd,
            "xml": preferred_xml,
            "xml_forcefield": (out_ffxml if ok_ffxml else ""),
            "xml_system": (out_xml if ok_xml else ""),
            "notes": list(notes),
        }
    def _openmm_parameterize_component_from_receptor(
        self,
        receptor_obj,
        comp,
        charge_method="bcc",
        atom_type="gaff2",
        net_charge=0,
    ):
        rec = str(receptor_obj or "").strip()
        if (not rec) or (not self._pymol_object_exists(rec)):
            return {"ok": False, "error": "Invalid receptor object."}
        c = dict(comp or {})
        key = self._openmm_component_uid(c)
        if not key:
            return {"ok": False, "error": "Invalid component key."}
        ff_cls = self._openmm_component_ff_class(c)
        if ff_cls == "standard":
            label = self._format_dock_hetatm_component(c)
            return {
                "ok": True,
                "skipped": True,
                "reason": "standard_component",
                "message": f"{label} is covered by the standard force-field path and does not need antechamber.",
            }
        comp_sel = self._dock_hetatm_component_selection(rec, c)
        if not comp_sel:
            return {"ok": False, "error": "Could not build component selection."}
        tag = f"{str(c.get('resn','UNK'))}_{str(c.get('chain','-') or '-')}_{str(c.get('resi','?'))}"
        safe_tag = self._dock_safe_obj_name(tag)
        work = os.path.join(self._openmm_workspace_dir(), "ligands", f"{safe_tag}_{datetime.datetime.now().strftime('%Y%m%d_%H%M%S')}")
        try:
            os.makedirs(work, exist_ok=True)
        except Exception:
            pass
        src_pdb = os.path.join(work, "component_input.pdb")
        try:
            cmd.save(src_pdb, str(comp_sel), state=1)
        except Exception as e:
            return {"ok": False, "error": f"Failed exporting component from PyMOL: {e}"}
        # Preserve crystal residue/atom naming from receptor export to maximize
        # residue-template matching reliability in OpenMM.
        src_for_param = src_pdb
        smiles_hint = self._openmm_component_smiles_hint(c)
        hydrated_pdb = os.path.join(work, "component_hydrated.pdb")
        hydrated_sdf = os.path.join(work, "component_hydrated.sdf")
        # MD ligands/cofactors are protonated at the MD pH (it used to be the docking pH)
        use_target_ph = float(self._openmm_ligand_target_ph())
        param_net_charge = int(net_charge)
        inferred_charge = int(self._rdkit_formal_charge_from_smiles(smiles_hint))
        protonation_note = ""
        if smiles_hint:
            hyd = self._openmm_build_hydrated_component_pdb(
                src_pdb,
                hydrated_pdb,
                c,
                smiles_hint=smiles_hint,
                target_ph=float(use_target_ph),
            )
            if bool(hyd.get("ok", False)) and os.path.isfile(hydrated_pdb):
                if hyd.get("formal_charge") is not None:
                    inferred_charge = int(hyd["formal_charge"])
                prot = dict(hyd.get("protonation") or {})
                protonation_note = (f"protonation:{prot.get('method', '?')}@pH{float(use_target_ph):.2f}"
                                    f"(charge {inferred_charge:+d})")
                try:
                    if self._prepare_ligand_3d_from_source(
                        src_pdb,
                        hydrated_sdf,
                        smiles_hint=smiles_hint,
                        target_ph=float(use_target_ph),
                    ):
                        src_for_param = str(hydrated_sdf)
                        q_sdf = self._ligand_file_formal_charge(hydrated_sdf)
                        if q_sdf is not None:
                            inferred_charge = int(q_sdf)     # the molecule antechamber actually reads
                    else:
                        src_for_param = str(hydrated_pdb)
                except Exception:
                    src_for_param = str(hydrated_pdb)
        # net charge 0 in the dialog means "automatic": use the pH-protonated molecule's charge,
        # not the raw CCD SMILES (which is usually the neutral form)
        if int(param_net_charge) == 0 and int(inferred_charge) != 0:
            param_net_charge = int(inferred_charge)
        elif int(param_net_charge) != int(inferred_charge):
            self._append_debug_log(
                f"OpenMM component {tag}: requested net charge {int(param_net_charge):+d} differs from the "
                f"protonated molecule at pH {float(use_target_ph):.2f} ({int(inferred_charge):+d})."
            )
        res = self._openmm_parameterize_ligand_source_to_xml(
            source_file=src_for_param,
            out_dir=work,
            charge_method=str(charge_method or "bcc"),
            atom_type=str(atom_type or "gaff2"),
            net_charge=int(param_net_charge),
            residue_name_hint=str(c.get("resn", "") or ""),
            smiles_hint=str(smiles_hint or ""),
            skip_smiles_source_rebuild=bool(src_for_param == hydrated_pdb),
            target_ph=float(use_target_ph),
        )
        if not bool(res.get("ok", False)):
            return res
        if int(param_net_charge) != int(net_charge):
            res["notes"] = list(res.get("notes", []) or []) + [
                f"auto_net_charge_from_protonation:{int(net_charge)}->{int(param_net_charge)}"
            ]
        if protonation_note:
            res["notes"] = list(res.get("notes", []) or []) + [protonation_note]
        xml_path = str(res.get("xml_forcefield", "") or "").strip()
        if (not xml_path) or (not os.path.isfile(xml_path)):
            xml_path = str(res.get("xml", "") or "").strip()
        if xml_path and os.path.isfile(xml_path):
            self._openmm_ligand_xml_map[str(key)] = str(xml_path)
        return res
    def _on_openmm_manage_crystal_ligands(self):
        receptor_obj = str(self._openmm_current_object() or "").strip()
        if (not receptor_obj) or (not self._pymol_object_exists(receptor_obj)):
            QtWidgets.QMessageBox.warning(self, "OpenMM", "Select a valid structure object first.")
            return
        comps = list(self._openmm_detect_ligand_candidates(receptor_obj) or [])
        if not comps:
            QtWidgets.QMessageBox.information(self, "OpenMM", "No non-water HETATM components found.")
            return
        rec_key = str(receptor_obj)
        selected_keys = set(self._openmm_ligand_xml_selected_keys.get(rec_key, []) or [])
        if not selected_keys:
            # Default to components that actually need XML/parameterization support.
            selected_keys = set(default_openmm_xml_selected_keys(comps))
        dlg = QtWidgets.QDialog(self)
        dlg.setWindowTitle("Crystal Ligands / XML Selection")
        dlg.resize(1060, 800)
        dlg.setMinimumSize(900, 680)
        self._fit_dialog_to_screen(dlg, preferred_w=1060, preferred_h=800, min_w=880, min_h=660)
        vbox = QtWidgets.QVBoxLayout(dlg)
        intro = QtWidgets.QLabel(
            "Detected non-water crystal HETATM components. Class is heuristic: 'standard' vs 'needs parameterization'.\n"
            "Standard ions/cofactors are skipped during parameterization. Checked entries are used for XML selection,"
            " while only 'needs parameterization' entries are sent to antechamber."
        )
        intro.setWordWrap(True)
        vbox.addWidget(intro)
        row_param = QtWidgets.QHBoxLayout()
        row_param.addWidget(QtWidgets.QLabel("Charge method"))
        cmb_charge = QtWidgets.QComboBox()
        cmb_charge.addItem("AM1-BCC", "bcc")
        cmb_charge.addItem("Gasteiger", "gas")
        row_param.addWidget(cmb_charge)
        row_param.addWidget(QtWidgets.QLabel("Atom type"))
        cmb_at = QtWidgets.QComboBox()
        cmb_at.addItem("GAFF2", "gaff2")
        cmb_at.addItem("GAFF", "gaff")
        row_param.addWidget(cmb_at)
        row_param.addWidget(QtWidgets.QLabel("Net charge"))
        spin_q = QtWidgets.QSpinBox()
        spin_q.setRange(-10, 10)
        spin_q.setValue(0)
        row_param.addWidget(spin_q)
        row_param.addStretch(1)
        vbox.addLayout(row_param)
        row_btn = QtWidgets.QHBoxLayout()
        btn_all = QtWidgets.QPushButton("Check All")
        btn_none = QtWidgets.QPushButton("Check None")
        btn_need = QtWidgets.QPushButton("Check Needs Param")
        btn_param = QtWidgets.QPushButton("Parameterize Checked")
        for b in (btn_all, btn_none, btn_need, btn_param):
            row_btn.addWidget(b)
        row_btn.addStretch(1)
        vbox.addLayout(row_btn)
        tbl = QtWidgets.QTableWidget(0, 9, dlg)
        tbl.setHorizontalHeaderLabels(["Use", "FF Class", "Resn", "Chain", "Resi", "Atoms", "Category", "XML", "Status"])
        tbl.setSelectionBehavior(QtWidgets.QAbstractItemView.SelectRows)
        tbl.setEditTriggers(QtWidgets.QAbstractItemView.NoEditTriggers)
        tbl.verticalHeader().setVisible(False)
        vbox.addWidget(tbl, 1)
        def _fill_table():
            tbl.setRowCount(0)
            for c in comps:
                key = self._openmm_component_uid(c)
                ff_cls = self._openmm_component_ff_class(c)
                xml_path = str(self._openmm_ligand_xml_map.get(key, "") or "").strip()
                r = int(tbl.rowCount())
                tbl.insertRow(r)
                it_use = QtWidgets.QTableWidgetItem("")
                it_use.setFlags(QtCore.Qt.ItemIsEnabled | QtCore.Qt.ItemIsSelectable | QtCore.Qt.ItemIsUserCheckable)
                it_use.setCheckState(QtCore.Qt.Checked if key in selected_keys else QtCore.Qt.Unchecked)
                tbl.setItem(r, 0, it_use)
                tbl.setItem(r, 1, QtWidgets.QTableWidgetItem("standard" if ff_cls == "standard" else "needs_parameterization"))
                tbl.setItem(r, 2, QtWidgets.QTableWidgetItem(str(c.get("resn", ""))))
                tbl.setItem(r, 3, QtWidgets.QTableWidgetItem(str(c.get("chain", "") or "-")))
                tbl.setItem(r, 4, QtWidgets.QTableWidgetItem(str(c.get("resi", ""))))
                tbl.setItem(r, 5, QtWidgets.QTableWidgetItem(str(int(c.get("atom_count", 0) or 0))))
                tbl.setItem(r, 6, QtWidgets.QTableWidgetItem(str(c.get("category", ""))))
                tbl.setItem(r, 7, QtWidgets.QTableWidgetItem(str(xml_path)))
                if xml_path and os.path.isfile(xml_path):
                    kind = self._openmm_xml_kind(xml_path)
                    if kind == "forcefield":
                        st = "ready_ffxml"
                    elif kind == "system":
                        st = "ready_system_xml"
                    else:
                        st = "ready_xml"
                else:
                    st = "standard_ff" if ff_cls == "standard" else "not_parameterized"
                tbl.setItem(r, 8, QtWidgets.QTableWidgetItem(st))
            try:
                hdr = tbl.horizontalHeader()
                hdr.setSectionResizeMode(0, QtWidgets.QHeaderView.ResizeToContents)
                hdr.setSectionResizeMode(1, QtWidgets.QHeaderView.ResizeToContents)
                hdr.setSectionResizeMode(2, QtWidgets.QHeaderView.ResizeToContents)
                hdr.setSectionResizeMode(3, QtWidgets.QHeaderView.ResizeToContents)
                hdr.setSectionResizeMode(4, QtWidgets.QHeaderView.ResizeToContents)
                hdr.setSectionResizeMode(5, QtWidgets.QHeaderView.ResizeToContents)
                hdr.setSectionResizeMode(6, QtWidgets.QHeaderView.ResizeToContents)
                hdr.setSectionResizeMode(7, QtWidgets.QHeaderView.Stretch)
                hdr.setSectionResizeMode(8, QtWidgets.QHeaderView.ResizeToContents)
            except Exception:
                pass
        def _sync_selected_from_table():
            selected_keys.clear()
            for i, c in enumerate(comps):
                it = tbl.item(int(i), 0)
                if it is not None and it.checkState() == QtCore.Qt.Checked:
                    selected_keys.add(self._openmm_component_uid(c))
        def _set_mode(mode):
            for i, c in enumerate(comps):
                it = tbl.item(int(i), 0)
                if it is None:
                    continue
                on = False
                if mode == "all":
                    on = True
                elif mode == "none":
                    on = False
                elif mode == "need":
                    on = (self._openmm_component_ff_class(c) == "needs_parameterization")
                it.setCheckState(QtCore.Qt.Checked if on else QtCore.Qt.Unchecked)
            _sync_selected_from_table()
        def _parameterize_checked():
            _sync_selected_from_table()
            selected_components = [c for c in comps if self._openmm_component_uid(c) in selected_keys]
            if not selected_components:
                QtWidgets.QMessageBox.information(dlg, "OpenMM", "No checked ligands to parameterize.")
                return
            plan = split_openmm_parameterization_targets(selected_components)
            todo = list(plan.get("parameterize", []) or [])
            skipped_standard = list(plan.get("skipped_standard", []) or [])
            if not todo:
                skipped_txt = "\n- ".join(self._format_dock_hetatm_component(c) for c in skipped_standard[:12])
                msg = "Checked components are already covered by the standard force-field path."
                if skipped_txt:
                    msg += "\n\nSkipped:\n- " + skipped_txt
                QtWidgets.QMessageBox.information(dlg, "OpenMM", msg)
                return
            pd = QtWidgets.QProgressDialog("Parameterizing selected ligands...", "Cancel", 0, len(todo), dlg)
            pd.setWindowModality(QtCore.Qt.WindowModal)
            ok_n = 0
            fail_msgs = []
            charge_method = str(cmb_charge.currentData() or "bcc")
            atom_type = str(cmb_at.currentData() or "gaff2")
            net_charge = int(spin_q.value())
            try:
                if not hasattr(self, "_settings") or self._settings is None:
                    self._settings = {}
                self._settings["openmm_crystal_charge_method"] = str(charge_method)
                self._settings["openmm_crystal_atom_type"] = str(atom_type)
                self._settings["openmm_crystal_net_charge"] = int(net_charge)
                self._save_settings()
            except Exception:
                pass
            for i, comp in enumerate(todo, start=1):
                if pd.wasCanceled():
                    break
                pd.setValue(i - 1)
                pd.setLabelText(
                    f"Parameterizing {str(comp.get('resn','UNK'))} {str(comp.get('chain','-') or '-')}:{str(comp.get('resi','?'))} ({i}/{len(todo)})"
                )
                try:
                    QtWidgets.QApplication.processEvents()
                except Exception:
                    pass
                rs = self._openmm_parameterize_component_from_receptor(
                    receptor_obj,
                    comp,
                    charge_method=charge_method,
                    atom_type=atom_type,
                    net_charge=net_charge,
                )
                if bool(rs.get("ok", False)):
                    if bool(rs.get("skipped", False)):
                        skipped_standard.append(comp)
                    else:
                        ok_n += 1
                else:
                    fail_msgs.append(
                        f"{str(comp.get('resn','UNK'))} {str(comp.get('chain','-') or '-')}:{str(comp.get('resi','?'))}: "
                        f"{str(rs.get('error', 'failed'))}"
                    )
            pd.setValue(len(todo))
            _fill_table()
            skipped_txt = "\n- ".join(self._format_dock_hetatm_component(c) for c in skipped_standard[:12])
            if fail_msgs:
                msg = (
                    f"Parameterized {ok_n}/{len(todo)} component(s) needing parameterization."
                )
                if skipped_txt:
                    msg += "\n\nSkipped standard components:\n- " + skipped_txt
                msg += "\n\nFailures:\n- " + "\n- ".join(fail_msgs[:12])
                QtWidgets.QMessageBox.warning(
                    dlg,
                    "OpenMM",
                    msg,
                )
            else:
                msg = f"Parameterized {ok_n}/{len(todo)} component(s) needing parameterization."
                if skipped_txt:
                    msg += "\n\nSkipped standard components:\n- " + skipped_txt
                QtWidgets.QMessageBox.information(
                    dlg,
                    "OpenMM",
                    msg,
                )
        btn_all.clicked.connect(lambda: _set_mode("all"))
        btn_none.clicked.connect(lambda: _set_mode("none"))
        btn_need.clicked.connect(lambda: _set_mode("need"))
        btn_param.clicked.connect(_parameterize_checked)
        _fill_table()
        bb = QtWidgets.QDialogButtonBox(QtWidgets.QDialogButtonBox.Ok | QtWidgets.QDialogButtonBox.Cancel, QtCore.Qt.Horizontal, dlg)
        bb.accepted.connect(dlg.accept)
        bb.rejected.connect(dlg.reject)
        vbox.addWidget(bb)
        if dlg.exec_() != QtWidgets.QDialog.Accepted:
            return
        _sync_selected_from_table()
        self._openmm_ligand_xml_selected_keys[rec_key] = sorted(list(selected_keys))
        selected_xml = []
        seen_xml = set()
        for c in comps:
            key = self._openmm_component_uid(c)
            if key not in selected_keys:
                continue
            xp = str(self._openmm_ligand_xml_map.get(key, "") or "").strip()
            if (not xp) or (not os.path.isfile(xp)) or (xp in seen_xml):
                continue
            selected_xml.append(xp)
            seen_xml.add(xp)
        self._openmm_set_ligand_xml_paths(selected_xml)
        self._append_debug_log(
            f"OpenMM crystal ligand XML selection updated: receptor={receptor_obj}, selected={len(selected_keys)}, xml={len(selected_xml)}"
        )
    def _on_openmm_solvent_mode_changed(self, *_args):
        mode = "explicit"
        try:
            if hasattr(self, "cmb_openmm_solvent_mode"):
                mode = str(self.cmb_openmm_solvent_mode.currentData() or "explicit")
        except Exception:
            mode = "explicit"
        is_explicit = bool(mode == "explicit")
        try:
            if hasattr(self, "cmb_openmm_water_model"):
                self.cmb_openmm_water_model.setEnabled(is_explicit)
            if hasattr(self, "spin_openmm_ionic_strength"):
                self.spin_openmm_ionic_strength.setEnabled(is_explicit)
            if hasattr(self, "spin_openmm_padding"):
                self.spin_openmm_padding.setEnabled(is_explicit)
            if hasattr(self, "spin_openmm_pressure"):
                self.spin_openmm_pressure.setEnabled(is_explicit)
            if hasattr(self, "cmb_openmm_ensemble"):
                ens = str(self.cmb_openmm_ensemble.currentData() or "npt")
                if (not is_explicit) and ens == "npt":
                    idx = self.cmb_openmm_ensemble.findData("nvt")
                    if idx >= 0:
                        self.cmb_openmm_ensemble.setCurrentIndex(idx)
        except Exception:
            pass
    def _openmm_detect_ligand_candidates(self, receptor_obj):
        comps = list(self._collect_receptor_hetatm_components(receptor_obj) or [])
        cands = []
        for comp in comps:
            try:
                cat = str(comp.get("category", "")).strip().lower()
            except Exception:
                cat = ""
            # Include all non-water HETATM components so users can decide
            # standard-vs-parameterized handling in one place.
            if cat == "water":
                continue
            try:
                nat = int(comp.get("atom_count", 0) or 0)
            except Exception:
                nat = 0
            if nat <= 0:
                continue
            cands.append(comp)
        cands.sort(
            key=lambda x: (
                -int(x.get("atom_count", 0) or 0),
                str(x.get("resn", "")),
                str(x.get("chain", "")),
                str(x.get("resi", "")),
            )
        )
        return cands
    def _openmm_is_standard_small_molecule_resn(self, resn):
        return bool(classify_openmm_component_ff_class({"resn": str(resn or ""), "category": "cofactor"}) == "standard")
    def _openmm_component_ff_class(self, comp):
        return str(classify_openmm_component_ff_class(comp))
    def _openmm_component_uid(self, comp):
        if not isinstance(comp, dict):
            return ""
        uid = str(comp.get("uid", "") or "").strip()
        if uid:
            return uid
        return str(comp.get("key", "") or "").strip()
    def _openmm_parse_xml_path_list(self, text):
        txt = str(text or "")
        if not txt.strip():
            return []
        toks = re.split(r"[;\n,]+", txt)
        out = []
        seen = set()
        for t in toks:
            p = str(t or "").strip()
            if not p:
                continue
            p = os.path.expanduser(p)
            if p in seen:
                continue
            seen.add(p)
            out.append(p)
        return out
    def _openmm_guess_forcefield_xml_from_system(self, xml_path):
        xp = str(xml_path or "").strip()
        if (not xp) or (not os.path.isfile(xp)):
            return ""
        base = os.path.splitext(xp)[0]
        candidates = [
            f"{base}_ff.xml",
            f"{base}.ffxml",
            xp.replace("_system.xml", "_ff.xml"),
            xp.replace(".xml", "_ff.xml"),
            xp.replace(".xml", ".ffxml"),
        ]
        seen = set()
        for c in candidates:
            cc = str(c or "").strip()
            if (not cc) or (cc in seen):
                continue
            seen.add(cc)
            if os.path.isfile(cc) and self._openmm_xml_kind(cc) == "forcefield":
                return cc
        return ""
    def _openmm_guess_system_xml_from_forcefield(self, xml_path):
        xp = str(xml_path or "").strip()
        if (not xp) or (not os.path.isfile(xp)):
            return ""
        base = os.path.splitext(xp)[0]
        candidates = [
            xp.replace("_ff.xml", "_system.xml"),
            xp.replace(".ffxml", "_system.xml"),
            f"{base}_system.xml",
            xp.replace(".ffxml", ".xml"),
        ]
        seen = set()
        for c in candidates:
            cc = str(c or "").strip()
            if (not cc) or (cc in seen):
                continue
            seen.add(cc)
            if os.path.isfile(cc) and self._openmm_xml_kind(cc) == "system":
                return cc
        return ""
    def _rdkit_topology_signature_from_smiles(self, smiles):
        out = {"rotb": -1, "aromatic_bonds": -1, "ok": False}
        if (not HAS_RDKIT) or (not smiles):
            return out
        try:
            mol = Chem.MolFromSmiles(str(smiles).strip())
            if mol is None:
                return out
            Chem.SanitizeMol(mol)
            core = Chem.RemoveHs(mol)
            Chem.SanitizeMol(core)
            rotb = int(rdMolDescriptors.CalcNumRotatableBonds(core))
            aro = int(sum(1 for b in core.GetBonds() if bool(b.GetIsAromatic())))
            out.update({"rotb": int(rotb), "aromatic_bonds": int(aro), "ok": True})
            return out
        except Exception:
            return out
    def _rdkit_formal_charge_from_smiles(self, smiles):
        if (not HAS_RDKIT) or (not smiles):
            return 0
        try:
            mol = Chem.MolFromSmiles(str(smiles).strip())
            if mol is None:
                return 0
            Chem.SanitizeMol(mol)
            return int(Chem.GetFormalCharge(mol))
        except Exception:
            return 0
    def _openmm_component_smiles_hint(self, comp):
        c = dict(comp or {})
        resn = str(c.get("resn", "") or "").strip().upper()
        if not resn:
            return ""
        overrides = {
            # 3PTB/trypsin benzamidine and common crystal-ligand benchmark case.
            "BEN": "[NH2+]=C(N)c1ccccc1",
        }
        if resn in overrides:
            return str(overrides.get(resn, "") or "")
        try:
            cache = dict(getattr(self, "_openmm_component_smiles_cache", {}) or {})
        except Exception:
            cache = {}
        if resn in cache:
            return str(cache.get(resn, "") or "")
        hint = ""
        try:
            hint = str(self._rcsb_chemcomp_smiles(resn, timeout=6) or "").strip()
        except Exception:
            hint = ""
        cache[resn] = str(hint)
        try:
            self._openmm_component_smiles_cache = dict(cache)
        except Exception:
            pass
        return str(hint)
    def _openmm_component_parameterization_paths(self, comp):
        c = dict(comp or {})
        cat = str(c.get("category", "") or "").strip().lower()
        if cat in {"ion", "water"}:
            return {"xml": "", "prmtop": "", "inpcrd": "", "hydrated_pdb": ""}
        key = str(self._openmm_component_uid(c) or "").strip()
        xml_path = ""
        try:
            xml_path = str(self._openmm_ligand_xml_map.get(key, "") or "").strip()
        except Exception:
            xml_path = ""
        if (not xml_path) or (not os.path.isfile(xml_path)):
            return {"xml": "", "prmtop": "", "inpcrd": "", "hydrated_pdb": ""}
        base = os.path.dirname(str(xml_path))
        prmtop = os.path.join(base, "ligand.prmtop")
        inpcrd = os.path.join(base, "ligand.inpcrd")
        hydrated_pdb = os.path.join(base, "component_hydrated.pdb")
        return {
            "xml": str(xml_path),
            "prmtop": (str(prmtop) if os.path.isfile(prmtop) else ""),
            "inpcrd": (str(inpcrd) if os.path.isfile(inpcrd) else ""),
            "hydrated_pdb": (str(hydrated_pdb) if os.path.isfile(hydrated_pdb) else ""),
        }
    def _openmm_ligand_target_ph(self):
        """pH for ligands/cofactors that go into MD: the OpenMM (MD) pH, else the docking pH."""
        try:
            if hasattr(self, "spin_openmm_ph"):
                return float(self.spin_openmm_ph.value())
        except Exception:
            pass
        try:
            return float(self._current_small_molecule_target_ph())
        except Exception:
            return 7.4
    def _openmm_build_hydrated_component_pdb(self, source_pdb, out_pdb, comp, smiles_hint="", target_ph=None):
        src = str(source_pdb or "").strip()
        outp = str(out_pdb or "").strip()
        smi = str(smiles_hint or "").strip()
        c = dict(comp or {})
        if (not HAS_RDKIT) or (not src) or (not os.path.isfile(src)) or (not outp) or (not smi):
            return {"ok": False, "error": "RDKit, source PDB, output path, and SMILES hint are required."}
        try:
            template = Chem.MolFromSmiles(smi)
            if template is None:
                return {"ok": False, "error": "Could not parse component SMILES hint."}
            ref = Chem.RemoveHs(Chem.Mol(template))
            crystal = Chem.MolFromPDBFile(src, removeHs=True, sanitize=False)
            if crystal is None:
                return {"ok": False, "error": "RDKit failed to parse crystal component PDB."}
            try:
                Chem.SanitizeMol(crystal)
            except Exception:
                pass
            mapped = AllChem.AssignBondOrdersFromTemplate(ref, crystal)
            # protonation at the MD pH before charges/parameters (the CCD SMILES is usually the
            # neutral form); crystal heavy atoms keep coordinates and names
            ph = float(self._openmm_ligand_target_ph() if target_ph is None else target_ph)
            protonation = {}
            try:
                pka_method = self._pka_method()
                mapped_h, protonation = pka_protonate_molecule(
                    mapped, ph, method=pka_method, cache_dir=self._pka_cache_dir(),
                    backend_options=self._pka_backend_options(pka_method))
            except Exception as exc:
                protonation = {"method": "none", "error": str(exc)}
                mapped_h = Chem.AddHs(mapped, addCoords=True)
            resn = str(c.get("resn", "") or "LIG").strip().upper()[:3] or "LIG"
            chain_id = str(c.get("chain", "") or "").strip()[:1]
            resi_raw = str(c.get("resi", "") or "1").strip()
            try:
                resi_num = int(resi_raw)
            except Exception:
                resi_num = 1
            h_idx = 1
            for idx, atom in enumerate(mapped_h.GetAtoms(), start=1):
                info = atom.GetPDBResidueInfo()
                atom_name = ""
                if info is not None and atom.GetAtomicNum() != 1:
                    try:
                        atom_name = str(info.GetName() or "").strip()
                    except Exception:
                        atom_name = ""
                if not atom_name:
                    if atom.GetAtomicNum() == 1:
                        atom_name = f"H{h_idx:02d}"
                        h_idx += 1
                    else:
                        atom_name = f"{atom.GetSymbol()}{idx}"
                new_info = Chem.AtomPDBResidueInfo(
                    f"{atom_name:<4s}",
                    serialNumber=int(idx),
                    altLoc="",
                    residueName=f"{resn:<3s}",
                    residueNumber=int(resi_num),
                    chainId=f"{chain_id:1s}",
                    insertionCode="",
                    occupancy=1.0,
                    tempFactor=0.0,
                )
                atom.SetMonomerInfo(new_info)
            pdb_block = Chem.MolToPDBBlock(mapped_h)
            lines = [
                ln.rstrip("\n")
                for ln in str(pdb_block or "").splitlines()
                if str(ln or "").strip() and str(ln[:6]).strip().upper() != "END"
            ]
            lines = rewrite_pdb_component_identity(
                lines,
                resn=resn,
                chain=chain_id,
                resi=resi_raw,
                hetero=True,
            )
            lines = normalize_pdb_conect_records(lines)
            try:
                os.makedirs(os.path.dirname(outp) or ".", exist_ok=True)
            except Exception:
                pass
            with open(outp, "w", encoding="utf-8") as fh:
                for line in lines:
                    fh.write(str(line) + "\n")
                fh.write("END\n")
            return {
                "ok": True,
                "atom_count": int(sum(1 for line in lines if str(line[:6]).strip().upper() in {"ATOM", "HETATM"})),
                "hydrogen_count": int(sum(1 for line in lines if str(line[76:78]).strip().upper() == "H")),
                "path": str(outp),
                "formal_charge": int(Chem.GetFormalCharge(mapped_h)),
                "protonation": dict(protonation or {}),
            }
        except Exception as e:
            return {"ok": False, "error": str(e)}
    def _openmm_crystal_parameterization_defaults(self):
        charge_method = "bcc"
        atom_type = "gaff2"
        net_charge = 0
        try:
            s = dict(getattr(self, "_settings", {}) or {})
        except Exception:
            s = {}
        try:
            charge_method = str(s.get("openmm_crystal_charge_method", "bcc") or "bcc").strip().lower()
        except Exception:
            charge_method = "bcc"
        if charge_method not in ("bcc", "gas", "rc"):
            charge_method = "bcc"
        try:
            atom_type = str(s.get("openmm_crystal_atom_type", "gaff2") or "gaff2").strip().lower()
        except Exception:
            atom_type = "gaff2"
        if atom_type not in ("gaff2", "gaff"):
            atom_type = "gaff2"
        try:
            net_charge = int(s.get("openmm_crystal_net_charge", 0))
        except Exception:
            net_charge = 0
        return {
            "charge_method": str(charge_method),
            "atom_type": str(atom_type),
            "net_charge": int(max(-20, min(20, net_charge))),
        }
    def _openmm_component_template_plan(self, components):
        return resolve_openmm_component_template_plan(
            components=components,
            xml_map=getattr(self, "_openmm_ligand_xml_map", {}) or {},
            file_exists_fn=os.path.isfile,
            component_uid_fn=self._openmm_component_uid,
            ff_class_fn=self._openmm_component_ff_class,
            xml_kind_fn=self._openmm_xml_kind,
            guess_forcefield_xml_from_system_fn=self._openmm_guess_forcefield_xml_from_system,
        )
    def _openmm_ensure_component_templates(self, receptor_obj, components, auto_parameterize=True):
        rec = str(receptor_obj or "").strip()
        comps = list(components or [])
        plan0 = dict(self._openmm_component_template_plan(comps) or {})
        missing = list(plan0.get("missing", []) or [])
        generated = []
        errors = []
        if bool(auto_parameterize) and missing:
            defaults = dict(self._openmm_crystal_parameterization_defaults() or {})
            for comp in list(missing):
                rs = self._openmm_parameterize_component_from_receptor(
                    rec,
                    comp,
                    charge_method=str(defaults.get("charge_method", "bcc") or "bcc"),
                    atom_type=str(defaults.get("atom_type", "gaff2") or "gaff2"),
                    net_charge=int(defaults.get("net_charge", 0) or 0),
                )
                if bool(rs.get("ok", False)):
                    if not bool(rs.get("skipped", False)):
                        generated.append(dict(comp))
                else:
                    errors.append(
                        {
                            "component": dict(comp),
                            "error": str(rs.get("error", "parameterization failed") or "parameterization failed"),
                        }
                    )
            plan0 = dict(self._openmm_component_template_plan(comps) or {})
            missing = list(plan0.get("missing", []) or [])
            if generated:
                try:
                    self._openmm_sync_xml_from_global()
                    self._openmm_update_ligand_status()
                except Exception:
                    pass
        return {
            "ok": bool((not missing) and (not errors)),
            "paths": list(plan0.get("paths", []) or []),
            "missing": list(missing),
            "generated": list(generated),
            "errors": list(errors),
            "skipped_standard": list(plan0.get("skipped_standard", []) or []),
        }
    def _openmm_sanitize_exported_component_bonds(self, pdb_path, components):
        path = str(pdb_path or "").strip()
        if (not path) or (not os.path.isfile(path)):
            return {"ok": False, "error": "Exported OpenMM PDB was not found.", "removed_links": 0, "notes": []}
        standalone = [
            dict(c)
            for c in list(components or [])
            if self._openmm_component_ff_class(c) != "standard"
        ]
        if not standalone:
            return {"ok": True, "removed_links": 0, "notes": []}
        try:
            with open(path, "r", encoding="utf-8", errors="ignore") as fh:
                lines = [ln.rstrip("\n") for ln in fh]
        except Exception as e:
            return {"ok": False, "error": f"Failed reading exported OpenMM PDB: {e}", "removed_links": 0, "notes": []}
        try:
            clean = sanitize_pdb_conect_for_standalone_components(lines, standalone)
        except Exception as e:
            return {"ok": False, "error": f"Failed sanitizing ligand CONECT records: {e}", "removed_links": 0, "notes": []}
        out_lines = list(clean.get("lines", []) or [])
        removed_links = int(clean.get("removed_links", 0) or 0)
        if removed_links > 0:
            try:
                with open(path, "w", encoding="utf-8") as fh:
                    for line in out_lines:
                        fh.write(str(line) + "\n")
            except Exception as e:
                return {"ok": False, "error": f"Failed writing sanitized OpenMM PDB: {e}", "removed_links": 0, "notes": []}
        notes = []
        if removed_links > 0:
            labels = ", ".join(self._format_dock_hetatm_component(c) for c in standalone[:6])
            if len(standalone) > 6:
                labels += ", ..."
            notes.append(
                f"Removed {removed_links} cross-residue CONECT link(s) for standalone crystal ligands/cofactors: {labels}"
            )
        return {"ok": True, "removed_links": int(removed_links), "notes": list(notes)}
    def _export_openmm_input_pdb(self, receptor_obj, out_pdb, include_components=None):
        rec = str(receptor_obj or "").strip()
        outp = str(out_pdb or "").strip()
        if (not rec) or (not outp):
            return {"ok": False, "error": "OpenMM export requires receptor object and output path.", "notes": []}
        try:
            rec_sel = self._pymol_model_selection(rec, wrap=True)
        except Exception:
            rec_sel = ""
        if not rec_sel:
            return {"ok": False, "error": "Could not resolve PyMOL selection for OpenMM export.", "notes": []}
        try:
            os.makedirs(os.path.dirname(outp) or ".", exist_ok=True)
        except Exception:
            pass
        try:
            state_idx = int(self._resolve_receptor_export_state(rec))
        except Exception:
            state_idx = 1
        polymer_lines = []
        component_blocks = []
        notes = []
        tmp_paths = []
        try:
            # peptide caps (ACE/NME...) belong to their chain, not to the components exported after it
            polymer_sel = f"{rec_sel} and (polymer or resn {OPENMM_PEPTIDE_CAPS_SEL})"
            try:
                polymer_count = int(cmd.count_atoms(polymer_sel))
            except Exception:
                polymer_count = 0
            if polymer_count > 0:
                tmp_poly = outp + ".polymer.tmp.pdb"
                tmp_paths.append(tmp_poly)
                try:
                    cmd.save(tmp_poly, polymer_sel, state=state_idx)
                except Exception:
                    cmd.save(tmp_poly, polymer_sel, state=1)
                with open(tmp_poly, "r", encoding="utf-8", errors="ignore") as fh:
                    polymer_lines = [ln.rstrip("\n") for ln in fh]
            for idx, comp in enumerate(list(include_components or []), start=1):
                if str((comp or {}).get("resn", "") or "").strip().upper() in OPENMM_PEPTIDE_CAPS:
                    continue
                csel = self._dock_hetatm_component_selection(rec, comp)
                if not csel:
                    continue
                ff_cls = self._openmm_component_ff_class(comp)
                tmp_comp = outp + f".component_{idx:03d}.tmp.pdb"
                tmp_paths.append(tmp_comp)
                try:
                    cmd.save(tmp_comp, str(csel), state=state_idx)
                except Exception:
                    cmd.save(tmp_comp, str(csel), state=1)
                comp_lines = []
                hydrated_used = False
                param_paths = self._openmm_component_parameterization_paths(comp)
                hydrated_path = ""
                if str(ff_cls) != "standard":
                    hydrated_path = str(param_paths.get("hydrated_pdb", "") or "").strip()
                    if (not hydrated_path) or (not os.path.isfile(hydrated_path)):
                        smiles_hint = self._openmm_component_smiles_hint(comp)
                        if smiles_hint:
                            hyd_tmp = outp + f".component_{idx:03d}.hydrated.tmp.pdb"
                            tmp_paths.append(hyd_tmp)
                            hyd = self._openmm_build_hydrated_component_pdb(  # MD pH (default)
                                tmp_comp,
                                hyd_tmp,
                                comp,
                                smiles_hint=smiles_hint,
                            )
                            if bool(hyd.get("ok", False)) and os.path.isfile(hyd_tmp):
                                hydrated_path = str(hyd_tmp)
                read_path = hydrated_path if hydrated_path and os.path.isfile(hydrated_path) else tmp_comp
                with open(read_path, "r", encoding="utf-8", errors="ignore") as fh:
                    comp_lines = [ln.rstrip("\n") for ln in fh]
                hydrated_used = bool(read_path != tmp_comp)
                if hydrated_used:
                    notes.append(
                        f"Using hydrated crystal-ligand block for {self._format_dock_hetatm_component(comp)} during OpenMM export."
                    )
                clean = sanitize_pdb_conect_for_standalone_components(comp_lines, [comp])
                removed = int(clean.get("removed_links", 0) or 0)
                if removed > 0:
                    notes.append(
                        f"Removed {removed} external CONECT link(s) from {self._format_dock_hetatm_component(comp)} during OpenMM export."
                    )
                component_blocks.append(list(clean.get("lines", []) or []))
            composed = compose_openmm_input_pdb(polymer_lines, component_blocks)
            out_lines = list(composed.get("lines", []) or [])
            atom_count = int(composed.get("atom_count", 0) or 0)
            if atom_count <= 0:
                return {"ok": False, "error": "OpenMM export produced no atoms.", "notes": list(notes)}
            with open(outp, "w", encoding="utf-8") as fh:
                for line in out_lines:
                    fh.write(str(line) + "\n")
            notes.append(
                f"OpenMM input prepared: atoms={atom_count}, ligand_conect={int(composed.get('conect_count', 0) or 0)}"
            )
            if composed.get("added_oxt"):
                notes.append("Added the missing C-terminal OXT to " + ", ".join(composed["added_oxt"][:8]))
            if composed.get("renamed_atoms"):
                notes.append("Gave unique atom names to " + ", ".join(composed["renamed_atoms"][:8])
                             + " (repeated names would merge atoms in OpenMM)")
            return {"ok": True, "notes": list(notes)}
        except Exception as e:
            return {"ok": False, "error": f"Failed building OpenMM input PDB: {e}", "notes": list(notes)}
        finally:
            for path in list(tmp_paths or []):
                try:
                    if path and os.path.isfile(path):
                        os.remove(path)
                except Exception:
                    pass
    def _openmm_resolve_selected_component_xml_paths(self, receptor_obj):
        rec = str(receptor_obj or "").strip()
        if not rec:
            return []
        use_keys = set(self._openmm_ligand_xml_selected_keys.get(rec, []) or [])
        export_keys = {
            self._openmm_component_uid(c)
            for c in list(self._openmm_selected_components(rec) or [])
            if str(self._openmm_component_uid(c) or "").strip()
        }
        use_keys.update(export_keys)
        if not use_keys:
            return []
        all_comps = list(self._openmm_detect_ligand_candidates(rec) or [])
        selected_comps = [c for c in all_comps if self._openmm_component_uid(c) in use_keys]
        plan = self._openmm_component_template_plan(selected_comps)
        return list(plan.get("paths", []) or [])
    def _resolve_openmm_ligand_xml_paths(self, receptor_obj=""):
        out = []
        seen = set()
        txt = ""
        if hasattr(self, "edit_openmm_ligand_xml"):
            try:
                txt = str(self.edit_openmm_ligand_xml.text() or "").strip()
            except Exception:
                txt = ""
        if not txt and hasattr(self, "edit_abfe_ligand_xml"):
            try:
                txt = str(self.edit_abfe_ligand_xml.text() or "").strip()
            except Exception:
                txt = ""
        for p in list(self._openmm_parse_xml_path_list(txt) or []):
            if not os.path.isfile(p):
                continue
            kind = self._openmm_xml_kind(p)
            if kind == "system":
                ff_alt = self._openmm_guess_forcefield_xml_from_system(p)
                if ff_alt and (ff_alt not in seen):
                    seen.add(ff_alt)
                    out.append(ff_alt)
                    # Prefer ForceField XML for OpenMM workflow inputs.
                    continue
            if p in seen:
                continue
            seen.add(p)
            out.append(p)
        for p in list(self._openmm_resolve_selected_component_xml_paths(receptor_obj) or []):
            if p in seen:
                continue
            seen.add(p)
            out.append(p)
        xmlf = str(getattr(self, "_parameterized_ligand_xml", "") or "").strip()
        if xmlf and os.path.isfile(xmlf):
            if self._openmm_xml_kind(xmlf) == "system":
                ff_alt = self._openmm_guess_forcefield_xml_from_system(xmlf)
                if ff_alt and (ff_alt not in seen):
                    out.append(ff_alt)
                    seen.add(ff_alt)
                    return out
            if xmlf not in seen:
                out.append(xmlf)
                seen.add(xmlf)
        return out
    def _openmm_set_ligand_xml_paths(self, xml_paths):
        paths = []
        seen = set()
        for p in list(xml_paths or []):
            sp = str(p or "").strip()
            if (not sp) or (sp in seen):
                continue
            seen.add(sp)
            paths.append(sp)
        text = "; ".join(paths)
        if hasattr(self, "edit_openmm_ligand_xml"):
            try:
                self.edit_openmm_ligand_xml.setText(text)
            except Exception:
                pass
        if hasattr(self, "edit_abfe_ligand_xml"):
            try:
                self.edit_abfe_ligand_xml.setText(text)
            except Exception:
                pass
        if len(paths) == 1:
            try:
                self._parameterized_ligand_xml = str(paths[0])
            except Exception:
                pass
        self._update_ligand_prep_outputs_label()
        self._openmm_update_ligand_status()
    def _openmm_update_ligand_status(self):
        if not hasattr(self, "lbl_openmm_ligand_status"):
            return
        obj = str(self._openmm_current_object() or "").strip()
        xml_paths = list(self._resolve_openmm_ligand_xml_paths(obj) or [])
        xml_txt = (
            f"{len(xml_paths)} xml(s): " + ", ".join(os.path.basename(x) for x in xml_paths[:3])
            + (" ..." if len(xml_paths) > 3 else "")
        ) if xml_paths else "none"
        if (not obj) or (not self._pymol_object_exists(obj)):
            self.lbl_openmm_ligand_status.setText(f"Ligand status: object not selected | XML={xml_txt}")
            return
        cands = self._openmm_detect_ligand_candidates(obj)
        if cands:
            top = cands[0]
            n_std = 0
            n_need = 0
            for c in cands:
                if self._openmm_component_ff_class(c) == "standard":
                    n_std += 1
                else:
                    n_need += 1
            self.lbl_openmm_ligand_status.setText(
                "Ligand detected: "
                f"{str(top.get('resn', 'UNK'))} {str(top.get('chain', '-') or '-')}:{str(top.get('resi', '?'))} "
                f"(candidates={len(cands)}, standard={n_std}, needs_param={n_need}) | XML={xml_txt}"
            )
        else:
            self.lbl_openmm_ligand_status.setText(
                f"Ligand status: no obvious non-polymer ligand detected | XML={xml_txt}"
            )
    def _openmm_selected_components(self, receptor_obj):
        comps = list(self._collect_receptor_hetatm_components(receptor_obj) or [])
        if not comps:
            return []
        keep_w = bool(hasattr(self, "cb_openmm_keep_waters") and self.cb_openmm_keep_waters.isChecked())
        keep_i = bool(hasattr(self, "cb_openmm_keep_ions") and self.cb_openmm_keep_ions.isChecked())
        keep_c = bool(hasattr(self, "cb_openmm_keep_cofactors") and self.cb_openmm_keep_cofactors.isChecked())
        rec_key = str(receptor_obj or "").strip()
        cached = set(self._openmm_hetatm_selection_cache.get(rec_key, []) or [])
        if cached:
            selected = [
                c for c in comps
                if (
                    self._dock_hetatm_component_cache_key(c) in cached
                    or str(c.get("key", "")) in cached
                )
            ]
            return selected
        out = []
        for c in comps:
            cat = str(c.get("category", "")).strip().lower()
            if cat == "water" and keep_w:
                out.append(c)
            elif cat == "ion" and keep_i:
                out.append(c)
            elif cat == "cofactor" and keep_c:
                out.append(c)
        return out
    def _openmm_update_component_summary(self):
        if not hasattr(self, "lbl_openmm_components"):
            return
        obj = str(self._openmm_current_object() or "").strip()
        if (not obj) or (not self._pymol_object_exists(obj)):
            self.lbl_openmm_components.setText("Components: select a structure object.")
            return
        all_comps = list(self._collect_receptor_hetatm_components(obj) or [])
        sel_comps = list(self._openmm_selected_components(obj) or [])
        cnt_all = collections.Counter(str(c.get("category", "")).lower() for c in all_comps)
        cnt_sel = collections.Counter(str(c.get("category", "")).lower() for c in sel_comps)
        self.lbl_openmm_components.setText(
            "Components selected for export: "
            f"cofactors={int(cnt_sel.get('cofactor', 0))}/{int(cnt_all.get('cofactor', 0))}, "
            f"ions={int(cnt_sel.get('ion', 0))}/{int(cnt_all.get('ion', 0))}, "
            f"waters={int(cnt_sel.get('water', 0))}/{int(cnt_all.get('water', 0))}."
        )
    def _on_openmm_customize_components(self):
        obj = str(self._openmm_current_object() or "").strip()
        if (not obj) or (not self._pymol_object_exists(obj)):
            QtWidgets.QMessageBox.warning(self, "OpenMM", "Select a valid structure object first.")
            return
        comps = list(self._collect_receptor_hetatm_components(obj) or [])
        if not comps:
            QtWidgets.QMessageBox.information(self, "OpenMM", "No non-polymer components detected.")
            return
        out = self._prompt_dock_hetatm_selection(
            receptor_obj=obj,
            components=comps,
            flow_label="openmm",
            cache_dict=self._openmm_hetatm_selection_cache,
            allow_cached_auto=False,
        )
        if bool(out.get("cancelled", False)):
            return
        self._openmm_update_component_summary()
        self._openmm_update_ligand_status()
    def _openmm_sync_object_to_analysis_context(self, obj_name):
        obj = str(obj_name or "").strip()
        if not obj:
            return
        self.loaded_object = obj
        self._traj_topology_object = obj
        try:
            self._populate_limit_combo()
        except Exception:
            pass
        try:
            if hasattr(self, "structure_combo"):
                idx = self.structure_combo.findText(obj)
                if idx >= 0:
                    self.structure_combo.setCurrentIndex(idx)
                else:
                    self.structure_combo.setCurrentText(obj)
        except Exception:
            pass
