            self.spin_redock_site_rmsd_max.setEnabled(self.cb_redock_site_qc.isChecked())
            self.cb_redock_site_qc.toggled.connect(self.spin_redock_site_rmsd_max.setEnabled)
            row_site_qc.addWidget(self.spin_redock_site_rmsd_max)
