    def _redock_modeler_mutation_label_map(self):
        out = {}
        runs = list(getattr(self, "_modeler_last_mutation_batch_runs", []) or [])
        for idx, rr in enumerate(list(runs), start=1):
            if not isinstance(rr, dict):
                continue
            muts = [str(x).strip() for x in list((rr or {}).get("mutations", []) or []) if str(x or "").strip()]
            if not muts:
                continue
            label = f"Mutant_{int(idx):03d}"
            out[str(label)] = ",".join(muts)
        return out
    def _redock_modeler_mutation_object_map(self):
        out = {}
        runs = list(getattr(self, "_modeler_last_mutation_batch_runs", []) or [])
        for rr in list(runs or []):
            if not isinstance(rr, dict):
                continue
            obj = str((rr or {}).get("output_object", "") or "").strip()
            muts = [str(x).strip() for x in list((rr or {}).get("mutations", []) or []) if str(x or "").strip()]
            if obj and muts:
                out[str(obj)] = ",".join(muts)
        out_to_run = dict(getattr(self, "_modeler_output_to_run", {}) or {})
        for obj, run_rec in list(out_to_run.items()):
            if not isinstance(run_rec, dict):
                continue
            obj_name = str(obj or "").strip()
            if not obj_name:
                continue
            muts = [str(x).strip() for x in list((run_rec or {}).get("mutations", []) or []) if str(x or "").strip()]
            if muts:
                out[str(obj_name)] = ",".join(muts)
        return out
    def _redock_mutations_for_label(self, mutant_label):
        label = str(mutant_label or "").strip()
        if not label:
            return ""
        by_label = dict(self._redock_modeler_mutation_label_map() or {})
        txt = str(by_label.get(label, "") or "").strip()
        if txt:
            return txt

        by_obj = dict(self._redock_modeler_mutation_object_map() or {})
        run_map = dict(getattr(self, "_redock_last_runs", {}) or {})
        run_info = dict(run_map.get(label, {}) or {})
        obj_candidates = []
        for key in ("source_receptor", "receptor_object"):
            obj = str((run_info or {}).get(key, "") or "").strip()
            if obj:
                obj_candidates.append(obj)
        for mem in list((run_info or {}).get("member_runs", []) or []):
            if not isinstance(mem, dict):
                continue
            for key in ("source_receptor", "receptor_object"):
                obj = str((mem or {}).get(key, "") or "").strip()
                if obj:
                    obj_candidates.append(obj)
        muts = []
        seen = set()
        for obj in list(obj_candidates or []):
            mm = str(by_obj.get(str(obj), "") or "").strip()
            if (not mm) or (mm in seen):
                continue
            seen.add(mm)
            muts.append(mm)
        if muts:
            return "; ".join(muts)
        return ""
    def _redock_enrich_comparison_rows_with_mutations(self, rows):
        out = []
        for rr in list(rows or []):
            if not isinstance(rr, dict):
                continue
            row = dict(rr or {})
            mut_label = str((row or {}).get("mutant_label", "") or "").strip()
            mut_text = str((row or {}).get("mutations", "") or "").strip()
            if (not mut_text) and mut_label:
                mut_text = str(self._redock_mutations_for_label(mut_label) or "").strip()
            row["mutations"] = str(mut_text)
            out.append(row)
        return list(out)
    def _redock_comparison_effect_score(self, row):
        rr = dict(row or {}) if isinstance(row, dict) else {}
        try:
            da = float(rr.get("delta_affinity_kcal", np.nan))
        except Exception:
            da = float("nan")
        try:
            dr = float(rr.get("delta_rmsd_a", np.nan))
        except Exception:
            dr = float("nan")
        score = 0.0
        if np.isfinite(da):
            score += abs(float(da))
        if np.isfinite(dr):
            score += abs(float(dr))
        cls = str(rr.get("classification", "") or "").strip().lower()
        if cls.startswith("resistant"):
            score *= 3.0
        elif cls.startswith("impacted"):
            score *= 2.0
        elif cls.startswith("sensitive"):
            score *= 1.5
        return float(score)
    def _redock_sort_comparison_rows(self, rows):
        rows_local = [dict(r or {}) for r in list(rows or []) if isinstance(r, dict)]
        return sorted(
            rows_local,
            key=lambda rr: (
                -float(self._redock_comparison_effect_score(rr)),
                str((rr or {}).get("mutant_label", "") or "").lower(),
            ),
        )
    def _populate_redocking_comparison_table(self, comparison_rows):
        rows_enriched = self._redock_enrich_comparison_rows_with_mutations(comparison_rows)
        rows_sorted = self._redock_sort_comparison_rows(rows_enriched)
        self._redock_last_comparison_rows = list(rows_sorted)
        if not hasattr(self, "tbl_redock_compare"):
            return

        def _fmt(v):
            try:
                f = float(v)
            except Exception:
                return "n/a"
            return f"{float(f):.3f}" if np.isfinite(f) else "n/a"

        cls_colors = {
            "resistant-like": "#f8d7da",
            "impacted (mixed effect)": "#fff3cd",
            "neutral-like": "#e2e3e5",
            "sensitive-like": "#d1f2eb",
        }
        self.tbl_redock_compare.blockSignals(True)
        self.tbl_redock_compare.setRowCount(0)
        for i, rr in enumerate(list(rows_sorted or [])):
            self.tbl_redock_compare.insertRow(i)
            mut_label = str((rr or {}).get("mutant_label", "") or "").strip()
            mut_text = str((rr or {}).get("mutations", "") or "").strip()
            cls = str((rr or {}).get("classification", "") or "").strip()
            values = [
                str(mut_label),
                str(mut_text),
                str(cls),
                _fmt((rr or {}).get("wt_affinity_kcal", np.nan)),
                _fmt((rr or {}).get("wt_rmsd_a", np.nan)),
                _fmt((rr or {}).get("mut_affinity_kcal", np.nan)),
                _fmt((rr or {}).get("mut_rmsd_a", np.nan)),
                _fmt((rr or {}).get("delta_affinity_kcal", np.nan)),
                _fmt((rr or {}).get("delta_rmsd_a", np.nan)),
                str((rr or {}).get("confidence_effect", "") or ""),
                str((rr or {}).get("confidence_sampling", "") or ""),
                str((rr or {}).get("redocking_quality", "") or ""),
            ]
            for j, vv in enumerate(values):
                item = QtWidgets.QTableWidgetItem(str(vv))
                if j == 0:
                    item.setData(QtCore.Qt.UserRole, str(mut_label))
                if j == 2:
                    c_hex = str(cls_colors.get(str(cls).lower(), "") or "").strip()
                    if c_hex:
                        try:
                            item.setBackground(QtGui.QBrush(QtGui.QColor(c_hex)))
                        except Exception:
                            pass
                self.tbl_redock_compare.setItem(i, j, item)
        if rows_sorted:
            self.tbl_redock_compare.selectRow(0)
        self.tbl_redock_compare.blockSignals(False)
        try:
            self.tbl_redock_compare.setVisible(True)
            self.tbl_redock_compare.resizeColumnsToContents()
        except Exception:
            pass
        has_rows = bool(rows_sorted)
        for btn_name in ("btn_redock_focus_mutant", "btn_redock_export_compare_csv"):
            btn = getattr(self, btn_name, None)
            if btn is not None:
                try:
                    btn.setEnabled(has_rows)
                except Exception:
                    pass
        self._refresh_redocking_results_popup_tables()
    def _selected_redock_comparison_row(self):
        rows = list(getattr(self, "_redock_last_comparison_rows", []) or [])
        if not rows:
            return None, -1
        row = int(self.tbl_redock_compare.currentRow()) if hasattr(self, "tbl_redock_compare") else -1
        if row < 0 and rows:
            row = 0
        if row < 0 or row >= len(rows):
            return None, -1
        return dict(rows[row]), int(row)
    def _redock_focus_results_for_system(self, system_label, silent=False):
        label = str(system_label or "").strip()
        if (not label) or (not hasattr(self, "tbl_redock_results")):
            return False
        rows = list(getattr(self, "_redock_results", []) or [])
        best_idx = -1
        best_rank = 10**9
        for i, rr in enumerate(list(rows or [])):
            if str((rr or {}).get("system", "") or "").strip() != label:
                continue
            try:
                rank = int((rr or {}).get("rank", i + 1) or (i + 1))
            except Exception:
                rank = int(i + 1)
            if int(rank) < int(best_rank):
                best_rank = int(rank)
                best_idx = int(i)
        if best_idx < 0:
            if not bool(silent):
                QtWidgets.QMessageBox.warning(self, "Redocking", f"No redocking result rows found for {label}.")
            return False
        try:
            self.tbl_redock_results.selectRow(int(best_idx))
        except Exception:
            return False
        try:
            self._on_redock_load_selected_pose(silent=True)
        except Exception:
            pass
        return True
    def _on_redock_compare_selection_changed(self):
        self._sync_redocking_popup_selection_from_main()
        try:
            self._on_redock_compare_focus_selected_mutant(silent=True)
        except Exception:
            pass
    def _on_redock_compare_focus_selected_mutant(self, silent=False):
        row, _idx = self._selected_redock_comparison_row()
        if not isinstance(row, dict):
            if not bool(silent):
                QtWidgets.QMessageBox.warning(self, "Redocking", "Select a mutant from the summary table first.")
            return
        mut_label = str((row or {}).get("mutant_label", "") or "").strip()
        if not mut_label:
            if not bool(silent):
                QtWidgets.QMessageBox.warning(self, "Redocking", "Selected summary row has no mutant label.")
            return
        self._redock_focus_results_for_system(mut_label, silent=bool(silent))
    def _on_redock_export_comparison_csv(self):
        rows = list(getattr(self, "_redock_last_comparison_rows", []) or [])
        if not rows:
            run_map = dict(getattr(self, "_redock_last_runs", {}) or {})
            rows = list(redock_build_comparison_rows(run_map) or [])
            rows = list(self._redock_enrich_comparison_rows_with_mutations(rows) or [])
            self._redock_last_comparison_rows = list(rows)
        if not rows:
            QtWidgets.QMessageBox.warning(
                self,
                "Redocking",
                "No mutant comparison rows available. Run WT+mutant redocking first.",
            )
            return
        default_path = str(getattr(self, "_redock_last_summary_csv", "") or "").strip()
        if not default_path:
            default_path = str(self._redock_default_summary_csv_path())
        out_csv, _ = QtWidgets.QFileDialog.getSaveFileName(
            self,
            "Export Redocking Comparison CSV",
            default_path,
            "CSV (*.csv)",
        )
        if not out_csv:
            return
        out_path = str(out_csv)
        if not out_path.lower().endswith(".csv"):
            out_path = f"{out_path}.csv"
        saved = str(redock_write_comparison_summary_csv(out_path, rows) or "")
        if not saved:
            QtWidgets.QMessageBox.critical(self, "Redocking", "Failed to export comparison CSV.")
            return
        self._redock_last_summary_csv = str(saved)
        QtWidgets.QMessageBox.information(self, "Redocking", f"Comparison CSV exported:\n{saved}")
