    def _redock_isolate_selected_system_view(self, selected_label):
        sel_label = str(selected_label or "").strip()
        views = dict(getattr(self, "_redock_traj_views", {}) or {})
        if not views:
            return
        actions = []
        for label, info in list(views.items()):
            lab = str(label or "").strip()
            ii = dict(info or {}) if isinstance(info, dict) else {}
            traj_obj = str(ii.get("traj_object", "") or "").strip()
            combo_obj = str(ii.get("combo_object", "") or "").strip()
            frame_obj = str(ii.get("frame_object", "") or "").strip()
            pose_frame_obj = str(ii.get("pose_frame_object", "") or "").strip()
            try:
                n_states = int(ii.get("n_states", 0) or 0)
            except Exception:
                n_states = 0
            keep_label = bool(sel_label) and (lab == sel_label)
            prefer_traj_object = bool((not combo_obj) and traj_obj and (int(n_states) > 1))
            if prefer_traj_object:
                actions.append({"action": ("enable" if keep_label else "disable"), "object": str(traj_obj)})
                if frame_obj:
                    actions.append({"action": "disable", "object": str(frame_obj)})
                if pose_frame_obj:
                    actions.append({"action": ("enable" if keep_label else "disable"), "object": str(pose_frame_obj)})
                continue
            if traj_obj:
                actions.append({"action": "disable", "object": str(traj_obj)})
            for obj in (combo_obj, frame_obj, pose_frame_obj):
                if not obj:
                    continue
                actions.append({"action": ("enable" if keep_label else "disable"), "object": str(obj)})
        if not actions:
            return
        try:
            known = set(cmd.get_names("objects"))
        except Exception:
            known = None
        self._redock_apply_object_actions(actions, known_objects=known)
    def _on_redock_load_selected_pose(self, silent=False):
        rows = list(getattr(self, "_redock_results", []) or [])
        if not rows:
            return
        row_idx = int(self.tbl_redock_results.currentRow()) if hasattr(self, "tbl_redock_results") else -1
        row_rec = {}
        if 0 <= int(row_idx) < int(len(rows)):
            try:
                row_rec = dict(rows[int(row_idx)] or {})
            except Exception:
                row_rec = {}
        selected_label = str((row_rec or {}).get("system", "") or "").strip()
        if selected_label:
            try:
                self._redock_isolate_selected_system_view(selected_label)
            except Exception:
                pass
        try:
            known = set(cmd.get_names("objects"))
        except Exception:
            known = set()
        payload = redock_run_selected_pose_runtime(
            rows=list(rows or []),
            row_index=int(row_idx),
            known_objects=set(known or set()),
            preview_object="redock_selected_pose_preview",
            default_action="disable",
            focus_zoom_buffer_a=6.0,
            hide_all_pose_objects_fn=self._redock_hide_all_pose_objects,
            hide_all_runtime_receptors_fn=self._redock_hide_all_runtime_receptors,
            delete_object_fn=lambda obj: cmd.delete(obj),
            create_object_fn=lambda obj, sel, src_state, dst_state: cmd.create(
                obj, sel, int(src_state), int(dst_state)
            ),
            model_selection_fn=self._pymol_model_selection,
            apply_ball_and_stick_style_fn=self._apply_ball_and_stick_style,
            apply_element_colors_fn=self._apply_element_colors,
            group_fn=lambda group_name, members: cmd.group(group_name, members),
            set_traj_frame_fn=self._redock_set_traj_frame,
            get_known_objects_fn=lambda: set(cmd.get_names("objects")),
            apply_scene_actions_fn=self._redock_apply_scene_actions,
            render_reference_context_fn=self._redock_render_reference_context,
            orient_fn=lambda sel: cmd.orient(sel),
            zoom_fn=lambda sel, buf: cmd.zoom(sel, float(buf)),
        )
        if bool(payload.get("ok", False)):
            return
        warning_payload = redock_resolve_selected_pose_warning_message(
            dict(payload or {}),
            silent=bool(silent),
        )
        if bool(warning_payload.get("show_warning", False)):
            QtWidgets.QMessageBox.warning(self, "Redocking", str(warning_payload.get("warning", "") or ""))
    def _redock_apply_selected_interaction_post_payload(self, post_payload):
        plan = redock_build_selected_interaction_post_apply_plan(
            post_payload=(dict(post_payload or {}) if isinstance(post_payload, dict) else {}),
            default_complex_object="redock_selected_complex",
        )
        for op in list((plan or {}).get("operations", []) or []):
            kind = str((op or {}).get("kind", "") or "").strip().lower()
            try:
                if kind == "set_attr":
                    name = str((op or {}).get("name", "") or "").strip()
                    if not name:
                        continue
                    setattr(self, name, (op or {}).get("value", None))
                    continue
                if kind == "set_text":
                    widget_name = str((op or {}).get("widget", "") or "").strip()
                    if (not widget_name) or (not hasattr(self, widget_name)):
                        continue
                    getattr(self, widget_name).setText(str((op or {}).get("value", "") or ""))
            except Exception:
                pass
