    def _redock_prepare_base_payload_checked(self):
        payload = redock_prepare_base_runtime(
            reference_obj_fn=(
                (lambda: self.cmb_redock_reference_obj.currentText())
                if hasattr(self, "cmb_redock_reference_obj")
                else None
            ),
            wt_obj_fn=(
                (lambda: self.cmb_redock_wt_obj.currentText())
                if hasattr(self, "cmb_redock_wt_obj")
                else None
            ),
            use_modeler_wt_fn=(
                (lambda: bool(getattr(self, "cb_redock_use_modeler_wt", None) and self.cb_redock_use_modeler_wt.isChecked()))
            ),
            modeler_wt_obj_fn=(lambda: str(getattr(self, "_modeler_last_model_object", "") or "")),
            ref_fields_fn=self._redock_get_reference_fields,
            run_mutant_fn=(lambda: bool(getattr(self, "cb_redock_run_mutant", None) and self.cb_redock_run_mutant.isChecked())),
            mutant_obj_fn=self._redock_selected_mutant_object_for_base_payload,
            mutant_systems_fn=self._redock_collect_mutant_systems_for_base_payload,
            params_fn=lambda: {
                "ph": float(self.spin_redock_ph.value()) if hasattr(self, "spin_redock_ph") else 7.4,
                "exhaustiveness": int(self.spin_redock_exhaust.value()) if hasattr(self, "spin_redock_exhaust") else 48,
                "num_modes": int(self.spin_redock_modes.value()) if hasattr(self, "spin_redock_modes") else 40,
                "energy_range": float(self.spin_redock_erange.value()) if hasattr(self, "spin_redock_erange") else 6.0,
                "min_rmsd": float(self.spin_redock_minrmsd.value()) if hasattr(self, "spin_redock_minrmsd") else 0.5,
                "autobox_add": float(self.spin_redock_padding.value()) if hasattr(self, "spin_redock_padding") else 4.0,
                "repeats": int(self.spin_redock_repeats.value()) if hasattr(self, "spin_redock_repeats") else 3,
                "seed0": int(self.spin_redock_seed0.value()) if hasattr(self, "spin_redock_seed0") else 0,
            },
            grid_from_reference_fn=self._redock_grid_from_reference,
        )
        if not bool(payload.get("ok", False)):
            QtWidgets.QMessageBox.warning(
                self,
                "Redocking",
                str(payload.get("error", "Invalid redocking setup.") or "Invalid redocking setup."),
            )
            return {}

        base_payload = dict(payload.get("payload", {}) or {})
        self._redock_last_reference_obj = str(base_payload.get("ref_obj", ""))
        self._redock_last_ref_fields = tuple(base_payload.get("ref_fields", ()))
        center = base_payload.get("center", None)
        size = base_payload.get("size", None)
        if center is not None and size is not None:
            self._show_redocking_grid(center, size, zoom=True)
        model_obj = str(payload.get("modeler_wt_obj", "") or "").strip()
        if bool(payload.get("used_modeler_wt", False)) and model_obj:
            if hasattr(self, "cmb_redock_wt_obj") and self.cmb_redock_wt_obj.findText(model_obj) >= 0:
                self.cmb_redock_wt_obj.setCurrentText(model_obj)
        return dict(base_payload or {})
