    def _redock_prepare_runtime_systems_checked(self, ref_obj, systems, params):
        align_rmsd_max = 4.0
        site_rmsd_max = 2.0
        try:
            if hasattr(self, "spin_redock_align_rmsd_max"):
                align_rmsd_max = float(self.spin_redock_align_rmsd_max.value())
        except Exception:
            align_rmsd_max = 4.0
        try:
            if hasattr(self, "spin_redock_site_rmsd_max"):
                site_rmsd_max = float(self.spin_redock_site_rmsd_max.value())
        except Exception:
            site_rmsd_max = 2.0
        payload = redock_prepare_runtime_systems_runtime(
            systems=list(systems or []),
            params=dict(params or {}),
            use_modeler_ensemble=bool(
                getattr(self, "cb_redock_use_mc_ensemble", None)
                and self.cb_redock_use_mc_ensemble.isChecked()
            ),
            align_to_ref=bool(getattr(self, "cb_redock_align_to_ref", None) and self.cb_redock_align_to_ref.isChecked()),
            ref_obj=str(ref_obj or ""),
            collect_modeler_ensemble_fn=self._redock_collect_mc_ensemble_systems,
            align_receptor_to_reference_fn=self._redock_align_receptor_to_reference,
            align_rmsd_max_a=float(align_rmsd_max),
            site_qc_enabled=bool(getattr(self, "cb_redock_site_qc", None) and self.cb_redock_site_qc.isChecked()),
            site_rmsd_max_a=float(site_rmsd_max),
            site_qc_min_anchor_matches=4,
            site_anchor_cutoff_a=float(self._redock_site_qc_anchor_cutoff_a()),
        )
        if not bool(payload.get("ok", False)) and getattr(self, "_redock_mc_deferred", False):
            return {}                          # sampling went to the background: resumed when it ends
        if not bool(payload.get("ok", False)):
            err_txt = str(payload.get("error", "unknown error") or "unknown error")
            hint = ""
            if "alignment RMSD too high" in err_txt:
                hint = (
                    "\n\nTip: increase 'Max alignment RMSD (A)' in Redocking settings "
                    "or disable alignment for exploratory runs."
                )
            elif ("local site RMSD too high" in err_txt) or ("local site QC" in err_txt):
                hint = (
                    "\n\nTip: increase 'Max site CA RMSD (A)' if your ensemble has real local pocket motion, "
                    "or disable local binding-site QC for exploratory runs."
                )
            QtWidgets.QMessageBox.critical(
                self,
                "Redocking",
                f"Failed to prepare redocking runtime systems: {err_txt}{hint}",
            )
            return {}
        for note in list(payload.get("align_notes", []) or []):
            try:
                self._append_debug_log(f"Redocking prep: {str(note)}")
            except Exception:
                pass
        for note in list(payload.get("site_qc_notes", []) or []):
            try:
                self._append_debug_log(f"Redocking prep: {str(note)}")
            except Exception:
                pass
        return dict(payload or {})
