    def _show_alphafold_dialog(self):
        try:
            self._af_gpu_info(refresh=True)
            self._refresh_af_source_combo()
            self._on_af_engine_changed()
            self._on_af_exec_mode_changed()
            self._on_af_relax_toggled(bool(self.cb_af_amber_relax.isChecked()))
            self._update_af_tool_status()
            self._fit_dialog_to_screen(self._af_dialog)
            self._af_dialog.show()
            self._af_dialog.raise_()
            self._af_dialog.activateWindow()
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "Error", f"Failed to open AlphaFold tools: {e}")
    def _af_current_engine(self):
        try:
            return str(self.cmb_af_engine.currentData() or AF_ENGINE_COLABFOLD)
        except Exception:
            return AF_ENGINE_COLABFOLD
    def _af_is_af3_engine(self):
        return self._af_current_engine() in {AF_ENGINE_AF3_LOCAL, AF_ENGINE_AF3_SERVER}
    def _af_af3_model_dir(self):
        try:
            return os.path.expanduser(str(self.edit_af3_model_dir.text() or "").strip())
        except Exception:
            return ""
    def _af_af3_db_dir(self):
        try:
            return os.path.expanduser(str(self.edit_af3_db_dir.text() or "").strip())
        except Exception:
            return ""
    def _af_af3_docker_image(self):
        try:
            return str(self.edit_af3_docker_image.text() or "alphafold3").strip() or "alphafold3"
        except Exception:
            return "alphafold3"
    def _af_af3_seed(self):
        try:
            return max(1, int(self.spin_af3_seed.value()))
        except Exception:
            return 1
    def _af_current_af3_chain_id(self):
        chain_id = "A"
        try:
            raw = str(self.cmb_af_chain.currentData() or "").strip()
            if raw and raw.upper() not in {"MAIN", "SYNTHETIC_MAIN"}:
                chain_id = af_sanitize_af3_chain_id(raw, 0)
        except Exception:
            chain_id = "A"
        return chain_id
    def _af_docker_path(self):
        return shutil.which("docker")
    def _af_af3_local_ready(self, deep_probe=False):
        docker_path = self._af_docker_path()
        model_dir = self._af_af3_model_dir()
        db_dir = self._af_af3_db_dir()
        model_ok = bool(model_dir) and os.path.isdir(model_dir)
        db_ok = bool(db_dir) and os.path.isdir(db_dir)
        gpu_required = True
        try:
            gpu_required = bool(self.cb_af3_gpu.isChecked())
        except Exception:
            gpu_required = True
        gpu_ok = True
        gpu_reason = "GPU not requested"
        if gpu_required:
            # Official AF3 Docker execution expects NVIDIA GPU access through Docker.
            gpu_ok, gpu_reason = self._af_local_gpu_available(deep=bool(deep_probe))
        ready = bool(docker_path) and model_ok and db_ok and bool(gpu_ok)
        missing = []
        if not docker_path:
            missing.append("Docker executable")
        if not model_ok:
            missing.append("AF3 model parameters")
        if not db_ok:
            missing.append("AF3 public databases")
        if gpu_required and not gpu_ok:
            missing.append(f"GPU ({gpu_reason})")
        return ready, missing, {
            "docker": docker_path or "",
            "model_dir": model_dir,
            "db_dir": db_dir,
            "gpu_ok": gpu_ok,
            "gpu_reason": gpu_reason,
        }
    def _on_af_engine_changed(self, *_args):
        engine = self._af_current_engine()
        is_af3 = engine in {AF_ENGINE_AF3_LOCAL, AF_ENGINE_AF3_SERVER}
        profile = af_engine_profile(engine)
        hint = profile.get("short", "")
        if engine == AF_ENGINE_AF3_LOCAL:
            hint += " Local execution requires Docker, NVIDIA GPU support, AF3 model parameters, and public databases."
            try:
                self.edit_af_colab_url.setText(AF3_SERVER_URL)
            except Exception:
                pass
        elif engine == AF_ENGINE_AF3_SERVER:
            hint += " This mode prepares AF3 JSON and opens AlphaFold Server; local Docker settings are optional."
            try:
                self.edit_af_colab_url.setText(AF3_SERVER_URL)
            except Exception:
                pass
        else:
            try:
                if str(self.edit_af_colab_url.text() or "").strip() in {AF3_SERVER_URL, "https://colab.research.google.com/notebooks/empty.ipynb"}:
                    self.edit_af_colab_url.setText(COLABFOLD_NOTEBOOK_URL)
            except Exception:
                pass
        try:
            self.lbl_af_engine_hint.setText(hint)
            self.btn_af_copy_fasta.setText("Copy AF3 JSON" if is_af3 else "Copy FASTA")
            self.lbl_af_colab_url.setText("AlphaFold Server" if is_af3 else "Colab Notebook")
            self.btn_af_open_colab.setText("Open" if is_af3 else "Prepare Job")
            self._set_af_widget_visible(getattr(self, "grp_af_colabfold_settings", None), engine == AF_ENGINE_COLABFOLD)
            self._set_af_widget_visible(getattr(self, "grp_af3_settings", None), is_af3)
            self.btn_af_plot_msa.setEnabled(engine == AF_ENGINE_COLABFOLD)
        except Exception:
            pass
        self._af_update_gpu_warning()
        try:
            self._on_af_exec_mode_changed()
        except Exception:
            pass
    def _on_af_pick_af3_model_dir(self):
        cur = self._af_af3_model_dir()
        out = QtWidgets.QFileDialog.getExistingDirectory(
            self,
            "Choose AlphaFold 3 Model Parameters Directory",
            cur or os.getcwd(),
        )
        if out:
            self.edit_af3_model_dir.setText(out)
            self._update_af_tool_status()
    def _on_af_pick_af3_db_dir(self):
        cur = self._af_af3_db_dir()
        out = QtWidgets.QFileDialog.getExistingDirectory(
            self,
            "Choose AlphaFold 3 Public Databases Directory",
            cur or os.getcwd(),
        )
        if out:
            self.edit_af3_db_dir.setText(out)
            self._update_af_tool_status()
    def _af_write_af3_json_for_bundle(self, bundle):
        job_dir = str(bundle.get("job_dir") or "").strip()
        if not job_dir:
            raise ValueError("missing job directory")
        af3_input_dir = os.path.join(job_dir, "af3_input")
        af3_output_dir = os.path.join(job_dir, "af3_output")
        os.makedirs(af3_input_dir, exist_ok=True)
        os.makedirs(af3_output_dir, exist_ok=True)
        chains = af_split_protein_chains(str(bundle.get("seq") or ""))
        payload = af_build_alphafold3_input_json(
            job_name=str(bundle.get("job_name") or "af_job"),
            protein_sequences=chains,
            # a single chain keeps the chain the user picked; a complex gets A, B, C, ...
            chain_ids=[self._af_current_af3_chain_id()] if len(chains) == 1 else None,
            model_seeds=[self._af_af3_seed()],
        )
        json_path = os.path.join(af3_input_dir, "fold_input.json")
        af_write_json(payload, json_path)
        bundle["af3_json"] = json_path
        bundle["af3_output_dir"] = af3_output_dir
        self._af_last_af3_json = json_path
        self._af_last_af3_output_dir = af3_output_dir
        return json_path
    def _af_build_af3_docker_command_for_bundle(self, bundle, interactive=True):
        json_path = str(bundle.get("af3_json") or getattr(self, "_af_last_af3_json", "") or "")
        out_dir = str(bundle.get("af3_output_dir") or getattr(self, "_af_last_af3_output_dir", "") or "")
        if not json_path:
            json_path = self._af_write_af3_json_for_bundle(bundle)
            out_dir = str(bundle.get("af3_output_dir") or "")
        cmdline = af_build_alphafold3_docker_command(
            input_json=json_path,
            output_dir=out_dir or os.path.dirname(os.path.dirname(json_path)),
            model_dir=self._af_af3_model_dir(),
            db_dir=self._af_af3_db_dir(),
            image=self._af_af3_docker_image(),
            gpu=bool(self.cb_af3_gpu.isChecked()) if hasattr(self, "cb_af3_gpu") else True,
            interactive=bool(interactive),
        )
        docker_path = self._af_docker_path()
        if docker_path:
            cmdline[0] = docker_path
        return cmdline
    def _on_af_prepare_af3_json(self):
        bundle = self._af_prepare_job_bundle()
        if not bundle:
            return
        try:
            json_path = self._af_write_af3_json_for_bundle(bundle)
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "AlphaFold 3", f"Could not write AF3 JSON: {e}")
            return
        self._af_append_log("=" * 60)
        self._af_append_log("Prepared AlphaFold 3 input JSON")
        self._af_append_log(f"json: {json_path}")
        self.lbl_af_status.setText(f"AlphaFold 3 JSON prepared: {json_path}")
        try:
            QtWidgets.QMessageBox.information(self, "AlphaFold 3", f"AF3 JSON written:\n{json_path}")
        except Exception:
            pass
    def _on_af_copy_af3_command(self):
        bundle = self._af_prepare_job_bundle()
        if not bundle:
            return
        try:
            json_path = self._af_write_af3_json_for_bundle(bundle)
            cmdline = self._af_build_af3_docker_command_for_bundle(bundle, interactive=True)
            cmd_txt = af_format_shell_command(cmdline)
            cb = QtWidgets.QApplication.clipboard()
            if cb is not None:
                cb.setText(cmd_txt)
            self._af_append_log("=" * 60)
            self._af_append_log("AlphaFold 3 Docker command copied")
            self._af_append_log(f"json: {json_path}")
            self._af_append_log(cmd_txt)
            self.lbl_af_status.setText("AlphaFold 3 Docker command copied to clipboard.")
        except Exception as e:
            QtWidgets.QMessageBox.warning(self, "AlphaFold 3", f"Could not build Docker command: {e}")
    def _af_tool_path(self):
        user_val = ""
        try:
            if hasattr(self, "edit_af_bin"):
                user_val = str(self.edit_af_bin.text() or "").strip()
        except Exception:
            user_val = ""
        if user_val:
            if os.path.isabs(user_val):
                try:
                    if os.path.isfile(user_val) and (os.access(user_val, os.X_OK) or str(user_val).lower().endswith(".py")):
                        return user_val
                except Exception:
                    pass
            p = shutil.which(user_val)
            if p:
                return p
        common_bins = [
            os.path.join(sys.prefix, "bin"),
            os.path.dirname(sys.executable),
            "/opt/anaconda3/envs/bgt-openmm82/bin",
            "/opt/anaconda3/bin",
            "/opt/homebrew/bin",
            "/usr/local/bin",
        ]
        for b in common_bins:
            if not b:
                continue
            c = os.path.join(b, "colabfold_batch")
            if os.path.isfile(c) and os.access(c, os.X_OK):
                return c
        return shutil.which("colabfold_batch")
    def _af_current_exec_mode(self):
        try:
            return str(self.cmb_af_exec_mode.currentData() or "auto")
        except Exception:
            return "auto"
    def _af_gpu_info(self, refresh=False):
        # nvidia-smi can take seconds; probe once per dialog opening, not on every UI refresh
        info = getattr(self, "_af_gpu_info_cache", None)
        if refresh or not isinstance(info, dict):
            try:
                info = dict(af_detect_local_gpu() or {})
            except Exception:
                info = {"available": False, "reason": "GPU detection failed", "apple_silicon": False}
            self._af_gpu_info_cache = info
        return dict(info)
    def _af_local_gpu_available(self, deep=False):
        """
        Detect whether local ColabFold GPU execution is available: an NVIDIA/CUDA GPU.
        Apple (Metal) GPUs and CPU-only JAX do not count.
        """
        info = self._af_gpu_info(refresh=bool(deep))
        return bool(info.get("available")), str(info.get("reason") or "no local GPU detected")
    def _af_ask_gpu_fallback(self, gpu_msg):
        """Return "colab", "local" or "cancel" for a local run requested without a detected GPU."""
        box = QtWidgets.QMessageBox(self)
        box.setIcon(QtWidgets.QMessageBox.Warning)
        box.setWindowTitle(GPU_REQUIRED_TITLE)
        box.setText(f"<b>{GPU_REQUIRED_TITLE}</b>")
        box.setInformativeText(
            f"{gpu_msg}\n\nIf this computer does have an NVIDIA GPU that was not detected, "
            "you can still run locally."
        )
        btn_colab = box.addButton("Prepare for Google Colab", QtWidgets.QMessageBox.AcceptRole)
        btn_local = box.addButton("Run locally anyway", QtWidgets.QMessageBox.DestructiveRole)
        box.addButton(QtWidgets.QMessageBox.Cancel)
        box.setDefaultButton(btn_colab)
        box.exec_()
        clicked = box.clickedButton()
        if clicked is btn_colab:
            return "colab"
        if clicked is btn_local:
            return "local"
        return "cancel"
    def _af_update_gpu_warning(self):
        lbl = getattr(self, "lbl_af_gpu_warning", None)
        if lbl is None:
            return ""
        msg = ""
        try:
            msg = af_gpu_requirement_message(self._af_current_engine(), self._af_gpu_info())
        except Exception:
            msg = ""
        try:
            lbl.setText(f"<b>&#9888; {GPU_REQUIRED_TITLE}.</b> {msg}" if msg else "")
            lbl.setVisible(bool(msg))
        except Exception:
            pass
        return msg
    def _af_resolve_exec_mode(self, deep_probe=False):
        mode = self._af_current_exec_mode()
        if mode != "auto":
            return mode, ""
        engine = self._af_current_engine()
        if engine == AF_ENGINE_AF3_SERVER:
            return "colab_remote", "auto: AlphaFold 3 Server is an external handoff workflow"
        if engine == AF_ENGINE_AF3_LOCAL:
            ready, missing, meta = self._af_af3_local_ready(deep_probe=bool(deep_probe))
            if ready:
                return "local", f"auto: AF3 local Docker ready ({meta.get('gpu_reason') or 'GPU ready'})"
            why = ", ".join(missing) if missing else "local AF3 runtime not ready"
            return "colab_remote", f"auto: preparing AF3 handoff ({why})"
        cf = self._af_tool_path()
        has_gpu, reason = self._af_local_gpu_available(deep=bool(deep_probe))
        if has_gpu and cf:
            return "local", f"auto: local GPU detected ({reason})"
        if not cf:
            why = "local colabfold_batch not found"
        else:
            why = reason
        return "colab_remote", f"auto: using Google Colab ({why})"
    def _set_af_widget_visible(self, widget, visible):
        try:
            if widget is not None:
                widget.setVisible(bool(visible))
        except Exception:
            pass
    def _on_af_exec_mode_changed(self, *_args):
        mode = self._af_current_exec_mode()
        engine = self._af_current_engine()
        eff_mode, auto_note = self._af_resolve_exec_mode(deep_probe=False)
        local = (eff_mode == "local")
        remote = (eff_mode == "colab_remote")
        is_af3 = engine in {AF_ENGINE_AF3_LOCAL, AF_ENGINE_AF3_SERVER}
        is_cf = engine == AF_ENGINE_COLABFOLD
        try:
            self.edit_af_bin.setEnabled(local and is_cf)
            self.edit_af_extra_args.setEnabled(local and is_cf)
            if mode == "auto":
                if local:
                    self.btn_af_run.setText("Run AF3 Local" if is_af3 else "Run (Auto: Local GPU)")
                else:
                    self.btn_af_run.setText("Prepare AF3 Handoff" if is_af3 else "Prepare (Auto: Google Colab)")
                self.btn_af_run.setToolTip(f"Auto mode decision: {auto_note or eff_mode}")
            else:
                if is_af3:
                    self.btn_af_run.setText("Run AlphaFold 3 Local" if local else "Prepare AlphaFold 3 Handoff")
                else:
                    self.btn_af_run.setText("Run ColabFold (Local)" if local else "Prepare for Google Colab")
                self.btn_af_run.setToolTip("")
            # Local-only advanced options
            self._set_af_widget_visible(getattr(self, "lbl_af_bin", None), local and is_cf)
            self._set_af_widget_visible(getattr(self, "edit_af_bin", None), local and is_cf)
            self._set_af_widget_visible(getattr(self, "lbl_af_extra_args", None), local and is_cf)
            self._set_af_widget_visible(getattr(self, "edit_af_extra_args", None), local and is_cf)
            # Remote (Google Colab sync) options
            self._set_af_widget_visible(getattr(self, "cb_af_open_colab_on_prepare", None), remote)
            self._set_af_widget_visible(getattr(self, "lbl_af_colab_url", None), remote)
            self._set_af_widget_visible(getattr(self, "edit_af_colab_url", None), remote)
            self._set_af_widget_visible(getattr(self, "btn_af_open_colab", None), remote)
            self._set_af_widget_visible(getattr(self, "btn_af_copy_fasta", None), remote)
            self._set_af_widget_visible(getattr(self, "lbl_af_sync_folder", None), remote and is_cf)
            self._set_af_widget_visible(getattr(self, "edit_af_sync_dir", None), remote and is_cf)
            self._set_af_widget_visible(getattr(self, "btn_af_pick_sync", None), remote and is_cf)
            self._set_af_widget_visible(getattr(self, "btn_af_scan_sync", None), remote and is_cf)
            self._set_af_widget_visible(getattr(self, "btn_af_import_result", None), remote)
            self._set_af_widget_visible(getattr(self, "cb_af_auto_sync", None), remote and is_cf)
            self._set_af_widget_visible(getattr(self, "lbl_af_sync_interval", None), remote and is_cf)
            self._set_af_widget_visible(getattr(self, "spin_af_sync_interval", None), remote and is_cf)
        except Exception:
            pass
        try:
            self._update_af_tool_status()
        except Exception:
            pass
    def _on_af_relax_toggled(self, checked):
        en = bool(checked)
        try:
            self.spin_af_num_relax.setEnabled(en)
            self.cb_af_gpu_relax.setEnabled(en)
            if not en:
                self.cb_af_gpu_relax.setChecked(False)
        except Exception:
            pass
    def _on_af_open_colab_notebook(self):
        if not self._af_is_af3_engine():
            script = str(getattr(self, "_af_last_colab_script", "") or "").strip()
            if script:
                self._af_copy_colab_script_to_clipboard()
                self._af_show_colab_job_dialog(opened_url="")
                self.lbl_af_status.setText("Prepared ColabFold job shown. Prefilled Colab cell copied to clipboard.")
                return
            try:
                previous_open = bool(self.cb_af_open_colab_on_prepare.isChecked())
            except Exception:
                previous_open = False
            try:
                self.cb_af_open_colab_on_prepare.setChecked(False)
            except Exception:
                pass
            try:
                self._on_af_run_colabfold()
            finally:
                try:
                    self.cb_af_open_colab_on_prepare.setChecked(previous_open)
                except Exception:
                    pass
            script = str(getattr(self, "_af_last_colab_script", "") or "").strip()
            if script:
                self._af_copy_colab_script_to_clipboard()
                self._af_show_colab_job_dialog(opened_url="")
                self.lbl_af_status.setText("Prepared ColabFold job shown. Prefilled Colab cell copied to clipboard.")
            return
        url = ""
        try:
            url = str(self.edit_af_colab_url.text() or "").strip()
        except Exception:
            url = ""
        if not url:
            url = AF3_SERVER_URL if self._af_is_af3_engine() else COLABFOLD_NOTEBOOK_URL
        try:
            webbrowser.open(url)
            self._af_append_log(f"Opened external prediction page: {url}")
            self.lbl_af_status.setText(f"Opened external prediction page: {url}")
            if (not self._af_is_af3_engine()) and str(getattr(self, "_af_last_colab_script", "") or "").strip():
                try:
                    self._af_copy_colab_script_to_clipboard()
                    self._af_show_colab_job_dialog(opened_url=url)
                except Exception:
                    pass
        except Exception as e:
            QtWidgets.QMessageBox.warning(self, "AlphaFold", f"Could not open browser: {e}")
    def _af_copy_colab_script_to_clipboard(self):
        script = str(getattr(self, "_af_last_colab_script", "") or "")
        if not script:
            return False
        try:
            cb = QtWidgets.QApplication.clipboard()
            if cb is not None:
                cb.setText(script)
                return True
        except Exception:
            pass
        return False
    def _af_show_colab_job_dialog(self, opened_url=""):
        script = str(getattr(self, "_af_last_colab_script", "") or "")
        notebook = str(getattr(self, "_af_last_colab_notebook", "") or "")
        script_path = str(getattr(self, "_af_last_colab_script_path", "") or "")
        if not script and not notebook:
            return
        dlg = QtWidgets.QDialog(getattr(self, "_af_dialog", self))
        dlg.setWindowTitle("ColabFold Job Prepared")
        dlg.resize(900, 680)
        self._fit_dialog_to_screen(dlg, preferred_w=900, preferred_h=680, min_w=700, min_h=480)
        lay = QtWidgets.QVBoxLayout(dlg)
        msg = QtWidgets.QLabel(
            "The hosted ColabFold notebook cannot be edited automatically with local Leonardo state. "
            "Leonardo generated an edited job notebook and copied a complete pre-filled Colab cell to the clipboard. "
            "Upload the prepared .ipynb to Colab or paste/run the cell in a GPU runtime."
        )
        msg.setWordWrap(True)
        lay.addWidget(msg)
        details = []
        if opened_url:
            details.append(f"Opened URL: {opened_url}")
        if notebook:
            details.append(f"Prepared notebook: {notebook}")
        if script_path:
            details.append(f"Prepared cell file: {script_path}")
        lbl_details = QtWidgets.QLabel("\n".join(details))
        lbl_details.setTextInteractionFlags(QtCore.Qt.TextSelectableByMouse)
        lbl_details.setWordWrap(True)
        lay.addWidget(lbl_details)
        txt = QtWidgets.QPlainTextEdit(dlg)
        txt.setReadOnly(True)
        txt.setPlainText(script)
        txt.setMinimumHeight(360)
        lay.addWidget(txt, 1)
        row = QtWidgets.QHBoxLayout()
        btn_copy = QtWidgets.QPushButton("Copy Cell")
        btn_copy.clicked.connect(lambda: self._af_copy_colab_script_to_clipboard())
        row.addWidget(btn_copy)
        if notebook:
            btn_open_nb = QtWidgets.QPushButton("Open Prepared Notebook File")
            btn_open_nb.clicked.connect(lambda: webbrowser.open(Path(notebook).resolve().as_uri()))
            row.addWidget(btn_open_nb)
        if script_path:
            btn_open_cell = QtWidgets.QPushButton("Open Cell File")
            btn_open_cell.clicked.connect(lambda: webbrowser.open(Path(script_path).resolve().as_uri()))
            row.addWidget(btn_open_cell)
        btn_official = QtWidgets.QPushButton("Official Notebook Fallback")
        btn_official.clicked.connect(lambda: webbrowser.open(COLABFOLD_NOTEBOOK_URL))
        row.addWidget(btn_official)
        row.addStretch(1)
        btn_close = QtWidgets.QPushButton("Close")
        btn_close.clicked.connect(dlg.accept)
        row.addWidget(btn_close)
        lay.addLayout(row)
        try:
            dlg.exec()
        except Exception:
            dlg.exec_()
    def _on_af_copy_fasta(self):
        seq = self._af_clean_sequence(self.txt_af_sequence.toPlainText() if hasattr(self, "txt_af_sequence") else "")
        if not seq:
            QtWidgets.QMessageBox.warning(self, "AlphaFold", "Sequence is empty.")
            return
        job_name = "af_job"
        try:
            job_name = str(self.edit_af_job_name.text() or "af_job").strip()
        except Exception:
            job_name = "af_job"
        job_name = af_sanitize_job_name(job_name)
        if self._af_is_af3_engine():
            try:
                chains = af_split_protein_chains(seq)
                payload = af_build_alphafold3_input_json(
                    job_name=job_name,
                    protein_sequences=chains,
                    chain_ids=[self._af_current_af3_chain_id()] if len(chains) == 1 else None,
                    model_seeds=[self._af_af3_seed()],
                )
                txt = json.dumps(payload, indent=2)
            except Exception as e:
                QtWidgets.QMessageBox.warning(self, "AlphaFold 3", f"Could not build AF3 JSON: {e}")
                return
        else:
            txt = af_fasta_text(job_name, seq)
        try:
            cb = QtWidgets.QApplication.clipboard()
            if cb is not None:
                cb.setText(txt)
            copied = "AF3 JSON" if self._af_is_af3_engine() else "FASTA"
            self.lbl_af_status.setText(f"{copied} copied to clipboard (length={len(seq)}).")
        except Exception as e:
            QtWidgets.QMessageBox.warning(self, "AlphaFold", f"Could not copy prediction input: {e}")
    def _update_af_tool_status(self):
        if not hasattr(self, "lbl_af_tools"):
            return
        mode = self._af_current_exec_mode()
        engine = self._af_current_engine()
        eff_mode, auto_note = self._af_resolve_exec_mode(deep_probe=False)
        cf = self._af_tool_path() if engine == AF_ENGINE_COLABFOLD else None
        if engine in {AF_ENGINE_AF3_LOCAL, AF_ENGINE_AF3_SERVER}:
            ready, missing, meta = self._af_af3_local_ready(deep_probe=False)
            if eff_mode == "local":
                msg = (
                    f"Engine: AlphaFold 3 | Mode: {'Auto->Local Docker' if mode == 'auto' else 'Local Docker'} | "
                    f"Docker={'OK' if meta.get('docker') else 'MISSING'} | "
                    f"GPU={meta.get('gpu_reason') or 'not checked'}"
                )
            else:
                msg = (
                    f"Engine: AlphaFold 3 | Mode: {'Auto->Handoff' if mode == 'auto' else 'Handoff'} | "
                    "prepare fold_input.json for AlphaFold Server or an external AF3 runtime."
                )
            if missing:
                msg += " | missing for local: " + ", ".join(missing)
            if mode == "auto" and auto_note:
                msg += f" | {auto_note}"
            self.lbl_af_tools.setText(msg)
            return
        if eff_mode == "local":
            msg = (
                f"Mode: {'Auto->Local' if mode == 'auto' else 'Local'} | "
                f"colabfold_batch={'OK' if cf else 'MISSING'} | "
                f"PyMOL Python={sys.executable}"
            )
            if cf:
                msg += f" | using: {cf}"
            if mode == "auto" and auto_note:
                msg += f" | {auto_note}"
        else:
            sync_root = ""
            try:
                sync_root = str(self.edit_af_sync_dir.text() or "").strip()
            except Exception:
                sync_root = ""
            msg = (
                f"Mode: {'Auto->Google Colab' if mode == 'auto' else 'Google Colab sync'} | "
                "prepare FASTA here, run notebook in browser, then import/auto-sync predicted PDB."
            )
            if sync_root:
                msg += f" | sync folder: {sync_root}"
            if cf:
                msg += f" | local fallback: {cf}"
            if mode == "auto" and auto_note:
                msg += f" | {auto_note}"
        self.lbl_af_tools.setText(msg)
    def _af_append_log(self, text):
        if not hasattr(self, "txt_af_log"):
            return
        try:
            self.txt_af_log.appendPlainText(str(text).rstrip("\n"))
            sb = self.txt_af_log.verticalScrollBar()
            if sb is not None:
                sb.setValue(sb.maximum())
        except Exception:
            pass
    def _af_clean_sequence(self, text):
        # Chains stay separated by ':' (ColabFold complex syntax); several FASTA records are
        # several chains, not one concatenated sequence.
        return af_colabfold_query(text)
    def _refresh_af_source_combo(self):
        if not hasattr(self, "af_source_combo"):
            return
        try:
            names = self._candidate_structure_objects()
            cur = self.af_source_combo.currentText()
            self.af_source_combo.blockSignals(True)
            self.af_source_combo.clear()
            self.af_source_combo.addItems(names)
            best = None
            if cur in names:
                best = cur
            if not best:
                best = self._pick_best_structure_object()
            if best and best in names:
                self.af_source_combo.setCurrentText(best)
            elif names:
                self.af_source_combo.setCurrentIndex(0)
            self.af_source_combo.blockSignals(False)
        except Exception:
            pass
        self._refresh_af_chain_combo()
    def _on_af_source_changed(self, _obj_name):
        self._refresh_af_chain_combo()
    def _refresh_af_chain_combo(self):
        if not hasattr(self, "cmb_af_chain"):
            return
        try:
            obj = str(self.af_source_combo.currentText() or "").strip()
        except Exception:
            obj = ""
        self.cmb_af_chain.blockSignals(True)
        self.cmb_af_chain.clear()
        if not obj:
            self.cmb_af_chain.addItem("A", "A")
            self.cmb_af_chain.blockSignals(False)
            return
        chain_data = {}
        try:
            chain_data = self._modeler_extract_chain_data(obj)
        except Exception:
            chain_data = {}
        chain_keys = sorted(chain_data.keys(), key=lambda c: (str(c).strip() == "", str(c)))
        if not chain_keys:
            self.cmb_af_chain.addItem("A", "A")
        else:
            for ch in chain_keys:
                disp = self._modeler_chain_display(ch)
                if str(chain_data.get(ch, {}).get("chain_origin", "")) == "synthetic_main":
                    disp = "MAIN"
                self.cmb_af_chain.addItem(disp, ch)
        self.cmb_af_chain.blockSignals(False)
    def _on_af_use_chain_sequence(self):
        obj = ""
        try:
            obj = str(self.af_source_combo.currentText() or "").strip()
        except Exception:
            obj = ""
        if not obj:
            QtWidgets.QMessageBox.warning(self, "AlphaFold", "Select a source object first.")
            return
        chain_data = {}
        try:
            chain_data = self._modeler_extract_chain_data(obj)
        except Exception:
            chain_data = {}
        if not chain_data:
            QtWidgets.QMessageBox.warning(self, "AlphaFold", "Could not extract chain sequence from selected object.")
            return
        chain_key = None
        try:
            chain_key = self.cmb_af_chain.currentData()
        except Exception:
            chain_key = None
        if chain_key not in chain_data:
            try:
                chain_key = next(iter(chain_data.keys()))
            except Exception:
                chain_key = None
        if chain_key is None:
            QtWidgets.QMessageBox.warning(self, "AlphaFold", "No chain data available.")
            return
        seq = str(chain_data.get(chain_key, {}).get("observed_seq", "") or "").strip().upper()
        if not seq:
            QtWidgets.QMessageBox.warning(self, "AlphaFold", "Selected chain has empty sequence.")
            return
        self.txt_af_sequence.setPlainText(seq)
        self.lbl_af_status.setText(
            f"Sequence imported from {obj} chain {self._modeler_chain_display(chain_key)} (length={len(seq)})."
        )
    def _on_af_pick_output_dir(self):
        cur = ""
        try:
            cur = str(self.edit_af_out_dir.text() or "").strip()
        except Exception:
            cur = ""
        out = QtWidgets.QFileDialog.getExistingDirectory(
            self,
            "Choose AlphaFold Output Root",
            cur or os.getcwd(),
        )
        if out:
            self.edit_af_out_dir.setText(out)
            try:
                if hasattr(self, "edit_af_sync_dir") and not str(self.edit_af_sync_dir.text() or "").strip():
                    self.edit_af_sync_dir.setText(out)
            except Exception:
                pass
    def _on_af_pick_sync_dir(self):
        cur = ""
        try:
            cur = str(self.edit_af_sync_dir.text() or "").strip()
        except Exception:
            cur = ""
        out = QtWidgets.QFileDialog.getExistingDirectory(
            self,
            "Choose AlphaFold Sync Folder",
            cur or os.getcwd(),
        )
        if out:
            self.edit_af_sync_dir.setText(out)
            self._update_af_tool_status()
    def _af_sync_root_dir(self):
        sync_root = ""
        try:
            sync_root = str(self.edit_af_sync_dir.text() or "").strip()
        except Exception:
            sync_root = ""
        if not sync_root:
            try:
                sync_root = str(self.edit_af_out_dir.text() or "").strip()
            except Exception:
                sync_root = ""
        if not sync_root:
            sync_root = os.path.join(self._dock_workspace_dir(), "alphafold")
        return sync_root
    def _af_relax_requested(self):
        try:
            if bool(getattr(self, "_af_last_relax_requested", False)):
                return True
        except Exception:
            pass
        try:
            return bool(self.cb_af_amber_relax.isChecked())
        except Exception:
            return False
    def _af_is_relaxed_name(self, name):
        return af_is_relaxed_name(name)
    def _af_model_patterns(self, prefer_relaxed=False):
        return af_model_patterns(prefer_relaxed=prefer_relaxed)
    def _af_find_best_model_recursive(self, root_dir, token="", prefer_relaxed=None):
        if prefer_relaxed is None:
            prefer_relaxed = self._af_relax_requested()
        return af_find_best_model_recursive(
            root_dir=root_dir,
            token=token,
            prefer_relaxed=bool(prefer_relaxed),
        )
    def _on_af_scan_sync_folder(self, silent=False, autoload=None):
        sync_root = self._af_sync_root_dir()
        token = str(getattr(self, "_af_pending_job_name", "") or "").strip()
        if not token:
            try:
                token = str(self.edit_af_job_name.text() or "").strip()
            except Exception:
                token = ""
        try:
            os.makedirs(sync_root, exist_ok=True)
        except Exception:
            pass
        # the Leonardo Colab cell downloads a ZIP; unpack it so its models can be found
        for unpacked in af_extract_result_zips(sync_root):
            self._af_append_log(f"Unpacked result ZIP: {unpacked}")
        best = self._af_find_best_model_recursive(sync_root, token=token, prefer_relaxed=self._af_relax_requested())
        if not best:
            if not silent:
                QtWidgets.QMessageBox.information(
                    self,
                    "AlphaFold",
                    f"No predicted model found yet in sync folder:\n{sync_root}",
                )
            return None
        self._af_last_best_pdb = best
        self._af_append_log(f"Sync match: {best}")
        self.lbl_af_status.setText(f"Synced best model from folder: {best}")
        if autoload is None:
            try:
                autoload = bool(self.cb_af_autoload.isChecked())
            except Exception:
                autoload = False
        if autoload and str(best) != str(getattr(self, "_af_last_sync_hit", "")):
            self._af_last_sync_hit = str(best)
            self._on_af_load_best_model(best)
            if not bool(silent):
                try:
                    QtWidgets.QMessageBox.information(
                        self,
                        "AlphaFold",
                        f"Prediction finished and synced.\n\nLoaded model:\n{best}",
                    )
                except Exception:
                    pass
        return best
    def _on_af_sync_timer_tick(self):
        try:
            if not bool(self.cb_af_auto_sync.isChecked()):
                if hasattr(self, "_af_sync_timer") and self._af_sync_timer.isActive():
                    self._af_sync_timer.stop()
                return
            if hasattr(self, "spin_af_sync_interval") and hasattr(self, "_af_sync_timer"):
                self._af_sync_timer.setInterval(int(self.spin_af_sync_interval.value()) * 1000)
        except Exception:
            pass
        self._on_af_scan_sync_folder(silent=True, autoload=True)
    def _on_af_import_result(self):
        out_root = ""
        try:
            out_root = str(self.edit_af_out_dir.text() or "").strip()
        except Exception:
            out_root = ""
        if not out_root:
            out_root = os.path.join(self._dock_workspace_dir(), "alphafold")
        try:
            os.makedirs(out_root, exist_ok=True)
        except Exception:
            pass
        fpath, _ = QtWidgets.QFileDialog.getOpenFileName(
            self,
            "Import AlphaFold Result",
            out_root,
            "Model/Archive (*.pdb *.ent *.cif *.mmcif *.zip)",
        )
        if not fpath:
            return
        fpath = str(fpath)
        best = None
        if fpath.lower().endswith(".zip"):
            ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
            dst = os.path.join(out_root, f"import_colab_{ts}")
            try:
                af_safe_extract_zip(fpath, dst)
                best = self._af_find_best_model_recursive(dst, token=str(getattr(self, "_af_pending_job_name", "") or ""), prefer_relaxed=self._af_relax_requested())
            except Exception as e:
                QtWidgets.QMessageBox.critical(self, "AlphaFold", f"Failed to import ZIP: {e}")
                return
        else:
            best = fpath
        if (not best) or (not os.path.isfile(best)):
            QtWidgets.QMessageBox.warning(self, "AlphaFold", "No valid model file found in imported result.")
            return
        self._af_last_best_pdb = str(best)
        self.lbl_af_status.setText(f"Imported model: {best}")
        self._af_append_log(f"Imported model: {best}")
        self._on_af_load_best_model(best)
    def _af_find_best_model(self, out_dir):
        return self._af_find_best_model_recursive(
            out_dir,
            token=str(getattr(self, "_af_pending_job_name", "") or ""),
            prefer_relaxed=self._af_relax_requested(),
        )
    def _af_copy_confidence_q_to_b_if_needed(self, sel):
        """
        Some AF/ColabFold exports place confidence in occupancy (q) instead of b.
        If b looks uninformative and q looks like pLDDT, copy q->b for visualization.
        """
        try:
            m = cmd.get_model(f"{sel} and name CA")
            atoms = list(getattr(m, "atom", []) or [])
        except Exception:
            atoms = []
        if not atoms:
            return False
        bvals = []
        qvals = []
        for a in atoms:
            try:
                bvals.append(float(getattr(a, "b", np.nan)))
            except Exception:
                pass
            try:
                qvals.append(float(getattr(a, "q", np.nan)))
            except Exception:
                pass
        if not bvals or not qvals:
            return False
        b = np.asarray(bvals, dtype=float)
        q = np.asarray(qvals, dtype=float)
        b = b[np.isfinite(b)]
        q = q[np.isfinite(q)]
        if b.size < 5 or q.size < 5:
            return False
        b_span = float(np.nanmax(b) - np.nanmin(b)) if b.size else 0.0
        q_span = float(np.nanmax(q) - np.nanmin(q)) if q.size else 0.0
        b_max = float(np.nanmax(b)) if b.size else 0.0
        q_min = float(np.nanmin(q)) if q.size else 0.0
        q_max = float(np.nanmax(q)) if q.size else 0.0
        # Trigger only when b has almost no information but q looks like 0..100 confidence.
        if ((b_span < 1.0) or (b_max <= 1.5)) and (q_span >= 5.0) and (q_min >= 0.0) and (q_max <= 100.0):
            try:
                cmd.alter(sel, "b=q")
                cmd.rebuild(sel)
                return True
            except Exception:
                return False
        return False
    def _af_apply_plddt_colors(self, obj_name):
        obj = str(obj_name or "").strip()
        if not obj:
            return
        try:
            sel = self._pymol_model_selection(obj, wrap=True)
        except Exception:
            sel = f"({obj})"
        if not sel:
            sel = f"({obj})"
        try:
            self._af_copy_confidence_q_to_b_if_needed(sel)
        except Exception:
            pass
        try:
            poly_n = int(cmd.count_atoms(f"{sel} and polymer"))
        except Exception:
            poly_n = 0
        vis_sel = f"{sel} and polymer" if poly_n > 0 else sel
        try:
            cmd.hide("everything", sel)
            cmd.show("cartoon", vis_sel)
            # Keep non-protein records visible as lines, but protein confidence on cartoon.
            cmd.show("lines", f"{sel} and not ({vis_sel})")
            cmd.set("cartoon_transparency", 0.06, vis_sel)
            try:
                cmd.spectrum("b", "red_yellow_cyan_blue", vis_sel, minimum=0.0, maximum=100.0)
            except Exception:
                cmd.color("red", f"{vis_sel} and b < 50")
                cmd.color("yellow", f"{vis_sel} and b >= 50 and b < 70")
                cmd.color("cyan", f"{vis_sel} and b >= 70 and b < 90")
                cmd.color("blue", f"{vis_sel} and b >= 90")
        except Exception:
            pass
    def _af_plot_title(self, kind):
        return af_plot_title(kind)
    def _af_plot_search_roots(self):
        candidates = [getattr(self, "_af_last_job_dir", "") or ""]
        best = ""
        try:
            best = str(getattr(self, "_af_last_best_pdb", "") or "").strip()
        except Exception:
            best = ""
        if best:
            candidates.append(os.path.dirname(best))
            candidates.append(os.path.dirname(os.path.dirname(best)))
        try:
            candidates.append(self._af_sync_root_dir())
        except Exception:
            pass
        try:
            candidates.append(str(self.edit_af_out_dir.text() or "").strip())
        except Exception:
            pass
        return af_collect_existing_dirs(candidates)
    def _af_plot_patterns(self, kind):
        return af_plot_patterns(kind)
    def _af_extract_plddt_pae_from_json(self, data):
        return af_extract_plddt_pae_from_json(data)
    def _af_generate_plot_from_scores_json(self, kind, roots=None, token=""):
        if not HAS_MPL:
            return None
        k = str(kind or "").strip().lower()
        if k not in {"plddt", "pae"}:
            return None
        roots = list(roots or self._af_plot_search_roots() or [])
        if not roots:
            return None
        tok = str(token or "").strip().lower()
        pats = ["*scores*.json", "*result*.json", "*ranking*.json", "*rank*.json", "*.json"]
        candidates = []
        seen = set()
        for ridx, root in enumerate(roots):
            rp = Path(str(root))
            if (not rp.exists()) or (not rp.is_dir()):
                continue
            for pidx, pat in enumerate(pats):
                try:
                    files = list(rp.rglob(pat))
                except Exception:
                    files = []
                for f in files:
                    try:
                        if (not f.is_file()) or f.stat().st_size <= 10:
                            continue
                        fp = str(f.resolve())
                        if fp in seen:
                            continue
                        seen.add(fp)
                        low = fp.lower()
                        token_hit = 1 if (tok and (tok in low)) else 0
                        mtime = float(f.stat().st_mtime)
                        candidates.append(((token_hit, -int(ridx), -int(pidx), mtime), fp))
                    except Exception:
                        continue
        if not candidates:
            return None
        candidates.sort(key=lambda x: x[0], reverse=True)
        for _score, fp in candidates:
            try:
                with open(fp, "r", encoding="utf-8") as fh:
                    data = json.load(fh)
            except Exception:
                continue
            plddt, pae = self._af_extract_plddt_pae_from_json(data)
            stem = Path(fp).stem
            out_dir = os.path.dirname(fp)
            if k == "plddt" and plddt is not None:
                out_png = os.path.join(out_dir, f"{stem}_plddt_autogen.png")
                try:
                    x = np.arange(1, int(plddt.size) + 1, dtype=int)
                    fig, ax = plt.subplots(1, 1, figsize=(8.2, 3.6))
                    ax.plot(x, plddt, color="#1f77b4", linewidth=1.2)
                    ax.set_ylim(0.0, 100.0)
                    ax.set_xlabel("Residue index")
                    ax.set_ylabel("pLDDT")
                    ax.set_title("Predicted confidence (auto-generated)")
                    ax.grid(alpha=0.25)
                    fig.tight_layout()
                    fig.savefig(out_png, dpi=150)
                    plt.close(fig)
                    return out_png
                except Exception:
                    try:
                        plt.close("all")
                    except Exception:
                        pass
            if k == "pae" and pae is not None:
                out_png = os.path.join(out_dir, f"{stem}_pae_autogen.png")
                try:
                    vmax = float(np.nanmax(pae)) if np.any(np.isfinite(pae)) else 30.0
                    vmax = max(5.0, min(50.0, vmax))
                    fig, ax = plt.subplots(1, 1, figsize=(5.8, 5.2))
                    im = ax.imshow(pae, cmap="viridis", vmin=0.0, vmax=vmax, interpolation="nearest", origin="upper")
                    ax.set_xlabel("Residue index")
                    ax.set_ylabel("Residue index")
                    ax.set_title("Predicted aligned error (auto-generated)")
                    cb = fig.colorbar(im, ax=ax, fraction=0.046, pad=0.04)
                    cb.set_label("PAE (A)")
                    fig.tight_layout()
                    fig.savefig(out_png, dpi=150)
                    plt.close(fig)
                    return out_png
                except Exception:
                    try:
                        plt.close("all")
                    except Exception:
                        pass
        return None
    def _af_find_plot_file(self, kind):
        roots = self._af_plot_search_roots()
        patterns = self._af_plot_patterns(kind)
        if not roots or not patterns:
            return None
        token = ""
        try:
            token = str(getattr(self, "_af_pending_job_name", "") or "").strip().lower()
        except Exception:
            token = ""
        best = af_pick_best_plot_image(roots=roots, patterns=patterns, token=token)
        if best:
            return best
        # Fallback: some ColabFold outputs provide JSON scores without PNG plots.
        gen = self._af_generate_plot_from_scores_json(kind, roots=roots, token=token)
        if gen and os.path.isfile(gen):
            try:
                self._af_append_log(f"Auto-generated {self._af_plot_title(kind)} plot from JSON: {gen}")
            except Exception:
                pass
            return gen
        return None
    def _af_show_plot_dialog(self, path, title):
        p = str(path or "").strip()
        if not p or (not os.path.isfile(p)):
            QtWidgets.QMessageBox.warning(self, "AlphaFold", f"Plot not found:\n{p}")
            return
        pix = QtGui.QPixmap(p)
        if pix.isNull():
            try:
                webbrowser.open(Path(p).resolve().as_uri())
                self.lbl_af_status.setText(f"Opened plot externally: {p}")
            except Exception as e:
                QtWidgets.QMessageBox.warning(self, "AlphaFold", f"Could not open plot image:\n{p}\n\n{e}")
            return
        dlg_parent = getattr(self, "_af_dialog", self)
        dlg = QtWidgets.QDialog(dlg_parent)
        dlg.setWindowTitle(str(title or "AlphaFold Plot"))
        dlg.setMinimumSize(680, 420)
        self._fit_dialog_to_screen(dlg, preferred_w=980, preferred_h=720, min_w=640, min_h=420)
        lay = QtWidgets.QVBoxLayout(dlg)
        scroll = QtWidgets.QScrollArea(dlg)
        scroll.setWidgetResizable(True)
        img_lbl = QtWidgets.QLabel(scroll)
        img_lbl.setAlignment(QtCore.Qt.AlignCenter)
        img_lbl.setPixmap(pix)
        img_lbl.setTextInteractionFlags(QtCore.Qt.TextSelectableByMouse)
        scroll.setWidget(img_lbl)
        lay.addWidget(scroll, 1)
        lbl_path = QtWidgets.QLabel(p, dlg)
        lbl_path.setWordWrap(True)
        lay.addWidget(lbl_path)
        row = QtWidgets.QHBoxLayout()
        row.addStretch(1)
        btn_ext = QtWidgets.QPushButton("Open External", dlg)
        btn_ext.clicked.connect(lambda: webbrowser.open(Path(p).resolve().as_uri()))
        row.addWidget(btn_ext)
        btn_close = QtWidgets.QPushButton("Close", dlg)
        btn_close.clicked.connect(dlg.accept)
        row.addWidget(btn_close)
        lay.addLayout(row)
        try:
            dlg.exec()
        except Exception:
            dlg.exec_()
    def _on_af_show_plot(self, kind):
        k = str(kind or "").strip().lower()
        title = self._af_plot_title(k)
        path = self._af_find_plot_file(k)
        if not path:
            roots = self._af_plot_search_roots()
            roots_txt = "\n".join([str(r) for r in roots]) if roots else "(none)"
            QtWidgets.QMessageBox.information(
                self,
                "AlphaFold",
                f"No {title} plot was found yet.\n\nSearched in:\n{roots_txt}",
            )
            return
        self._af_append_log(f"{title} plot: {path}")
        self.lbl_af_status.setText(f"{title} plot: {path}")
        self._af_show_plot_dialog(path, f"AlphaFold {title} Plot")
    def _on_af_load_best_model(self, pdb_path=None):
        path = str(pdb_path or getattr(self, "_af_last_best_pdb", "") or "").strip()
        if path and os.path.isfile(path) and self._af_relax_requested():
            try:
                base_name = os.path.basename(path)
                if ("unrelaxed" in base_name.lower()) or (not self._af_is_relaxed_name(base_name)):
                    pref = self._af_find_best_model_recursive(
                        os.path.dirname(path),
                        token=str(getattr(self, "_af_pending_job_name", "") or ""),
                        prefer_relaxed=True,
                    )
                    if pref and os.path.isfile(pref) and self._af_is_relaxed_name(os.path.basename(pref)):
                        path = str(pref)
            except Exception:
                pass
        if not path or (not os.path.isfile(path)):
            QtWidgets.QMessageBox.warning(self, "AlphaFold", "No predicted model found to load.")
            return
        stem = os.path.splitext(os.path.basename(path))[0]
        base = self._dock_safe_obj_name(f"af_{stem}")
        existing = set(cmd.get_names("objects"))
        obj = base
        idx = 1
        while obj in existing:
            idx += 1
            obj = f"{base}_{idx}"
        try:
            cmd.load(path, obj)
            self._af_apply_plddt_colors(obj)
            cmd.orient(obj)
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "AlphaFold", f"Failed to load predicted model: {e}")
            return
        self._af_last_loaded_object = obj
        self.loaded_object = obj
        try:
            self._populate_limit_combo()
        except Exception:
            pass
        try:
            self._refresh_modeler_object_combo()
        except Exception:
            pass
        try:
            self._refresh_docking_object_combo()
        except Exception:
            pass
        ca_bs = []
        try:
            m = cmd.get_model(f'(model "{obj}") and name CA')
            for a in list(getattr(m, "atom", []) or []):
                try:
                    ca_bs.append(float(getattr(a, "b", np.nan)))
                except Exception:
                    pass
        except Exception:
            pass
        if ca_bs:
            mean_plddt = float(np.nanmean(ca_bs))
            self.lbl_af_status.setText(
                f"Loaded {obj} from {path}. Mean CA pLDDT={mean_plddt:.1f}."
            )
        else:
            self.lbl_af_status.setText(f"Loaded {obj} from {path}.")
        try:
            found = []
            for _k in ("plddt", "pae", "msa"):
                _p = self._af_find_plot_file(_k)
                if _p:
                    found.append(f"{self._af_plot_title(_k)}={os.path.basename(_p)}")
            if found:
                self._af_append_log("AlphaFold plots: " + " | ".join(found))
        except Exception:
            pass
    def _af_prepare_job_bundle(self):
        seq_raw = ""
        try:
            seq_raw = self.txt_af_sequence.toPlainText()
        except Exception:
            seq_raw = ""
        seq = self._af_clean_sequence(seq_raw)
        if not seq:
            QtWidgets.QMessageBox.warning(self, "AlphaFold", "Sequence is empty.")
            return None
        invalid = sorted(set([c for c in seq if c not in set("ACDEFGHIKLMNPQRSTVWYBXZJUO:")]))
        if invalid:
            QtWidgets.QMessageBox.warning(
                self,
                "AlphaFold",
                f"Sequence contains unsupported characters: {''.join(invalid)}",
            )
            return None
        job_name = "af_job"
        try:
            job_name = str(self.edit_af_job_name.text() or "af_job").strip()
        except Exception:
            job_name = "af_job"
        if not job_name:
            job_name = "af_job"
        job_name = af_sanitize_job_name(job_name)
        engine = self._af_current_engine()
        out_root = ""
        try:
            out_root = str(self.edit_af_out_dir.text() or "").strip()
        except Exception:
            out_root = ""
        if not out_root:
            out_root = os.path.join(self._dock_workspace_dir(), "alphafold")
        try:
            os.makedirs(out_root, exist_ok=True)
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "AlphaFold", f"Cannot create output directory: {e}")
            return None
        model_type = "alphafold2"
        try:
            model_type = str(self.cmb_af_model_type.currentData() or "alphafold2")
        except Exception:
            model_type = "alphafold2"
        num_recycle = 3
        try:
            num_recycle = int(self.spin_af_num_recycle.value())
        except Exception:
            num_recycle = 3
        num_models = 5
        try:
            num_models = int(self.spin_af_num_models.value())
        except Exception:
            num_models = 5
        msa_mode = ""
        try:
            msa_mode = str(self.cmb_af_msa_mode.currentData() or "").strip()
        except Exception:
            msa_mode = ""
        amber_relax = False
        num_relax = 1
        gpu_relax = False
        try:
            amber_relax = bool(self.cb_af_amber_relax.isChecked())
        except Exception:
            amber_relax = False
        try:
            num_relax = int(self.spin_af_num_relax.value())
        except Exception:
            num_relax = 1
        try:
            gpu_relax = bool(self.cb_af_gpu_relax.isChecked())
        except Exception:
            gpu_relax = False
        extra_args = []
        try:
            extra_txt = str(self.edit_af_extra_args.text() or "").strip()
            if extra_txt:
                extra_args = list(shlex.split(extra_txt))
        except Exception:
            extra_args = []
        ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        job_dir = os.path.join(out_root, f"{job_name}_{ts}")
        try:
            os.makedirs(job_dir, exist_ok=False)
        except Exception:
            try:
                os.makedirs(job_dir, exist_ok=True)
            except Exception as e:
                QtWidgets.QMessageBox.critical(self, "AlphaFold", f"Cannot create job directory: {e}")
                return None
        fasta = os.path.join(job_dir, f"{job_name}.fasta")
        try:
            with open(fasta, "w", encoding="utf-8") as fh:
                # ColabFold: one record, chains joined by ':'; AlphaFold 3: one record per chain
                fh.write(af_fasta_text(job_name, seq, per_chain=engine in {AF_ENGINE_AF3_LOCAL, AF_ENGINE_AF3_SERVER}))
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "AlphaFold", f"Failed to write FASTA: {e}")
            return None
        self._af_last_job_dir = job_dir
        self._af_last_best_pdb = None
        self._af_last_loaded_object = None
        self._af_pending_job_name = job_name
        self._af_last_relax_requested = bool(amber_relax)
        return {
            "engine": engine,
            "seq": seq,
            "job_name": job_name,
            "out_root": out_root,
            "job_dir": job_dir,
            "fasta": fasta,
            "model_type": model_type,
            "num_recycle": num_recycle,
            "num_models": max(1, int(num_models)),
            "msa_mode": msa_mode,
            "amber_relax": amber_relax,
            "num_relax": max(1, int(num_relax)),
            "gpu_relax": gpu_relax,
            "extra_args": extra_args,
        }
    def _af_execute_streaming_command(self, cmdline, cwd, label):
        self._af_append_log("=" * 60)
        self._af_append_log(str(label or "Running AlphaFold command"))
        self._af_append_log(f"work_dir: {cwd}")
        self._af_append_log("command: " + af_format_shell_command(cmdline))
        try:
            self.btn_af_run.setEnabled(False)
            self.btn_af_load_best.setEnabled(False)
        except Exception:
            pass
        QtWidgets.QApplication.setOverrideCursor(QtCore.Qt.WaitCursor)
        rc = -1
        err_tail = ""
        try:
            proc = subprocess.Popen(
                list(cmdline),
                cwd=str(cwd or os.getcwd()),
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                bufsize=1,
            )
            if proc.stdout is not None:
                while True:
                    line = proc.stdout.readline()
                    if line:
                        self._af_append_log(line.rstrip("\n"))
                    if proc.poll() is not None:
                        break
                    QtWidgets.QApplication.processEvents()
                for line in proc.stdout.readlines():
                    if line:
                        self._af_append_log(line.rstrip("\n"))
            rc = int(proc.wait())
        except Exception as e:
            err_tail = str(e)
            rc = -1
        finally:
            QtWidgets.QApplication.restoreOverrideCursor()
            try:
                self.btn_af_run.setEnabled(True)
                self.btn_af_load_best.setEnabled(True)
            except Exception:
                pass
        return rc, err_tail
    def _on_af_run_colabfold(self):
        bundle = self._af_prepare_job_bundle()
        if not bundle:
            return
        engine = str(bundle.get("engine") or self._af_current_engine())
        mode = self._af_current_exec_mode()
        if mode == "auto":
            mode, auto_note = self._af_resolve_exec_mode(deep_probe=True)
            try:
                if auto_note:
                    self._af_append_log(auto_note)
                    self.lbl_af_status.setText(auto_note)
            except Exception:
                pass
        if engine == AF_ENGINE_AF3_SERVER:
            mode = "colab_remote"
        if engine in {AF_ENGINE_AF3_LOCAL, AF_ENGINE_AF3_SERVER}:
            try:
                json_path = self._af_write_af3_json_for_bundle(bundle)
                docker_cmd = self._af_build_af3_docker_command_for_bundle(bundle, interactive=True)
                docker_cmd_txt = af_format_shell_command(docker_cmd)
            except Exception as e:
                QtWidgets.QMessageBox.critical(self, "AlphaFold 3", f"Could not prepare AF3 input: {e}")
                return
            if mode == "colab_remote":
                ready, missing, _meta = self._af_af3_local_ready(deep_probe=False)
                server_url = ""
                try:
                    server_url = str(self.edit_af_colab_url.text() or "").strip()
                except Exception:
                    server_url = ""
                if not server_url:
                    server_url = AF3_SERVER_URL
                server_json = os.path.join(bundle["job_dir"], "af3_input", "alphafold_server_input.json")
                try:
                    af_write_json(
                        af_build_alphafold_server_json(
                            bundle["job_name"],
                            af_split_protein_chains(str(bundle.get("seq") or "")),
                            model_seeds=[self._af_af3_seed()],
                        ),
                        server_json,
                    )
                    bundle["af3_server_json"] = server_json
                except Exception as e:
                    server_json = f"(not written: {e})"
                info_txt = os.path.join(bundle["job_dir"], "AF3_HANDOFF_INSTRUCTIONS.txt")
                try:
                    with open(info_txt, "w", encoding="utf-8") as fh:
                        fh.write(
                            "AlphaFold 3 handoff workflow\n"
                            f"Job: {bundle['job_name']}\n"
                            f"AlphaFold Server upload file: {server_json}\n"
                            f"AF3 Docker/cluster input: {json_path}\n"
                            f"Suggested output folder: {bundle.get('af3_output_dir')}\n"
                            f"AlphaFold Server: {server_url}\n\n"
                            "AlphaFold Server: use 'Upload JSON' with alphafold_server_input.json (the Server\n"
                            "format; fold_input.json is the AlphaFold 3 Docker format and is rejected there).\n"
                            "The Server accepts only its own list of CCD ligands, not SMILES.\n\n"
                            "Local Docker command template:\n"
                            f"{docker_cmd_txt}\n\n"
                            "Notes:\n"
                            "- AlphaFold 3 local inference requires Docker, GPU support, model parameters, and public databases.\n"
                            "- For a Colab or remote machine, copy fold_input.json and use an AF3-capable environment with the required assets.\n"
                            "- After prediction, import the generated CIF/PDB/ZIP with 'Import Result...'.\n"
                        )
                except Exception:
                    pass
                self._af_append_log("=" * 60)
                self._af_append_log("Prepared AlphaFold 3 handoff")
                self._af_append_log(f"job_dir: {bundle['job_dir']}")
                self._af_append_log(f"json: {json_path}")
                self._af_append_log(f"server_json: {server_json}")
                self._af_append_log(f"instructions: {info_txt}")
                self._af_append_log("docker_command: " + docker_cmd_txt)
                if missing:
                    self._af_append_log("local_missing: " + ", ".join(missing))
                try:
                    if bool(self.cb_af_open_colab_on_prepare.isChecked()):
                        self._on_af_open_colab_notebook()
                except Exception:
                    pass
                self.lbl_af_status.setText(f"Prepared AlphaFold 3 handoff JSON: {json_path}")
                QtWidgets.QMessageBox.information(
                    self,
                    "AlphaFold 3",
                    "AlphaFold 3 input prepared.\n\n"
                    f"AlphaFold Server upload: {server_json}\n"
                    f"AF3 Docker/cluster JSON: {json_path}\n"
                    f"Instructions: {info_txt}\n\n"
                    "Run AF3 on AlphaFold Server or an AF3-capable Colab/remote/local runtime, then import the CIF/PDB/ZIP result.",
                )
                return
            ready, missing, _meta = self._af_af3_local_ready(deep_probe=True)
            if not ready:
                QtWidgets.QMessageBox.critical(
                    self,
                    "AlphaFold 3",
                    "Local AlphaFold 3 is not ready.\n\nMissing:\n"
                    + "\n".join([f"- {x}" for x in (missing or ["unknown requirement"])])
                    + "\n\nUse handoff mode or configure Docker, GPU, model parameters, and databases.",
                )
                return
            cmdline = self._af_build_af3_docker_command_for_bundle(bundle, interactive=False)
            rc, err_tail = self._af_execute_streaming_command(
                cmdline=cmdline,
                cwd=bundle["job_dir"],
                label="Running local AlphaFold 3 Docker job",
            )
            if rc != 0:
                msg = f"AlphaFold 3 Docker run failed with code {rc}."
                if err_tail:
                    msg += f"\n{err_tail}"
                msg += "\nCheck Docker GPU support, AF3 model parameters, public databases, and the run log."
                self.lbl_af_status.setText(msg)
                QtWidgets.QMessageBox.critical(self, "AlphaFold 3", msg)
                return
            best_model = self._af_find_best_model(bundle["job_dir"])
            self._af_last_best_pdb = best_model
            if not best_model:
                self.lbl_af_status.setText(
                    f"AlphaFold 3 finished in {bundle['job_dir']}, but no CIF/PDB model was found. Check run log."
                )
                QtWidgets.QMessageBox.warning(
                    self,
                    "AlphaFold 3",
                    "Run finished but no CIF/PDB model was found in the output directory.",
                )
                return
            self.lbl_af_status.setText(f"AlphaFold 3 finished. Best model: {best_model}")
            self._af_append_log(f"Best model: {best_model}")
            autoload = False
            try:
                autoload = bool(self.cb_af_autoload.isChecked())
            except Exception:
                autoload = False
            if autoload:
                self._on_af_load_best_model(best_model)
            try:
                QtWidgets.QMessageBox.information(
                    self,
                    "AlphaFold 3",
                    f"Prediction finished.\n\nBest model:\n{best_model}",
                )
            except Exception:
                pass
            return
        if mode == "local":
            has_gpu, _gpu_reason = self._af_local_gpu_available(deep=True)
            if not has_gpu:
                gpu_msg = af_gpu_requirement_message(engine, self._af_gpu_info())
                self._af_update_gpu_warning()
                self._af_append_log(f"{GPU_REQUIRED_TITLE}: {gpu_msg}")
                choice = self._af_ask_gpu_fallback(gpu_msg)
                if choice == "cancel":
                    self.lbl_af_status.setText(f"{GPU_REQUIRED_TITLE}: local run cancelled (no NVIDIA GPU).")
                    return
                if choice == "colab":
                    mode = "colab_remote"
                else:
                    # detection can miss a real GPU (nvidia-smi not on PATH, WSL2, containers)
                    self._af_append_log("Running locally without a detected NVIDIA GPU at the user's request.")
        if mode == "colab_remote":
            sync_root = self._af_sync_root_dir()
            try:
                os.makedirs(sync_root, exist_ok=True)
            except Exception as e:
                QtWidgets.QMessageBox.critical(self, "AlphaFold", f"Cannot create sync directory: {e}")
                return
            colab_url = ""
            try:
                colab_url = str(self.edit_af_colab_url.text() or "").strip()
            except Exception:
                colab_url = ""
            if not colab_url:
                colab_url = COLABFOLD_NOTEBOOK_URL
            colab_cmd = af_build_colabfold_colab_cell(
                input_fasta="input.fasta",
                output_dir="/content/out",
                model_type=bundle["model_type"],
                num_recycle=bundle["num_recycle"],
                num_models=bundle.get("num_models"),
                msa_mode=bundle.get("msa_mode"),
                amber_relax=bundle.get("amber_relax"),
                num_relax=bundle.get("num_relax", 1),
                gpu_relax=bundle.get("gpu_relax"),
                extra_args=bundle.get("extra_args"),
            )
            job_script = ""
            job_script_path = os.path.join(bundle["job_dir"], f"{bundle['job_name']}_colabfold_cell.py")
            try:
                job_script = af_build_colabfold_job_script(
                    job_name=bundle["job_name"],
                    sequence=bundle["seq"],
                    model_type=bundle["model_type"],
                    num_recycle=bundle["num_recycle"],
                    num_models=bundle.get("num_models"),
                    msa_mode=bundle.get("msa_mode"),
                    amber_relax=bundle.get("amber_relax"),
                    num_relax=bundle.get("num_relax", 1),
                    gpu_relax=bundle.get("gpu_relax"),
                    extra_args=bundle.get("extra_args"),
                )
                with open(job_script_path, "w", encoding="utf-8") as fh:
                    fh.write(job_script)
                    fh.write("\n")
            except Exception:
                job_script = ""
                job_script_path = ""
            job_notebook = os.path.join(bundle["job_dir"], f"{bundle['job_name']}_colabfold.ipynb")
            try:
                nb_payload = af_build_colabfold_job_notebook(
                    job_name=bundle["job_name"],
                    sequence=bundle["seq"],
                    model_type=bundle["model_type"],
                    num_recycle=bundle["num_recycle"],
                    num_models=bundle.get("num_models"),
                    msa_mode=bundle.get("msa_mode"),
                    amber_relax=bundle.get("amber_relax"),
                    num_relax=bundle.get("num_relax", 1),
                    gpu_relax=bundle.get("gpu_relax"),
                    extra_args=bundle.get("extra_args"),
                )
                af_write_json(nb_payload, job_notebook)
            except Exception:
                job_notebook = ""
            self._af_last_colab_notebook = job_notebook
            self._af_last_colab_script = job_script
            self._af_last_colab_script_path = job_script_path
            try:
                self._af_copy_colab_script_to_clipboard()
            except Exception:
                pass
            info_txt = os.path.join(bundle["job_dir"], "COLAB_SYNC_INSTRUCTIONS.txt")
            try:
                with open(info_txt, "w", encoding="utf-8") as fh:
                    fh.write(
                        "Google Colab sync workflow\n"
                        f"Job: {bundle['job_name']}\n"
                        f"FASTA: {bundle['fasta']}\n"
                        f"Prepared notebook: {job_notebook or '(not written)'}\n"
                        f"Prepared Colab cell: {job_script_path or '(not written)'}\n"
                        f"Sync folder: {sync_root}\n"
                        f"Notebook: {colab_url}\n"
                        f"Relaxation: amber={bool(bundle.get('amber_relax'))}, num_relax={int(bundle.get('num_relax', 1))}, gpu_relax={bool(bundle.get('gpu_relax'))}\n\n"
                        "1) Upload the prepared notebook above to Colab, or open any GPU Colab runtime and paste the prepared Colab cell.\n"
                        "2) The official ColabFold notebook URL is only a fallback; it cannot be edited automatically by Leonardo.\n"
                        "3) Minimal command alternative after uploading FASTA manually:\n"
                        f"   {colab_cmd}\n"
                        "4) Download PDB/CIF/ZIP output and place it in Sync Folder.\n"
                        "5) In Leonardo use Scan & Load or keep Auto-sync enabled.\n"
                    )
            except Exception:
                pass
            self._af_append_log("=" * 60)
            self._af_append_log("Prepared Google Colab job")
            self._af_append_log(f"job_dir: {bundle['job_dir']}")
            self._af_append_log(f"fasta: {bundle['fasta']}")
            if job_notebook:
                self._af_append_log(f"prepared_notebook: {job_notebook}")
            if job_script_path:
                self._af_append_log(f"prepared_colab_cell: {job_script_path}")
            self._af_append_log(f"sync_folder: {sync_root}")
            self._af_append_log(f"notebook: {colab_url}")
            if hasattr(self, "_af_sync_timer"):
                try:
                    self._af_sync_timer.setInterval(int(self.spin_af_sync_interval.value()) * 1000)
                    if bool(self.cb_af_auto_sync.isChecked()):
                        self._af_sync_timer.start()
                    else:
                        self._af_sync_timer.stop()
                except Exception:
                    pass
            opened_colab = False
            try:
                if bool(self.cb_af_open_colab_on_prepare.isChecked()):
                    self._on_af_open_colab_notebook()
                    opened_colab = True
            except Exception:
                pass
            if not opened_colab:
                try:
                    self._af_show_colab_job_dialog(opened_url="")
                except Exception:
                    pass
            self.lbl_af_status.setText(
                f"Prepared Colab job {bundle['job_name']}. Prefilled Colab cell copied; put output PDB/CIF/ZIP into sync folder: {sync_root}"
            )
            QtWidgets.QMessageBox.information(
                self,
                "AlphaFold",
                "Google Colab job prepared.\n\n"
                f"FASTA: {bundle['fasta']}\n"
                f"Prepared notebook: {job_notebook or '(not written)'}\n"
                f"Prepared Colab cell: {job_script_path or '(not written)'}\n"
                f"Sync folder: {sync_root}\n\n"
                "The complete cell with Leonardo sequence and parameters was copied to the clipboard. Paste/run it in Colab, then place output PDB/CIF/ZIP in sync folder and click 'Scan & Load'."
            )
            return
        cf_bin = self._af_tool_path()
        if not cf_bin:
            QtWidgets.QMessageBox.critical(
                self,
                "AlphaFold",
                "colabfold_batch not found. Install ColabFold in the environment used by PyMOL or provide full path.",
            )
            return
        cmdline = af_build_colabfold_command(
            executable=str(cf_bin),
            input_fasta=str(bundle["fasta"]),
            output_dir=str(bundle["job_dir"]),
            model_type=str(bundle["model_type"]),
            num_recycle=int(bundle["num_recycle"]),
            num_models=bundle.get("num_models"),
            msa_mode=str(bundle.get("msa_mode") or ""),
            amber_relax=bool(bundle.get("amber_relax")),
            num_relax=int(bundle.get("num_relax", 1)),
            gpu_relax=bool(bundle.get("gpu_relax")),
            extra_args=list(bundle.get("extra_args") or []),
            python_executable=sys.executable,
        )
        rc, err_tail = self._af_execute_streaming_command(
            cmdline=cmdline,
            cwd=bundle["job_dir"],
            label="Running local ColabFold job",
        )
        if rc != 0:
            msg = f"colabfold_batch failed with code {rc}."
            if err_tail:
                msg += f"\n{err_tail}"
            msg += "\nTip: switch Execution to 'Google Colab GPU (prepare + sync)' if local run is too slow/unstable."
            self.lbl_af_status.setText(msg)
            QtWidgets.QMessageBox.critical(self, "AlphaFold", msg)
            return
        best_pdb = self._af_find_best_model(bundle["job_dir"])
        self._af_last_best_pdb = best_pdb
        if not best_pdb:
            self.lbl_af_status.setText(
                f"ColabFold finished in {bundle['job_dir']}, but no output PDB was found. Check run log."
            )
            QtWidgets.QMessageBox.warning(
                self,
                "AlphaFold",
                "Run finished but no PDB model was found in output directory.",
            )
            return
        self.lbl_af_status.setText(f"ColabFold finished. Best model: {best_pdb}")
        self._af_append_log(f"Best model: {best_pdb}")
        autoload = False
        try:
            autoload = bool(self.cb_af_autoload.isChecked())
        except Exception:
            autoload = False
        if autoload:
            self._on_af_load_best_model(best_pdb)
        try:
            QtWidgets.QMessageBox.information(
                self,
                "AlphaFold",
                f"Simulation finished.\n\nBest model:\n{best_pdb}",
            )
        except Exception:
            pass
    def _setup_bioseq_ui(self):
        """
        Sequence-first bioinformatics panel for structural simulation planning:
          A) homolog search, B) MSA/conservation, C) domains,
          D) disorder, E) transmembrane/signal, F) motifs/coevolution.
        """
        try:
            self._bioseq_dialog = QtWidgets.QDialog(self)
            self._bioseq_dialog.setWindowTitle("Bioinformatics Sequence Analysis")
            # Bioinformatics tabs provide their own scrolling surfaces.
            self._bioseq_dialog._leonardo_scroll_checked = True
            self._bioseq_dialog.resize(1080, 880)
            self._bioseq_dialog.setMinimumSize(940, 720)
            self._fit_dialog_to_screen(self._bioseq_dialog, preferred_w=1080, preferred_h=880, min_w=900, min_h=700)
            vbox = QtWidgets.QVBoxLayout(self._bioseq_dialog)
            tabs = QtWidgets.QTabWidget(self._bioseq_dialog)
            self.tabs_bioseq = tabs
            vbox.addWidget(tabs, 1)

            # Tab 1: responsive local analysis hub (heavy views moved to popups).
            tab_local = QtWidgets.QWidget()
            local_outer = QtWidgets.QVBoxLayout(tab_local)
            local_outer.setContentsMargins(0, 0, 0, 0)
            local_scroll = QtWidgets.QScrollArea(tab_local)
            local_scroll.setObjectName("bioseqLocalScrollArea")
            local_scroll.setProperty("leonardoVerticalOnly", True)
            local_scroll.setWidgetResizable(True)
            local_scroll.setFrameShape(QtWidgets.QFrame.NoFrame)
            local_scroll.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarAlwaysOff)
            local_body = QtWidgets.QWidget(local_scroll)
            local_body.setObjectName("bioseqLocalScrollContent")
            local_scroll.setWidget(local_body)
            local_outer.addWidget(local_scroll, 1)
            local_box = QtWidgets.QVBoxLayout(local_body)
            local_box.setContentsMargins(10, 10, 10, 10)
            local_box.setSpacing(10)

            source_group = QtWidgets.QGroupBox("Sequence Source")
            source_grid = QtWidgets.QGridLayout(source_group)
            source_grid.addWidget(QtWidgets.QLabel("Structure Object"), 0, 0)
            self.cmb_bioseq_object = QtWidgets.QComboBox()
            self.cmb_bioseq_object.currentTextChanged.connect(self._bioseq_on_object_changed)
            source_grid.addWidget(self.cmb_bioseq_object, 0, 1, 1, 2)
            self.btn_bioseq_refresh_objects = QtWidgets.QPushButton("Refresh")
            self.btn_bioseq_refresh_objects.clicked.connect(self._bioseq_refresh_object_combo)
            source_grid.addWidget(self.btn_bioseq_refresh_objects, 0, 3)
            source_grid.addWidget(QtWidgets.QLabel("Chain"), 1, 0)
            self.cmb_bioseq_chain = QtWidgets.QComboBox()
            source_grid.addWidget(self.cmb_bioseq_chain, 1, 1, 1, 3)
            self.btn_bioseq_import_chain = QtWidgets.QPushButton("Use Observed Chain Sequence")
            self.btn_bioseq_import_chain.clicked.connect(self._bioseq_import_chain_sequence)
            source_grid.addWidget(self.btn_bioseq_import_chain, 2, 0, 1, 2)
            self.btn_bioseq_use_modeler = QtWidgets.QPushButton("Use Modeler Sequence")
            self.btn_bioseq_use_modeler.clicked.connect(self._bioseq_use_modeler_sequence)
            source_grid.addWidget(self.btn_bioseq_use_modeler, 2, 2, 1, 2)
            source_grid.setColumnStretch(1, 1)
            source_grid.setColumnStretch(2, 1)
            source_grid.setColumnStretch(3, 1)
            local_box.addWidget(source_group)

            identifiers_group = QtWidgets.QGroupBox("Database Identifiers")
            identifiers_grid = QtWidgets.QGridLayout(identifiers_group)
            identifiers_grid.addWidget(QtWidgets.QLabel("RCSB PDB ID"), 0, 0)
            self.edit_bioseq_pdb_id = QtWidgets.QLineEdit()
            self.edit_bioseq_pdb_id.setPlaceholderText("Optional, e.g. 3PTB")
            identifiers_grid.addWidget(self.edit_bioseq_pdb_id, 0, 1)
            self.btn_bioseq_fetch_rcsb = QtWidgets.QPushButton("Fetch Full Chain Sequence from RCSB")
            self.btn_bioseq_fetch_rcsb.clicked.connect(self._bioseq_fetch_rcsb_sequence)
            identifiers_grid.addWidget(self.btn_bioseq_fetch_rcsb, 0, 2)
            identifiers_grid.addWidget(QtWidgets.QLabel("UniProt"), 1, 0)
            self.edit_bioseq_uniprot_id = QtWidgets.QLineEdit()
            self.edit_bioseq_uniprot_id.setPlaceholderText("Optional accession, e.g. P00760")
            identifiers_grid.addWidget(self.edit_bioseq_uniprot_id, 1, 1, 1, 2)
            identifiers_grid.setColumnStretch(1, 1)
            identifiers_grid.setColumnStretch(2, 1)
            local_box.addWidget(identifiers_group)

            sequence_group = QtWidgets.QGroupBox("Protein Sequence")
            sequence_box = QtWidgets.QVBoxLayout(sequence_group)
            self.txt_bioseq_sequence = QtWidgets.QPlainTextEdit()
            self.txt_bioseq_sequence.setObjectName("bioseqLocalSequence")
            self.txt_bioseq_sequence.setPlaceholderText(
                "Paste protein sequence (single-letter amino acids) or import from object/chain."
            )
            self.txt_bioseq_sequence.setMinimumHeight(120)
            sequence_box.addWidget(self.txt_bioseq_sequence)
            local_box.addWidget(sequence_group)

            actions_group = QtWidgets.QGroupBox("Analysis Actions")
            actions_grid = QtWidgets.QGridLayout(actions_group)
            self.btn_bioseq_run_local = QtWidgets.QPushButton("Run Local Simulation-Readiness Analysis")
            self.btn_bioseq_run_local.clicked.connect(self._bioseq_run_local_analysis)
            actions_grid.addWidget(self.btn_bioseq_run_local, 0, 0, 1, 2)
            self.btn_bioseq_run_msa = QtWidgets.QPushButton("Compute MSA Conservation")
            self.btn_bioseq_run_msa.clicked.connect(self._bioseq_run_msa_conservation)
            actions_grid.addWidget(self.btn_bioseq_run_msa, 1, 0)
            self.btn_bioseq_clear = QtWidgets.QPushButton("Clear")
            self.btn_bioseq_clear.clicked.connect(lambda: self.txt_bioseq_sequence.setPlainText(""))
            actions_grid.addWidget(self.btn_bioseq_clear, 1, 1)
            self.btn_bioseq_open_summary = QtWidgets.QPushButton("Open Summary...")
            self.btn_bioseq_open_summary.clicked.connect(self._bioseq_open_summary_dialog)
            actions_grid.addWidget(self.btn_bioseq_open_summary, 2, 0)
            self.btn_bioseq_open_motifs = QtWidgets.QPushButton("Open Motifs...")
            self.btn_bioseq_open_motifs.clicked.connect(self._bioseq_open_motif_dialog)
            actions_grid.addWidget(self.btn_bioseq_open_motifs, 2, 1)
            self.btn_bioseq_open_msa = QtWidgets.QPushButton("Open MSA...")
            self.btn_bioseq_open_msa.clicked.connect(self._bioseq_open_msa_dialog)
            actions_grid.addWidget(self.btn_bioseq_open_msa, 3, 0)
            self.btn_bioseq_open_questions = QtWidgets.QPushButton("Open Questions...")
            self.btn_bioseq_open_questions.clicked.connect(self._bioseq_open_questions_dialog)
            actions_grid.addWidget(self.btn_bioseq_open_questions, 3, 1)
            actions_grid.setColumnStretch(0, 1)
            actions_grid.setColumnStretch(1, 1)
            local_box.addWidget(actions_group)
            self.lbl_bioseq_local_hint = QtWidgets.QLabel(
                "Local tab is compact. Use the buttons above to open dedicated windows for each analysis tool."
            )
            self.lbl_bioseq_local_hint.setWordWrap(True)
            local_box.addWidget(self.lbl_bioseq_local_hint)
            local_box.addStretch(1)
            local_idx = tabs.addTab(tab_local, "Local")
            tabs.setTabToolTip(local_idx, "Local Analysis")

            # Tab 2: external tool launcher
            tab_tools = QtWidgets.QWidget()
            tool_outer = QtWidgets.QVBoxLayout(tab_tools)
            tool_outer.setContentsMargins(0, 0, 0, 0)
            tool_scroll = QtWidgets.QScrollArea(tab_tools)
            tool_scroll.setObjectName("bioseqToolScrollArea")
            tool_scroll.setProperty("leonardoVerticalOnly", True)
            tool_scroll.setWidgetResizable(True)
            tool_scroll.setFrameShape(QtWidgets.QFrame.NoFrame)
            tool_scroll.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarAlwaysOff)
            tool_body = QtWidgets.QWidget(tool_scroll)
            tool_scroll.setWidget(tool_body)
            tool_outer.addWidget(tool_scroll, 1)
            tool_box = QtWidgets.QVBoxLayout(tool_body)
            tool_box.setContentsMargins(10, 10, 10, 10)
            tool_box.setSpacing(10)
            self.lbl_bioseq_catalog = QtWidgets.QLabel("")
            self.lbl_bioseq_catalog.setWordWrap(True)
            tool_box.addWidget(self.lbl_bioseq_catalog)
            grp_tools = QtWidgets.QGroupBox("Open Web Tools")
            grid = QtWidgets.QGridLayout(grp_tools)
            btn_specs = [
                ("A) BLAST", "blast"),
                ("A) HMMER", "hmmer"),
                ("B) MSA (Clustal Omega)", "msa"),
                ("C) InterPro (Domains)", "interpro"),
                ("D) IUPred (Disorder)", "iupred"),
                ("E) DeepTMHMM", "tmhmm"),
                ("E) SignalP", "signalp"),
                ("F) ScanPROSITE", "prosite"),
                ("Coevolution (EVcouplings)", "coevolution"),
            ]
            self._bioseq_tool_buttons = {}
            for i, (label, key) in enumerate(btn_specs):
                b = QtWidgets.QPushButton(label)
                b.clicked.connect(lambda _checked=False, k=key: self._bioseq_open_tool_popup(k))
                rr = i // 2
                cc = i % 2
                grid.addWidget(b, rr, cc)
                self._bioseq_tool_buttons[str(key)] = b
            grid.setColumnStretch(0, 1)
            grid.setColumnStretch(1, 1)
            tool_box.addWidget(grp_tools)
            tool_box.addStretch(1)
            tools_idx = tabs.addTab(tab_tools, "Tools")
            tabs.setTabToolTip(tools_idx, "Tool Launcher")

            # Tab 3: scientific question mapper
            tab_q = QtWidgets.QWidget()
            q_box = QtWidgets.QVBoxLayout(tab_q)
            self.tbl_bioseq_questions = QtWidgets.QTableWidget(0, 3)
            self.tbl_bioseq_questions.setObjectName("bioseqQuestionsTable")
            self.tbl_bioseq_questions.setHorizontalHeaderLabels(
                ["Question", "Recommended Analysis", "Current Result"]
            )
            self.tbl_bioseq_questions.setSelectionBehavior(QtWidgets.QAbstractItemView.SelectRows)
            self.tbl_bioseq_questions.setEditTriggers(QtWidgets.QAbstractItemView.NoEditTriggers)
            self.tbl_bioseq_questions.setWordWrap(True)
            self.tbl_bioseq_questions.setTextElideMode(QtCore.Qt.ElideNone)
            self.tbl_bioseq_questions.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarAlwaysOff)
            self.tbl_bioseq_questions.verticalHeader().setVisible(False)
            q_box.addWidget(self.tbl_bioseq_questions, 1)
            try:
                hdr = self.tbl_bioseq_questions.horizontalHeader()
                hdr.setSectionResizeMode(0, QtWidgets.QHeaderView.Stretch)
                hdr.setSectionResizeMode(1, QtWidgets.QHeaderView.Stretch)
                hdr.setSectionResizeMode(2, QtWidgets.QHeaderView.Stretch)
            except Exception:
                pass
            questions_idx = tabs.addTab(tab_q, "Questions")
            tabs.setTabToolTip(questions_idx, "Scientific Questions")
            self._bioseq_setup_local_tool_popups()

            self.lbl_bioseq_status = QtWidgets.QLabel(
                "Status: import/paste sequence and run local analysis. Use web tools for full homolog/domain/disorder workflows."
            )
            self.lbl_bioseq_status.setWordWrap(True)
            vbox.addWidget(self.lbl_bioseq_status)
            close_row = QtWidgets.QHBoxLayout()
            close_row.addStretch(1)
            btn_close = QtWidgets.QPushButton("Close")
            btn_close.clicked.connect(self._bioseq_dialog.close)
            close_row.addWidget(btn_close)
            vbox.addLayout(close_row)

            self.btn_open_bioseq = QtWidgets.QPushButton("Sequence Bioinformatics...")
            self.btn_open_bioseq.setToolTip(
                "Analyze sequence for structural simulation planning: homologs, MSA, domains, disorder, TM/signal, motifs"
            )
            self.btn_open_bioseq.clicked.connect(self._show_bioseq_dialog)
            if hasattr(self, "verticalLayout"):
                insert_idx = 6 if self.verticalLayout.count() >= 6 else self.verticalLayout.count()
                self.verticalLayout.insertWidget(insert_idx, self.btn_open_bioseq)
            else:
                self.layout().addWidget(self.btn_open_bioseq)

            self._bioseq_populate_catalog_text()
            self._bioseq_populate_question_table()
            self._bioseq_refresh_object_combo()
        except Exception as e:
            print(f"Bioseq UI Setup Error: {e}")
