    def _bioseq_show_popup_dialog(self, dlg):
        if dlg is None:
            return
        try:
            self._fit_dialog_to_screen(dlg)
            dlg.show()
            dlg.raise_()
            dlg.activateWindow()
        except Exception:
            pass
    def _bioseq_open_summary_dialog(self):
        self._bioseq_show_popup_dialog(getattr(self, "_bioseq_summary_dialog", None))
    def _bioseq_open_motif_dialog(self):
        try:
            rep = dict(getattr(self, "_bioseq_last_report", {}) or {})
            seq = self._bioseq_current_sequence() or str(rep.get("sequence", "") or "")
            if seq and rep:
                self._bioseq_update_motif_summary_popup(seq, rep)
        except Exception:
            pass
        self._bioseq_show_popup_dialog(getattr(self, "_bioseq_motif_dialog", None))
    def _bioseq_open_msa_dialog(self):
        self._bioseq_show_popup_dialog(getattr(self, "_bioseq_msa_dialog", None))
    def _bioseq_open_questions_dialog(self):
        self._bioseq_populate_question_table()
        self._bioseq_show_popup_dialog(getattr(self, "_bioseq_questions_dialog", None))
    def _bioseq_current_chain_id(self):
        try:
            return self._normalize_chain_id(self.cmb_bioseq_chain.currentData())
        except Exception:
            return ""
    def _bioseq_clear_sequence_highlights(self):
        editor = getattr(self, "txt_bioseq_sequence", None)
        if editor is None:
            return
        try:
            editor.setExtraSelections([])
        except Exception:
            pass
    def _bioseq_apply_sequence_highlights(self, ranges):
        editor = getattr(self, "txt_bioseq_sequence", None)
        if editor is None:
            return
        try:
            raw = str(editor.toPlainText() or "")
        except Exception:
            raw = ""
        try:
            aa_pos_map = list(bioseq_sequence_text_residue_offsets(raw, keep_gaps=False) or [])
        except Exception:
            aa_pos_map = [i for i, ch in enumerate(raw) if str(ch).isalpha()]
        selections = []
        for ent in list(ranges or []):
            if not isinstance(ent, dict):
                continue
            try:
                a = int(ent.get("start", 0) or 0)
                b = int(ent.get("end", 0) or 0)
            except Exception:
                continue
            if a <= 0 or b <= 0:
                continue
            if b < a:
                a, b = b, a
            if a > len(aa_pos_map):
                continue
            b = min(int(b), int(len(aa_pos_map)))
            if b < a:
                continue
            try:
                c = QtGui.QColor(str(ent.get("color", "#ffe08a") or "#ffe08a"))
            except Exception:
                c = QtGui.QColor("#ffe08a")
            cursor = editor.textCursor()
            cursor.setPosition(int(aa_pos_map[a - 1]))
            cursor.setPosition(int(aa_pos_map[b - 1]) + 1, QtGui.QTextCursor.KeepAnchor)
            sel = QtWidgets.QTextEdit.ExtraSelection()
            sel.cursor = cursor
            fmt = QtGui.QTextCharFormat()
            fmt.setBackground(c)
            fmt.setForeground(QtGui.QBrush(QtGui.QColor("#101010")))
            sel.format = fmt
            selections.append(sel)
        try:
            editor.setExtraSelections(selections)
        except Exception:
            pass
    def _bioseq_highlight_motif_in_sequence(self, start_pos=None, end_pos=None):
        specs = []
        rep = dict(getattr(self, "_bioseq_last_report", {}) or {})
        for m in list(rep.get("motifs", []) or []):
            try:
                a = int(m.get("start", 0) or 0)
                b = int(m.get("end", 0) or 0)
            except Exception:
                continue
            if a > 0 and b > 0:
                specs.append({"start": a, "end": b, "color": "#d8f0ff"})
        try:
            a_sel = int(start_pos or 0)
            b_sel = int(end_pos or 0)
        except Exception:
            a_sel = 0
            b_sel = 0
        if a_sel > 0 and b_sel > 0:
            specs.append({"start": a_sel, "end": b_sel, "color": "#ffb3b3"})
        self._bioseq_apply_sequence_highlights(specs)
    def _bioseq_motif_row_values(self, row=None):
        tbl = getattr(self, "tbl_bioseq_motifs", None)
        if tbl is None:
            return {}
        r = int(row if row is not None else tbl.currentRow())
        if r < 0 or r >= int(tbl.rowCount()):
            return {}
        try:
            motif = str((tbl.item(r, 0).text() if tbl.item(r, 0) else "") or "")
        except Exception:
            motif = ""
        try:
            start = int((tbl.item(r, 1).text() if tbl.item(r, 1) else "0") or 0)
        except Exception:
            start = 0
        try:
            end = int((tbl.item(r, 2).text() if tbl.item(r, 2) else "0") or 0)
        except Exception:
            end = 0
        try:
            match = str((tbl.item(r, 3).text() if tbl.item(r, 3) else "") or "")
        except Exception:
            match = ""
        return {"motif": motif, "start": int(start), "end": int(end), "match": match}
    def _bioseq_on_motif_row_selected(self):
        vals = dict(self._bioseq_motif_row_values() or {})
        if not vals:
            self._bioseq_highlight_motif_in_sequence()
            self._bioseq_apply_structure_highlights(report=self._bioseq_last_report, msa=self._bioseq_last_msa)
            return
        self._bioseq_highlight_motif_in_sequence(vals.get("start"), vals.get("end"))
        self._bioseq_apply_structure_highlights(
            report=self._bioseq_last_report,
            msa=self._bioseq_last_msa,
            selected_motif=vals,
        )
        if hasattr(self, "lbl_bioseq_status"):
            self.lbl_bioseq_status.setText(
                f"Selected motif: {str(vals.get('motif', '') or 'motif')} "
                f"({int(vals.get('start', 0) or 0)}-{int(vals.get('end', 0) or 0)})."
            )
    def _bioseq_align_sequence_index_map(self, seq_a, seq_b):
        try:
            return dict(bioseq_align_residue_index_map(seq_a, seq_b).get("map", {}) or {})
        except Exception:
            return {}
    def _bioseq_build_seq_index_to_resi_map(self, seq_clean, obj_name, chain_id):
        """Sequence index (1-based) -> PDB residue label ("184", "184A", "-3")."""
        seq = str(seq_clean or "").strip()
        n = int(len(seq))
        if n <= 0:
            return {}
        out = {}
        meta = dict(getattr(self, "_bioseq_sequence_meta", {}) or {})
        idx_to_resi = list(meta.get("index_to_resi", []) or [])
        if len(idx_to_resi) == n:
            out = {i: str(rv) for i, rv in enumerate(idx_to_resi, start=1)}
        ch = self._normalize_chain_id(chain_id)
        data = {}
        try:
            if (not self._bioseq_chain_data) and obj_name:
                self._bioseq_on_object_changed(obj_name)
            data = dict((self._bioseq_chain_data or {}).get(ch, {}) or {})
        except Exception:
            data = {}
        labels = [str(x) for x in list(data.get("residue_labels", []) or data.get("positions", []) or [])]
        observed_seq = bioseq_clean_sequence(str(data.get("observed_seq", "") or ""))
        if labels and observed_seq and len(labels) == len(observed_seq):
            if seq == observed_seq:
                out = {i: labels[i - 1] for i in range(1, n + 1)}
            else:
                # full/RCSB/modeler sequence vs observed chain: align (gaps, tags, mutations)
                for ii, jj in self._bioseq_align_sequence_index_map(seq, observed_seq).items():
                    if 1 <= int(jj) <= len(labels):
                        out[int(ii)] = labels[int(jj) - 1]
        if out:
            return out
        start_guess = 1
        for cand in (meta.get("sequence_start", None), data.get("start", None)):
            try:
                start_guess = int(cand)
                break
            except (TypeError, ValueError):
                continue
        return {i: str(start_guess + i - 1) for i in range(1, n + 1)}
    def _bioseq_chain_selection_expr(self, obj_name, chain_id):
        obj = str(obj_name or "").strip()
        if not obj:
            return ""
        sel = f"({obj}) and polymer.protein"
        ch = self._normalize_chain_id(chain_id)
        if ch.strip():
            ch_esc = str(ch).replace("\\", "\\\\").replace('"', '\\"')
            sel += f' and chain "{ch_esc}"'
        return sel
    def _bioseq_residue_ranges_for_seq_range(self, seq_start, seq_end, idx_to_resi):
        """PDB residue labels (in chain order) covered by sequence positions seq_start..seq_end."""
        try:
            a = int(seq_start or 0)
            b = int(seq_end or 0)
        except Exception:
            return []
        if a <= 0 or b <= 0:
            return []
        if b < a:
            a, b = b, a
        out = []
        for i in range(a, b + 1):
            lbl = idx_to_resi.get(i)
            if lbl is not None and str(lbl) not in out:
                out.append(str(lbl))
        return out
    def _bioseq_resi_expression(self, labels):
        # plain numbers collapse to ranges; insertion codes (184A) and negatives stay explicit
        parts = []
        run = []

        def _flush():
            if run:
                parts.append(f"{run[0]}-{run[-1]}" if len(run) > 1 else str(run[0]))
                run.clear()

        for lbl in list(labels or []):
            txt = str(lbl).strip()
            if re.fullmatch(r"\d+", txt):
                if run and int(txt) != run[-1] + 1:
                    _flush()
                run.append(int(txt))
                continue
            _flush()
            if txt:
                parts.append(txt.replace("-", "\\-"))
        _flush()
        return "+".join(parts)
    def _bioseq_color_residue_ranges(self, obj_name, chain_id, ranges, color_name):
        resi_expr = self._bioseq_resi_expression(ranges)
        if not resi_expr:
            return
        base_sel = self._bioseq_chain_selection_expr(obj_name, chain_id)
        if not base_sel:
            return
        target_sel = f"{base_sel} and resi {resi_expr}"
        try:
            cmd.color(str(color_name or "cyan"), target_sel)
        except Exception:
            pass
    def _bioseq_apply_structure_highlights(self, report=None, msa=None, selected_motif=None):
        rep = dict(report or getattr(self, "_bioseq_last_report", {}) or {})
        obj = self._bioseq_current_object()
        ch = self._bioseq_current_chain_id()
        meta = dict(getattr(self, "_bioseq_sequence_meta", {}) or {})
        if not obj:
            obj = str(meta.get("object", "") or "").strip()
        if not ch:
            ch = self._normalize_chain_id(meta.get("chain", ""))
        if not obj:
            return False
        try:
            if int(cmd.count_atoms(f"({obj}) and polymer.protein")) <= 0:
                return False
        except Exception:
            return False
        base_sel = self._bioseq_chain_selection_expr(obj, ch)
        if not base_sel:
            return False
        seq = self._bioseq_current_sequence()
        if not seq:
            seq = bioseq_clean_sequence(str(rep.get("sequence", "") or ""))
        if not seq:
            return False
        idx_map = self._bioseq_build_seq_index_to_resi_map(seq, obj, ch)
        if not idx_map:
            return False
        try:
            cmd.show("cartoon", base_sel)
            cmd.color("gray80", base_sel)
        except Exception:
            pass
        # Structured core baseline.
        core = dict(rep.get("suggested_structured_core", {}) or {})
        try:
            a = int(core.get("start", 0) or 0)
            b = int(core.get("end", 0) or 0)
        except Exception:
            a = 0
            b = 0
        if a > 0 and b > 0:
            self._bioseq_color_residue_ranges(
                obj, ch, self._bioseq_residue_ranges_for_seq_range(a, b, idx_map), "palegreen"
            )
        # Signal peptide.
        sig = dict(rep.get("signal_peptide", {}) or {})
        if bool(sig.get("predicted", False)):
            try:
                csite = int(sig.get("cleavage_site_estimate", 0) or 0)
            except Exception:
                csite = 0
            if csite > 1:
                self._bioseq_color_residue_ranges(
                    obj, ch, self._bioseq_residue_ranges_for_seq_range(1, csite, idx_map), "yellow"
                )
        # Transmembrane and disorder regions.
        for seg in list(rep.get("tm_segments", []) or []):
            try:
                sa = int(seg.get("start", 0) or 0)
                sb = int(seg.get("end", 0) or 0)
            except Exception:
                continue
            self._bioseq_color_residue_ranges(
                obj, ch, self._bioseq_residue_ranges_for_seq_range(sa, sb, idx_map), "orange"
            )
        for seg in list(rep.get("disorder_segments", []) or []):
            try:
                sa = int(seg.get("start", 0) or 0)
                sb = int(seg.get("end", 0) or 0)
            except Exception:
                continue
            self._bioseq_color_residue_ranges(
                obj, ch, self._bioseq_residue_ranges_for_seq_range(sa, sb, idx_map), "magenta"
            )
        # Motif hits.
        for m in list(rep.get("motifs", []) or []):
            try:
                sa = int(m.get("start", 0) or 0)
                sb = int(m.get("end", 0) or 0)
            except Exception:
                continue
            self._bioseq_color_residue_ranges(
                obj, ch, self._bioseq_residue_ranges_for_seq_range(sa, sb, idx_map), "cyan"
            )
        # MSA high-conservation landmarks (if available).
        msa_data = dict(msa or getattr(self, "_bioseq_last_msa", {}) or {})
        top_rows = list(msa_data.get("top_positions", []) or [])
        cons_marks = []
        for row in list(top_rows[:50]):
            try:
                if "reference_position" in row:
                    pos = int(row.get("reference_position", 0) or 0)
                else:
                    pos = int(row.get("position", 0) or 0)
                cons = float(row.get("conservation", 0.0) or 0.0)
                cov = float(row.get("coverage", 0.0) or 0.0)
            except Exception:
                continue
            if pos > 0 and cons >= 0.85 and cov >= 0.60:
                cons_marks.append(pos)
            if len(cons_marks) >= 25:
                break
        for pos in list(cons_marks):
            self._bioseq_color_residue_ranges(
                obj, ch, self._bioseq_residue_ranges_for_seq_range(pos, pos, idx_map), "marine"
            )
        # Selected motif gets strong focus color.
        sel = dict(selected_motif or {})
        try:
            sa = int(sel.get("start", 0) or 0)
            sb = int(sel.get("end", 0) or 0)
        except Exception:
            sa = 0
            sb = 0
        if sa > 0 and sb > 0:
            focus_ranges = self._bioseq_residue_ranges_for_seq_range(sa, sb, idx_map)
            self._bioseq_color_residue_ranges(obj, ch, focus_ranges, "red")
        return True
    def _bioseq_sync_object_chain_selection(self, obj_name, chain_id=""):
        obj = str(obj_name or "").strip()
        if not obj:
            return False
        self._bioseq_refresh_object_combo()
        if hasattr(self, "cmb_bioseq_object"):
            idx_obj = self.cmb_bioseq_object.findText(obj)
            if idx_obj >= 0:
                self.cmb_bioseq_object.setCurrentIndex(idx_obj)
            else:
                self.cmb_bioseq_object.addItem(obj)
                self.cmb_bioseq_object.setCurrentText(obj)
        self._bioseq_on_object_changed(obj)
        ch = self._normalize_chain_id(chain_id)
        if hasattr(self, "cmb_bioseq_chain") and self.cmb_bioseq_chain.count() > 0:
            idx_ch = self.cmb_bioseq_chain.findData(ch)
            if idx_ch >= 0:
                self.cmb_bioseq_chain.setCurrentIndex(idx_ch)
        return True
    def _bioseq_fetch_rcsb_structure_object(self, pdb_id, preferred_chain=""):
        pid = str(pdb_id or "").strip().upper()
        if not pid:
            return ""
        existing = []
        try:
            existing = list(cmd.get_names("objects"))
        except Exception:
            existing = []
        for cand in (pid, pid.lower()):
            try:
                if cand in existing and int(cmd.count_atoms(cand)) > 0:
                    self._bioseq_sync_object_chain_selection(cand, preferred_chain)
                    return str(cand)
            except Exception:
                continue
        base = self._dock_safe_obj_name(pid.lower()) if hasattr(self, "_dock_safe_obj_name") else pid.lower()
        obj_name = str(base or pid.lower())
        if obj_name in existing:
            k = 2
            while f"{obj_name}_{k}" in existing:
                k += 1
            obj_name = f"{obj_name}_{k}"
        try:
            cmd.fetch(pid, name=obj_name, type="pdb", async_=0)
        except Exception:
            cmd.fetch(pid, obj_name)
        try:
            if int(cmd.count_atoms(obj_name)) <= 0:
                raise RuntimeError("RCSB fetch returned empty object.")
        except Exception as e:
            raise RuntimeError(f"Failed to load fetched structure for {pid}: {e}")
        try:
            self.loaded_object = obj_name
            self._traj_topology_object = obj_name
        except Exception:
            pass
        self._bioseq_sync_object_chain_selection(obj_name, preferred_chain)
        return str(obj_name)
    def _bioseq_current_object(self):
        try:
            return str(self.cmb_bioseq_object.currentText() or "").strip()
        except Exception:
            return ""
    def _bioseq_refresh_object_combo(self):
        if not hasattr(self, "cmb_bioseq_object"):
            return
        current = str(self.cmb_bioseq_object.currentText() or "").strip()
        candidates = []
        try:
            names = list(cmd.get_names("objects"))
        except Exception:
            names = []
        for obj in list(names or []):
            try:
                n = int(cmd.count_atoms(f'(model "{obj}") and polymer.protein'))
            except Exception:
                n = 0
            if n > 0:
                candidates.append(str(obj))
        if not candidates:
            candidates = [str(n) for n in list(names or [])]
        candidates = sorted(set(candidates))
        self.cmb_bioseq_object.blockSignals(True)
        self.cmb_bioseq_object.clear()
        for obj in list(candidates or []):
            self.cmb_bioseq_object.addItem(str(obj))
        preferred = str(current or "").strip()
        if not preferred:
            preferred = str(getattr(self, "loaded_object", "") or "").strip()
        if preferred:
            idx = self.cmb_bioseq_object.findText(preferred)
            if idx >= 0:
                self.cmb_bioseq_object.setCurrentIndex(idx)
        self.cmb_bioseq_object.blockSignals(False)
        self._bioseq_on_object_changed(self.cmb_bioseq_object.currentText() if self.cmb_bioseq_object.count() else "")
    def _bioseq_on_object_changed(self, _text):
        obj = self._bioseq_current_object()
        self._bioseq_chain_data = {}
        if obj:
            try:
                self._bioseq_chain_data = dict(self._modeler_extract_chain_data(obj) or {})
            except Exception:
                self._bioseq_chain_data = {}
        if hasattr(self, "cmb_bioseq_chain"):
            self.cmb_bioseq_chain.blockSignals(True)
            self.cmb_bioseq_chain.clear()
            chain_keys = sorted(self._bioseq_chain_data.keys(), key=lambda c: (str(c).strip() == "", str(c)))
            for ch in list(chain_keys or []):
                self.cmb_bioseq_chain.addItem(self._modeler_chain_display(ch), ch)
            if not chain_keys:
                self.cmb_bioseq_chain.addItem("-", "")
            self.cmb_bioseq_chain.blockSignals(False)
        if hasattr(self, "edit_bioseq_pdb_id"):
            try:
                pid = str(self._modeler_infer_pdb_id(obj) or "")
                if pid and (not str(self.edit_bioseq_pdb_id.text() or "").strip()):
                    self.edit_bioseq_pdb_id.setText(pid)
            except Exception:
                pass
    def _bioseq_set_sequence_text(self, seq, source_note="", seq_meta=None):
        seq_clean = bioseq_clean_sequence(seq)
        if not seq_clean:
            return False
        self.txt_bioseq_sequence.setPlainText(seq_clean)
        meta = dict(seq_meta or {})
        if not meta:
            meta = {
                "source": "manual",
                "object": self._bioseq_current_object(),
                "chain": self._bioseq_current_chain_id(),
            }
        meta["sequence"] = str(seq_clean)
        try:
            uid = str(self.edit_bioseq_uniprot_id.text() or "").strip().upper()
            if uid:
                meta["uniprot_id"] = uid
        except Exception:
            pass
        self._bioseq_sequence_meta = dict(meta)
        self._bioseq_clear_sequence_highlights()
        if hasattr(self, "lbl_bioseq_status"):
            msg = f"Loaded sequence ({len(seq_clean)} aa)."
            if source_note:
                msg += f" Source: {source_note}."
            self.lbl_bioseq_status.setText(msg)
        return True
    def _bioseq_import_chain_sequence(self):
        obj = self._bioseq_current_object()
        if not obj:
            QtWidgets.QMessageBox.warning(self, "Bioinformatics", "Select a structure object first.")
            return
        ch = ""
        try:
            ch = self._normalize_chain_id(self.cmb_bioseq_chain.currentData())
        except Exception:
            ch = ""
        if (not self._bioseq_chain_data) or (ch not in self._bioseq_chain_data):
            self._bioseq_on_object_changed(obj)
        data = dict(self._bioseq_chain_data.get(ch, {}) or {})
        seq = str(data.get("observed_seq", "") or "")
        meta = {
            "source": "observed_chain",
            "object": obj,
            "chain": ch,
            "sequence_start": int(data.get("start", 1) or 1),
            "index_to_resi": [str(x) for x in list(data.get("residue_labels", []) or data.get("positions", []) or [])],
        }
        if not self._bioseq_set_sequence_text(
            seq,
            source_note=f"{obj} chain {self._modeler_chain_display(ch)}",
            seq_meta=meta,
        ):
            QtWidgets.QMessageBox.warning(self, "Bioinformatics", "Could not extract chain sequence from selected object.")
    def _bioseq_use_modeler_sequence(self):
        seq = ""
        try:
            if hasattr(self, "txt_modeler_full_sequence"):
                seq = str(self.txt_modeler_full_sequence.toPlainText() or "")
        except Exception:
            seq = ""
        seq_start = 1
        try:
            if hasattr(self, "spin_modeler_seq_start"):
                seq_start = int(self.spin_modeler_seq_start.value())
        except Exception:
            seq_start = 1
        meta = {
            "source": "modeler_sequence",
            "object": self._bioseq_current_object(),
            "chain": self._bioseq_current_chain_id(),
            "sequence_start": int(seq_start),
        }
        if self._bioseq_set_sequence_text(seq, source_note="Protein Modeling panel", seq_meta=meta):
            return
        self._bioseq_import_chain_sequence()
    def _bioseq_fetch_rcsb_sequence(self):
        obj = self._bioseq_current_object()
        ch = ""
        try:
            ch = self._normalize_chain_id(self.cmb_bioseq_chain.currentData())
        except Exception:
            ch = ""
        pdb_id = ""
        try:
            pdb_id = str(self.edit_bioseq_pdb_id.text() or "").strip().upper()
        except Exception:
            pdb_id = ""
        if not pdb_id:
            pdb_id = str(self._modeler_infer_pdb_id(obj) or "").strip().upper()
        if not pdb_id:
            QtWidgets.QMessageBox.warning(self, "Bioinformatics", "Provide a 4-letter PDB ID or select an object with inferable PDB ID.")
            return
        try:
            seq = self._modeler_fetch_rcsb_chain_sequence(pdb_id, ch)
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "Bioinformatics", f"Failed to fetch RCSB sequence: {e}")
            return
        fetched_obj = ""
        fetch_note = ""
        try:
            fetched_obj = str(self._bioseq_fetch_rcsb_structure_object(pdb_id, preferred_chain=ch) or "")
            if fetched_obj:
                fetch_note = f" Structure object loaded: {fetched_obj}."
        except Exception as e:
            fetch_note = f" Structure fetch warning: {e}."
        meta = {
            "source": "rcsb",
            "pdb_id": pdb_id,
            "object": fetched_obj or obj,
            "chain": ch,
            "sequence_start": 1,
        }
        if not self._bioseq_set_sequence_text(
            seq,
            source_note=f"RCSB {pdb_id} chain {self._modeler_chain_display(ch)}.{fetch_note}",
            seq_meta=meta,
        ):
            QtWidgets.QMessageBox.warning(self, "Bioinformatics", f"No sequence returned for {pdb_id} chain {self._modeler_chain_display(ch)}.")
            return
        # Auto-run local analysis so structural coloring is ready immediately after RCSB import.
        try:
            self._bioseq_run_local_analysis()
        except Exception:
            pass
    def _bioseq_current_sequence(self):
        try:
            return str(bioseq_clean_sequence(self.txt_bioseq_sequence.toPlainText()))
        except Exception:
            return ""
    def _bioseq_open_external_url(self, url):
        u = str(url or "").strip()
        if not u:
            return False
        opened = False
        try:
            opened = bool(webbrowser.open(u, new=2))
        except Exception:
            opened = False
        if not opened:
            try:
                QtGui.QDesktopServices.openUrl(QtCore.QUrl(u))
                opened = True
            except Exception:
                opened = False
        return bool(opened)
