    def _bioseq_copy_text_to_clipboard(self, text):
        txt = str(text or "")
        if not txt:
            return
        try:
            cb = QtWidgets.QApplication.clipboard()
            if cb is not None:
                cb.setText(txt)
        except Exception:
            pass
    def _bioseq_open_tool_popup(self, tool_key):
        seq = self._bioseq_current_sequence()
        key = str(tool_key or "").strip().lower()
        spec = dict(self._bioseq_tool_popup_spec(key) or {})
        urls = dict(bioseq_build_external_tool_urls(seq) or {})
        url = str(urls.get(key, "") or "").strip()
        if key == "blast":
            try:
                base_urls = dict(bioseq_build_external_tool_urls("") or {})
                url = str(base_urls.get("blast", url) or url).strip()
            except Exception:
                pass
        if not url:
            QtWidgets.QMessageBox.warning(self, "Bioinformatics", f"No URL configured for tool '{key}'.")
            return
        dlg_parent = getattr(self, "_bioseq_dialog", self)
        dlg = QtWidgets.QDialog(dlg_parent)
        dlg.setWindowTitle(str(spec.get("title", key)))
        dlg._leonardo_scroll_checked = True
        dlg.resize(820, 680)
        dlg.setMinimumSize(600, 440)
        self._fit_dialog_to_screen(dlg, preferred_w=820, preferred_h=680, min_w=580, min_h=420)
        self._bioseq_tool_dialog = dlg
        self._bioseq_tool_dialog_key = key
        vbox = QtWidgets.QVBoxLayout(dlg)
        content_scroll = QtWidgets.QScrollArea(dlg)
        content_scroll.setObjectName("bioseqToolDialogScroll")
        content_scroll.setProperty("leonardoVerticalOnly", True)
        content_scroll.setWidgetResizable(True)
        content_scroll.setFrameShape(QtWidgets.QFrame.NoFrame)
        content_scroll.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarAlwaysOff)
        content = QtWidgets.QWidget(content_scroll)
        content.setObjectName("bioseqToolDialogContent")
        content_scroll.setWidget(content)
        vbox.addWidget(content_scroll, 1)
        content_box = QtWidgets.QVBoxLayout(content)
        content_box.setContentsMargins(8, 8, 8, 8)
        content_box.setSpacing(10)
        lbl = QtWidgets.QLabel(str(spec.get("objective", "")))
        lbl.setWordWrap(True)
        content_box.addWidget(lbl)
        url_group = QtWidgets.QGroupBox("Tool Address")
        url_box = QtWidgets.QVBoxLayout(url_group)
        edit_url = QtWidgets.QLineEdit(str(url))
        try:
            edit_url.setCursorPosition(0)
        except Exception:
            pass
        url_box.addWidget(edit_url)
        content_box.addWidget(url_group)
        params_group = QtWidgets.QGroupBox("Suggested Parameters")
        params_form = QtWidgets.QFormLayout(params_group)
        params_form.setRowWrapPolicy(QtWidgets.QFormLayout.WrapAllRows)
        params_form.setFieldGrowthPolicy(QtWidgets.QFormLayout.AllNonFixedFieldsGrow)
        params_form.setLabelAlignment(QtCore.Qt.AlignLeft | QtCore.Qt.AlignVCenter)
        params_form.setHorizontalSpacing(8)
        params_form.setVerticalSpacing(6)
        param_widgets = []
        for ent in list(spec.get("parameters", []) or []):
            if not isinstance(ent, (list, tuple)) or len(ent) < 2:
                continue
            lbl_p = str(ent[0] or "").strip()
            val_p = str(ent[1] or "").strip()
            w = QtWidgets.QLineEdit(val_p)
            params_form.addRow(lbl_p, w)
            param_widgets.append((lbl_p, w))
        content_box.addWidget(params_group)
        seq_group = QtWidgets.QGroupBox("Sequence")
        seq_box = QtWidgets.QVBoxLayout(seq_group)
        txt_seq = QtWidgets.QPlainTextEdit()
        txt_seq.setObjectName("bioseqToolSequence")
        txt_seq.setPlainText(str(seq or ""))
        txt_seq.setMinimumHeight(140)
        txt_seq.setPlaceholderText("Sequence used for this tool (editable).")
        seq_box.addWidget(txt_seq)
        content_box.addWidget(seq_group)
        content_box.addStretch(1)

        action_grid = QtWidgets.QGridLayout()
        action_grid.setHorizontalSpacing(8)
        action_grid.setVerticalSpacing(8)
        btn_copy_seq = QtWidgets.QPushButton("Copy Sequence")
        btn_copy_params = QtWidgets.QPushButton("Copy Parameter Notes")
        btn_open = QtWidgets.QPushButton("Open Tool")
        btn_open_copy = QtWidgets.QPushButton("Open Tool + Copy Sequence")
        btn_close = QtWidgets.QPushButton("Close")
        action_grid.addWidget(btn_copy_seq, 0, 0)
        action_grid.addWidget(btn_copy_params, 0, 1)
        action_grid.addWidget(btn_open, 1, 0)
        action_grid.addWidget(btn_open_copy, 1, 1)
        action_grid.setColumnStretch(0, 1)
        action_grid.setColumnStretch(1, 1)
        vbox.addLayout(action_grid)
        close_row = QtWidgets.QHBoxLayout()
        close_row.addStretch(1)
        close_row.addWidget(btn_close)
        vbox.addLayout(close_row)

        def _param_notes():
            lines = [f"{str(spec.get('title', key))} suggested parameters:"]
            for lbl_p, w in list(param_widgets or []):
                try:
                    vv = str(w.text() or "").strip()
                except Exception:
                    vv = ""
                lines.append(f"- {lbl_p}: {vv}")
            return "\n".join(lines)

        def _resolve_tool_url_from_editor():
            manual_url = str(edit_url.text() or "").strip()
            if manual_url.lower().startswith(("http://", "https://")):
                return manual_url
            seq_local = bioseq_clean_sequence(str(txt_seq.toPlainText() or ""))
            urls_local = dict(bioseq_build_external_tool_urls(seq_local) or {})
            if key == "blast":
                urls_local = dict(bioseq_build_external_tool_urls("") or {})
            url_local = str(urls_local.get(key, "") or "").strip()
            if not url_local:
                url_local = manual_url
            return str(url_local)

        btn_copy_seq.clicked.connect(lambda: self._bioseq_copy_text_to_clipboard(txt_seq.toPlainText()))
        btn_copy_params.clicked.connect(lambda: self._bioseq_copy_text_to_clipboard(_param_notes()))
        btn_close.clicked.connect(dlg.close)

        def _open(copy_seq=False):
            url_open = _resolve_tool_url_from_editor()
            ok = self._bioseq_open_external_url(url_open)
            if not ok:
                QtWidgets.QMessageBox.warning(self, "Bioinformatics", f"Could not open tool URL:\n{url_open}")
                return
            if copy_seq:
                self._bioseq_copy_text_to_clipboard(txt_seq.toPlainText())
            if hasattr(self, "lbl_bioseq_status"):
                self.lbl_bioseq_status.setText(f"Opened {key} in browser.")

        btn_open.clicked.connect(lambda: _open(copy_seq=False))
        btn_open_copy.clicked.connect(lambda: _open(copy_seq=True))
        try:
            dlg.exec()
        except Exception:
            dlg.exec_()
    def _bioseq_open_tool(self, tool_key):
        # Compatibility wrapper
        self._bioseq_open_tool_popup(tool_key)
    def _bioseq_populate_catalog_text(self):
        if not hasattr(self, "lbl_bioseq_catalog"):
            return
        lines = ["Recommended sequence analyses before structural simulation:"]
        for ent in list(BIOSEQ_ANALYSIS_CATALOG or []):
            title = str(ent.get("title", "") or "").strip()
            tools = str(ent.get("tools", "") or "").strip()
            purpose = str(ent.get("purpose", "") or "").strip()
            lines.append(f"- {title}: {tools}. {purpose}")
        self.lbl_bioseq_catalog.setText(
            "Choose an external analysis tool. Each button opens a clean form with the sequence, "
            "recommended parameters, and launch options."
        )
        self.lbl_bioseq_catalog.setToolTip("\n".join(lines))
    def _bioseq_populate_question_table(self, answers=None):
        answer_map = {}
        for row in list(answers or []):
            q = str((row or {}).get("question", "") or "").strip()
            if q:
                answer_map[q] = str((row or {}).get("answer_hint", "") or "").strip()
        tables = []
        if hasattr(self, "tbl_bioseq_questions"):
            tables.append(self.tbl_bioseq_questions)
        if hasattr(self, "tbl_bioseq_questions_popup"):
            tables.append(self.tbl_bioseq_questions_popup)
        for tbl in list(tables or []):
            tbl.setRowCount(0)
            for row in list(BIOSEQ_QUESTION_MAP or []):
                q = str(row.get("question", "") or "").strip()
                a = str(row.get("analysis", "") or "").strip()
                hint = str(answer_map.get(q, "Run analysis to estimate."))
                r = int(tbl.rowCount())
                tbl.insertRow(r)
                tbl.setItem(r, 0, QtWidgets.QTableWidgetItem(q))
                tbl.setItem(r, 1, QtWidgets.QTableWidgetItem(a))
                tbl.setItem(r, 2, QtWidgets.QTableWidgetItem(hint))
                for col, full_text in enumerate((q, a, hint)):
                    item = tbl.item(r, col)
                    if item is not None:
                        item.setToolTip(full_text)
            try:
                tbl.resizeRowsToContents()
                tbl.verticalHeader().setMinimumSectionSize(42)
            except Exception:
                pass
    def _bioseq_format_range_list(self, segments, value_key=""):
        out = []
        for seg in list(segments or []):
            try:
                a = int(seg.get("start", 0) or 0)
                b = int(seg.get("end", 0) or 0)
            except Exception:
                continue
            if (a <= 0) or (b <= 0):
                continue
            base = f"{a}-{b}"
            if value_key:
                try:
                    vv = float(seg.get(value_key, np.nan))
                    if np.isfinite(vv):
                        base += f" ({value_key}={vv:.2f})"
                except Exception:
                    pass
            out.append(base)
        return ", ".join(out) if out else "none"
    def _bioseq_uniprot_lookup_context(self):
        meta = dict(getattr(self, "_bioseq_sequence_meta", {}) or {})
        accession = ""
        try:
            accession = str(self.edit_bioseq_uniprot_id.text() or "").strip().upper()
        except Exception:
            accession = ""
        if not accession:
            accession = str(meta.get("uniprot_id", "") or "").strip().upper()
        pdb_id = ""
        try:
            pdb_id = str(self.edit_bioseq_pdb_id.text() or "").strip().upper()
        except Exception:
            pdb_id = ""
        if not pdb_id:
            pdb_id = str(meta.get("pdb_id", "") or "").strip().upper()
        if not pdb_id:
            try:
                pdb_id = str(self._modeler_infer_pdb_id(self._bioseq_current_object()) or "").strip().upper()
            except Exception:
                pdb_id = ""
        chain = self._bioseq_current_chain_id()
        if not chain:
            chain = self._normalize_chain_id(meta.get("chain", ""))
        return {"accession": accession, "pdb_id": pdb_id, "chain": chain}
    def _bioseq_fetch_uniprot_annotations_for_report(self, seq):
        ctx = dict(self._bioseq_uniprot_lookup_context() or {})
        try:
            return dict(
                bioseq_fetch_uniprot_feature_summary(
                    seq,
                    accession=ctx.get("accession", ""),
                    pdb_id=ctx.get("pdb_id", ""),
                    chain_id=ctx.get("chain", ""),
                    timeout=6.0,
                    max_results=6,
                    max_features=40,
                )
                or {}
            )
        except Exception as e:
            return {"ok": False, "error": f"UniProt lookup failed: {e}", "features": []}
    def _bioseq_format_uniprot_feature_line(self, feature):
        row = dict(feature or {})
        ftype = str(row.get("type", "Feature") or "Feature")
        desc = str(row.get("description", "") or "").strip()
        try:
            a = int(row.get("start", 0) or 0)
            b = int(row.get("end", 0) or 0)
        except Exception:
            a = 0
            b = 0
        if a > 0 and b > 0:
            loc = f"UniProt {a}" if a == b else f"UniProt {a}-{b}"
        else:
            loc = "UniProt position unknown"
        try:
            qa = int(row.get("query_start", 0) or 0)
            qb = int(row.get("query_end", 0) or 0)
        except Exception:
            qa = 0
            qb = 0
        if qa > 0 and qb > 0:
            loc += f"; local {qa}" if qa == qb else f"; local {qa}-{qb}"
        label = f"{ftype}: {desc}" if desc else ftype
        return f"  - {label} ({loc})"
    def _bioseq_update_motif_summary_popup(self, seq, report):
        txt = getattr(self, "txt_bioseq_motif_summary", None)
        if txt is None:
            return ""
        rep = dict(report or {})
        try:
            lines = list(
                bioseq_build_motif_summary_lines(
                    seq,
                    local_motifs=list(rep.get("motifs", []) or []),
                    uniprot_summary=dict(rep.get("uniprot", {}) or {}),
                    max_items=60,
                    motif_total=rep.get("motif_total"),
                )
                or []
            )
        except Exception as e:
            lines = [f"Motif summary failed: {e}"]
        summary = "\n".join(str(x) for x in lines)
        try:
            txt.setPlainText(summary)
            txt.moveCursor(QtGui.QTextCursor.Start)
        except Exception:
            pass
        return summary
    def _bioseq_show_motif_summary_popup(self):
        dlg = getattr(self, "_bioseq_motif_dialog", None)
        if dlg is None:
            return
        self._bioseq_show_popup_dialog(dlg)
    def _bioseq_run_local_analysis(self):
        seq = self._bioseq_current_sequence()
        if not seq:
            QtWidgets.QMessageBox.warning(self, "Bioinformatics", "Sequence is empty.")
            return
        rep = dict(bioseq_build_simulation_readiness_report(seq) or {})
        if not bool(rep.get("ok", False)):
            QtWidgets.QMessageBox.warning(self, "Bioinformatics", str(rep.get("error", "Local analysis failed.")))
            return
        metrics = dict(rep.get("metrics", {}) or {})
        tm_segments = list(rep.get("tm_segments", []) or [])
        dis_segments = list(rep.get("disorder_segments", []) or [])
        sig = dict(rep.get("signal_peptide", {}) or {})
        motifs = list(rep.get("motifs", []) or [])
        core = dict(rep.get("suggested_structured_core", {}) or {})
        uniprot = dict(self._bioseq_fetch_uniprot_annotations_for_report(seq) or {})
        rep["uniprot"] = dict(uniprot)
        self._bioseq_last_report = dict(rep)
        lines = []
        lines.append("Sequence Bioinformatics Report (Simulation-Oriented)")
        lines.append(f"Length: {int(rep.get('length', 0))} aa")
        lines.append(
            "Composition: "
            f"hydrophobic={float(metrics.get('fraction_hydrophobic', 0.0)):.2f}, "
            f"polar={float(metrics.get('fraction_polar', 0.0)):.2f}, "
            f"charged={float(metrics.get('fraction_charged', 0.0)):.2f}, "
            f"aromatic={float(metrics.get('fraction_aromatic', 0.0)):.2f}"
        )
        lines.append(f"Estimated net charge at pH~7: {float(metrics.get('estimated_net_charge_ph7', 0.0)):.1f}")
        lines.append(
            "Transmembrane heuristic: "
            + ("likely membrane protein" if tm_segments else "likely soluble protein")
        )
        lines.append("TM segments: " + self._bioseq_format_range_list(tm_segments, value_key="hydrophobicity"))
        lines.append(
            f"Disorder fraction (heuristic): {float(rep.get('disorder_fraction', 0.0) or 0.0):.2f}"
        )
        lines.append("Disordered segments: " + self._bioseq_format_range_list(dis_segments))
        if bool(sig.get("predicted", False)):
            lines.append(
                "Signal peptide heuristic: predicted "
                f"(cleavage ~{int(sig.get('cleavage_site_estimate', 0) or 0)})."
            )
        else:
            lines.append("Signal peptide heuristic: not strongly predicted.")
        lines.append(
            "Suggested structured core for first simulations: "
            f"{int(core.get('start', 1) or 1)}-{int(core.get('end', len(seq)) or len(seq))}"
        )
        motif_total = int(rep.get("motif_total", len(motifs)) or len(motifs))
        lines.append(
            f"Simple motif hits: {motif_total}"
            + (f" (table shows the {len(motifs)} most specific)" if motif_total > len(motifs) else "")
        )
        for m in list(motifs[:12]):
            lines.append(
                f"  - {str(m.get('motif', 'motif'))}: "
                f"{int(m.get('start', 0))}-{int(m.get('end', 0))} ({str(m.get('match', ''))})"
            )
        lines.append("UniProt motifs/domain/site annotations:")
        if bool(uniprot.get("ok", False)):
            features = list(uniprot.get("features", []) or [])
            acc = str(uniprot.get("accession", "") or "").strip()
            entry_id = str(uniprot.get("entry_id", "") or "").strip()
            protein = str(uniprot.get("protein_name", "") or "").strip()
            organism = str(uniprot.get("organism", "") or "").strip()
            src = f"{acc} {entry_id}".strip()
            lines.append(
                "  Source: "
                + (src if src else "UniProtKB")
                + (f" | {protein}" if protein else "")
                + (f" | {organism}" if organism else "")
            )
            if str(uniprot.get("warning", "") or "").strip():
                lines.append("  WARNING: " + str(uniprot.get("warning")).strip())
            if features:
                for feat in list(features[:20]):
                    lines.append(self._bioseq_format_uniprot_feature_line(feat))
                if len(features) > 20:
                    lines.append(f"  - ... {len(features) - 20} additional UniProt annotations hidden.")
            else:
                lines.append("  No motif/domain/site annotations overlapped the current sequence.")
        else:
            lines.append(f"  UniProt lookup unavailable: {str(uniprot.get('error', 'not available') or 'not available')}")
        recs = [str(x) for x in list(rep.get("recommendations", []) or []) if str(x).strip()]
        if recs:
            lines.append("Recommendations:")
            for r in list(recs):
                lines.append(f"  - {r}")
        self.txt_bioseq_report.setPlainText("\n".join(lines))

        # Populate motif table.
        self.tbl_bioseq_motifs.setRowCount(0)
        for m in list(motifs or []):
            r = int(self.tbl_bioseq_motifs.rowCount())
            self.tbl_bioseq_motifs.insertRow(r)
            self.tbl_bioseq_motifs.setItem(r, 0, QtWidgets.QTableWidgetItem(str(m.get("motif", ""))))
            self.tbl_bioseq_motifs.setItem(r, 1, QtWidgets.QTableWidgetItem(str(int(m.get("start", 0) or 0))))
            self.tbl_bioseq_motifs.setItem(r, 2, QtWidgets.QTableWidgetItem(str(int(m.get("end", 0) or 0))))
            self.tbl_bioseq_motifs.setItem(r, 3, QtWidgets.QTableWidgetItem(str(m.get("match", ""))))
        self._bioseq_update_motif_summary_popup(seq, rep)

        # Highlight motif regions in sequence and color mapped residues on structure.
        self._bioseq_highlight_motif_in_sequence()
        self._bioseq_apply_structure_highlights(report=rep, msa=self._bioseq_last_msa)

        answers = list(bioseq_summarize_question_answers(seq) or [])
        self._bioseq_populate_question_table(answers=answers)
        if hasattr(self, "lbl_bioseq_status"):
            self.lbl_bioseq_status.setText(
                f"Local sequence analysis complete ({len(seq)} aa). TM={len(tm_segments)} | motifs={motif_total}."
            )
        self._bioseq_show_motif_summary_popup()
    def _bioseq_run_msa_conservation(self):
        txt = ""
        try:
            txt = str(self.txt_bioseq_msa.toPlainText() or "")
        except Exception:
            txt = ""
        res = dict(bioseq_compute_msa_conservation(txt) or {})
        if not bool(res.get("ok", False)):
            QtWidgets.QMessageBox.warning(self, "Bioinformatics", str(res.get("error", "MSA conservation failed.")))
            return
        self._bioseq_last_msa = dict(res)
        rows = list(res.get("top_positions", []) or [])
        self.tbl_bioseq_conservation.setRowCount(0)
        for row in list(rows[:80]):
            r = int(self.tbl_bioseq_conservation.rowCount())
            self.tbl_bioseq_conservation.insertRow(r)
            self.tbl_bioseq_conservation.setItem(r, 0, QtWidgets.QTableWidgetItem(str(int(row.get("position", 0)))))
            ref_pos = row.get("reference_position", None)
            ref_txt = "-" if ref_pos in (None, "") else str(int(ref_pos))
            self.tbl_bioseq_conservation.setItem(r, 1, QtWidgets.QTableWidgetItem(ref_txt))
            self.tbl_bioseq_conservation.setItem(r, 2, QtWidgets.QTableWidgetItem(str(row.get("consensus", ""))))
            self.tbl_bioseq_conservation.setItem(
                r, 3, QtWidgets.QTableWidgetItem(f"{float(row.get('conservation', 0.0)):.3f}")
            )
            self.tbl_bioseq_conservation.setItem(
                r, 4, QtWidgets.QTableWidgetItem(f"{float(row.get('entropy', 0.0)):.3f}")
            )
            self.tbl_bioseq_conservation.setItem(
                r, 5, QtWidgets.QTableWidgetItem(f"{float(row.get('coverage', 0.0)):.3f}")
            )
        prev = str(self.txt_bioseq_report.toPlainText() or "").strip()
        extra = (
            f"MSA conservation summary: n_seq={int(res.get('n_sequences', 0))}, "
            f"length={int(res.get('alignment_length', 0))}, "
            f"mean_conservation={float(res.get('mean_conservation', 0.0)):.3f}"
        )
        merged = f"{prev}\n\n{extra}" if prev else extra
        self.txt_bioseq_report.setPlainText(merged)
        self._bioseq_apply_structure_highlights(report=self._bioseq_last_report, msa=res)
        if hasattr(self, "lbl_bioseq_status"):
            self.lbl_bioseq_status.setText(extra)
