                page = QtWidgets.QWidget()
                lay = QtWidgets.QVBoxLayout(page)
                lay.setContentsMargins(6, 6, 6, 6)
                lay.setSpacing(8)
                scroll.setWidget(page)
                outer.addWidget(scroll, 1)
                tabs.addTab(tab, title)
                return lay

