    def _show_psi4_cluster_dialog(self):
        self._setup_psi4_cluster_dialog()
        dlg = getattr(self, "_psi4_cluster_dialog", None)
        if dlg is None:
            return
        self._psi4_cluster_refresh_source_combo()
        self._fit_dialog_to_screen(dlg)
        dlg.show()
        dlg.raise_()
        dlg.activateWindow()
    def _psi4_cluster_refresh_source_combo(self):
        if not hasattr(self, "cmb_psi4_cluster_source"):
            return
        cur = ""
        try:
            cur = str(self.cmb_psi4_cluster_source.currentText() or "").strip()
        except Exception:
            cur = ""
        names = []
        try:
            names = list(self._candidate_structure_objects() or [])
        except Exception:
            names = []
        self.cmb_psi4_cluster_source.blockSignals(True)
        self.cmb_psi4_cluster_source.clear()
        self.cmb_psi4_cluster_source.addItems(list(names or []))
        if cur and cur in names:
            self.cmb_psi4_cluster_source.setCurrentText(cur)
        else:
            try:
                main_obj = str(self.psi4_source_combo.currentText() or "").strip() if hasattr(self, "psi4_source_combo") else ""
            except Exception:
                main_obj = ""
            if main_obj and main_obj in names:
                self.cmb_psi4_cluster_source.setCurrentText(main_obj)
            elif names:
                self.cmb_psi4_cluster_source.setCurrentIndex(0)
        self.cmb_psi4_cluster_source.blockSignals(False)
    def _psi4_cluster_current_source(self):
        try:
            return str(self.cmb_psi4_cluster_source.currentText() or "").strip()
        except Exception:
            return ""
    def _psi4_capture_pymol_sele_into_edit(self, edit_widget):
        if edit_widget is None:
            return False
        sel = str(self._openmm_current_pymol_selection() or "").strip()
        if not sel:
            QtWidgets.QMessageBox.information(
                self,
                "Psi4 Cluster",
                "No active PyMOL selection named 'sele'. Select atoms first, then retry.",
            )
            return False
        try:
            edit_widget.setText(sel)
        except Exception:
            return False
        return True
    def _psi4_cluster_use_main_source(self):
        main_obj = ""
        try:
            if hasattr(self, "psi4_source_combo"):
                main_obj = str(self.psi4_source_combo.currentText() or "").strip()
        except Exception:
            main_obj = ""
        if not main_obj:
            return
        self._psi4_cluster_refresh_source_combo()
        try:
            idx = self.cmb_psi4_cluster_source.findText(main_obj)
            if idx >= 0:
                self.cmb_psi4_cluster_source.setCurrentIndex(idx)
        except Exception:
            pass
    def _psi4_cluster_apply_default_selection(self):
        if not hasattr(self, "edit_psi4_cluster_selection"):
            return
        txt = str(self.edit_psi4_cluster_selection.text() or "").strip()
        if txt:
            return
        sel = str(self._openmm_current_pymol_selection() or "").strip()
        if sel:
            self.edit_psi4_cluster_selection.setText(sel)
        else:
            self.edit_psi4_cluster_selection.setText("sele")
    def _psi4_cluster_resolve_selection(self):
        obj = self._psi4_cluster_current_source()
        expr = ""
        try:
            expr = str(self.edit_psi4_cluster_selection.text() or "").strip()
        except Exception:
            expr = ""
        mode = "around_selection"
        try:
            mode = str(self.cmb_psi4_cluster_build_mode.currentData() or "around_selection")
        except Exception:
            mode = "around_selection"
        radius = 5.0
        try:
            radius = float(self.spin_psi4_cluster_radius.value())
        except Exception:
            radius = 5.0
        seed_indices = ""
        try:
            seed_indices = str(self.edit_psi4_cluster_seed_indices.text() or "").strip()
        except Exception:
            seed_indices = ""
        expand_residues = bool(
            getattr(self, "cb_psi4_cluster_autobyres", None)
            and self.cb_psi4_cluster_autobyres.isChecked()
        )
        include_waters = bool(
            getattr(self, "cb_psi4_cluster_include_waters", None)
            and self.cb_psi4_cluster_include_waters.isChecked()
        )
        try:
            mod = self._psi4_cluster_runtime_mod()
            return dict(mod.build_pymol_cluster_selection(
                source_object=str(obj),
                mode=str(mode),
                seed_selection=str(expr),
                seed_indices=str(seed_indices),
                radius=float(radius),
                expand_residues=bool(expand_residues),
                include_waters=bool(include_waters),
            ) or {})
        except Exception:
            if not expr:
                expr = "polymer.protein"
            low = expr.lower()
            explicit = ("model " in low) or ("obj " in low) or ("sele" in low)
            base_sel = str(expr) if explicit or not obj else f"({obj}) and ({expr})"
            if expand_residues:
                base_sel = f"byres ({base_sel})"
            return {
                "source_object": str(obj),
                "mode": str(mode),
                "core_sel": str(base_sel),
                "cap_sel": "",
                "final_sel": str(base_sel),
                "radius": float(radius),
                "seed_indices": [],
            }
    def _psi4_cluster_refresh_atoms_table(self):
        if not hasattr(self, "tbl_psi4_cluster_atoms"):
            return
        state = dict(getattr(self, "_psi4_cluster_state", {}) or {})
        atoms = [dict(a or {}) for a in list(state.get("atoms", []) or [])]
        freeze_idx = set(int(x) for x in list(state.get("freeze_atom_indices", []) or []) if int(x) > 0)
        cap_keys = set(tuple(x) for x in list(state.get("boundary_residue_keys", []) or []))
        bb_fn = None
        try:
            bb_fn = self._psi4_cluster_runtime_mod().is_backbone_atom
        except Exception:
            bb_fn = None
        tbl = self.tbl_psi4_cluster_atoms
        tbl.setRowCount(0)
        max_rows = int(min(5000, len(atoms)))
        for i, a in enumerate(list(atoms[:max_rows]), start=0):
            r = int(tbl.rowCount())
            tbl.insertRow(r)
            idx = int((a or {}).get("index", i + 1) or (i + 1))
            elem = str((a or {}).get("element", "") or "")
            name = str((a or {}).get("name", "") or "")
            resn = str((a or {}).get("resn", "") or "")
            chain = str((a or {}).get("chain", "") or "")
            resi = str((a or {}).get("resi", "") or "")
            flags = []
            if bool((a or {}).get("is_cap", False)):
                flags.append("cap-H")
            if idx in freeze_idx:
                flags.append("freeze")
            try:
                if callable(bb_fn) and bool(bb_fn(a)):
                    flags.append("bb")
            except Exception:
                pass
            if (chain, resi, str(resn).upper()) in cap_keys:
                flags.append("cap")
            tbl.setItem(r, 0, QtWidgets.QTableWidgetItem(str(idx)))
            tbl.setItem(r, 1, QtWidgets.QTableWidgetItem(elem))
            tbl.setItem(r, 2, QtWidgets.QTableWidgetItem(name))
            tbl.setItem(r, 3, QtWidgets.QTableWidgetItem(resn))
            tbl.setItem(r, 4, QtWidgets.QTableWidgetItem(chain))
            tbl.setItem(r, 5, QtWidgets.QTableWidgetItem(resi))
            tbl.setItem(r, 6, QtWidgets.QTableWidgetItem(",".join(flags) if flags else ""))
        if len(atoms) > max_rows:
            self._psi4_append_log(
                f"Psi4 cluster table truncated to {max_rows} rows (total atoms={len(atoms)})."
            )
    def _on_psi4_cluster_build_preview(self):
        sel_info = dict(self._psi4_cluster_resolve_selection() or {})
        sel = str(sel_info.get("final_sel", "") or "").strip()
        core_sel = str(sel_info.get("core_sel", "") or "").strip()
        cap_sel = str(sel_info.get("cap_sel", "") or "").strip()
        if not sel:
            QtWidgets.QMessageBox.warning(
                self,
                "Psi4 Cluster",
                "No cluster selection could be built. Choose a seed selection or atom indices first.",
            )
            return
        atoms = self._psi4_collect_atoms_from_selection(sel, state=1)
        if len(atoms) <= 0:
            QtWidgets.QMessageBox.warning(self, "Psi4 Cluster", f"Selection returned no atoms:\n{sel}")
            return
        freeze_backbone = bool(
            getattr(self, "cb_psi4_cluster_freeze_backbone", None)
            and self.cb_psi4_cluster_freeze_backbone.isChecked()
        )
        freeze_caps = bool(
            getattr(self, "cb_psi4_cluster_freeze_cap", None)
            and self.cb_psi4_cluster_freeze_cap.isChecked()
        )
        add_caps = bool(
            getattr(self, "cb_psi4_cluster_autocap", None)
            and self.cb_psi4_cluster_autocap.isChecked()
        )
        context_atoms = []
        src_obj = self._psi4_cluster_current_source()
        if src_obj:
            try:
                context_atoms = self._psi4_collect_atoms_from_selection(str(src_obj), state=1)
            except Exception:
                context_atoms = []
        try:
            mod = self._psi4_cluster_runtime_mod()
            model_atoms, freeze_idx, prep_meta = mod.prepare_cluster_model(
                atoms,
                context_atoms=(context_atoms if context_atoms else None),
                seed_indices=None,
                radius=float(sel_info.get("radius", 5.0) or 5.0),
                expand_residues=True,
                add_caps=bool(add_caps),
                freeze_backbone=bool(freeze_backbone),
                freeze_caps=bool(freeze_caps),
            )
        except Exception as e:
            QtWidgets.QMessageBox.warning(self, "Psi4 Cluster", f"Failed to prepare capped cluster:\n{e}")
            return
        preview = self._dock_safe_obj_name("psi4_cluster_preview")
        preview_xyz = ""
        try:
            if preview in cmd.get_names("objects"):
                cmd.delete(preview)
            out_dir = str(self._psi4_workspace_dir() or ".")
            os.makedirs(out_dir, exist_ok=True)
            preview_xyz = os.path.join(
                out_dir,
                f"psi4_cluster_reactant_{datetime.datetime.now().strftime('%Y%m%d_%H%M%S')}.xyz",
            )
            self._psi4_write_atoms_xyz(model_atoms, preview_xyz, comment="Capped cluster reactant")
            loaded = self._psi4_load_xyz_object(preview_xyz, obj_prefix="psi4_cluster_preview")
            preview = str(loaded or preview)
            if not loaded:
                cmd.create(preview, sel, 1, 1)
                cmd.show("sticks", preview)
                cmd.show("spheres", preview)
                cmd.set("sphere_scale", 0.16, preview)
                cmd.set("stick_radius", 0.10, preview)
                self._apply_element_colors(preview)
                cmd.color("gray80", f"({preview}) and polymer.protein")
                cmd.orient(preview)
        except Exception as e:
            QtWidgets.QMessageBox.warning(self, "Psi4 Cluster", f"Preview creation failed:\n{e}")
            return
        caps_meta = dict((prep_meta or {}).get("caps", {}) or {})
        freeze_meta = dict((prep_meta or {}).get("freeze", {}) or {})
        state = {
            "selection": str(sel),
            "core_selection": str(core_sel),
            "cap_selection": str(cap_sel),
            "source_object": self._psi4_cluster_current_source(),
            "atoms": list(model_atoms or []),
            "reactant_atoms": list(model_atoms or []),
            "raw_selected_atoms": list(atoms or []),
            "context_atom_count": int(len(context_atoms or [])),
            "prepare_meta": dict(prep_meta or {}),
            "core_residue_keys": [],
            "cap_residue_keys": list(caps_meta.get("capped_residue_keys", []) or []),
            "freeze_atom_indices": list(freeze_idx),
            "freeze_info": dict(freeze_meta or {}),
            "boundary_residue_keys": list((freeze_meta or {}).get("boundary_residue_keys", []) or []),
            "preview_object": str(preview),
            "preview_xyz": str(preview_xyz),
        }
        self._psi4_cluster_state = dict(state)
        self._psi4_cluster_preview_obj = str(preview)
        self._psi4_cluster_refresh_atoms_table()
        if hasattr(self, "edit_psi4_cluster_react"):
            try:
                self.edit_psi4_cluster_react.setText("__cluster_reactant__")
            except Exception:
                pass
        if hasattr(self, "lbl_psi4_cluster_status"):
            cap_count = int(caps_meta.get("cap_count", 0) or 0)
            self.lbl_psi4_cluster_status.setText(
                f"Cluster ready: selected={len(atoms)} | model_atoms={len(model_atoms)} | "
                f"H-link caps={cap_count} | frozen={len(freeze_idx)} | preview={preview}"
            )
    def _on_psi4_cluster_set_react_from_current(self):
        if not hasattr(self, "edit_psi4_cluster_react"):
            return
        sel = self._psi4_current_selection()
        if not sel:
            sel = str(getattr(self, "_psi4_cluster_preview_obj", "") or "").strip()
        if not sel:
            sel = str(self._psi4_cluster_current_source() or "")
        if not sel:
            self._psi4_capture_pymol_sele_into_edit(self.edit_psi4_cluster_react)
            return
        try:
            self.edit_psi4_cluster_react.setText(str(sel))
        except Exception:
            pass
    def _on_psi4_cluster_set_prod_from_current(self):
        if not hasattr(self, "edit_psi4_cluster_prod"):
            return
        sel = self._psi4_current_selection()
        if not sel:
            sel = str(self._psi4_cluster_current_source() or "")
        if not sel:
            self._psi4_capture_pymol_sele_into_edit(self.edit_psi4_cluster_prod)
            return
        try:
            self.edit_psi4_cluster_prod.setText(str(sel))
        except Exception:
            pass
    def _psi4_write_atoms_xyz(self, atoms, out_xyz, comment="ProtLigInteract Psi4 cluster"):
        arr = list(atoms or [])
        if len(arr) <= 0:
            raise RuntimeError("No atoms to write.")
        with open(out_xyz, "w", encoding="utf-8") as fh:
            fh.write(f"{len(arr)}\n")
            fh.write(str(comment or "Generated by ProtLigInteract") + "\n")
            for a in arr:
                sym = self._psi4_element_token(a.get("element", a.get("symbol", "C")))
                x = float(a.get("x", 0.0))
                y = float(a.get("y", 0.0))
                z = float(a.get("z", 0.0))
                fh.write(f"{sym} {x:.10f} {y:.10f} {z:.10f}\n")
    def _psi4_cluster_write_atoms_pdb(self, atoms, out_pdb, title="ProtLigInteract Psi4 Cluster"):
        rows = [dict(a or {}) for a in list(atoms or [])]
        if not rows:
            raise RuntimeError("No atoms provided.")
        with open(out_pdb, "w", encoding="utf-8") as fh:
            fh.write(f"TITLE     {str(title or 'ProtLigInteract Psi4 Cluster')[:60]}\n")
            serial = 1
            last_chain = None
            last_resi = None
            for a in rows:
                name = str(a.get("name", "") or "").strip() or f"A{serial}"
                if len(name) > 4:
                    name = name[:4]
                elem = self._psi4_element_token(a.get("element", a.get("symbol", "C")))
                resn = str(a.get("resn", "") or "").strip().upper() or "UNK"
                if len(resn) > 3:
                    resn = resn[:3]
                chain = str(a.get("chain", "") or "").strip()[:1] or "A"
                try:
                    resi = int(str(a.get("resi", "") or "").strip())
                except Exception:
                    resi = 1
                x = float(a.get("x", 0.0) or 0.0)
                y = float(a.get("y", 0.0) or 0.0)
                z = float(a.get("z", 0.0) or 0.0)
                if (last_chain is not None) and ((chain != last_chain) or (resi != last_resi)):
                    pass
                last_chain = chain
                last_resi = resi
                atom_name = name.rjust(4)
                line = (
                    f"ATOM  {int(serial):5d} {atom_name:4s} {resn:>3s} {chain:1s}"
                    f"{int(resi):4d}    {x:8.3f}{y:8.3f}{z:8.3f}"
                    f"  1.00  0.00          {str(elem):>2s}\n"
                )
                fh.write(line)
                serial += 1
            fh.write("TER\nEND\n")
    def _psi4_cluster_minimize_atoms_openmm(self, atoms, freeze_atom_indices=None, max_iterations=300):
        src = [dict(a or {}) for a in list(atoms or [])]
        if not src:
            return False, [], "No atoms supplied for classical minimization."
        if (not HAS_OPENMM) or (OMM is None) or (OMM_APP is None) or (OMM_UNIT is None):
            return False, list(src), "OpenMM is unavailable in this environment."
        try:
            mod = self._psi4_cluster_runtime_mod()
            aa_set = set(str(x).upper() for x in list(getattr(mod, "AA_PROTEIN_RESN", set()) or set()))
        except Exception:
            aa_set = set()
        protein_rows = []
        non_protein = set()
        for i, a in enumerate(list(src or [])):
            resn = str((a or {}).get("resn", "") or "").strip().upper()
            if resn in aa_set:
                protein_rows.append((int(i), dict(a or {})))
            else:
                non_protein.add(resn or "UNK")
        if len(protein_rows) <= 2:
            return (
                False,
                list(src),
                "Classical FF minimization needs at least 3 protein atoms in the cluster.",
            )
        prot_atoms = [dict(x[1] or {}) for x in list(protein_rows or [])]
        freeze_set_src = set(int(x) for x in list(freeze_atom_indices or []) if int(x) > 0)
        freeze_set_new = set()
        for new_i, (_old_i, a) in enumerate(list(protein_rows or []), start=1):
            idx_orig = int((a or {}).get("index", 0) or 0)
            if idx_orig in freeze_set_src:
                freeze_set_new.add(int(new_i))
        tmp_pdb = os.path.join(
            self._psi4_workspace_dir(),
            f"psi4_cluster_mm_{datetime.datetime.now().strftime('%H%M%S_%f')}.pdb",
        )
        try:
            self._psi4_cluster_write_atoms_pdb(prot_atoms, tmp_pdb, title="Cluster MM pre-min")
            pdb = OMM_APP.PDBFile(tmp_pdb)
            ff = OMM_APP.ForceField("amber14/protein.ff14SB.xml")
            modeller = OMM_APP.Modeller(pdb.topology, pdb.positions)
            try:
                modeller.addHydrogens(ff, pH=7.0)
            except Exception:
                pass
            system = ff.createSystem(
                modeller.topology,
                nonbondedMethod=OMM_APP.NoCutoff,
                constraints=OMM_APP.HBonds,
            )
            freeze_set = set(int(x) for x in list(freeze_set_new or []) if int(x) > 0)
            if freeze_set:
                kf = OMM.CustomExternalForce("k*((x-x0)^2 + (y-y0)^2 + (z-z0)^2)")
                kf.addPerParticleParameter("k")
                kf.addPerParticleParameter("x0")
                kf.addPerParticleParameter("y0")
                kf.addPerParticleParameter("z0")
                pos = list(modeller.positions)
                nat = int(system.getNumParticles())
                n_in = int(len(prot_atoms))
                for i in range(nat):
                    p = pos[i]
                    kval = 100000.0 if (i < n_in and (i + 1) in freeze_set) else 0.0
                    kf.addParticle(
                        int(i),
                        [
                            float(kval),
                            float(p.x / OMM_UNIT.nanometer),
                            float(p.y / OMM_UNIT.nanometer),
                            float(p.z / OMM_UNIT.nanometer),
                        ],
                    )
                system.addForce(kf)
            integ = OMM.VerletIntegrator(0.001 * OMM_UNIT.picoseconds)
            ctx = OMM.Context(system, integ)
            ctx.setPositions(modeller.positions)
            OMM.LocalEnergyMinimizer.minimize(ctx, maxIterations=int(max(20, int(max_iterations))))
            st = ctx.getState(getPositions=True)
            pos_fin = list(st.getPositions(asNumpy=False))
            n_take = min(int(len(prot_atoms)), int(len(pos_fin)))
            out_prot = []
            for i in range(n_take):
                aa = dict(prot_atoms[i])
                p = pos_fin[i]
                aa["x"] = float(p.x / OMM_UNIT.angstrom)
                aa["y"] = float(p.y / OMM_UNIT.angstrom)
                aa["z"] = float(p.z / OMM_UNIT.angstrom)
                out_prot.append(aa)
            if n_take < len(prot_atoms):
                out_prot.extend(list(prot_atoms[n_take:]))
            out = [dict(a or {}) for a in list(src or [])]
            for new_i, (old_i, _a_old) in enumerate(list(protein_rows or [])):
                if new_i < len(out_prot):
                    out[int(old_i)] = dict(out_prot[new_i])
            try:
                del ctx
            except Exception:
                pass
            try:
                del integ
            except Exception:
                pass
            note = f"OpenMM minimization complete (steps={int(max_iterations)}; protein_atoms={len(prot_atoms)}"
            if non_protein:
                note += f"; non_protein_held_fixed={len(non_protein)}"
            note += ")."
            return True, out, note
        except Exception as e:
            return False, list(src), f"OpenMM minimization failed: {e}"
        finally:
            try:
                if os.path.isfile(tmp_pdb):
                    os.remove(tmp_pdb)
            except Exception:
                pass
    def _psi4_load_xyz_object(self, xyz_file, obj_prefix="psi4_cluster"):
        p = str(xyz_file or "").strip()
        if (not p) or (not os.path.isfile(p)):
            return ""
        obj = self._dock_safe_obj_name(str(obj_prefix or "psi4_cluster"))
        existing = set(cmd.get_names("objects"))
        k = 1
        out = obj
        while out in existing:
            k += 1
            out = f"{obj}_{k}"
        try:
            cmd.load(p, out)
            cmd.show("sticks", out)
            cmd.show("spheres", out)
            cmd.set("sphere_scale", 0.18, out)
            cmd.set("stick_radius", 0.12, out)
            self._apply_element_colors(out)
            cmd.orient(out)
            return out
        except Exception:
            return ""
    def _on_psi4_cluster_generate_product_guess(self):
        react_src = ""
        try:
            react_src = str(self.edit_psi4_cluster_react.text() or "").strip()
        except Exception:
            react_src = ""
        if not react_src:
            react_src = "__cluster_reactant__" if dict(getattr(self, "_psi4_cluster_state", {}) or {}).get("reactant_atoms") else ""
        if not react_src:
            react_src = str(getattr(self, "_psi4_cluster_preview_obj", "") or "").strip()
        if not react_src:
            QtWidgets.QMessageBox.warning(self, "Psi4 Cluster", "Reactant source is required.")
            return
        form_txt = ""
        break_txt = ""
        try:
            form_txt = str(self.edit_psi4_cluster_form.text() or "").strip()
            break_txt = str(self.edit_psi4_cluster_break.text() or "").strip()
        except Exception:
            pass
        try:
            mod = self._psi4_cluster_runtime_mod()
            form_pairs = list(mod.parse_bond_change_pairs(form_txt) or [])
            break_pairs = list(mod.parse_bond_change_pairs(break_txt) or [])
        except Exception as e:
            QtWidgets.QMessageBox.warning(self, "Psi4 Cluster", f"Could not parse reaction coordinates:\n{e}")
            return
        if (not form_pairs) and (not break_pairs):
            QtWidgets.QMessageBox.warning(
                self,
                "Psi4 Cluster",
                "No bond changes provided. Fill 'Bonds forming' and/or 'Bonds breaking'.",
            )
            return
        st_cluster = dict(getattr(self, "_psi4_cluster_state", {}) or {})
        if str(react_src).strip() == "__cluster_reactant__":
            atoms = [dict(a or {}) for a in list(st_cluster.get("reactant_atoms", []) or [])]
            err = "" if atoms else "No built cluster reactant is available. Click 'Build Cluster Preview' first."
            used = "built_cluster_reactant"
        else:
            atoms, _m2, _meta, err, used = self._psi4_collect_atoms_from_source_text(react_src, need_mol2=False)
        if err and (not atoms):
            QtWidgets.QMessageBox.warning(self, "Psi4 Cluster", f"Reactant source failed:\n{err}")
            return
        try:
            prod_atoms, note = mod.adjust_atoms_for_bond_changes(
                atoms,
                form_pairs=form_pairs,
                break_pairs=break_pairs,
            )
        except Exception as e:
            QtWidgets.QMessageBox.warning(self, "Psi4 Cluster", f"Product-guess generation failed:\n{e}")
            return
        out_dir = str(self._psi4_workspace_dir() or ".")
        try:
            os.makedirs(out_dir, exist_ok=True)
        except Exception:
            pass
        out_xyz = os.path.join(
            out_dir,
            f"psi4_cluster_product_guess_{datetime.datetime.now().strftime('%Y%m%d_%H%M%S')}.xyz",
        )
        try:
            self._psi4_write_atoms_xyz(prod_atoms, out_xyz, comment="Cluster reaction product guess")
        except Exception as e:
            QtWidgets.QMessageBox.warning(self, "Psi4 Cluster", f"Failed writing product XYZ:\n{e}")
            return
        obj = self._psi4_load_xyz_object(out_xyz, obj_prefix="psi4_cluster_product_guess")
        self._psi4_cluster_generated_product_xyz = str(out_xyz)
        self._psi4_cluster_generated_product_obj = str(obj or "")
        st = dict(getattr(self, "_psi4_cluster_state", {}) or {})
        st["generated_product_atoms"] = [dict(a or {}) for a in list(prod_atoms or [])]
        st["generated_product_xyz"] = str(out_xyz)
        st["generated_product_object"] = str(obj or "")
        self._psi4_cluster_state = dict(st)
        try:
            self.edit_psi4_cluster_prod.setText("__cluster_product_guess__")
        except Exception:
            pass
        if hasattr(self, "lbl_psi4_cluster_status"):
            self.lbl_psi4_cluster_status.setText(
                f"Product guess ready (internal token + file): {out_xyz} | source={used} | {note}"
            )
    def _psi4_collect_optimized_atoms_from_run_result(self, run_result, fallback_atoms=None):
        rr = dict(run_result or {})
        res = dict(rr.get("result", {}) or {})
        jdir = str(rr.get("job_dir", "") or "").strip()
        rel = str(res.get("optimized_xyz", "") or "").strip()
        if rel:
            p = os.path.join(jdir, rel)
            if os.path.isfile(p):
                try:
                    at = self._psi4_collect_atoms_from_xyz(p)
                    if at:
                        return list(at)
                except Exception:
                    pass
        return list(fallback_atoms or [])
    def _psi4_execute_cluster_reaction_worker(self, payload, progress_cb=None):
        cfg = dict(payload or {})
        method = str(cfg.get("method", "wb97x-d") or "wb97x-d").strip()
        basis = str(cfg.get("basis", "def2-SVP") or "def2-SVP").strip()
        charge = int(cfg.get("charge", 0) or 0)
        mult = int(cfg.get("mult", 1) or 1)
        memory_gb = int(cfg.get("memory_gb", 8) or 8)
        threads = int(cfg.get("threads", 1) or 1)
        geom_maxiter = int(cfg.get("geom_maxiter", 100) or 100)
        timeout_s = int(cfg.get("timeout_s", 3600) or 3600)
        use_pcm = bool(cfg.get("use_pcm", False))
        solvent = str(cfg.get("solvent", "Water") or "Water")
        freeze_atoms = [int(x) for x in list(cfg.get("freeze_atom_indices", []) or []) if int(x) > 0]
        do_classical = bool(cfg.get("do_classical_min", True))
        mm_steps = int(max(20, int(cfg.get("mm_steps", 300) or 300)))
        do_preopt = bool(cfg.get("do_preopt", True))
        run_irc = bool(cfg.get("run_irc", True))
        run_qst3 = bool(cfg.get("run_qst3", True))
        ts_weight = float(cfg.get("ts_weight", 0.35) or 0.35)
        psi4_bin = str(cfg.get("psi4_bin", "") or "").strip()
        job_dir = str(cfg.get("job_dir", "") or "").strip()
        react_atoms = [dict(a or {}) for a in list(cfg.get("react_atoms", []) or [])]
        prod_atoms = [dict(a or {}) for a in list(cfg.get("prod_atoms", []) or [])]
        out = {
            "ok": False,
            "logs": [],
            "stage_payloads": {},
            "final_run_result": None,
            "final_attempt_summaries": [],
            "final_operation": "ts_qst2",
        }
        if (not react_atoms) or (not prod_atoms):
            out["error"] = "Reactant/product atoms are missing."
            return out
        if not psi4_bin:
            out["error"] = "Psi4 executable not set."
            return out
        def _emit(frac, msg="", status="Running"):
            if callable(progress_cb):
                try:
                    progress_cb(
                        {
                            "progress": float(max(0.0, min(100.0, float(frac)))),
                            "message": str(msg or ""),
                            "status": str(status or "Running"),
                            "job_dir": str(job_dir or ""),
                        }
                    )
                except Exception:
                    pass
        def _run_stage(stage_key, stage_title, stage_job, stage_dir, p0, p1):
            out["logs"].append(f"[{stage_key}] {stage_title}")
            try:
                os.makedirs(stage_dir, exist_ok=True)
            except Exception as e:
                out["logs"].append(f"[{stage_key}] failed creating stage directory: {e}")
                return None
            def _sub_progress(pp):
                p = float((pp or {}).get("progress", 0.0) or 0.0)
                m = str((pp or {}).get("message", "") or "").strip()
                frac = float(p0 + (p1 - p0) * max(0.0, min(100.0, p)) / 100.0)
                _emit(frac, f"{stage_title}: {m}" if m else stage_title)
            payload_stage = self._psi4_execute_with_fallback_worker(
                job=stage_job,
                job_dir=stage_dir,
                psi4_bin=psi4_bin,
                timeout_s=max(60, int(timeout_s)),
                use_pcm=bool(use_pcm),
                solvent=str(solvent),
                progress_cb=_sub_progress,
            )
            out["stage_payloads"][stage_key] = dict(payload_stage or {})
            for ln in list((payload_stage or {}).get("logs", []) or []):
                out["logs"].append(f"[{stage_key}] {str(ln)}")
            rr = dict((payload_stage or {}).get("run_result", {}) or {})
            if not bool(rr.get("success", False)):
                return None
            return rr
        def _base_job(atoms, operation, qst_payload=None):
            job = {
                "operation": str(operation),
                "method": str(method),
                "basis": str(basis),
                "molecule_block": self._psi4_molecule_block(atoms, charge=charge, multiplicity=mult),
                "memory_gb": int(memory_gb),
                "threads": int(threads),
                "geom_maxiter": int(geom_maxiter),
                "implicit": bool(use_pcm),
                "solvent": str(solvent),
                "scf_type": ("pk" if use_pcm else "df"),
                "pcm_solver": "IEFPCM",
                "irc_direction": str(cfg.get("irc_direction", "BOTH") or "BOTH"),
                "irc_points": int(cfg.get("irc_points", 20) or 20),
                "irc_step": float(cfg.get("irc_step", 0.20) or 0.20),
                "irc_require_valid_ts": True,
                "esp_grid_file": "grid.dat",
                "charge": int(charge),
                "freeze_atom_indices": list(freeze_atoms or []),
            }
            if qst_payload:
                job["qst"] = self._psi4_qst_script_payload(qst_payload, charge=charge, multiplicity=mult)
            return job
        try:
            os.makedirs(job_dir, exist_ok=True)
        except Exception:
            pass
        _emit(1, "Preparing cluster workflow")
        react_work = list(react_atoms)
        prod_work = list(prod_atoms)
        if do_classical:
            _emit(4, "Classical FF minimization (reactant)")
            ok_mm_r, react_mm, note_r = self._psi4_cluster_minimize_atoms_openmm(
                react_work,
                freeze_atom_indices=freeze_atoms,
                max_iterations=int(mm_steps),
            )
            out["logs"].append(f"[mm_react] {note_r}")
            if not ok_mm_r:
                out["error"] = f"Classical reactant minimization failed: {note_r}"
                return out
            react_work = list(react_mm or react_work)
            _emit(14, "Classical FF minimization (product)")
            ok_mm_p, prod_mm, note_p = self._psi4_cluster_minimize_atoms_openmm(
                prod_work,
                freeze_atom_indices=freeze_atoms,
                max_iterations=int(mm_steps),
            )
            out["logs"].append(f"[mm_prod] {note_p}")
            if not ok_mm_p:
                out["error"] = f"Classical product minimization failed: {note_p}"
                return out
            prod_work = list(prod_mm or prod_work)
        if do_preopt:
            rr1 = _run_stage(
                "react_preopt",
                "Reactant constrained pre-optimization",
                _base_job(react_work, "optimize"),
                os.path.join(job_dir, "01_react_preopt"),
                18,
                38,
            )
            if rr1 is None:
                out["error"] = "Reactant pre-optimization failed."
                return out
            react_work = self._psi4_collect_optimized_atoms_from_run_result(rr1, fallback_atoms=react_work)
            rr2 = _run_stage(
                "prod_preopt",
                "Product constrained pre-optimization",
                _base_job(prod_work, "optimize"),
                os.path.join(job_dir, "02_prod_preopt"),
                38,
                56,
            )
            if rr2 is None:
                out["error"] = "Product pre-optimization failed."
                return out
            prod_work = self._psi4_collect_optimized_atoms_from_run_result(rr2, fallback_atoms=prod_work)
        _emit(58, "Building QST2 TS guess")
        qst_atoms, qst_note, qst_payload = self._psi4_build_qst_guess_atoms(
            react_work,
            prod_work,
            ts_guess_atoms=None,
            ts_weight=float(ts_weight),
            return_payload=True,
        )
        out["logs"].append(f"[qst2] {qst_note}")
        if len(qst_atoms) <= 0:
            out["error"] = f"QST2 guess failed: {qst_note}"
            return out
        qst2_p1 = 72 if run_qst3 else 82
        rr_qst2 = _run_stage(
            "qst2_ts",
            "QST2 TS optimization + frequency",
            _base_job(qst_atoms, "ts", qst_payload=qst_payload),
            os.path.join(job_dir, "03_qst2_ts"),
            58,
            qst2_p1,
        )
        if rr_qst2 is None:
            out["error"] = "QST2 TS optimization stage failed."
            return out
        final_rr = dict(rr_qst2 or {})
        final_attempts = list((out["stage_payloads"].get("qst2_ts", {}) or {}).get("attempt_summaries", []) or [])
        final_op = "ts_qst2"
        final_ts_atoms = self._psi4_collect_optimized_atoms_from_run_result(rr_qst2, fallback_atoms=qst_atoms)
        if run_qst3:
            _emit(73, "Building QST3 TS guess")
            qst3_atoms, qst3_note, qst3_payload = self._psi4_build_qst_guess_atoms(
                react_work,
                prod_work,
                ts_guess_atoms=final_ts_atoms,
                ts_weight=float(ts_weight),
                return_payload=True,
            )
            out["logs"].append(f"[qst3] {qst3_note}")
            if len(qst3_atoms) <= 0:
                out["error"] = f"QST3 guess failed: {qst3_note}"
                return out
            rr_qst3 = _run_stage(
                "qst3_ts",
                "QST3 TS optimization + frequency",
                _base_job(qst3_atoms, "ts", qst_payload=qst3_payload),
                os.path.join(job_dir, "04_qst3_ts"),
                73,
                88,
            )
            if rr_qst3 is None:
                out["error"] = "QST3 TS optimization stage failed."
                return out
            final_rr = dict(rr_qst3 or {})
            final_attempts = list((out["stage_payloads"].get("qst3_ts", {}) or {}).get("attempt_summaries", []) or [])
            final_op = "ts_qst3"
            final_ts_atoms = self._psi4_collect_optimized_atoms_from_run_result(rr_qst3, fallback_atoms=qst3_atoms)
        if run_irc:
            rr_irc = _run_stage(
                "irc",
                "IRC propagation from TS",
                _base_job(final_ts_atoms, "irc"),
                os.path.join(job_dir, "05_irc" if run_qst3 else "04_irc"),
                88 if run_qst3 else 82,
                100,
            )
            if rr_irc is None:
                out["error"] = "IRC stage failed."
                return out
            final_rr = dict(rr_irc or {})
            final_attempts = list((out["stage_payloads"].get("irc", {}) or {}).get("attempt_summaries", []) or [])
            final_op = "irc"
        out["final_operation"] = str(final_op)
        out["final_run_result"] = dict(final_rr or {})
        out["final_attempt_summaries"] = list(final_attempts or [])
        out["ok"] = True
        _emit(100, "Cluster reaction workflow complete", status="Completed")
        return out
    def _on_psi4_cluster_run_workflow(self):
        psi4_bin = self._psi4_tool_path()
        if not psi4_bin:
            QtWidgets.QMessageBox.critical(
                self,
                "Psi4 Cluster",
                "psi4 executable not found. Install Psi4 or set executable path in Psi4 panel.",
            )
            return
        method = str(self.cmb_psi4_method.currentText() or "").strip() if hasattr(self, "cmb_psi4_method") else ""
        basis = str(self.cmb_psi4_basis.currentText() or "").strip() if hasattr(self, "cmb_psi4_basis") else ""
        if not method or not basis:
            QtWidgets.QMessageBox.warning(self, "Psi4 Cluster", "Method and basis are required.")
            return
        react_src = str(self.edit_psi4_cluster_react.text() or "").strip() if hasattr(self, "edit_psi4_cluster_react") else ""
        prod_src = str(self.edit_psi4_cluster_prod.text() or "").strip() if hasattr(self, "edit_psi4_cluster_prod") else ""
        if not react_src or not prod_src:
            QtWidgets.QMessageBox.warning(self, "Psi4 Cluster", "Reactant and product sources are required.")
            return
        out_root = str(self.edit_psi4_out_dir.text() or "").strip() if hasattr(self, "edit_psi4_out_dir") else ""
        if not out_root:
            out_root = self._psi4_workspace_dir()
        ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        job_dir = os.path.join(out_root, f"psi4_cluster_reaction_{ts}")
        try:
            os.makedirs(job_dir, exist_ok=True)
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "Psi4 Cluster", f"Cannot create job dir:\n{e}")
            return
        st_cluster = dict(getattr(self, "_psi4_cluster_state", {}) or {})
        if str(react_src).strip() == "__cluster_reactant__":
            r_atoms = [dict(a or {}) for a in list(st_cluster.get("reactant_atoms", []) or [])]
            r_meta = {}
            r_err = "" if r_atoms else "No built cluster reactant is available. Click 'Build Cluster Preview' first."
            r_used = "built_cluster_reactant"
        else:
            r_atoms, _r_m2, r_meta, r_err, r_used = self._psi4_collect_atoms_from_source_text(
                react_src,
                job_dir=job_dir,
                need_mol2=False,
            )
        if r_err and (not r_atoms):
            QtWidgets.QMessageBox.warning(self, "Psi4 Cluster", f"Reactant source failed:\n{r_err}")
            return
        if str(prod_src).strip() == "__cluster_product_guess__":
            p_atoms = [dict(a or {}) for a in list(st_cluster.get("generated_product_atoms", []) or [])]
            p_err = ""
            p_used = "generated_product_guess"
            if not p_atoms:
                p_err = "No generated product guess is available. Click 'Generate Product Guess' first."
        else:
            p_atoms, _p_m2, _p_meta, p_err, p_used = self._psi4_collect_atoms_from_source_text(
                prod_src,
                job_dir=job_dir,
                need_mol2=False,
            )
        if p_err and (not p_atoms):
            QtWidgets.QMessageBox.warning(self, "Psi4 Cluster", f"Product source failed:\n{p_err}")
            return
        state = dict(getattr(self, "_psi4_cluster_state", {}) or {})
        freeze_idx = []
        freeze_backbone = bool(self.cb_psi4_cluster_freeze_backbone.isChecked()) if hasattr(self, "cb_psi4_cluster_freeze_backbone") else True
        freeze_caps = bool(self.cb_psi4_cluster_freeze_cap.isChecked()) if hasattr(self, "cb_psi4_cluster_freeze_cap") else True
        if str(react_src).strip() == "__cluster_reactant__":
            freeze_idx = [int(x) for x in list(state.get("freeze_atom_indices", []) or []) if int(x) > 0]
        if not freeze_idx:
            try:
                mod = self._psi4_cluster_runtime_mod()
                freeze_idx, _meta = mod.build_cluster_freeze_indices(
                    r_atoms,
                    freeze_backbone=freeze_backbone,
                    freeze_caps=freeze_caps,
                )
            except Exception:
                freeze_idx = [int(x) for x in list(state.get("freeze_atom_indices", []) or []) if int(x) > 0]
        auto_spin_on = bool(self.cb_psi4_auto_spin.isChecked()) if hasattr(self, "cb_psi4_auto_spin") else False
        if auto_spin_on:
            charge, mult, auto_note = self._psi4_auto_charge_multiplicity(
                atoms=r_atoms,
                source_file=(react_src if os.path.isfile(react_src) else ""),
                source_meta=r_meta,
                quiet=True,
            )
            self._psi4_append_log(f"Cluster workflow auto charge/multiplicity: {charge}/{mult} ({auto_note})")
        else:
            charge = int(self.spin_psi4_charge.value()) if hasattr(self, "spin_psi4_charge") else 0
            mult = int(self.spin_psi4_mult.value()) if hasattr(self, "spin_psi4_mult") else 1
        timeout_s = int(self.spin_psi4_timeout_min.value()) * 60 if hasattr(self, "spin_psi4_timeout_min") else 7200
        payload = {
            "method": str(method),
            "basis": str(basis),
            "charge": int(charge),
            "mult": int(mult),
            "memory_gb": int(self.spin_psi4_memory_gb.value()) if hasattr(self, "spin_psi4_memory_gb") else 8,
            "threads": int(self.spin_psi4_threads.value()) if hasattr(self, "spin_psi4_threads") else 1,
            "geom_maxiter": int(self.spin_psi4_geom_maxiter.value()) if hasattr(self, "spin_psi4_geom_maxiter") else 100,
            "timeout_s": int(timeout_s),
            "use_pcm": bool(self.cb_psi4_pcm.isChecked()) if hasattr(self, "cb_psi4_pcm") else False,
            "solvent": str(self.cmb_psi4_solvent.currentData() or "Water") if hasattr(self, "cmb_psi4_solvent") else "Water",
            "irc_direction": str(self.cmb_psi4_irc_direction.currentData() or "BOTH") if hasattr(self, "cmb_psi4_irc_direction") else "BOTH",
            "irc_points": int(self.spin_psi4_irc_points.value()) if hasattr(self, "spin_psi4_irc_points") else 20,
            "irc_step": float(self.spin_psi4_irc_step.value()) if hasattr(self, "spin_psi4_irc_step") else 0.20,
            "freeze_atom_indices": list(freeze_idx or []),
            "do_classical_min": bool(self.cb_psi4_cluster_classical.isChecked()) if hasattr(self, "cb_psi4_cluster_classical") else True,
            "mm_steps": int(self.spin_psi4_cluster_mm_steps.value()) if hasattr(self, "spin_psi4_cluster_mm_steps") else 300,
            "do_preopt": bool(self.cb_psi4_cluster_preopt.isChecked()) if hasattr(self, "cb_psi4_cluster_preopt") else True,
            "run_irc": bool(self.cb_psi4_cluster_run_irc.isChecked()) if hasattr(self, "cb_psi4_cluster_run_irc") else True,
            "run_qst3": bool(self.cb_psi4_cluster_run_qst3.isChecked()) if hasattr(self, "cb_psi4_cluster_run_qst3") else True,
            "ts_weight": float(self.spin_psi4_qst_ts_weight.value()) if hasattr(self, "spin_psi4_qst_ts_weight") else 0.35,
            "psi4_bin": str(psi4_bin),
            "job_dir": str(job_dir),
            "react_atoms": list(r_atoms or []),
            "prod_atoms": list(p_atoms or []),
            "react_source": str(r_used or react_src),
            "prod_source": str(p_used or prod_src),
        }
        self._psi4_append_log("=" * 60)
        self._psi4_append_log(f"Cluster reaction workflow dir: {job_dir}")
        self._psi4_append_log(f"Reactant: {r_used or react_src}")
        self._psi4_append_log(f"Product: {p_used or prod_src}")
        self._psi4_append_log(f"Method/Basis: {method}/{basis}")
        self._psi4_append_log(f"Charge/Multiplicity: {charge}/{mult}")
        self._psi4_append_log(
            f"Freeze atoms: {len(freeze_idx)} | mm={bool(payload['do_classical_min'])}({int(payload['mm_steps'])}) "
            f"| preopt={bool(payload['do_preopt'])} | qst3={bool(payload['run_qst3'])} | run_irc={bool(payload['run_irc'])}"
        )
        self.lbl_psi4_status.setText("Psi4 cluster workflow queued in background...")
        if hasattr(self, "lbl_psi4_cluster_status"):
            self.lbl_psi4_cluster_status.setText("Cluster workflow queued...")
        try:
            if hasattr(self, "btn_psi4_cluster_run"):
                self.btn_psi4_cluster_run.setEnabled(False)
        except Exception:
            pass
        self._psi4_last_job_dir = str(job_dir)
        def _job(progress_cb):
            return self._psi4_execute_cluster_reaction_worker(payload, progress_cb=progress_cb)
        def _on_success(data):
            res = dict(data or {})
            for ln in list(res.get("logs", []) or []):
                self._psi4_append_log(str(ln))
            if not bool(res.get("ok", False)):
                msg = str(res.get("error", "Cluster workflow failed.") or "Cluster workflow failed.")
                if hasattr(self, "lbl_psi4_cluster_status"):
                    self.lbl_psi4_cluster_status.setText(msg)
                QtWidgets.QMessageBox.critical(self, "Psi4 Cluster", msg)
                return
            final_rr = dict(res.get("final_run_result", {}) or {})
            final_attempts = list(res.get("final_attempt_summaries", []) or [])
            final_op = str(res.get("final_operation", "ts_qst2") or "ts_qst2")
            self._psi4_finalize_background_run(
                run_result=final_rr,
                attempt_summaries=final_attempts,
                operation=final_op,
                qst_on=True,
                source_mol2="",
                default_job_dir=str(job_dir),
                use_pcm=bool(payload.get("use_pcm", False)),
            )
            if hasattr(self, "lbl_psi4_cluster_status"):
                self.lbl_psi4_cluster_status.setText(
                    f"Cluster workflow finished. Final stage: {final_op}."
                )
        def _on_error(err_text):
            msg = str(err_text or "").strip()
            self.lbl_psi4_status.setText(f"Psi4 cluster failed: {msg[:300]}")
            if hasattr(self, "lbl_psi4_cluster_status"):
                self.lbl_psi4_cluster_status.setText(f"Failed: {msg[:260]}")
            self._psi4_append_log(msg)
            QtWidgets.QMessageBox.critical(self, "Psi4 Cluster", f"Cluster workflow failed:\n{msg[:3000]}")
        def _on_finished():
            try:
                if hasattr(self, "btn_psi4_cluster_run"):
                    self.btn_psi4_cluster_run.setEnabled(True)
            except Exception:
                pass
        self._submit_monitored_background_task(
            _job,
            tool_label="Psi4",
            task_label="cluster_reaction_path",
            on_success=_on_success,
            on_error=_on_error,
            on_finished=_on_finished,
            with_progress=True,
            job_dir=str(job_dir),
        )
    def _on_psi4_plot_ir_experimental(self):
        vib = dict(getattr(self, "_psi4_last_vib_data", {}) or {})
        try:
            fwhm = float(self.spin_psi4_ir_fwhm.value()) if hasattr(self, "spin_psi4_ir_fwhm") else 18.0
        except Exception:
            fwhm = 18.0
        if np.asarray(vib.get("mode_cart_ang", []), dtype=float).ndim != 3:
            if not isinstance(getattr(self, "_psi4_last_result", None), dict):
                QtWidgets.QMessageBox.warning(self, "Psi4", "No vibrational data available yet.")
                return
            self._psi4_present_analysis(result=self._psi4_last_result, job_dir=self._psi4_last_job_dir)
            vib = dict(getattr(self, "_psi4_last_vib_data", {}) or {})
        self._psi4_plot_ir_spectrum(vib_data=vib, auto_animate=True, include_broadened=True, fwhm_cm=float(fwhm))
