    def _psi4_prepare_rdkit_source_for_parameterization_runtime(self, mol_src, out_sdf):
        def _write_one_mol_sdf(mol_obj, sdf_path):
            writer = Chem.SDWriter(str(sdf_path))
            writer.write(mol_obj)
            writer.close()
            return str(sdf_path)
        return psi4_prepare_rdkit_source_for_parameterization(
            mol_src=mol_src,
            out_sdf=out_sdf,
            clone_mol_fn=lambda src: Chem.Mol(src),
            formal_charge_fn=lambda m: int(sum(int(a.GetFormalCharge()) for a in m.GetAtoms())),
            atomic_z_sum_fn=lambda m: int(sum(int(a.GetAtomicNum()) for a in m.GetAtoms())),
            has_conformer_fn=lambda m: int(m.GetNumConformers()) > 0,
            add_hs_fn=lambda m: Chem.AddHs(m, addCoords=True),
            embed_fn=lambda m: AllChem.EmbedMolecule(m, randomSeed=0xC0FFEE),
            optimize_fn=lambda m: AllChem.UFFOptimizeMolecule(m, maxIters=300),
            write_sdf_fn=_write_one_mol_sdf,
        )
