    def _psi4_pick_target_object(self):
        obj = str(getattr(self, "_psi4_last_loaded_object", "") or "").strip()
        try:
            if obj and obj in cmd.get_names("objects"):
                return obj
        except Exception:
            pass
        try:
            self._psi4_load_last_geometry()
            obj = str(getattr(self, "_psi4_last_loaded_object", "") or "").strip()
            if obj and obj in cmd.get_names("objects"):
                return obj
        except Exception:
            pass
        return ""
    def _on_psi4_show_electrostatic_surface(self):
        if not isinstance(getattr(self, "_psi4_last_result", None), dict):
            QtWidgets.QMessageBox.warning(self, "Psi4", "Run a Psi4 job first.")
            return
        res = dict(self._psi4_last_result or {})
        jdir = str(getattr(self, "_psi4_last_job_dir", "") or "").strip()
        charges = np.asarray(res.get("mulliken_charges", []), dtype=float).reshape(-1)
        density_cube = self._psi4_resolve_density_cube(res, jdir)
        if (not density_cube) or (not os.path.isfile(density_cube)):
            QtWidgets.QMessageBox.warning(
                self,
                "Psi4",
                "Could not find a density cube file for electrostatic mapping. Re-run Psi4 (it now writes density cubes).",
            )
            return
        esp_payload = self._psi4_resolve_esp_cube(res, jdir, density_cube, has_charges=(charges.size > 0))
        esp_cube = str(esp_payload.get("esp_cube", "") or "").strip()
        esp_source = str(esp_payload.get("esp_source", "qm_esp_cube") or "qm_esp_cube")
        if str(esp_payload.get("error", "") or "") == "missing_charges":
            QtWidgets.QMessageBox.warning(
                self,
                "Psi4",
                "No QM ESP cube is available and Mulliken charges were not produced. Re-run Psi4 frequencies/optimize first.",
            )
            return
        if bool(esp_payload.get("needs_build", False)):
            ok_esp, msg_esp = self._psi4_build_mulliken_esp_cube_from_density(density_cube, charges.tolist(), esp_cube)
            if (not ok_esp) or (not os.path.isfile(esp_cube)):
                QtWidgets.QMessageBox.warning(self, "Psi4", f"Failed building ESP cube from charges: {msg_esp}")
                return
        obj = self._psi4_pick_target_object()
        if not obj:
            QtWidgets.QMessageBox.warning(self, "Psi4", "Could not locate/load the Psi4 geometry object.")
            return
        try:
            old = dict(getattr(self, "_psi4_esp_objects", {}) or {})
            for _k, oname in old.items():
                try:
                    if oname:
                        cmd.delete(str(oname))
                except Exception:
                    pass
        except Exception:
            pass
        try:
            density_iso = float(self.spin_psi4_density_iso.value()) if hasattr(self, "spin_psi4_density_iso") else 0.001
            esp_iso = float(self.spin_psi4_esp_iso.value()) if hasattr(self, "spin_psi4_esp_iso") else 0.030
            ramp_max = float(self.spin_psi4_esp_ramp.value()) if hasattr(self, "spin_psi4_esp_ramp") else 0.060
        except Exception:
            density_iso = 0.001
            esp_iso = 0.030
            ramp_max = 0.060
        density_iso = float(max(0.0002, min(0.05, density_iso)))
        esp_iso = float(max(0.003, min(0.20, esp_iso)))
        ramp_max = float(max(0.01, min(0.40, ramp_max)))
        ts = datetime.datetime.now().strftime("%H%M%S")
        den_map = self._dock_safe_obj_name(f"psi4_density_map_{ts}")
        esp_map = self._dock_safe_obj_name(f"psi4_esp_map_{ts}")
        surf_den = self._dock_safe_obj_name(f"psi4_density_surf_{ts}")
        surf_pos = self._dock_safe_obj_name(f"psi4_esp_pos_{ts}")
        surf_neg = self._dock_safe_obj_name(f"psi4_esp_neg_{ts}")
        ramp_name = self._dock_safe_obj_name(f"psi4_esp_ramp_{ts}")
        try:
            cmd.load(density_cube, den_map)
            cmd.load(esp_cube, esp_map)
            cmd.isosurface(surf_den, den_map, float(density_iso))
            cmd.color("white", surf_den)
            cmd.set("transparency", 0.25, surf_den)
            cmd.isosurface(surf_pos, esp_map, float(esp_iso))
            cmd.isosurface(surf_neg, esp_map, -float(esp_iso))
            cmd.color("blue", surf_pos)
            cmd.color("red", surf_neg)
            cmd.set("transparency", 0.42, surf_pos)
            cmd.set("transparency", 0.42, surf_neg)
            # Try classical ESP mapping on density surface (red negative, blue positive).
            try:
                cmd.ramp_new(ramp_name, esp_map, [-float(ramp_max), 0.0, float(ramp_max)], ["red", "white", "blue"])
                cmd.set("surface_color", ramp_name, surf_den)
            except Exception:
                pass
            try:
                cmd.group("Psi4.ESP", den_map)
                cmd.group("Psi4.ESP", esp_map)
                cmd.group("Psi4.ESP", surf_den)
                cmd.group("Psi4.ESP", surf_pos)
                cmd.group("Psi4.ESP", surf_neg)
            except Exception:
                pass
            try:
                self._redock_apply_scene_actions(
                    [
                        {"action": "disable", "object": str(den_map)},
                        {"action": "disable", "object": str(esp_map)},
                    ],
                    known_objects=None,
                    default_action="disable",
                )
            except Exception:
                pass
            self._psi4_esp_objects = {
                "density_map": den_map,
                "esp_map": esp_map,
                "density_surface": surf_den,
                "esp_pos_surface": surf_pos,
                "esp_neg_surface": surf_neg,
                "ramp": ramp_name,
            }
            cmd.show("sticks", obj)
            cmd.set("stick_radius", 0.12, obj)
            self._apply_element_colors(obj)
            cmd.orient(f"({obj}) or {surf_den} or {surf_pos} or {surf_neg}")
            try:
                if hasattr(self, "lbl_psi4_visual_status"):
                    if esp_source == "qm_esp_cube":
                        self.lbl_psi4_visual_status.setText(
                            "Electrostatic visualization updated: QM ESP cube mapped as +blue / -red with density envelope."
                        )
                    else:
                        self.lbl_psi4_visual_status.setText(
                            "Electrostatic visualization updated: Mulliken-charge ESP approximation mapped as +blue / -red with density envelope."
                        )
            except Exception:
                pass
        except Exception as e:
            QtWidgets.QMessageBox.warning(self, "Psi4", f"Failed showing electrostatic surface: {e}")
    def _on_psi4_orbital_visibility_changed(self):
        objs = dict(getattr(self, "_psi4_orbital_objects", {}) or {})
        if not objs:
            return
        try:
            show_homo = bool(self.cb_psi4_show_homo.isChecked()) if hasattr(self, "cb_psi4_show_homo") else True
        except Exception:
            show_homo = True
        try:
            show_lumo = bool(self.cb_psi4_show_lumo.isChecked()) if hasattr(self, "cb_psi4_show_lumo") else True
        except Exception:
            show_lumo = True
        homo_objs = [objs.get("homo_pos"), objs.get("homo_neg")]
        lumo_objs = [objs.get("lumo_pos"), objs.get("lumo_neg")]
        map_objs = [objs.get("homo_map"), objs.get("lumo_map")]
        actions = []
        for o in homo_objs:
            if not o:
                continue
            actions.append({"action": ("enable" if show_homo else "disable"), "object": str(o)})
        for o in lumo_objs:
            if not o:
                continue
            actions.append({"action": ("enable" if show_lumo else "disable"), "object": str(o)})
        for o in map_objs:
            if not o:
                continue
            actions.append({"action": "disable", "object": str(o)})
        self._redock_apply_scene_actions(
            list(actions or []),
            known_objects=None,
            default_action="disable",
        )
        try:
            if hasattr(self, "lbl_psi4_visual_status"):
                self.lbl_psi4_visual_status.setText(
                    f"Orbital visibility: HOMO={'on' if show_homo else 'off'}, LUMO={'on' if show_lumo else 'off'}."
                )
        except Exception:
            pass
    def _on_psi4_show_homo_lumo(self):
        if not isinstance(getattr(self, "_psi4_last_result", None), dict):
            QtWidgets.QMessageBox.warning(self, "Psi4", "Run a Psi4 job first.")
            return
        res = dict(self._psi4_last_result or {})
        jdir = str(getattr(self, "_psi4_last_job_dir", "") or "").strip()
        try:
            show_homo = bool(self.cb_psi4_show_homo.isChecked()) if hasattr(self, "cb_psi4_show_homo") else True
            show_lumo = bool(self.cb_psi4_show_lumo.isChecked()) if hasattr(self, "cb_psi4_show_lumo") else True
        except Exception:
            show_homo, show_lumo = True, True
        if (not show_homo) and (not show_lumo):
            QtWidgets.QMessageBox.warning(self, "Psi4", "Enable HOMO and/or LUMO checkboxes first.")
            return
        orb_payload = self._psi4_resolve_homo_lumo_cubes(res, jdir)
        homo_cube = str(orb_payload.get("homo_cube", "") or "").strip()
        lumo_cube = str(orb_payload.get("lumo_cube", "") or "").strip()
        if show_homo and ((not homo_cube) or (not os.path.isfile(homo_cube))):
            QtWidgets.QMessageBox.warning(self, "Psi4", "Could not locate HOMO cube file.")
            return
        if show_lumo and ((not lumo_cube) or (not os.path.isfile(lumo_cube))):
            QtWidgets.QMessageBox.warning(self, "Psi4", "Could not locate LUMO cube file.")
            return
        iso, ok = QtWidgets.QInputDialog.getDouble(
            self,
            "HOMO/LUMO Isovalue",
            "Isovalue",
            0.03,
            0.005,
            0.20,
            3,
        )
        if not ok:
            return
        try:
            old = dict(getattr(self, "_psi4_orbital_objects", {}) or {})
            for _k, oname in old.items():
                try:
                    if oname:
                        cmd.delete(str(oname))
                except Exception:
                    pass
        except Exception:
            pass
        try:
            ts = datetime.datetime.now().strftime("%H%M%S")
            homo_map = ""
            lumo_map = ""
            homo_pos = ""
            homo_neg = ""
            lumo_pos = ""
            lumo_neg = ""
            if show_homo:
                homo_map = self._dock_safe_obj_name(f"psi4_homo_map_{ts}")
                cmd.load(homo_cube, homo_map)
                homo_pos = self._dock_safe_obj_name(f"psi4_homo_pos_{ts}")
                homo_neg = self._dock_safe_obj_name(f"psi4_homo_neg_{ts}")
                cmd.isosurface(homo_pos, homo_map, float(iso))
                cmd.isosurface(homo_neg, homo_map, -float(iso))
                # Conventional MO phase colors: positive blue, negative red.
                cmd.color("blue", homo_pos)
                cmd.color("red", homo_neg)
            if show_lumo:
                lumo_map = self._dock_safe_obj_name(f"psi4_lumo_map_{ts}")
                cmd.load(lumo_cube, lumo_map)
                lumo_pos = self._dock_safe_obj_name(f"psi4_lumo_pos_{ts}")
                lumo_neg = self._dock_safe_obj_name(f"psi4_lumo_neg_{ts}")
                cmd.isosurface(lumo_pos, lumo_map, float(iso))
                cmd.isosurface(lumo_neg, lumo_map, -float(iso))
                cmd.color("blue", lumo_pos)
                cmd.color("red", lumo_neg)
            for o in (homo_pos, homo_neg, lumo_pos, lumo_neg):
                if o:
                    cmd.set("transparency", 0.34, o)
            try:
                for gobj in (homo_map, lumo_map, homo_pos, homo_neg, lumo_pos, lumo_neg):
                    if gobj:
                        cmd.group("Psi4.Orbitals", gobj)
            except Exception:
                pass
            self._psi4_orbital_objects = {
                "homo_map": homo_map,
                "lumo_map": lumo_map,
                "homo_pos": homo_pos,
                "homo_neg": homo_neg,
                "lumo_pos": lumo_pos,
                "lumo_neg": lumo_neg,
            }
            self._on_psi4_orbital_visibility_changed()
            obj = self._psi4_pick_target_object()
            vis_parts = []
            if show_homo:
                vis_parts.extend([homo_pos, homo_neg])
            if show_lumo:
                vis_parts.extend([lumo_pos, lumo_neg])
            if obj:
                cmd.show("sticks", obj)
                cmd.set("stick_radius", 0.12, obj)
                self._apply_element_colors(obj)
                focus = f"({obj})"
                if vis_parts:
                    focus += " or " + " or ".join(vis_parts)
                cmd.orient(focus)
            elif vis_parts:
                cmd.orient(" or ".join(vis_parts))
            try:
                if hasattr(self, "lbl_psi4_visual_status"):
                    self.lbl_psi4_visual_status.setText(
                        f"HOMO/LUMO isosurfaces loaded (iso={float(iso):.3f}); HOMO={'on' if show_homo else 'off'}, LUMO={'on' if show_lumo else 'off'}."
                    )
            except Exception:
                pass
        except Exception as e:
            QtWidgets.QMessageBox.warning(self, "Psi4", f"Failed loading HOMO/LUMO orbitals: {e}")
    def _psi4_workspace_dir(self):
        root = os.path.join(self._dock_workspace_dir(), "psi4_jobs")
        try:
            os.makedirs(root, exist_ok=True)
        except Exception:
            pass
        return root
    def _psi4_tool_path(self):
        user_val = ""
        try:
            user_val = str(self.edit_psi4_bin.text() or "").strip() if hasattr(self, "edit_psi4_bin") else ""
        except Exception:
            user_val = ""
        if user_val:
            if os.path.isabs(user_val):
                try:
                    if os.path.isfile(user_val) and os.access(user_val, os.X_OK):
                        return user_val
                except Exception:
                    pass
            p = shutil.which(user_val)
            if p:
                return p
        p = self._dock_tool_path("psi4")
        if p:
            return p
        common_bins = [
            os.path.join(sys.prefix, "bin"),
            os.path.dirname(sys.executable),
            "/opt/anaconda3/envs/bgt-openmm82/bin",
            "/opt/anaconda3/bin",
            "/opt/homebrew/bin",
            "/usr/local/bin",
        ]
        for b in common_bins:
            if not b:
                continue
            c = os.path.join(b, "psi4")
            if os.path.isfile(c) and os.access(c, os.X_OK):
                return c
        return shutil.which("psi4")
    def _psi4_update_tool_status(self):
        if not hasattr(self, "lbl_psi4_tools"):
            return
        tool = self._psi4_tool_path()
        msg = f"psi4={'OK' if tool else 'MISSING'} | PyMOL Python={sys.executable}"
        if tool:
            msg += f" | using: {tool}"
        else:
            msg += " | install psi4 in this environment or set executable path"
        self.lbl_psi4_tools.setText(msg)
    def _psi4_append_log(self, text):
        if not hasattr(self, "txt_psi4_log"):
            return
        try:
            self.txt_psi4_log.appendPlainText(str(text).rstrip("\n"))
            sb = self.txt_psi4_log.verticalScrollBar()
            if sb is not None:
                sb.setValue(sb.maximum())
        except Exception:
            pass
    def _refresh_psi4_source_combo(self):
        if not hasattr(self, "psi4_source_combo"):
            return
        try:
            names = self._candidate_structure_objects()
            cur = self.psi4_source_combo.currentText()
            self.psi4_source_combo.blockSignals(True)
            self.psi4_source_combo.clear()
            self.psi4_source_combo.addItems(names)
            if cur and cur in names:
                self.psi4_source_combo.setCurrentText(cur)
            elif names:
                best = self._pick_best_structure_object()
                if best and best in names:
                    self.psi4_source_combo.setCurrentText(best)
                else:
                    self.psi4_source_combo.setCurrentIndex(0)
            self.psi4_source_combo.blockSignals(False)
        except Exception:
            pass
