    def _show_virtual_screening_dialog(self):
        try:
            self._refresh_virtual_screening_receptor_combo()
            self._refresh_virtual_screening_pocket_combo()
            self._update_virtual_screening_tool_status()
            self._update_lead_optimization_tool_status()
            self._fit_dialog_to_screen(self._vs_dialog)
            self._vs_dialog.show()
            self._vs_dialog.raise_()
            self._vs_dialog.activateWindow()
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "Error", f"Failed to open virtual screening tools: {e}")
    def _update_virtual_screening_tool_status(self):
        if not hasattr(self, "lbl_vs_tools"):
            return
        sm = self._dock_tool_path("smina")
        ob = self._dock_tool_path("obabel")
        fp = self._dock_tool_path("fpocket")
        meeko_ok = self._vs_meeko_available()
        deepchem_ok = self._vs_module_available("deepchem")
        openff_ok = self._vs_module_available("openff.toolkit")
        pymbar_ok = self._vs_module_available("pymbar")
        msg = (
            f"Tools: smina={'OK' if sm else 'MISSING'} | fpocket={'OK' if fp else 'MISSING'} | "
            f"RDKit={'OK' if HAS_RDKIT else 'MISSING'} | Meeko={'OK' if meeko_ok else 'MISSING'} | "
            f"obabel={'OK' if ob else 'MISSING'} | DeepChem={'OK' if deepchem_ok else 'OPTIONAL'} | "
            f"OpenFF={'OK' if openff_ok else 'OPTIONAL'} | PyMBAR={'OK' if pymbar_ok else 'OPTIONAL'}"
        )
        self.lbl_vs_tools.setText(msg)
    def _refresh_virtual_screening_receptor_combo(self):
        if not hasattr(self, "vs_structure_combo"):
            return
        try:
            names = []
            for n in self._candidate_structure_objects():
                if self._is_generated_docking_object(n):
                    continue
                try:
                    if cmd.count_atoms(f"({n}) and polymer") > 0:
                        names.append(n)
                except Exception:
                    continue
            if not names:
                names = [n for n in self._candidate_structure_objects() if not self._is_generated_docking_object(n)]
            if not names:
                names = self._candidate_structure_objects()
            current = self.vs_structure_combo.currentText()
            preferred = None
            if self._vs_receptor_object in names:
                preferred = self._vs_receptor_object
            elif self._docking_receptor_object in names:
                preferred = self._docking_receptor_object
            elif current in names:
                preferred = current
            elif self.loaded_object in names:
                preferred = self.loaded_object
            elif names:
                preferred = names[0]
            self.vs_structure_combo.blockSignals(True)
            self.vs_structure_combo.clear()
            self.vs_structure_combo.addItems(names)
            if preferred:
                self.vs_structure_combo.setCurrentText(preferred)
                self._vs_receptor_object = str(preferred)
            self.vs_structure_combo.blockSignals(False)
        except Exception as e:
            print(f"VS receptor refresh failed: {e}")
    def _on_vs_receptor_changed(self, obj_name):
        try:
            if obj_name and cmd.count_atoms(obj_name) > 0:
                self._vs_receptor_object = str(obj_name)
                if hasattr(self, "lbl_vs_status"):
                    self.lbl_vs_status.setText(f"Status: receptor={self._vs_receptor_object}.")
        except Exception:
            pass
    def _get_selected_vs_receptor(self):
        try:
            if hasattr(self, "vs_structure_combo"):
                obj = self.vs_structure_combo.currentText()
                if obj and cmd.count_atoms(obj) > 0:
                    return str(obj)
        except Exception:
            pass
        return self._resolve_valid_docking_receptor_object() or self._resolve_analysis_object(prefer_combo=True)
    def _on_vs_upload_receptor(self):
        self._on_upload_docking_receptor()
        self._refresh_virtual_screening_receptor_combo()
        self._refresh_virtual_screening_pocket_combo()
    def _refresh_virtual_screening_pocket_combo(self):
        if not hasattr(self, "cmb_vs_pocket"):
            return
        try:
            current_pid = None
            try:
                cur = self.cmb_vs_pocket.currentData()
                if isinstance(cur, dict):
                    current_pid = int(cur.get("id", 0))
            except Exception:
                current_pid = None
            self.cmb_vs_pocket.blockSignals(True)
            self.cmb_vs_pocket.clear()
            for p in list(self._fpocket_pockets or []):
                if not isinstance(p, dict):
                    continue
                try:
                    pid = int(p.get("id", 0))
                except Exception:
                    pid = 0
                rank = self._dock_float_or_nan(p.get("rank_score", np.nan))
                atoms = 0
                try:
                    atoms = int(p.get("atom_count", 0) or 0)
                except Exception:
                    atoms = 0
                label = f"Pocket {pid}" if pid > 0 else "Pocket"
                if np.isfinite(rank):
                    label += f" (score {rank:.3f})"
                if atoms > 0:
                    label += f" | atoms {atoms}"
                self.cmb_vs_pocket.addItem(label, p)
            if self.cmb_vs_pocket.count() > 0:
                set_idx = 0
                if current_pid is not None:
                    for i in range(self.cmb_vs_pocket.count()):
                        d = self.cmb_vs_pocket.itemData(i)
                        if isinstance(d, dict):
                            try:
                                if int(d.get("id", 0)) == int(current_pid):
                                    set_idx = i
                                    break
                            except Exception:
                                pass
                self.cmb_vs_pocket.setCurrentIndex(set_idx)
                self._on_vs_pocket_changed(set_idx)
            else:
                self._update_vs_grid_summary_label(source="manual")
            self.cmb_vs_pocket.blockSignals(False)
        except Exception as e:
            print(f"VS pocket refresh failed: {e}")
    def _on_vs_run_fpocket(self):
        rec = self._get_selected_vs_receptor()
        if rec:
            self._docking_receptor_object = str(rec)
            try:
                if hasattr(self, "dock_structure_combo"):
                    self.dock_structure_combo.setCurrentText(str(rec))
            except Exception:
                pass
        self._on_run_fpocket_scan()
        self._refresh_virtual_screening_pocket_combo()
    def _get_selected_vs_pocket(self, idx=None):
        """Return the active VS pocket and back-fill geometry from fpocket PDB if needed."""
        pocket = None
        pidx = -1
        if idx is None:
            try:
                pidx = int(self.cmb_vs_pocket.currentIndex()) if hasattr(self, "cmb_vs_pocket") else -1
            except Exception:
                pidx = -1
        else:
            try:
                pidx = int(idx)
            except Exception:
                pidx = -1
        try:
            fp = list(getattr(self, "_fpocket_pockets", []) or [])
        except Exception:
            fp = []
        if pidx >= 0 and pidx < len(fp) and isinstance(fp[pidx], dict):
            pocket = fp[pidx]
        if pocket is None and hasattr(self, "cmb_vs_pocket"):
            try:
                cand = self.cmb_vs_pocket.currentData()
            except Exception:
                cand = None
            if isinstance(cand, dict):
                pocket = cand
        if not isinstance(pocket, dict):
            return None, pidx
        c = pocket.get("center")
        s = pocket.get("size")
        pfile = str(pocket.get("pocket_file", "") or "").strip()
        if (c is None or s is None) and pfile and os.path.isfile(pfile):
            try:
                c2, s2, n2 = self._pocket_geometry_from_pdb(pfile)
            except Exception:
                c2, s2, n2 = None, None, 0
            if c2 is not None and s2 is not None:
                pocket["center"] = c2
                pocket["size"] = s2
                pocket["atom_count"] = int(n2)
                if pidx >= 0 and pidx < len(fp):
                    try:
                        self._fpocket_pockets[pidx] = pocket
                    except Exception:
                        pass
        return pocket, pidx
    def _vs_grid_padding_value(self):
        try:
            return float(self.spin_vs_grid_padding.value()) if hasattr(self, "spin_vs_grid_padding") else 0.0
        except Exception:
            return 0.0
    def _vs_grid_min_edge_value(self):
        try:
            return float(self.spin_vs_grid_min_edge.value()) if hasattr(self, "spin_vs_grid_min_edge") else 6.0
        except Exception:
            return 6.0
    def _set_vs_grid_controls(self, center, size):
        """Set six grid spin boxes without firing half-updated change events."""
        if not all(hasattr(self, k) for k in ("spin_vs_cx", "spin_vs_cy", "spin_vs_cz", "spin_vs_sx", "spin_vs_sy", "spin_vs_sz")):
            return
        spins = (self.spin_vs_cx, self.spin_vs_cy, self.spin_vs_cz, self.spin_vs_sx, self.spin_vs_sy, self.spin_vs_sz)
        try:
            for sp in spins:
                sp.blockSignals(True)
            self.spin_vs_cx.setValue(float(center[0]))
            self.spin_vs_cy.setValue(float(center[1]))
            self.spin_vs_cz.setValue(float(center[2]))
            self.spin_vs_sx.setValue(float(size[0]))
            self.spin_vs_sy.setValue(float(size[1]))
            self.spin_vs_sz.setValue(float(size[2]))
        finally:
            for sp in spins:
                try:
                    sp.blockSignals(False)
                except Exception:
                    pass
    def _vs_grid_payload_from_controls(self, pocket=None):
        """Read visible controls and return normalized values safe for smina."""
        raw = {
            "target_ph": float(self.spin_vs_ph.value()) if hasattr(self, "spin_vs_ph") else 7.4,
            "max_ligs": int(self.spin_vs_max_ligands.value()) if hasattr(self, "spin_vs_max_ligands") else 250,
            "center": (
                float(self.spin_vs_cx.value()) if hasattr(self, "spin_vs_cx") else 0.0,
                float(self.spin_vs_cy.value()) if hasattr(self, "spin_vs_cy") else 0.0,
                float(self.spin_vs_cz.value()) if hasattr(self, "spin_vs_cz") else 0.0,
            ),
            "size": (
                float(self.spin_vs_sx.value()) if hasattr(self, "spin_vs_sx") else 18.0,
                float(self.spin_vs_sy.value()) if hasattr(self, "spin_vs_sy") else 18.0,
                float(self.spin_vs_sz.value()) if hasattr(self, "spin_vs_sz") else 18.0,
            ),
            "exhaustiveness": int(self.spin_vs_exhaustiveness.value()) if hasattr(self, "spin_vs_exhaustiveness") else 8,
            "timeout_lig": int(self.spin_vs_timeout.value()) if hasattr(self, "spin_vs_timeout") else 300,
            "grid_padding": self._vs_grid_padding_value(),
            "grid_min_edge": self._vs_grid_min_edge_value(),
        }
        return normalize_virtual_screening_controls(raw, pocket=pocket)
    def _update_vs_grid_summary_label(self, source="manual", pocket_id=None):
        if not hasattr(self, "lbl_vs_grid_summary"):
            return
        pocket = None
        if pocket_id is None:
            pocket, _ = self._get_selected_vs_pocket(None)
            if isinstance(pocket, dict):
                pocket_id = pocket.get("id", None)
        payload = self._vs_grid_payload_from_controls(pocket=pocket)
        if bool(payload.get("ok", False)):
            self.lbl_vs_grid_summary.setText(
                dock_format_docking_grid_summary(
                    payload.get("center", []),
                    payload.get("size", []),
                    source=source,
                    pocket_id=pocket_id,
                )
            )
        else:
            self.lbl_vs_grid_summary.setText(f"Grid: {payload.get('error', 'not defined')}")
    def _sync_vs_grid_from_pocket(self, pocket):
        """
        Apply the user-visible fpocket grid policy to the VS controls.

        The center is the pocket center; dimensions are padded and given a
        minimum edge so narrow pocket atom clouds do not create failed smina
        boxes.  The same normalized values are later read by the run step.
        """
        if not isinstance(pocket, dict):
            return False, None, None
        c = pocket.get("center")
        s = pocket.get("size")
        if c is None or s is None:
            return False, None, None
        grid = normalize_virtual_screening_grid(
            c,
            s,
            padding=self._vs_grid_padding_value(),
            min_edge=self._vs_grid_min_edge_value(),
            max_edge=120.0,
        )
        if not bool(grid.get("ok", False)):
            return False, None, None
        center = tuple(grid.get("center", (0.0, 0.0, 0.0)))
        size = tuple(grid.get("size", (18.0, 18.0, 18.0)))
        self._set_vs_grid_controls(center, size)
        self._update_vs_grid_summary_label(source="pocket", pocket_id=pocket.get("id", None))
        if bool(getattr(self, "_vs_grid_visible", True)):
            self._show_docking_grid_box(list(center), list(size), zoom=False)
        return True, center, size
    def _on_vs_grid_policy_changed(self, *_args):
        pocket, _pidx = self._get_selected_vs_pocket(None)
        if isinstance(pocket, dict):
            self._sync_vs_grid_from_pocket(pocket)
        else:
            self._update_vs_grid_summary_label(source="manual")
    def _on_sync_vs_grid_from_selected_pocket(self):
        pocket, _pidx = self._get_selected_vs_pocket(None)
        if not isinstance(pocket, dict):
            QtWidgets.QMessageBox.warning(self, "Virtual Screening Grid", "Choose a pocket before syncing the grid.")
            return
        ok_sync, _center, _size = self._sync_vs_grid_from_pocket(pocket)
        if not bool(ok_sync):
            QtWidgets.QMessageBox.warning(
                self,
                "Virtual Screening Grid",
                "Selected pocket has no usable geometry for a screening grid.",
            )
    def _on_vs_pocket_changed(self, _idx):
        if not hasattr(self, "cmb_vs_pocket"):
            return
        p, _pidx = self._get_selected_vs_pocket(_idx)
        if not isinstance(p, dict):
            return
        ok_sync, _center, _size = self._sync_vs_grid_from_pocket(p)
        if not bool(ok_sync):
            self._update_vs_grid_summary_label(source="pocket", pocket_id=p.get("id", None))
    def _on_vs_grid_changed(self, *_args):
        if not hasattr(self, "spin_vs_cx"):
            return
        self._update_vs_grid_summary_label(source="manual")
        if not bool(getattr(self, "_vs_grid_visible", True)):
            return
        payload = self._vs_grid_payload_from_controls()
        if not bool(payload.get("ok", False)):
            return
        center = list(payload.get("center", (0.0, 0.0, 0.0)))
        size = list(payload.get("size", (18.0, 18.0, 18.0)))
        try:
            spins = [getattr(self, k) for k in ("spin_vs_cx", "spin_vs_cy", "spin_vs_cz",
                                                "spin_vs_sx", "spin_vs_sy", "spin_vs_sz")]
            if any(w.hasFocus() for w in spins):
                self._vs_grid_user_defined = True
        except Exception:
            pass
        # (0, 0, 0) is the untouched default: no grid to draw yet
        if not (bool(getattr(self, "_vs_grid_user_defined", False)) or any(abs(float(c)) > 1e-6 for c in center)):
            return
        self._show_docking_grid_box(center, size, zoom=False)
    def _set_vs_grid_visibility(self, visible):
        self._vs_grid_visible = bool(visible)
        if self._vs_grid_visible:
            self._on_vs_grid_changed()
        else:
            self._delete_docking_grid_objects()
    def _on_vs_pick_library(self):
        fname, _ = QtWidgets.QFileDialog.getOpenFileName(
            self,
            "Select SDF Library",
            "",
            "SDF Files (*.sdf);;All Files (*)",
        )
        if not fname:
            return
        self._vs_library_sdf = str(fname)
        if hasattr(self, "lbl_vs_library"):
            self.lbl_vs_library.setText(f"Library: {self._vs_library_sdf}")
        try:
            preview_limit = min(100, int(self.spin_vs_max_ligands.value()) if hasattr(self, "spin_vs_max_ligands") else 100)
        except Exception:
            preview_limit = 100
        _preview_entries, preview_info = self._vs_load_sdf_library(self._vs_library_sdf, max_ligands=preview_limit)
        self._update_vs_library_status(self._vs_library_sdf, preview_info, preview=True)
        if hasattr(self, "lbl_vs_status"):
            self.lbl_vs_status.setText("Status: library selected, ready to run screening.")
    def _update_vs_library_status(self, library_path=None, info=None, preview=False):
        if hasattr(self, "lbl_vs_library_stats"):
            self.lbl_vs_library_stats.setText(
                format_virtual_screening_library_status(
                    library_path or getattr(self, "_vs_library_sdf", ""),
                    info=info,
                    preview=preview,
                )
            )
    def _vs_meeko_available(self):
        if not HAS_RDKIT:
            return False
        try:
            return importlib.util.find_spec("meeko") is not None
        except Exception:
            return False
    def _vs_prepare_ligand_with_meeko(self, mol, out_pdbqt, target_ph=None):
        """Meeko PDBQT for a ligand. With ``target_ph`` the ligand is first protonated at that pH
        by the pKa module (Virtual Screening / Lead Optimization libraries arrive as drawn);
        docking passes None because its ligand was already protonated (or chosen in the pKa window)."""
        if (not HAS_RDKIT) or mol is None:
            return False, "RDKit unavailable or invalid molecule"
        try:
            from meeko import MoleculePreparation, PDBQTWriterLegacy
        except Exception as e:
            return False, f"Meeko import failed: {e}"
        try:
            work = Chem.Mol(mol)
            Chem.SanitizeMol(work)
        except Exception as e:
            return False, f"Sanitization failed: {e}"
        try:
            core = self._select_best_ligand_fragment(Chem.RemoveHs(work))
            Chem.SanitizeMol(core)
        except Exception:
            core = Chem.RemoveHs(work)
        try:
            # Rebuild from canonical SMILES to avoid malformed source topology
            # propagating into Meeko/PDBQT generation.
            smi = Chem.MolToSmiles(Chem.RemoveHs(core), isomericSmiles=True)
            rebuilt = Chem.MolFromSmiles(smi)
            if rebuilt is not None:
                Chem.SanitizeMol(rebuilt)
                core = rebuilt
        except Exception:
            pass
        if target_ph is not None:
            try:
                core = Chem.RemoveHs(pka_protonate_molecule(core, float(target_ph), method=self._pka_method(bulk=True),
                                                            cache_dir=self._pka_cache_dir())[0])
            except Exception as exc:
                self._append_debug_log(f"Meeko prep: pKa protonation skipped ({exc}).")
        try:
            work = Chem.AddHs(core, addCoords=True)
        except Exception as e:
            return False, f"AddHs failed: {e}"
        bad_geom, _gdiag = self._ligand_geometry_is_bad(work)
        if bad_geom:
            try:
                params = AllChem.ETKDGv3()
                params.randomSeed = 20260219
                params.useSmallRingTorsions = True
                rc = AllChem.EmbedMolecule(work, params)
                if int(rc) != 0:
                    rc2 = AllChem.EmbedMolecule(work, randomSeed=20260219)
                    if int(rc2) != 0:
                        return False, "3D embedding failed"
            except Exception as e:
                return False, f"3D embedding failed: {e}"
        try:
            if int(work.GetNumAtoms()) <= 70:
                for fn in (AllChem.MMFFOptimizeMolecule, AllChem.UFFOptimizeMolecule):
                    try:
                        fn(work, maxIters=300)
                        break
                    except Exception:
                        continue
        except Exception:
            pass
        try:
            prep = MoleculePreparation()
            setups = prep.prepare(work)
            if isinstance(setups, (list, tuple)):
                if len(setups) <= 0:
                    return False, "Meeko produced no ligand setup"
                setup = setups[0]
            else:
                setup = setups
            ws = PDBQTWriterLegacy.write_string(setup)
            pdbqt_text = ""
            if isinstance(ws, tuple):
                pdbqt_text = str(ws[0] or "")
                ok_flag = bool(ws[1]) if len(ws) > 1 else True
                err_txt = str(ws[2]) if len(ws) > 2 else ""
                if (not ok_flag) and (not pdbqt_text.strip()):
                    return False, f"Meeko writer failed: {err_txt}"
            else:
                pdbqt_text = str(ws or "")
            if ("ATOM" not in pdbqt_text) and ("HETATM" not in pdbqt_text):
                return False, "Meeko output missing ATOM/HETATM records"
            with open(out_pdbqt, "w", encoding="utf-8") as fh:
                fh.write(pdbqt_text)
            if not self._dock_pdbqt_syntax_ok(out_pdbqt, min_atoms=3, require_types=True):
                self._dock_repair_pdbqt_atom_types(out_pdbqt)
            if not self._dock_pdbqt_syntax_ok(out_pdbqt, min_atoms=3, require_types=True):
                return False, "Generated PDBQT has invalid syntax"
        except Exception as e:
            return False, f"Meeko preparation failed: {e}"
        return True, "meeko"
    def _vs_load_sdf_library(self, sdf_file, max_ligands=250):
        if not HAS_RDKIT:
            return [], {"loaded": 0, "skipped": 0, "total": 0, "reason": "RDKit unavailable"}
        lib = str(sdf_file or "").strip()
        if (not lib) or (not os.path.isfile(lib)):
            return [], {"loaded": 0, "skipped": 0, "total": 0, "reason": "missing_sdf"}
        out = []
        total = 0
        skipped = 0
        lim = max(1, int(max_ligands))
        truncated = False
        try:
            sup = Chem.SDMolSupplier(lib, removeHs=False, sanitize=False)
        except Exception:
            return [], {"loaded": 0, "skipped": 0, "total": 0, "reason": "invalid_sdf"}
        # the drug-likeness filter runs while reading, so the limit counts compounds that pass it
        rule = str(self.cmb_vs_druglike_filter.currentData() or "none") if hasattr(self, "cmb_vs_druglike_filter") else "none"
        no_pains = bool(self.cb_vs_exclude_pains.isChecked()) if hasattr(self, "cb_vs_exclude_pains") else False
        rejected = []
        log = getattr(self, "_append_debug_log", lambda _m: None)
        try:
            try:
                dl = self._modeler_import_module("druglike_runtime")
            except Exception:
                import druglike_runtime as dl
        except Exception as e:
            dl = None
            log(f"VS drug-likeness filter skipped: {e}")
        for i, m in enumerate(sup):
            total += 1
            if len(out) >= lim:
                truncated = True
                break
            if m is None:
                skipped += 1
                continue
            try:
                mol = Chem.Mol(m)
                Chem.SanitizeMol(mol)
                mol = self._select_best_ligand_fragment(mol)
                Chem.SanitizeMol(mol)
                try:
                    # Force a clean valence-consistent graph before VS prep.
                    smi = Chem.MolToSmiles(Chem.RemoveHs(mol), isomericSmiles=True)
                    rebuilt = Chem.MolFromSmiles(smi)
                    if rebuilt is not None:
                        Chem.SanitizeMol(rebuilt)
                        mol = rebuilt
                except Exception:
                    pass
                if int(mol.GetNumHeavyAtoms()) < 3:
                    skipped += 1
                    continue
            except Exception:
                skipped += 1
                continue
            name = ""
            ident = ""
            for p in ("_Name", "NAME", "name", "ID", "id", "CID", "cid"):
                try:
                    # the SDF record (m) keeps the properties; the rebuilt molecule does not
                    if m.HasProp(p):
                        v = str(m.GetProp(p)).strip()
                        if v and (not name):
                            name = v
                        if v and p.lower() in ("id", "cid") and (not ident):
                            ident = v
                except Exception:
                    continue
            if not name:
                name = f"Lig_{i+1}"
            entry = {
                "index": int(i + 1),
                "name": str(name),
                "identifier": str(ident),
                "mol": mol,
            }
            if dl is not None:
                try:
                    kept, rej = dl.filter_entries([entry], rule=rule, exclude_pains=no_pains)
                except Exception:
                    kept, rej = [entry], []
                rejected.extend(rej)
                if not kept:
                    continue
            out.append(entry)
        try:
            self._vs_library_props = {int(e["index"]): dict(e.get("druglike") or {}) for e in out + rejected}
            self._vs_filter_rejected = [{"index": e.get("index"), "name": e.get("name"),
                                         "reason": e.get("filter_reason", "")} for e in rejected]
            if rejected:
                log(f"VS drug-likeness filter '{rule}'{' + PAINS' if no_pains else ''}: "
                    f"{len(rejected)} compound(s) removed before docking")
        except Exception as e:
            log(f"VS drug-likeness filter skipped: {e}")
        return out, {
            "loaded": int(len(out)),
            "skipped": int(skipped),
            "total": int(total),
            "limit": int(lim),
            "truncated": bool(truncated),
            "filtered": int(len(rejected)),
            "filter": rule + (" + PAINS" if no_pains else ""),
            "reason": "ok",
        }
    def _populate_vs_table(self):
        if not hasattr(self, "tbl_vs_hits"):
            return
        self.tbl_vs_hits.setRowCount(0)
        for i, h in enumerate(list(self._vs_results or [])):
            self.tbl_vs_hits.insertRow(i)
            rank = h.get("rank", None)
            rank_txt = str(int(rank)) if isinstance(rank, (int, np.integer)) else "-"
            try:
                idx_txt = str(int(h.get("index", i + 1)))
            except Exception:
                idx_txt = str(i + 1)
            name_txt = str(h.get("name", ""))[:160]
            id_txt = str(h.get("identifier", ""))
            aff = self._dock_float_or_nan(h.get("affinity", np.nan))
            aff_txt = f"{aff:.3f}" if np.isfinite(aff) else "n/a"
            prep_txt = str(h.get("prep", ""))
            status_txt = str(h.get("status", ""))
            self.tbl_vs_hits.setItem(i, 0, QtWidgets.QTableWidgetItem(rank_txt))
            self.tbl_vs_hits.setItem(i, 1, QtWidgets.QTableWidgetItem(idx_txt))
            self.tbl_vs_hits.setItem(i, 2, QtWidgets.QTableWidgetItem(name_txt))
            self.tbl_vs_hits.setItem(i, 3, QtWidgets.QTableWidgetItem(id_txt))
            self.tbl_vs_hits.setItem(i, 4, QtWidgets.QTableWidgetItem(aff_txt))
            self.tbl_vs_hits.setItem(i, 5, QtWidgets.QTableWidgetItem(prep_txt))
            self.tbl_vs_hits.setItem(i, 6, QtWidgets.QTableWidgetItem(status_txt))
        try:
            self.tbl_vs_hits.resizeRowsToContents()
            self.tbl_vs_hits.resizeColumnsToContents()
        except Exception:
            pass
        if self.tbl_vs_hits.rowCount() > 0:
            self.tbl_vs_hits.selectRow(0)
    def _selected_vs_hit(self):
        if not getattr(self, "_vs_results", None):
            return None, -1
        row = int(self.tbl_vs_hits.currentRow()) if hasattr(self, "tbl_vs_hits") else -1
        if row < 0 and len(self._vs_results) > 0:
            row = 0
        if row < 0 or row >= len(self._vs_results):
            return None, -1
        return dict(self._vs_results[row]), int(row)
    def _show_vs_selected_hit_preview(self, zoom=False):
        hit, row = self._selected_vs_hit()
        if not hit:
            return
        if str(hit.get("status", "")).lower() != "ok":
            return
        pose_file = str(hit.get("pose_view_file", "") or hit.get("pose_file", "")).strip()
        if (not pose_file) or (not os.path.isfile(pose_file)):
            return
        pose_obj = str(getattr(self, "_vs_pose_preview_obj", "vs_selected_pose_preview"))
        receptor_obj = str(self._vs_receptor_object or self._get_selected_vs_receptor() or "")
        receptor_sel = self._pymol_model_selection(receptor_obj, wrap=True) if receptor_obj else ""
        try:
            if pose_obj in cmd.get_names("objects"):
                cmd.delete(pose_obj)
            cmd.load(pose_file, pose_obj)
            if int(cmd.count_atoms(pose_obj)) <= 0:
                return
            self._apply_ball_and_stick_style(pose_obj, sphere_scale=0.22, stick_radius=0.16)
            self._apply_element_colors(pose_obj)
            cmd.group("VirtualScreening.Results", pose_obj)
            if receptor_obj and (receptor_obj in cmd.get_names("objects")) and receptor_sel:
                cmd.show("cartoon", f"{receptor_sel} and polymer")
                if bool(zoom):
                    cmd.zoom(f"{receptor_sel} or ({pose_obj})", 8.0)
            else:
                if bool(zoom):
                    cmd.zoom(pose_obj, 8.0)
        except Exception as e:
            self._append_debug_log(f"VS pose preview warning (row={row}): {e}")
    def _on_vs_hit_selection_changed(self):
        self._show_vs_selected_hit_preview(zoom=False)
    def _plot_virtual_screening_results(self):
        if not HAS_MPL:
            QtWidgets.QMessageBox.warning(self, "Plot", "matplotlib is not available in this environment.")
            return
        vals = []
        for h in list(getattr(self, "_vs_results", []) or []):
            try:
                if str(h.get("status", "")).lower() != "ok":
                    continue
                a = float(h.get("affinity", np.nan))
                if np.isfinite(a):
                    vals.append(a)
            except Exception:
                continue
        if len(vals) <= 0:
            QtWidgets.QMessageBox.information(self, "Plot", "No valid virtual screening scores to plot.")
            return
        arr = np.array(sorted(vals), dtype=float)
        ranks = np.arange(1, arr.size + 1, dtype=int)
        bins = int(np.clip(np.sqrt(float(arr.size)), 8, 40))
        fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(11, 4.5))
        fig.patch.set_facecolor("#f7f7f7")
        ax1.plot(ranks, arr, color="#4a4a4a", linewidth=1.4)
        ax1.scatter([1], [float(arr[0])], color="#1f1f1f", s=45, label="Best")
        ax1.set_xlabel("Rank")
        ax1.set_ylabel("Affinity (kcal/mol)")
        ax1.set_title("Virtual Screening Ranking")
        ax1.grid(alpha=0.25)
        ax1.legend(loc="best", fontsize=8)
        ax2.hist(arr, bins=bins, color="#8a8a8a", alpha=0.85, edgecolor="#1f1f1f", linewidth=0.4)
        ax2.set_xlabel("Affinity (kcal/mol)")
        ax2.set_ylabel("Count")
        ax2.set_title("Score Distribution")
        ax2.grid(alpha=0.20)
        fig.suptitle(
            f"Virtual Screening Summary | N={arr.size} | best={arr.min():.3f} kcal/mol | median={np.median(arr):.3f}"
        )
        fig.tight_layout()
        plt.show()
    def _prepare_vs_selected_complex(self):
        hit, row = self._selected_vs_hit()
        if not hit:
            QtWidgets.QMessageBox.warning(self, "Virtual Screening", "Select a hit first.")
            return None
        if str(hit.get("status", "")).lower() != "ok":
            QtWidgets.QMessageBox.warning(self, "Virtual Screening", "Selected hit has no valid docking pose.")
            return None
        self._show_vs_selected_hit_preview(zoom=False)
        pose_obj = str(getattr(self, "_vs_pose_preview_obj", "vs_selected_pose_preview"))
        if pose_obj not in cmd.get_names("objects") or int(cmd.count_atoms(pose_obj)) <= 0:
            QtWidgets.QMessageBox.warning(self, "Virtual Screening", "Could not load selected hit pose.")
            return None
        receptor_obj = str(self._vs_receptor_object or self._get_selected_vs_receptor() or "")
        if not receptor_obj or receptor_obj not in cmd.get_names("objects"):
            QtWidgets.QMessageBox.warning(self, "Virtual Screening", "No valid receptor object available.")
            return None
        rank_val = hit.get("rank", None)
        try:
            rank_tag = int(rank_val) if rank_val is not None else int(row + 1)
        except Exception:
            rank_tag = int(row + 1)
        complex_obj = f"vs_complex_rank{rank_tag}"
        try:
            if complex_obj in cmd.get_names("objects"):
                cmd.delete(complex_obj)
            receptor_sel = self._pymol_model_selection(receptor_obj, wrap=True)
            rec_poly_sel = f"{receptor_sel} and polymer"
            if int(cmd.count_atoms(rec_poly_sel)) > 0:
                src_sel = rec_poly_sel
            else:
                src_sel = receptor_sel
            cmd.create(complex_obj, f"({src_sel}) or ({pose_obj})", 1, 1)
            if int(cmd.count_atoms(complex_obj)) <= 0:
                raise RuntimeError("complex has 0 atoms")
            cmd.show("cartoon", f"({complex_obj}) and polymer")
            self._apply_ball_and_stick_style(f"({complex_obj}) and not polymer", sphere_scale=0.22, stick_radius=0.16)
            self._apply_element_colors(f"({complex_obj}) and not polymer")
            cmd.group("VirtualScreening.Results", complex_obj)
            cmd.zoom(f"({complex_obj})", 8.0)
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "Virtual Screening", f"Failed to build hit complex: {e}")
            return None
        self.loaded_object = complex_obj
        self._traj_topology_object = complex_obj
        try:
            self._populate_limit_combo()
        except Exception:
            pass
        lig = self._auto_detect_ligand_in_object(complex_obj) or self._auto_detect_ligand()
        if lig:
            self.ligand_info = lig
            try:
                self.ligand_chain.setText(str(lig[0]))
                self.ligand_resi.setText(str(lig[1]))
                self.ligand_resn.setText(str(lig[2]))
            except Exception:
                pass
        return complex_obj
    def _on_vs_load_selected_hit(self):
        obj = self._prepare_vs_selected_complex()
        if not obj:
            return
        QtWidgets.QMessageBox.information(self, "Virtual Screening", f"Loaded selected hit into '{obj}'.")
    def _on_vs_compute_interactions_selected_hit(self):
        obj = self._prepare_vs_selected_complex()
        if not obj:
            return
        self._append_debug_log(f"Computing interactions for VS hit object: {obj}")
        self._on_calc_interactions()
    def _vs_prepare_job_paths_runtime(self, workspace_dir, receptor_obj, tag=None):
        return dict(
            vs_prepare_job_paths(
                workspace_dir=workspace_dir,
                receptor_obj=receptor_obj,
                safe_name_fn=self._dock_safe_obj_name,
                tag=tag,
                makedirs_fn=os.makedirs,
            )
        )
    def _vs_read_screening_controls(self, pocket):
        payload = self._vs_grid_payload_from_controls(pocket=pocket)
        if bool(payload.get("ok", False)):
            self._set_vs_grid_controls(payload.get("center", (0.0, 0.0, 0.0)), payload.get("size", (18.0, 18.0, 18.0)))
            self._update_vs_grid_summary_label(source="controls", pocket_id=(pocket or {}).get("id", None) if isinstance(pocket, dict) else None)
        return dict(payload)
    def _vs_write_sdf_for_docking(self, mol, lig_sdf, lig_name):
        try:
            w = Chem.SDWriter(str(lig_sdf))
            msave = Chem.Mol(mol)
            try:
                if msave is not None:
                    msave.SetProp("_Name", str(lig_name))
            except Exception:
                pass
            w.write(msave)
            w.close()
            return True, ""
        except Exception as e:
            return False, str(e)
    def _vs_prepare_meeko_for_docking(self, mol, out_pdbqt):
        ph = float(self.spin_vs_ph.value()) if hasattr(self, "spin_vs_ph") else 7.4
        return self._vs_prepare_ligand_with_meeko(mol, out_pdbqt, target_ph=ph)
    def _vs_fallback_prepare_ligand_for_docking(self, lig_sdf, fallback_job, target_ph_local):
        try:
            os.makedirs(fallback_job, exist_ok=True)
        except Exception:
            pass
        # library-scale preparation: the pKa default Psi4 becomes PM7 (minutes per molecule otherwise)
        with self._pka_bulk_mode():
            return self._prepare_ligand_for_docking(
                lig_sdf,
                fallback_job,
                target_ph=float(target_ph_local),
                smiles_hint="",
                preserve_input_charges=False,
            )
    def _vs_convert_pose_for_view_runtime(self, out_pose, pose_dir_local, stem_local):
        pose_view_local = str(out_pose)
        if str(out_pose).lower().endswith(".pdbqt"):
            view_sdf = os.path.join(pose_dir_local, f"{stem_local}_view.sdf")
            if self._convert_pdbqt_to_sdf_for_pymol(out_pose, view_sdf):
                pose_view_local = view_sdf
            else:
                view_pdb = os.path.join(pose_dir_local, f"{stem_local}_view.pdb")
                if self._convert_pdbqt_to_pdb_for_pymol(out_pose, view_pdb):
                    pose_view_local = view_pdb
        return pose_view_local
    def _run_docking_entries_with_progress(self, progress_label, total_entries, run_fn, run_kwargs):
        """Execute an entry runner with a modal progress dialog and cancel hook."""
        pd = QtWidgets.QProgressDialog(
            str(progress_label),
            "Cancel",
            0,
            int(total_entries),
            self,
        )
        pd.setWindowModality(QtCore.Qt.WindowModal)
        on_progress = functools.partial(self._dock_progress_dialog_callback, pd)
        payload = dict(run_kwargs or {})
        payload["on_progress"] = on_progress
        results = []
        cancelled = False
        QtWidgets.QApplication.setOverrideCursor(QtCore.Qt.WaitCursor)
        try:
            results, cancelled = run_fn(**payload)
            pd.setValue(int(len(results)))
        finally:
            QtWidgets.QApplication.restoreOverrideCursor()
        return list(results or []), bool(cancelled)
    def _run_post_docking_pipeline(
        self,
        results,
        context=None,
        rank_fn=None,
        transform_fn=None,
        summary_fn=None,
        apply_state_fn=None,
        log_fn=None,
        status_fn=None,
        dialog_fn=None,
    ):
        """Thin UI wrapper around runtime post-docking pipeline composition."""
        return dict(
            run_post_docking_pipeline(
                results=results,
                context=context,
                rank_fn=rank_fn,
                transform_fn=transform_fn,
                summary_fn=summary_fn,
                apply_state_fn=apply_state_fn,
                log_fn=log_fn,
                status_fn=status_fn,
                dialog_fn=dialog_fn,
            )
        )
    def _vs_run_screening_entries(
        self,
        entries,
        smina_bin,
        receptor_input,
        center,
        size,
        exhaustiveness,
        timeout_lig,
        lig_dir,
        pose_dir,
        target_ph,
    ):
        return self._run_docking_entries_with_progress(
            progress_label=f"Running virtual screening ({len(entries)} ligands)...",
            total_entries=len(entries),
            run_fn=run_virtual_screening_entries,
            run_kwargs={
                "entries": entries,
                "smina_bin": smina_bin,
                "receptor_input": receptor_input,
                "center": center,
                "size": size,
                "exhaustiveness": exhaustiveness,
                "timeout_lig": timeout_lig,
                "lig_dir": lig_dir,
                "pose_dir": pose_dir,
                "target_ph": target_ph,
                "safe_name_fn": self._dock_safe_obj_name,
                "write_sdf": self._vs_write_sdf_for_docking,
                "prepare_with_meeko": self._vs_prepare_meeko_for_docking,
                "fallback_prepare_ligand": self._vs_fallback_prepare_ligand_for_docking,
                "run_command": self._dock_run_command,
                "parse_pose_scores": self._parse_smina_pose_scores,
                "convert_pose_for_view": self._vs_convert_pose_for_view_runtime,
            },
        )
    def _prepare_docking_receptor_input_checked(
        self,
        receptor_obj,
        job_dir,
        target_ph,
        flow_label,
        warning_title,
        fail_context,
    ):
        """Prepare receptor once and return a structured status payload."""
        receptor_input, rec_info = self._prepare_receptor_for_docking(
            receptor_obj,
            job_dir,
            target_ph=float(target_ph),
            flow_label=str(flow_label),
        )
        if isinstance(rec_info, dict) and str(rec_info.get("error", "")) == "cancelled":
            return {
                "ok": False,
                "cancelled": True,
                "receptor_input": "",
                "rec_info": rec_info,
            }
        if (not receptor_input) or (not os.path.isfile(receptor_input)):
            QtWidgets.QMessageBox.warning(
                self,
                str(warning_title),
                f"Failed to prepare receptor for {fail_context}. Details: {rec_info}",
            )
            return {
                "ok": False,
                "cancelled": False,
                "receptor_input": "",
                "rec_info": rec_info,
            }
        return {
            "ok": True,
            "cancelled": False,
            "receptor_input": str(receptor_input),
            "rec_info": rec_info,
        }
    def _vs_validate_run_prereqs(self):
        smina_bin = self._dock_tool_path("smina")
        if not smina_bin:
            QtWidgets.QMessageBox.warning(self, "Missing Tool", "smina was not found in PATH.")
            return {}
        if not HAS_RDKIT:
            QtWidgets.QMessageBox.warning(self, "Missing Dependency", "RDKit is required for virtual screening.")
            return {}
        if not self._vs_meeko_available():
            QtWidgets.QMessageBox.warning(
                self,
                "Missing Dependency",
                "Meeko is required for virtual screening ligand preparation.\n"
                "Install it in the active PyMOL Python environment: pip install meeko",
            )
            return {}
        receptor_obj = self._get_selected_vs_receptor()
        if not receptor_obj:
            QtWidgets.QMessageBox.warning(self, "Input", "Select a receptor object first.")
            return {}
        pocket, _pidx = self._get_selected_vs_pocket(None)
        if not isinstance(pocket, dict):
            QtWidgets.QMessageBox.warning(self, "Input", "Run fpocket and choose a pocket first.")
            return {}
        lib = str(getattr(self, "_vs_library_sdf", "") or "").strip()
        if (not lib) or (not os.path.isfile(lib)):
            QtWidgets.QMessageBox.warning(self, "Input", "Choose an SDF library file first.")
            return {}
        return {
            "smina_bin": str(smina_bin),
            "receptor_obj": str(receptor_obj),
            "pocket": pocket,
            "lib": str(lib),
        }
    def _vs_load_library_entries_checked(self, lib, max_ligands):
        entries, lib_info = self._vs_load_sdf_library(lib, max_ligands=int(max_ligands))
        self._update_vs_library_status(lib, lib_info, preview=False)
        if len(entries) <= 0:
            QtWidgets.QMessageBox.warning(
                self,
                "Input",
                f"No valid ligands parsed from SDF library. Details: {lib_info}",
            )
            return [], lib_info, False
        return entries, lib_info, True
    def _vs_apply_results_state(self, results, receptor_obj, job_dir):
        self._vs_results = list(results or [])
        self._vs_receptor_object = str(receptor_obj)
        self._vs_job_dir = str(job_dir)
        self._populate_vs_table()
        self._show_vs_selected_hit_preview(zoom=True)
    def _vs_update_status_and_plot(self, best, n_ok, n_total):
        if hasattr(self, "lbl_vs_status"):
            self.lbl_vs_status.setText(vs_status_text(best=best, n_ok=n_ok, n_total=n_total))
        if int(n_ok) > 0:
            try:
                self._plot_virtual_screening_results()
            except Exception:
                pass
    def _vs_log_screening_run(self, receptor_obj, lib, lib_info, n_ok, n_fail, cancelled, job_dir, rec_info):
        self._append_debug_log(
            f"virtual_screen: receptor={receptor_obj}, library={lib}, loaded={lib_info.get('loaded')}, "
            f"ok={n_ok}, fail={n_fail}, cancelled={cancelled}, out={job_dir}, "
            f"rec_notes={rec_info.get('notes') if isinstance(rec_info, dict) else rec_info}"
        )
    def _vs_show_summary_dialog(self, receptor_obj, lib, lib_info, n_ok, n_fail, job_dir, best, cancelled):
        lines = build_virtual_screening_summary_lines(
            receptor_obj=receptor_obj,
            library_path=lib,
            loaded_count=lib_info.get("loaded", 0),
            skipped_count=lib_info.get("skipped", 0),
            n_ok=n_ok,
            n_fail=n_fail,
            output_dir=job_dir,
            best=best,
            cancelled=cancelled,
        )
        QtWidgets.QMessageBox.information(self, "Virtual Screening", "\n".join(lines))
    def _vs_post_rank_pipeline(self, results, _context, _summary):
        """VS hook: rank raw docking rows."""
        return {"results": list(rank_virtual_screening_results(results))}
    def _vs_post_summary_pipeline(self, results, _context, _summary):
        """VS hook: compute summary counters and best row."""
        return {"summary": dict(summarize_virtual_screening_results(results))}
    def _vs_post_apply_state_pipeline(self, results, context, _summary):
        """VS hook: persist ranked rows into UI state."""
        self._vs_apply_results_state(
            results=results,
            receptor_obj=str(context.get("receptor_obj", "")),
            job_dir=str(context.get("job_dir", "")),
        )
        return {}
    def _vs_post_log_pipeline(self, _results, context, summary):
        """VS hook: emit run metadata to debug log."""
        self._vs_log_screening_run(
            receptor_obj=str(context.get("receptor_obj", "")),
            lib=str(context.get("lib", "")),
            lib_info=dict(context.get("lib_info", {}) or {}),
            n_ok=int(summary.get("n_ok", 0) or 0),
            n_fail=int(summary.get("n_fail", 0) or 0),
            cancelled=bool(context.get("cancelled", False)),
            job_dir=str(context.get("job_dir", "")),
            rec_info=context.get("rec_info", None),
        )
        return {}
    def _vs_post_status_pipeline(self, _results, _context, summary):
        """VS hook: update status label and optional plot."""
        self._vs_update_status_and_plot(
            best=summary.get("best", None),
            n_ok=int(summary.get("n_ok", 0) or 0),
            n_total=int(summary.get("n_total", 0) or 0),
        )
        return {}
    def _vs_post_dialog_pipeline(self, _results, context, summary):
        """VS hook: show user-facing completion summary dialog."""
        self._vs_show_summary_dialog(
            receptor_obj=str(context.get("receptor_obj", "")),
            lib=str(context.get("lib", "")),
            lib_info=dict(context.get("lib_info", {}) or {}),
            n_ok=int(summary.get("n_ok", 0) or 0),
            n_fail=int(summary.get("n_fail", 0) or 0),
            job_dir=str(context.get("job_dir", "")),
            best=summary.get("best", None),
            cancelled=bool(context.get("cancelled", False)),
        )
        return {}
    def _on_run_virtual_screening(self):
        preflight = self._vs_validate_run_prereqs()
        if not preflight:
            return
        smina_bin = str(preflight.get("smina_bin", ""))
        receptor_obj = str(preflight.get("receptor_obj", ""))
        pocket = preflight.get("pocket", None)
        lib = str(preflight.get("lib", ""))
        vs_controls = self._vs_read_screening_controls(pocket=pocket)
        if not bool(vs_controls.get("ok", False)):
            QtWidgets.QMessageBox.warning(
                self,
                "Virtual Screening Grid",
                str(vs_controls.get("error", "The screening grid is invalid.")),
            )
            return
        max_ligs = int(vs_controls.get("max_ligs", 250) or 250)
        entries, lib_info, ok_lib = self._vs_load_library_entries_checked(lib=lib, max_ligands=int(max_ligs))
        if not bool(ok_lib):
            return
        path_payload = self._vs_prepare_job_paths_runtime(
            workspace_dir=self._dock_workspace_dir(),
            receptor_obj=receptor_obj,
            tag=None,
        )
        job_dir = str(path_payload.get("job_dir", ""))
        lig_dir = str(path_payload.get("lig_dir", ""))
        pose_dir = str(path_payload.get("pose_dir", ""))
        target_ph = float(vs_controls.get("target_ph", 7.4) or 7.4)
        receptor_payload = self._prepare_docking_receptor_input_checked(
            receptor_obj,
            job_dir,
            target_ph,
            flow_label="virtual_screening",
            warning_title="Error",
            fail_context="screening",
        )
        if bool(receptor_payload.get("cancelled", False)):
            return
        if not bool(receptor_payload.get("ok", False)):
            return
        receptor_input = str(receptor_payload.get("receptor_input", ""))
        rec_info = receptor_payload.get("rec_info", None)
        self._set_vs_grid_visibility(bool(getattr(self, "_vs_grid_visible", True)))
        results, cancelled = self._vs_run_screening_entries(
            entries=entries,
            smina_bin=smina_bin,
            receptor_input=receptor_input,
            center=tuple(vs_controls.get("center", (0.0, 0.0, 0.0))),
            size=tuple(vs_controls.get("size", (18.0, 18.0, 18.0))),
            exhaustiveness=int(vs_controls.get("exhaustiveness", 8) or 8),
            timeout_lig=int(vs_controls.get("timeout_lig", 300) or 300),
            lig_dir=lig_dir,
            pose_dir=pose_dir,
            target_ph=target_ph,
        )
        self._run_post_docking_pipeline(
            results=results,
            context={
                "receptor_obj": str(receptor_obj),
                "lib": str(lib),
                "lib_info": dict(lib_info or {}),
                "cancelled": bool(cancelled),
                "job_dir": str(job_dir),
                "rec_info": rec_info,
            },
            rank_fn=self._vs_post_rank_pipeline,
            summary_fn=self._vs_post_summary_pipeline,
            apply_state_fn=self._vs_post_apply_state_pipeline,
            log_fn=self._vs_post_log_pipeline,
            status_fn=self._vs_post_status_pipeline,
            dialog_fn=self._vs_post_dialog_pipeline,
        )
    def _vs_module_available(self, module_name):
        try:
            return importlib.util.find_spec(str(module_name)) is not None
        except Exception:
            return False
