    def _show_lead_optimization_dialog(self):
        try:
            if not hasattr(self, "_leadopt_dialog"):
                self._setup_lead_optimization_ui()
            self._update_lead_optimization_tool_status()
            self._on_leadopt_use_selected_vs_hit(silent=True)
            self._fit_dialog_to_screen(self._leadopt_dialog)
            self._leadopt_dialog.show()
            self._leadopt_dialog.raise_()
            self._leadopt_dialog.activateWindow()
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "Lead Optimization", f"Failed to open lead optimization dialog: {e}")
    def _update_lead_optimization_tool_status(self):
        if not hasattr(self, "lbl_lo_tools"):
            return
        sm = self._dock_tool_path("smina")
        ob = self._dock_tool_path("obabel")
        meeko_ok = self._vs_meeko_available()
        deepchem_ok = self._vs_module_available("deepchem")
        openff_ok = self._vs_module_available("openff.toolkit")
        pymbar_ok = self._vs_module_available("pymbar")
        msg = (
            f"Stack: RDKit={'OK' if HAS_RDKIT else 'MISSING'} | Meeko={'OK' if meeko_ok else 'MISSING'} | "
            f"smina={'OK' if sm else 'MISSING'} | obabel={'OK' if ob else 'MISSING'} | "
            f"DeepChem={'OK' if deepchem_ok else 'OPTIONAL/MISSING'} | "
            f"OpenFF={'OK' if openff_ok else 'OPTIONAL/MISSING'} | PyMBAR={'OK' if pymbar_ok else 'OPTIONAL/MISSING'}"
        )
        self.lbl_lo_tools.setText(msg)
    def _leadopt_hit_label(self, hit):
        if not isinstance(hit, dict):
            return "No seed selected"
        try:
            name = str(hit.get("name", ""))
            idx = int(hit.get("index", 0) or 0)
            aff = float(hit.get("affinity", np.nan))
            if np.isfinite(aff):
                return f"{name} (library #{idx}, affinity {aff:.3f} kcal/mol)"
            return f"{name} (library #{idx})"
        except Exception:
            return str(hit.get("name", "selected hit"))
    def _on_leadopt_use_selected_vs_hit(self, silent=False):
        hit, _row = self._selected_vs_hit()
        if not hit:
            if not silent:
                QtWidgets.QMessageBox.warning(self, "Lead Optimization", "Select a valid VS hit first.")
            return
        self._leadopt_seed_hit = dict(hit)
        if hasattr(self, "lbl_lo_seed"):
            self.lbl_lo_seed.setText(self._leadopt_hit_label(self._leadopt_seed_hit))
    def _vs_load_library_molecule_by_index(self, index_one_based):
        if (not HAS_RDKIT) or (not self._vs_library_sdf) or (not os.path.isfile(self._vs_library_sdf)):
            return None
        try:
            want = int(index_one_based)
        except Exception:
            return None
        if want <= 0:
            return None
        try:
            sup = Chem.SDMolSupplier(str(self._vs_library_sdf), removeHs=False, sanitize=False)
        except Exception:
            return None
        for i, m in enumerate(sup, start=1):
            if i == want:
                return m
        return None
    def _leadopt_canonicalize_mol(self, mol):
        if (not HAS_RDKIT) or mol is None:
            return None
        try:
            m = Chem.Mol(mol)
            Chem.SanitizeMol(m)
            m = self._select_best_ligand_fragment(m)
            Chem.SanitizeMol(m)
            smi = Chem.MolToSmiles(Chem.RemoveHs(m), isomericSmiles=True)
            c = Chem.MolFromSmiles(smi)
            if c is None:
                return None
            Chem.SanitizeMol(c)
            return c
        except Exception:
            return None
    def _leadopt_get_seed_molecule(self):
        hit = self._leadopt_seed_hit if isinstance(self._leadopt_seed_hit, dict) else None
        if not hit:
            return None, ""
        mol = hit.get("mol") if isinstance(hit, dict) else None
        if mol is None:
            mol = self._vs_load_library_molecule_by_index(hit.get("index", 0))
        cmol = self._leadopt_canonicalize_mol(mol)
        return cmol, str(hit.get("name", "Seed"))
    def _leadopt_get_pool_molecules_from_vs(self, max_hits=30):
        out = []
        lim = max(1, int(max_hits))
        for h in list(getattr(self, "_vs_results", []) or []):
            if len(out) >= lim:
                break
            try:
                if str(h.get("status", "")).lower() != "ok":
                    continue
            except Exception:
                continue
            m = h.get("mol")
            if m is None:
                m = self._vs_load_library_molecule_by_index(h.get("index", 0))
            cm = self._leadopt_canonicalize_mol(m)
            if cm is not None:
                out.append(cm)
        return out
    def _leadopt_generate_analogs(self, seed_mol, pool_mols, max_analogs=120, min_sim=0.35, max_sim=0.95):
        if (not HAS_RDKIT) or seed_mol is None:
            return []
        max_n = max(5, int(max_analogs))
        min_sim = float(np.clip(float(min_sim), 0.0, 1.0))
        max_sim = float(np.clip(float(max_sim), min_sim, 1.0))
        seed = self._leadopt_canonicalize_mol(seed_mol)
        if seed is None:
            return []
        seed_fp = AllChem.GetMorganFingerprintAsBitVect(seed, 2, 2048)
        seen = set()
        out = []
        def _push(mol, source, sim_low=None, sim_high=None, enforce_window=True):
            if mol is None:
                return
            cm = self._leadopt_canonicalize_mol(mol)
            if cm is None:
                return
            try:
                if int(cm.GetNumHeavyAtoms()) < 6:
                    return
            except Exception:
                return
            smi = Chem.MolToSmiles(cm, isomericSmiles=True)
            if (not smi) or (smi in seen):
                return
            fp = AllChem.GetMorganFingerprintAsBitVect(cm, 2, 2048)
            sim = float(DataStructs.TanimotoSimilarity(seed_fp, fp))
            lo = min_sim if sim_low is None else float(sim_low)
            hi = max_sim if sim_high is None else float(sim_high)
            if enforce_window and source != "seed":
                if sim < lo or sim > hi:
                    return
            seen.add(smi)
            out.append(
                {
                    "name": f"{source}_{len(out)+1:04d}",
                    "smiles": smi,
                    "sim_seed": sim,
                    "source": source,
                    "mol": cm,
                }
            )
        _push(seed, "seed")
        # Stage A: directly use top VS pool under user similarity window.
        for pm in list(pool_mols or []):
            if len(out) >= max_n:
                break
            _push(pm, "pool")
        # Stage B: BRICS recombination from seed + pool fragments.
        frag_set = set()
        frag_mols = [seed] + list(pool_mols or [])
        for m in frag_mols:
            if m is None:
                continue
            try:
                for frag in BRICS.BRICSDecompose(Chem.RemoveHs(m), minFragmentSize=2):
                    if frag:
                        frag_set.add(str(frag))
            except Exception:
                continue
        if frag_set and len(out) < max_n:
            frags = sorted(frag_set)
            frag_build = []
            for fsmi in frags:
                try:
                    fm = Chem.MolFromSmiles(str(fsmi))
                    if fm is not None:
                        frag_build.append(fm)
                except Exception:
                    continue
            attempts = 0
            if frag_build:
                try:
                    for bm in BRICS.BRICSBuild(frag_build, maxDepth=2, scrambleReagents=True):
                        attempts += 1
                        if attempts > 12000:
                            break
                        _push(bm, "brics")
                        if len(out) >= max_n:
                            break
                except Exception:
                    pass
        # Stage C (fallback): reaction-based local decoration to avoid seed-only collapse.
        if len(out) < min(max_n, 12):
            relaxed_lo = float(max(0.15, min(min_sim, 0.35) - 0.10))
            relaxed_hi = 1.00
            rxn_smarts = [
                ("aryl_f", "[cH:1]>>[c:1]F"),
                ("aryl_cl", "[cH:1]>>[c:1]Cl"),
                ("aryl_br", "[cH:1]>>[c:1]Br"),
                ("aryl_me", "[cH:1]>>[c:1]C"),
                ("aryl_ome", "[cH:1]>>[c:1]OC"),
                ("aryl_nh2", "[cH:1]>>[c:1]N"),
                ("aryl_cf3", "[cH:1]>>[c:1]C(F)(F)F"),
            ]
            rxn_lib = []
            for tag, sm in rxn_smarts:
                try:
                    rxn = AllChem.ReactionFromSmarts(sm)
                    if rxn is not None:
                        rxn_lib.append((tag, rxn))
                except Exception:
                    continue
            src = [seed]
            for pm in list(pool_mols or []):
                if len(src) >= 8:
                    break
                cm = self._leadopt_canonicalize_mol(pm)
                if cm is not None:
                    src.append(cm)
            attempts = 0
            for bm in src:
                if len(out) >= max_n:
                    break
                try:
                    reactant = Chem.RemoveHs(Chem.Mol(bm))
                    Chem.SanitizeMol(reactant)
                except Exception:
                    continue
                for tag, rxn in rxn_lib:
                    if len(out) >= max_n:
                        break
                    try:
                        products = rxn.RunReactants((reactant,))
                    except Exception:
                        continue
                    for prod in list(products or []):
                        attempts += 1
                        if attempts > 16000:
                            break
                        if not prod:
                            continue
                        pmol = prod[0]
                        try:
                            Chem.SanitizeMol(pmol)
                        except Exception:
                            continue
                        _push(pmol, f"rxn_{tag}", sim_low=relaxed_lo, sim_high=relaxed_hi)
                        if len(out) >= max_n:
                            break
                    if attempts > 16000:
                        break
        # Stage D (fallback): simple atom substitutions when chemistry is not aromatic/BRICS-friendly.
        if len(out) < min(max_n, 8):
            rdlog_muted = False
            try:
                if RDLOGGER is not None:
                    try:
                        RDLOGGER.DisableLog("rdApp.error")
                        rdlog_muted = True
                    except Exception:
                        rdlog_muted = False
                base = Chem.RemoveHs(Chem.Mol(seed))
                Chem.SanitizeMol(base)
                attempts = 0
                for ai in range(int(base.GetNumAtoms())):
                    if len(out) >= max_n:
                        break
                    a0 = base.GetAtomWithIdx(int(ai))
                    z0 = int(a0.GetAtomicNum())
                    if int(a0.GetDegree()) > 3:
                        continue
                    if z0 == 6:
                        repl = (7, 8, 9, 17)
                    elif z0 == 7:
                        repl = (6, 8, 16)
                    elif z0 == 8:
                        repl = (6, 7, 16)
                    else:
                        continue
                    for z1 in repl:
                        if int(z1) == int(z0):
                            continue
                        attempts += 1
                        if attempts > 400:
                            break
                        try:
                            rw = Chem.RWMol(base)
                            rw.GetAtomWithIdx(int(ai)).SetAtomicNum(int(z1))
                            m2 = rw.GetMol()
                            Chem.SanitizeMol(m2)
                        except Exception:
                            continue
                        _push(m2, "mut_atom", sim_low=0.0, sim_high=1.0, enforce_window=False)
                        if len(out) >= max_n:
                            break
                    if attempts > 400:
                        break
            except Exception:
                pass
            finally:
                if rdlog_muted and RDLOGGER is not None:
                    try:
                        RDLOGGER.EnableLog("rdApp.error")
                    except Exception:
                        pass
        # Stage E (last resort): allow pool compounds regardless of similarity,
        # so workflow does not collapse to a single unchanged seed.
        if len(out) < min(max_n, 10):
            for pm in list(pool_mols or []):
                if len(out) >= max_n:
                    break
                _push(pm, "pool_any", sim_low=0.0, sim_high=1.0, enforce_window=False)
        return out[:max_n]
    def _leadopt_get_pains_catalog(self):
        cached = getattr(self, "_leadopt_filter_catalog", None)
        if cached is False:
            return None
        if cached is not None:
            return cached
        if (FilterCatalog is None) or (FilterCatalogParams is None):
            self._leadopt_filter_catalog = False
            return None
        try:
            params = FilterCatalogParams()
            for cat in (
                FilterCatalogParams.FilterCatalogs.PAINS_A,
                FilterCatalogParams.FilterCatalogs.PAINS_B,
                FilterCatalogParams.FilterCatalogs.PAINS_C,
            ):
                params.AddCatalog(cat)
            self._leadopt_filter_catalog = FilterCatalog(params)
            return self._leadopt_filter_catalog
        except Exception:
            self._leadopt_filter_catalog = False
            return None
    def _leadopt_compute_props(self, mol):
        props = {
            "mw": np.nan,
            "logp": np.nan,
            "hba": np.nan,
            "hbd": np.nan,
            "tpsa": np.nan,
            "rotb": np.nan,
            "qed": np.nan,
            "pains": False,
        }
        if (not HAS_RDKIT) or mol is None:
            return props
        try:
            props["mw"] = float(Descriptors.MolWt(mol))
            props["logp"] = float(Crippen.MolLogP(mol))
            props["hba"] = int(Lipinski.NumHAcceptors(mol))
            props["hbd"] = int(Lipinski.NumHDonors(mol))
            props["tpsa"] = float(rdMolDescriptors.CalcTPSA(mol))
            props["rotb"] = int(rdMolDescriptors.CalcNumRotatableBonds(mol))
            props["qed"] = float(QED.qed(mol))
            cat = self._leadopt_get_pains_catalog()
            if cat is not None:
                props["pains"] = bool(cat.HasMatch(mol))
        except Exception:
            pass
        return props
    def _leadopt_admet_score(self, props):
        return float(leadopt_admet_score(props))
    def _leadopt_get_filter_limits(self):
        try:
            mw_max = float(self.spin_lo_mw_max.value()) if hasattr(self, "spin_lo_mw_max") else 550.0
            logp_max = float(self.spin_lo_logp_max.value()) if hasattr(self, "spin_lo_logp_max") else 5.5
            hba_max = int(self.spin_lo_hba_max.value()) if hasattr(self, "spin_lo_hba_max") else 12
            hbd_max = int(self.spin_lo_hbd_max.value()) if hasattr(self, "spin_lo_hbd_max") else 7
            tpsa_max = float(self.spin_lo_tpsa_max.value()) if hasattr(self, "spin_lo_tpsa_max") else 160.0
            rot_max = int(self.spin_lo_rot_max.value()) if hasattr(self, "spin_lo_rot_max") else 12
            block_pains = bool(self.cb_lo_block_pains.isChecked()) if hasattr(self, "cb_lo_block_pains") else True
        except Exception:
            mw_max, logp_max, hba_max, hbd_max, tpsa_max, rot_max, block_pains = 550.0, 5.5, 12, 7, 160.0, 12, True
        return {
            "mw_max": float(mw_max),
            "logp_max": float(logp_max),
            "hba_max": int(hba_max),
            "hbd_max": int(hbd_max),
            "tpsa_max": float(tpsa_max),
            "rot_max": int(rot_max),
            "block_pains": bool(block_pains),
        }
    def _leadopt_relax_filter_limits(self, base_limits, level=1):
        return dict(leadopt_relax_filter_limits(base_limits, level=level))
    def _leadopt_filter_fail_reason(self, props, limits=None):
        lim = dict(limits or self._leadopt_get_filter_limits())
        return str(leadopt_filter_fail_reason(props, lim))
    def _leadopt_pass_filters(self, props, limits=None):
        lim = dict(limits or self._leadopt_get_filter_limits())
        return bool(leadopt_pass_filters(props, lim))
    def _leadopt_mpo_score(self, affinity_kcal, admet_score, qed_score, sim_seed):
        try:
            wd = float(self.spin_lo_w_dock.value()) if hasattr(self, "spin_lo_w_dock") else 0.55
            wa = float(self.spin_lo_w_admet.value()) if hasattr(self, "spin_lo_w_admet") else 0.25
            wq = float(self.spin_lo_w_qed.value()) if hasattr(self, "spin_lo_w_qed") else 0.15
            ws = float(self.spin_lo_w_sim.value()) if hasattr(self, "spin_lo_w_sim") else 0.05
        except Exception:
            wd, wa, wq, ws = 0.55, 0.25, 0.15, 0.05
        return float(
            leadopt_mpo_score(
                affinity_kcal,
                admet_score,
                qed_score,
                sim_seed,
                weights=(wd, wa, wq, ws),
            )
        )
