    def _leadopt_filter_and_rescue_candidates_runtime(self, candidate_rows, base_limits):
        def _fp_morgan2_2048(mol_obj):
            if not HAS_RDKIT:
                return None
            if mol_obj is None:
                return None
            m1 = Chem.RemoveHs(Chem.Mol(mol_obj))
            return AllChem.GetMorganFingerprintAsBitVect(m1, 2, 2048)
        return dict(
            leadopt_filter_and_rescue_candidates(
                candidate_rows=candidate_rows,
                base_limits=base_limits,
                filter_fail_reason_fn=self._leadopt_filter_fail_reason,
                relax_limits_fn=self._leadopt_relax_filter_limits,
                relax_levels=(1, 2, 3),
                has_rdkit=bool(HAS_RDKIT),
                fingerprint_fn=_fp_morgan2_2048,
                similarity_fn=lambda fp_a, fp_b: float(DataStructs.TanimotoSimilarity(fp_a, fp_b)),
            )
        )
