            cleanup_known_objects = list(cleanup_inventory.get("object_names", []) or [])
            cleanup_plan = abfe_build_local_md_cleanup_plan(
                live_view_object=str(live_view_obj or ""),
                known_objects=list(cleanup_known_objects or []),
                context_object=str(abfe_context_obj or ""),
                source_object=str(abfe_source_obj or ""),
                state_index=int(state_idx),
            )
            if bool(cleanup_plan.get("should_delete_live_view", False)):
                try:
                    cmd.delete(str(cleanup_plan.get("live_view_object", "")))
                except Exception:
                    pass
            if bool(cleanup_plan.get("should_build_context_fallback", False)):
                try:
                    abfe_context_obj = self._build_abfe_context_protein(
                        str(cleanup_plan.get("context_source_object", abfe_source_obj)),
                        state_idx=int(cleanup_plan.get("context_state_index", state_idx)),
                    )
                except Exception:
                    abfe_context_obj = None
            keep_scene_requested = bool(self._abfe_keep_scene_visible()) if final_view_obj else False
