    def _show_pka_dialog(self):
        """pKa & Protonation window (protonation is decided before charges/parameters)."""
        try:
            try:
                from .pka_dialog import PkaDialog
            except ImportError:
                from leonardo.pka_dialog import PkaDialog
            dlg = getattr(self, "_pka_dialog", None)
            if dlg is None:
                dlg = PkaDialog(
                    self,
                    submit_task=lambda fn, ok, err, fin: self._submit_background_task(
                        fn, on_success=ok, on_error=err, on_finished=fin, task_name="pKa calculation"),
                    load_selection=self._pka_selection_molecule,
                    current_docking_ligand=lambda: str(getattr(self, "_docking_ligand_file", "") or ""),
                    use_for_docking=lambda mol, info: self._pka_use_state(mol, info, target="docking"),
                    use_for_parametrization=lambda mol, info: self._pka_use_state(mol, info, target="parametrization"),
                    cache_dir=self._pka_cache_dir(),
                    default_ph=float(self._current_small_molecule_target_ph()),
                    default_method=self._pka_method(),
                    set_default_method=self._pka_set_default_method,
                    backend_options=self._pka_backend_options,
                    default_level=dict(getattr(self, "_pka_default_level", None) or {}),
                )
                self._pka_dialog = dlg
            self._fit_dialog_to_screen(dlg, preferred_w=1060, preferred_h=860, min_w=900, min_h=700)
            dlg.show()
            dlg.raise_()
            dlg.activateWindow()
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "pKa & Protonation", f"Failed to open the pKa window: {e}")
    def _pka_set_default_method(self, method, level=None):
        self._pka_default_method = str(method or "empirical")
        self._pka_default_level = dict(level or {})
        shown = ", ".join(f"{k}={v}" for k, v in self._pka_default_level.items())
        self._append_debug_log(f"Automatic protonation method set to: {self._pka_default_method}"
                               + (f" ({shown})" if shown else ""))
    def _pka_selection_molecule(self, selection="sele"):
        """Small molecule from a PyMOL selection ('sele' by default) with bond orders. In order: the bond
        orders PyMOL already holds (a molecule built in the ligand editor or read from SDF/MOL/MOL2), the PDB
        chemical component of the residue, Open Babel, RDKit's bond perception from the 3D geometry."""
        if not HAS_RDKIT:
            raise RuntimeError("RDKit is required.")
        sel = str(selection or "sele")
        try:
            n_atoms = int(cmd.count_atoms(f"({sel}) and not hydro"))
        except Exception:
            n_atoms = 0
        if n_atoms <= 0:
            raise RuntimeError("Select the ligand/cofactor in PyMOL first (it must be in the selection 'sele').")
        try:
            objects = [o for o in cmd.get_object_list(f"({sel})") if int(cmd.count_atoms(f"({sel}) and %{o}")) > 0]
        except Exception:
            objects = []
        if len(objects) > 1:
            raise RuntimeError("The selection covers several objects (" + ", ".join(objects[:4])
                               + "); select the atoms of one molecule.")
        if n_atoms > 200:
            raise RuntimeError(f"The selection has {n_atoms} heavy atoms; select a single small molecule.")
        resns = set()
        cmd.iterate(f"({sel}) and not hydro", "resns.add(resn)", space={"resns": resns})
        resn = sorted(resns)[0] if len(resns) == 1 else ""
        mol, how, problems = None, "", []

        # 1. bond orders PyMOL already holds from the file (SDF/MOL/MOL2: explicit double/triple bonds). For a
        #    PDB PyMOL guesses orders itself: it marks rings, and sometimes amidines, aromatic (order 4); an
        #    aromatic bond outside a ring is such a guess, and those bonds are not used
        try:
            model = cmd.get_model(f"({sel})")
            if any(int(b.order) in (2, 3) for b in model.bond):
                cand = Chem.MolFromMolBlock(cmd.get_str("mol", f"({sel})"), removeHs=False, sanitize=True)
                guessed = cand is None or any(b.GetIsAromatic() and not b.IsInRing() for b in cand.GetBonds())
                if not guessed and not any(a.GetNumRadicalElectrons() for a in cand.GetAtoms()):
                    mol, how = Chem.RemoveHs(cand), "bond orders from PyMOL"
        except Exception as exc:
            problems.append(f"PyMOL bonds: {exc}")
        pdb_heavy = cmd.get_pdbstr(f"({sel}) and not hydro")
        # 2. the PDB chemical component of the residue (crystal ligands; generic names have none)
        if mol is None and resn and resn.upper() not in ("UNK", "UNL", "LIG", "MOL", "DRG", "INH", "LG1", "UNX"):
            template_smiles = self._openmm_component_smiles_hint({"resn": resn})
            if template_smiles:
                try:
                    crystal = Chem.MolFromPDBBlock(pdb_heavy, removeHs=True, sanitize=False)
                    template = Chem.RemoveHs(Chem.MolFromSmiles(template_smiles))
                    mol = AllChem.AssignBondOrdersFromTemplate(template, crystal)
                    how = f"PDB component {resn}"
                except Exception as exc:
                    problems.append(f"template {resn}: {exc}")
        # 3. Open Babel on the full selection (hydrogens help the perception)
        if mol is None:
            obabel = self._dock_tool_path("obabel")
            if obabel:
                import tempfile
                with tempfile.TemporaryDirectory() as td:
                    pin, pout = os.path.join(td, "sel.pdb"), os.path.join(td, "sel.sdf")
                    with open(pin, "w", encoding="utf-8") as fh:
                        fh.write(cmd.get_pdbstr(f"({sel})"))
                    run = subprocess.run([obabel, pin, "-O", pout], capture_output=True, text=True, timeout=120,
                                         check=False)
                    if os.path.isfile(pout):
                        mol = next((m for m in Chem.SDMolSupplier(pout, removeHs=True) if m is not None), None)
                    if mol is None:
                        problems.append("Open Babel: " + (str(run.stderr or "").strip().splitlines() or ["no output"])[-1])
                    else:
                        how = "bond orders perceived by Open Babel"
            else:
                problems.append("Open Babel: not found")
        # 4. RDKit bond perception from the coordinates (needs the hydrogens)
        if mol is None:
            try:
                from rdkit.Chem import rdDetermineBonds
                xyz = Chem.MolFromPDBBlock(cmd.get_pdbstr(f"({sel})"), removeHs=False, sanitize=False,
                                           proximityBonding=False)
                rw = Chem.RWMol(xyz)
                rdDetermineBonds.DetermineBonds(rw, charge=0)
                mol, how = Chem.RemoveHs(rw.GetMol()), "bond orders perceived by RDKit"
            except Exception as exc:
                problems.append(f"RDKit: {exc}")
        if mol is None:
            raise RuntimeError("Could not assign bond orders to the selection ("
                               + "; ".join(problems[-3:] or ["no method applied"])
                               + "). Load the molecule from an SDF/MOL2 file, or type its SMILES.")
        label = f"PyMOL selection ({resn or 'mixed residues'}, {n_atoms} heavy atoms; {how})"
        return mol, label
    def _pka_use_state(self, mol, info, target="docking"):
        """Hand a protonation state from the pKa window to docking or parametrization. The state is
        locked: docking/parametrization keep its hydrogens instead of re-protonating."""
        try:
            from .pka_dialog import write_state_sdf
        except ImportError:
            from leonardo.pka_dialog import write_state_sdf
        lig_dir = os.path.join(self._dock_workspace_dir(), "ligands")
        os.makedirs(lig_dir, exist_ok=True)
        tag = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        path = os.path.join(lig_dir, f"pka_state_{tag}_pH{float(info.get('ph', 7.4)):.2f}.sdf")
        write_state_sdf(mol, info, path)
        label = f"pKa module: {info.get('method')}, pH {float(info.get('ph', 7.4)):.2f}, charge {int(info.get('charge', 0)):+d}"
        self._set_docking_ligand_file(path, source_label=label)
        self._pka_locked_ligand_file = str(path)
        try:
            if hasattr(self, "spin_docking_ph"):
                self.spin_docking_ph.setValue(float(info.get("ph", 7.4)))
            if hasattr(self, "spin_net_charge"):
                self.spin_net_charge.setValue(int(info.get("charge", 0)))
        except Exception:
            pass
        self._append_debug_log(f"pKa state sent to {target}: {path} ({label}; population "
                               f"{100 * float(info.get('population', float('nan'))):.0f}%)")
        if target == "parametrization":
            return (f"State set as the ligand source (net charge {int(info.get('charge', 0)):+d}). "
                    "Now run 'Build Charged MOL2 + Amber FF' to assign charges and parameters.")
        return f"State set as the docking ligand (net charge {int(info.get('charge', 0)):+d}); it will not be re-protonated."
    def _pka_ligand_is_locked(self, path):
        """True when ``path`` is a state chosen in the pKa window (keep its hydrogens)."""
        locked = str(getattr(self, "_pka_locked_ligand_file", "") or "")
        return bool(locked) and os.path.abspath(str(path or "")) == os.path.abspath(locked)
    def _pka_locked_state_note(self, path, current_ph):
        """(note, warning) for a ligand locked from the pKa window, or (None, None)."""
        if not self._pka_ligand_is_locked(path) or not HAS_RDKIT:
            return None, None
        try:
            m = next((x for x in Chem.SDMolSupplier(str(path), removeHs=False) if x is not None), None)
            method = m.GetProp("LEONARDO_PROTONATION_METHOD") if m is not None and m.HasProp("LEONARDO_PROTONATION_METHOD") else "?"
            ph = float(m.GetProp("LEONARDO_PROTONATION_PH")) if m is not None and m.HasProp("LEONARDO_PROTONATION_PH") else None
        except Exception:
            method, ph = "?", None
        note = f"protonation_locked:pka_window({method}, pH {ph:.2f})" if ph is not None else "protonation_locked:pka_window"
        warn = None
        if ph is not None and abs(float(current_ph) - ph) > 0.5:
            warn = (f"The ligand's protonation state was chosen at pH {ph:.2f} in the pKa window, but the current pH "
                    f"is {float(current_ph):.2f}; the locked state is used. Recompute it in the pKa window if needed.")
        return note, warn
    def _pka_cache_dir(self):
        try:
            return os.path.join(self._dock_workspace_dir(), "pka_cache")
        except Exception:
            return None
    def _repair_and_protonate(self, mol, target_ph=7.4):
        """
        pH-dependent protonation of a small molecule (heavy-atom coordinates kept).

        Delegates to leonardo.pka_runtime (empirical class pKa by default, PM7 or Psi4 when
        chosen in the pKa window); the older Dimorphite-DL path is only a fallback when the pKa
        module cannot handle the molecule. The result (method, site pKa, population,
        warnings) is kept in self._last_protonation_info.
        """
        if not HAS_RDKIT:
            return None
        try:
            method = self._pka_method()
            out, info = pka_protonate_molecule(mol, float(target_ph), method=method,
                                               cache_dir=self._pka_cache_dir(),
                                               backend_options=self._pka_backend_options(method))
            self._last_protonation_info = dict(info)
            for warn in list(info.get("warnings", []) or [])[:4]:
                self._append_debug_log(f"Protonation ({info.get('method')}, pH {float(target_ph):.2f}): {warn}")
            return out
        except Exception as exc:
            try:
                self._append_debug_log(f"pKa module could not protonate the ligand ({exc}); using Dimorphite-DL fallback.")
            except Exception:
                pass
            self._last_protonation_info = {"method": "dimorphite_fallback", "ph": float(target_ph), "error": str(exc)}
            return self._repair_and_protonate_dimorphite(mol, target_ph=target_ph)
    def _repair_and_protonate_dimorphite(self, mol, target_ph=7.4):
        """
        Fallback: repair common ligand ionization states with Dimorphite-DL at target pH.
        """
        if not HAS_RDKIT:
            return None
        print(f"Chemistry Repair: Starting (target pH={target_ph:.2f})...")
        try:
            base = Chem.RemoveHs(Chem.Mol(mol))
        except Exception:
            base = Chem.Mol(mol)
        try:
            Chem.SanitizeMol(base)
        except Exception:
            pass
        # Start from input topology and optionally transfer pH-aware bond orders/charges.
        rw_mol = Chem.RWMol(base)
        used_dimorphite = False
        # Dimorphite path: get pH-correct protonation template and transfer formal charges.
        try:
            ref_smi = self._try_dimorphite_protonate_smiles(Chem.MolToSmiles(Chem.RemoveHs(base)), target_ph)
            if ref_smi:
                ref = Chem.MolFromSmiles(ref_smi)
                if ref:
                    ref_noh = Chem.RemoveHs(ref)
                    # Transfer bond orders from protonation template onto the input topology.
                    try:
                        bo = AllChem.AssignBondOrdersFromTemplate(ref_noh, base)
                        rw_mol = Chem.RWMol(bo)
                    except Exception:
                        rw_mol = Chem.RWMol(base)
                    # Transfer formal charges by graph mapping.
                    curr_noh = Chem.RemoveHs(Chem.Mol(rw_mol))
                    match = curr_noh.GetSubstructMatch(ref_noh)
                    if match and len(match) == ref_noh.GetNumAtoms():
                        for ref_idx, curr_idx in enumerate(match):
                            fc = int(ref_noh.GetAtomWithIdx(ref_idx).GetFormalCharge())
                            rw_mol.GetAtomWithIdx(curr_idx).SetFormalCharge(fc)
                        used_dimorphite = True
        except Exception as e:
            print(f"Template protonation transfer warning: {e}")
        # Carboxylic groups: at physiological pH they are typically deprotonated.
        carboxyl = Chem.MolFromSmarts("[CX3](=O)[OX1-,OX2H1]")
        for c_idx, _od_idx, os_idx in rw_mol.GetSubstructMatches(carboxyl):
            if target_ph >= 4.5:
                o_single = rw_mol.GetAtomWithIdx(os_idx)
                o_single.SetFormalCharge(-1)
                o_single.SetNumExplicitHs(0)
                o_single.SetNoImplicit(True)
        # When Dimorphite-DL is unavailable, do not broadly infer amine
        # protonation.  A neutral primary/secondary/tertiary amine may be
        # protonated at physiological pH, but without pKa-aware chemistry that
        # inference creates false salt-bridge/cation-pi positives.  We only keep
        # the very specific amidinium/guanidinium rescue below.
        if target_ph <= 9.5 and not used_dimorphite:
            print("Chemistry Repair: Dimorphite-DL not used; skipping generic amine charge inference.")
            # Keep amidinium/guanidinium-like motifs cationic, but assign only one +1
            # per motif to avoid overcharging every nitrogen atom.
            # amidine (benzamidine) or guanidine: N-C(=N)-C/N; amidoximes (=N-O) are not basic.
            # The old pattern needed three N on the carbon, so it only matched guanidines.
            amidinium = Chem.MolFromSmarts("[NX3;!$(N-C=O)][CX3](=[NX2;!$(N-[OX2])])[#6,#7]")
            if amidinium:
                for match in rw_mol.GetSubstructMatches(amidinium):
                    n_idxs = [idx for idx in match if rw_mol.GetAtomWithIdx(idx).GetAtomicNum() == 7]
                    # Skip motifs that are already explicitly charged.
                    if any(rw_mol.GetAtomWithIdx(idx).GetFormalCharge() > 0 for idx in n_idxs):
                        continue
                    # protonate the imine N: -C(=N)- -> -C(=[NH2+])-  (one +1 per motif)
                    a = rw_mol.GetAtomWithIdx(match[2])
                    n_h = int(a.GetTotalNumHs())
                    a.SetFormalCharge(1)
                    a.SetNumExplicitHs(n_h + 1)
                    a.SetNoImplicit(True)
        try:
            Chem.SanitizeMol(rw_mol)
            final_mol = Chem.AddHs(rw_mol, addCoords=True)
            return final_mol
        except Exception as e:
            print(f"Repair Failed during Sanitize/AddHs: {e}")
            return None
    def _ligand_chem_from_input(self, pdb_block, resn=""):
        """(RDKit mol, source) for typing a ligand from its input atoms: bond orders on the heavy atoms
        and, when the input has hydrogens, those hydrogens (formal charges follow from them: an N
        with four bonds is +1, a lone O on a single bond is -1). (None, reason) without bond orders."""
        heavy, source = self._ligand_bond_order_mol(pdb_block, resn)
        if heavy is None:
            return None, f"none ({source}); topology rules used"
        try:
            raw = Chem.MolFromPDBBlock(str(pdb_block or ""), removeHs=False, sanitize=False)
            h_coords = []
            if raw is not None and raw.GetNumConformers():
                rconf = raw.GetConformer()
                h_coords = [rconf.GetAtomPosition(a.GetIdx()) for a in raw.GetAtoms() if a.GetAtomicNum() == 1]
            if not h_coords:
                return heavy, f"{source}, implicit hydrogens"
            rw = Chem.RWMol(heavy)
            Chem.Kekulize(rw, clearAromaticFlags=True)
            conf = rw.GetConformer()
            n_heavy = rw.GetNumAtoms()
            for p in h_coords:
                best, best_d = None, 1.35
                for i in range(n_heavy):
                    d = (conf.GetAtomPosition(i) - p).Length()
                    if d < best_d:
                        best, best_d = i, d
                if best is None:
                    continue
                hi = rw.AddAtom(Chem.Atom(1))
                rw.AddBond(best, hi, Chem.BondType.SINGLE)
                conf.SetAtomPosition(hi, p)
            for a in list(rw.GetAtoms())[:n_heavy]:
                a.SetNoImplicit(True)
                a.SetNumExplicitHs(0)
                a.SetFormalCharge(0)
                valence = sum(int(round(b.GetBondTypeAsDouble())) for b in a.GetBonds())
                if a.GetSymbol() == "N" and valence == 4:
                    a.SetFormalCharge(1)
                elif a.GetSymbol() == "O" and valence == 1:
                    a.SetFormalCharge(-1)
                elif a.GetSymbol() == "O" and valence == 3:
                    a.SetFormalCharge(1)
            out = rw.GetMol()
            Chem.SanitizeMol(out)
            return out, f"{source}, input hydrogens"
        except Exception as exc:
            return heavy, f"{source}, implicit hydrogens (input hydrogens not usable: {exc})"
    def _ligand_bond_order_mol(self, pdb_block, resn=""):
        """(heavy-atom RDKit mol with bond orders, source) for a ligand PDB block; (None, reason) on failure.
        CCD template of the residue first, then Leonardo's SMILES hint, then Open Babel on the geometry."""
        if not HAS_RDKIT:
            return None, "RDKit unavailable"
        cache = getattr(self, "_ligand_bond_order_cache", None)
        if not isinstance(cache, dict):
            cache = {}
            self._ligand_bond_order_cache = cache
        key = (str(resn or "").strip().upper(), str(pdb_block or ""))
        if key in cache:
            mol, source = cache[key]
            return (Chem.Mol(mol) if mol is not None else None), source
        mol, source = component_ligand_bond_orders_from_pdb(pdb_block, resn=resn)
        if mol is None and resn:
            try:
                hint = str(self._openmm_component_smiles_hint({"resn": resn}) or "")
            except Exception:
                hint = ""
            if hint:
                mol, source = component_ligand_bond_orders_from_pdb(pdb_block, resn="", smiles_hint=hint,
                                                                    fetch_ccd=False)
        cache[key] = (mol, source)
        return (Chem.Mol(mol) if mol is not None else None), source
    def _refine_ligand_geometry(self, target_ph=None, update_scene=False):
        """
        Orchestrates the repair and PyMOL update.
        """
        if not HAS_RDKIT:
            raise RuntimeError("RDKit is required for ligand chemistry repair.")
        print("Refining Ligand Geometry...")
        try:
            # 1. Get raw PDB block from PyMOL
            l_c, l_i, l_n = self.ligand_info
            sel = self._pymol_residue_selection(self.loaded_object, l_c, l_i, l_n, wrap=True)
            pdb_str = cmd.get_pdbstr(sel)
            
            if not pdb_str:
                 raise ValueError("Could not extract ligand PDB from PyMOL.")
                 
            # 2. Load into RDKit with bond orders (a PDB has none: read as all-single bonds an
            #    aromatic ring became a cyclohexane and got twice the hydrogens)
            mol, bo_source = self._ligand_bond_order_mol(pdb_str, l_n)
            if mol is None:
                 raise ValueError(f"Could not assign ligand bond orders: {bo_source}")
            self._ligand_bond_order_source = str(bo_source)
            self._append_debug_log(f"Ligand bond orders: {bo_source}.")

            # 3. RUN REPAIR
            use_ph = float(target_ph if target_ph is not None else getattr(self, "_target_ph", 7.4))
            target_mol = self._repair_and_protonate(mol, target_ph=use_ph)
            
            if not target_mol:
                 raise ValueError("Chemistry Repair returned None.")
            # Keep the repaired chemistry model for charge/group typing.
            self._ligand_refined_mol = target_mol
            print("Ligand chemistry model updated for interaction typing.")
            if update_scene:
                # Optional destructive update (disabled by default because some inputs lose residue identity).
                self._update_pymol_coords(target_mol)
        except Exception as e:
            print(f"Refinement Critically Failed: {e}")
            raise e # Propagate to caller for MessageBox
    def _update_pymol_coords(self, mol):
        """
        Push RDKit coordinates back to PyMOL with Topology Awareness.
        CRITICAL: We must ensure ALL atoms (especially new Hydrogens)
        have the correct Chain/Resi/Resn info, otherwise PyMOL loads them
        as 'UNL' and the plugin logic ignores them.
        """
        try:
             print("Pushing refined coordinates to PyMOL...")
             
             # 1. FORCE PDB INFO ON ALL ATOMS
             # New H atoms from AddHs have no PDB info.
             l_c, l_i, l_n = self.ligand_info
             
             for i, atom in enumerate(mol.GetAtoms()):
                  # Create or Update PDBResidueInfo
                  # RDKit names must be unique for PDB?
                  # Generate clean names if missing.
                  
                  # New H?
                  if atom.GetSymbol() == "H" and (not atom.GetPDBResidueInfo()):
                       atom_name = f"H{i:02d}" # H01, H02...
                  else:
                       # Keep existing name if possible, but strip spaces
                       info = atom.GetPDBResidueInfo()
                       atom_name = info.GetName().strip() if info else f"{atom.GetSymbol()}{i}"
                  
                  # Re-assign Info
                  # Chem.AtomPDBResidueInfo(atomName, serialNumber, altLoc, residueName, residueNumber, chainId, insertionCode, occupancy, tempFactor)
                  # Note: This is an object construction, tricky in python API sometimes.
                  # Easier: Use SetProp? No, MolToPDBBlock uses MonomerInfo.
                  
                  new_info = Chem.AtomPDBResidueInfo(
                       f"{atom_name:<4s}", # Padded name? RDKit handles padding usually?
                       serialNumber=i+1,
                       altLoc="", 
                       residueName=f"{l_n:<3s}", 
                       residueNumber=l_i, 
                       chainId=f"{l_c:1s}", 
                       insertionCode="", 
                       occupancy=1.0, 
                       tempFactor=0.0
                  )
                  atom.SetMonomerInfo(new_info)
             
             # 2. GENERATE COMPATIBLE PDB BLOCK
             pdb_block = Chem.MolToPDBBlock(mol)
             
             print(f"DEBUG PDB UPDATE:\n{pdb_block[:200]}...") # First few lines
             
             # 3. TOPOLOGY UPDATE IN PYMOL
             # Selection string for the TARGET ligand
             sel = self._pymol_residue_selection(self.loaded_object, l_c, l_i, l_n, wrap=True)
             
             # Check if selection exists
             count_before = cmd.count_atoms(sel)
             if count_before == 0:
                  print(f"WARNING: Ligand selection {sel} implies no atoms found to replace.")
             
             # Hard Remove
             cmd.remove(sel)
             
             # Load New
             cmd.read_pdbstr(pdb_block, self.loaded_object)
             
             # Log
             count_after = cmd.count_atoms(sel)
             print(f"PyMOL Update: Removed {count_before} -> Added {count_after} atoms.")
             
             # 4. USER FEEDBACK
             # Use a non-modal message if possible, or print to status
             # But user requested "corroboration".
             QtWidgets.QMessageBox.information(
                 self, "Refinement Complete", 
                 f"Ligand Topology Updated.\n"
                 f"Old Atoms: {count_before}\n"
                 f"New Atoms: {count_after}\n"
                 f"Hydrogens: {count_after - mol.GetNumHeavyAtoms()}"
             )
             
        except Exception as e:
             print(f"PyMOL Update Failed: {e}")
             import traceback
             traceback.print_exc()
             raise e
    def _map_rdkit_atoms_to_feature_indices(self, mol, ligand_atoms):
        """
        Map RDKit atom indices to ligand feature indices using element + coordinates.
        This avoids ambiguous atom-name mapping in docking outputs (e.g., many atoms
        named simply "N", "C", "O").
        """
        mapping = {}
        if not HAS_RDKIT or mol is None or not ligand_atoms:
            return mapping
        try:
            conf = mol.GetConformer()
        except Exception:
            return mapping
        buckets = defaultdict(list)
        for fi, a in enumerate(ligand_atoms):
            el = str(a.get("element", "")).strip().upper()
            if not el:
                continue
            try:
                c = np.array(a.get("coord"), dtype=float)
            except Exception:
                continue
            buckets[el].append((fi, c))
        used_feat = set()
        for atom in mol.GetAtoms():
            rd_idx = int(atom.GetIdx())
            el = str(atom.GetSymbol()).strip().upper()
            cand = buckets.get(el, [])
            if not cand:
                continue
            try:
                p = conf.GetAtomPosition(rd_idx)
                rc = np.array([float(p.x), float(p.y), float(p.z)], dtype=float)
            except Exception:
                continue
            best_fi = None
            best_d = 1e9
            for fi, fc in cand:
                if fi in used_feat:
                    continue
                d = float(np.linalg.norm(fc - rc))
                if d < best_d:
                    best_d = d
                    best_fi = fi
            tol = 0.45 if el == "H" else 1.20
            if best_fi is not None and best_d <= tol:
                mapping[rd_idx] = best_fi
                used_feat.add(best_fi)
        return mapping
    def _compute_ligand_charges(self, mol, rd_to_feat_idx=None):
        """
        Compute per-atom formal and partial charges from an RDKit ligand molecule.
        Returns keys by mapped ligand index first, with name fallback:
        {("idx", lig_idx): {...}, ("name", atom_name): {...}}
        """
        charges = {}
        if not HAS_RDKIT or mol is None:
            return charges
        rd_to_feat_idx = rd_to_feat_idx or {}
        try:
            work = Chem.Mol(mol)
            try:
                Chem.SanitizeMol(work)
            except Exception:
                pass
            # Seed with formal charges from the sanitized graph.
            for atom in work.GetAtoms():
                rec = {"formal": int(atom.GetFormalCharge()), "partial": 0.0}
                rd_idx = int(atom.GetIdx())
                if rd_idx in rd_to_feat_idx:
                    charges[("idx", int(rd_to_feat_idx[rd_idx]))] = dict(rec)
                info = atom.GetPDBResidueInfo()
                if info:
                    name = info.GetName().strip()
                    charges[("name", name)] = dict(rec)
            # Compute Gasteiger charges on an H-complete copy.
            calc = Chem.AddHs(Chem.Mol(work), addCoords=False)
            try:
                AllChem.ComputeGasteigerCharges(calc)
            except Exception:
                calc = work
            for atom in calc.GetAtoms():
                if atom.GetAtomicNum() == 1:
                    continue
                rec = {"formal": int(atom.GetFormalCharge()), "partial": 0.0}
                if atom.HasProp("_GasteigerCharge"):
                    try:
                        q = float(atom.GetDoubleProp("_GasteigerCharge"))
                        if np.isfinite(q):
                            rec["partial"] = q
                    except Exception:
                        pass
                rd_idx = int(atom.GetIdx())
                if rd_idx in rd_to_feat_idx:
                    charges[("idx", int(rd_to_feat_idx[rd_idx]))] = dict(rec)
                info = atom.GetPDBResidueInfo()
                if info:
                    name = info.GetName().strip()
                    charges[("name", name)] = dict(rec)
        except Exception as e:
            print(f"Charge Calc Error: {e}")
        return charges
    def _annotate_ligand_groups(self, mol, features, rd_to_feat_idx=None):
        """
        Identify likely ionic ligand groups (anion/cation) for interaction typing.
        """
        if not HAS_RDKIT or not features.get("ligand_atoms"):
            return
        rd_to_feat_idx = rd_to_feat_idx or {}
        lig_atoms = list(features["ligand_atoms"])
        feat_map = defaultdict(list)
        for fi, a in enumerate(lig_atoms):
            k = (str(a["chain"]), int(a["resi"]), str(a["name"]).strip().upper())
            feat_map[k].append(fi)
        try:
            conf = mol.GetConformer()
        except Exception:
            conf = None
        def _pick_from_name_key(key, rd_idx=None):
            idxs = feat_map.get(key, [])
            if not idxs:
                return None
            if len(idxs) == 1 or conf is None or rd_idx is None:
                return lig_atoms[idxs[0]]
            try:
                p = conf.GetAtomPosition(int(rd_idx))
                rc = np.array([float(p.x), float(p.y), float(p.z)], dtype=float)
                best_i = idxs[0]
                best_d = 1e9
                for fi in idxs:
                    fc = np.array(lig_atoms[fi].get("coord"), dtype=float)
                    d = float(np.linalg.norm(fc - rc))
                    if d < best_d:
                        best_d = d
                        best_i = fi
                return lig_atoms[best_i]
            except Exception:
                return lig_atoms[idxs[0]]
        def _flag(atom, is_anion=False, is_cation=False, group="", group_id="", group_members=None, group_center_members=None):
            target = None
            rd_idx = int(atom.GetIdx())
            fi = rd_to_feat_idx.get(rd_idx)
            if fi is not None and 0 <= int(fi) < len(lig_atoms):
                target = lig_atoms[int(fi)]
            if target is None:
                info = atom.GetPDBResidueInfo()
                if info:
                    key = (str(info.GetChainId()), int(info.GetResidueNumber()), str(info.GetName()).strip().upper())
                    target = _pick_from_name_key(key, rd_idx=rd_idx)
            if not target:
                return
            if is_anion:
                target["is_anion"] = True
            if is_cation:
                target["is_cation"] = True
            if group and not target.get("group_type"):
                target["group_type"] = group
            if group_id:
                target["ionic_group_id"] = str(group_id)
            if group_members and not target.get("ionic_group_members"):
                target["ionic_group_members"] = tuple(str(x) for x in group_members if str(x).strip())
            if group_center_members and not target.get("ionic_group_center_members"):
                target["ionic_group_center_members"] = tuple(
                    str(x) for x in group_center_members if str(x).strip()
                )
        # Conservatively flag only chemically explicit ionic atoms.
        # This avoids neutral carbonyls/amides being mislabeled as ionic.
        ionic_patterns = [
            # group, smarts, flagged atom indices, center indices, anion?, cation?
            ("Carboxylate", "[CX3](=[OX1,OX2])[O-]", [1, 2], [1, 2], True, False),
            ("Phosphate", "[PX4](=[OX1,OX2])([O-])[O-]", [2, 3], [2, 3], True, False),
            ("Sulfonate", "[SX4](=[OX1,OX2])(=[OX1,OX2])[O-]", [3], [3], True, False),
            ("Sulfate", "[SX4](=[OX1,OX2])(=[OX1,OX2])([O-])[O-]", [3, 4], [3, 4], True, False),
            ("Ammonium", "[NX4+]", [0], [0], False, True),
            ("Aromatic Cation", "[n+]", [0], [0], False, True),
            ("Iminium", "[NX2+]=[CX3]", [0], [0, 1], False, True),
            ("Amidinium", "[CX3](=[NX2+])[NX3,NX2]", [1, 2], [1, 2], False, True),
            ("Guanidinium", "[NX3][CX3](=[NX2+])[NX3]", [0, 2, 3], [0, 2, 3], False, True),
        ]
        for group, smarts, idxs, center_idxs, is_anion, is_cation in ionic_patterns:
            pat = Chem.MolFromSmarts(smarts)
            if not pat:
                continue
            for match_no, match in enumerate(mol.GetSubstructMatches(pat), start=1):
                member_names = []
                center_names = []
                for ridx in match:
                    info = mol.GetAtomWithIdx(int(ridx)).GetPDBResidueInfo()
                    if info:
                        member_names.append(str(info.GetName()).strip().upper())
                for cidx in center_idxs:
                    if cidx < 0 or cidx >= len(match):
                        continue
                    info = mol.GetAtomWithIdx(int(match[cidx])).GetPDBResidueInfo()
                    if info:
                        center_names.append(str(info.GetName()).strip().upper())
                group_id = f"{group}:{match_no}:{'-'.join(str(int(x)) for x in match)}"
                for midx in idxs:
                    if midx < 0 or midx >= len(match):
                        continue
                    _flag(
                        mol.GetAtomWithIdx(match[midx]),
                        is_anion=is_anion,
                        is_cation=is_cation,
                        group=group,
                        group_id=group_id,
                        group_members=member_names,
                        group_center_members=center_names,
                    )
        # Fallback: honor explicit formal charges in the source mol.
        for atom in mol.GetAtoms():
            fc = int(atom.GetFormalCharge())
            z = int(atom.GetAtomicNum())
            if fc < 0:
                # Restrict fallback anions to typical acidic heteroatoms.
                if z in (8, 16):
                    _flag(
                        atom,
                        is_anion=True,
                        group="FormalCharge",
                        group_id=f"FormalCharge:-:{int(atom.GetIdx())}",
                    )
            elif fc > 0:
                # Very conservative fallback: only phosphorus keeps formal-charge cation fallback.
                # Nitrogen cations must come from explicit ionic SMARTS matches above.
                if z == 15:
                    _flag(
                        atom,
                        is_cation=True,
                        group="FormalCharge",
                        group_id=f"FormalCharge:+:{int(atom.GetIdx())}",
                    )
    def _detect_ligand_rings_rdkit(self, features, mol=None, rd_to_feat_idx=None):
        """
        Prefer chemically perceived aromatic rings from RDKit (PLIP-like behavior).
        Falls back to [] when chemistry/mapping is unavailable.
        """
        if not HAS_RDKIT or mol is None:
            return []
        lig_atoms = list(features.get("ligand_atoms", []))
        if not lig_atoms:
            return []
        mapping = dict(rd_to_feat_idx or {})
        if not mapping:
            mapping = self._map_rdkit_atoms_to_feature_indices(mol, lig_atoms)
        if not mapping:
            return []
        try:
            ring_info = mol.GetRingInfo()
            atom_rings = list(ring_info.AtomRings()) if ring_info is not None else []
        except Exception:
            atom_rings = []
        if not atom_rings:
            return []
        try:
            lig_chain, lig_resi, lig_resn = self.ligand_info
        except Exception:
            lig_chain, lig_resi, lig_resn = "", 0, "LIG"
        rings = []
        seen = set()
        for rd_ring in atom_rings:
            if len(rd_ring) < 5 or len(rd_ring) > 7:
                continue
            try:
                if not all(bool(mol.GetAtomWithIdx(int(i)).GetIsAromatic()) for i in rd_ring):
                    continue
            except Exception:
                continue
            feat_idxs = []
            for rd_idx in rd_ring:
                fi = mapping.get(int(rd_idx))
                if fi is None:
                    continue
                fi = int(fi)
                if fi < 0 or fi >= len(lig_atoms):
                    continue
                if str(lig_atoms[fi].get("element", "")).upper() == "H":
                    continue
                feat_idxs.append(fi)
            feat_idxs = sorted(set(feat_idxs))
            if len(feat_idxs) < 5:
                continue
            key = tuple(feat_idxs)
            if key in seen:
                continue
            seen.add(key)
            ring_coords = [np.array(lig_atoms[i]["coord"], dtype=float) for i in feat_idxs]
            if len(ring_coords) < 3:
                continue
            normal = get_normal(ring_coords)
            cent = get_centroid(ring_coords)
            plane_d = [abs(float(np.dot(normal, p - cent))) for p in ring_coords]
            if plane_d and max(plane_d) > 0.35:
                continue
            radius = get_ring_radius(ring_coords, cent)
            rings.append(
                {
                    "resn": lig_resn,
                    "resi": lig_resi,
                    "chain": lig_chain,
                    "coords": ring_coords,
                    "centroid": cent,
                    "normal": normal,
                    "radius": radius,
                    "atom_indices": tuple(feat_idxs),
                    "source": "rdkit",
                }
            )
        return rings
    def _detect_ligand_rings(self, features):
        # Build adjacency for ligand atoms
        lig = features["ligand_atoms"]
        if not lig:
            return []
        # Map index for stability
        {id(a): i for i, a in enumerate(lig)}
        coords = [a["coord"] for a in lig]
        elements = [a["element"].upper() for a in lig]
        adj = {i: set() for i in range(len(lig))}
        for i in range(len(lig)):
            for j in range(i + 1, len(lig)):
                if distance(coords[i], coords[j]) <= self._bond_threshold(elements[i], elements[j]):
                    adj[i].add(j)
                    adj[j].add(i)
        # Find simple cycles of length 5 or 6 via DFS, canonicalize by sorted tuple
        cycles = set()
        target_lengths = {5, 6}
        def dfs(start, current, visited):
            if len(current) > 6:
                return
            u = current[-1]
            for v in adj[u]:
                if v == start and len(current) in target_lengths:
                    cyc = tuple(sorted(current))
                    cycles.add(cyc)
                if v in visited or v < start:  # simple ordering to reduce duplicates
                    continue
                dfs(start, current + [v], visited | {v})
        for s in range(len(lig)):
            dfs(s, [s], {s})
        rings = []
        lig_chain, lig_resi, lig_resn = self.ligand_info
        for cyc in cycles:
            ring_coords = [coords[i] for i in cyc]
            # planarity check
            normal = get_normal(ring_coords)
            centroid = get_centroid(ring_coords)
            # distance of each atom from plane
            plane_d = []
            for p in ring_coords:
                plane_d.append(abs(np.dot(normal, p - centroid)))
            if max(plane_d) > 0.2:  # Å
                continue
            # aromatic-like composition
            en = [elements[i] for i in cyc]
            aro_frac = sum(1 for e in en if e in ("C", "N")) / len(en)
            if aro_frac < 0.8:
                continue
            radius = get_ring_radius(ring_coords, centroid)
            rings.append(
                {
                    "resn": lig_resn,
                    "resi": lig_resi,
                    "chain": lig_chain,
                    "coords": ring_coords,
                    "centroid": centroid,
                    "normal": normal,
                    "radius": radius,
                    "atom_indices": tuple(int(i) for i in cyc),
                    "source": "geometry",
                }
            )
        return rings
    def _calculate_all_interactions(self):
        """Main calculation function that orchestrates finding all interaction types."""
        if not self.structure or not self.ligand_info:
            return []
        update_coords = getattr(self, "_traj_mode", False)
        features = self._precompute_atom_features(update_coords=update_coords)
        lig_chain, lig_resi, lig_resn = self.ligand_info
        if not update_coords:
            try:
                self._append_debug_log(
                    f"Feature counts: protein_atoms={len(features.get('protein_atoms', []))}, "
                    f"ligand_atoms={len(features.get('ligand_atoms', []))}, "
                    f"protein_rings={len(features.get('protein_rings', []))}, "
                    f"ligand_rings={len(features.get('ligand_rings', []))}."
                )
            except Exception:
                pass
        interactions = []
        seen = set()
        def _coord_key(value):
            if value is None:
                return ()
            try:
                arr = np.array(value, dtype=float)
                if arr.size < 3:
                    return ()
                return tuple(float(x) for x in np.round(arr[:3], 2))
            except Exception:
                return ()

        def _atom_key(atom):
            return (
                str(atom.get("chain", "") or ""),
                str(atom.get("resi", "") or ""),
                str(atom.get("resn", "") or ""),
                str(atom.get("name", "") or ""),
                _coord_key(atom.get("coord")),
            )

        def _group_anchor(group):
            atoms = list(group.get("atoms", []) or [])
            rep = str(group.get("representative_atom", "") or "")
            for atom in atoms:
                if str(atom.get("name", "") or "") == rep:
                    return dict(atom)
            if atoms:
                return dict(atoms[0])
            return {
                "resn": str(group.get("resn", "") or ""),
                "resi": str(group.get("resi", "") or ""),
                "chain": str(group.get("chain", "") or ""),
                "name": rep,
            }

        def _store_best(mapping, key, candidate, score):
            current = mapping.get(key)
            if current is None or tuple(score) < tuple(current["score"]):
                mapping[key] = {"score": tuple(score), "candidate": dict(candidate)}

        def add_interaction(itype, prot, lig, dist, details=None, extra=None, prot_coord=None, lig_coord=None):
            rec = build_interaction_record(
                itype,
                prot,
                lig,
                dist,
                details=str(details or ""),
                extra=extra,
                prot_coord=prot_coord,
                lig_coord=lig_coord,
            )
            key = (
                str(rec.get("type", "") or ""),
                str(rec.get("prot_res", "") or ""),
                str(rec.get("prot_atom", "") or ""),
                str(rec.get("lig_atom", "") or ""),
                _coord_key(rec.get("prot_coord")),
                _coord_key(rec.get("lig_coord")),
            )
            if key in seen:
                return None
            seen.add(key)
            interactions.append(rec)
            return rec

        def _is_ligand_oxyanion(atom):
            return bool(is_ligand_anion_center(atom))

        lig_pos_atoms = []
        lig_neg_atoms = []
        for atom in list(features.get("ligand_atoms", []) or []):
            if self._is_supported_ligand_cation_center(atom, features["ligand_atoms"]):
                atom["is_cation"] = True
                if not atom.get("group_type"):
                    atom["group_type"] = "SupportedCation"
                lig_pos_atoms.append(atom)
            if _is_ligand_oxyanion(atom):
                lig_neg_atoms.append(atom)

        protein_charge_groups = build_protein_charge_groups(features.get("protein_atoms", []))
        ligand_charge_groups = build_ligand_charge_groups(features.get("ligand_atoms", []))
        prot_pos_groups = list(protein_charge_groups.get("positive", []) or [])
        prot_neg_groups = list(protein_charge_groups.get("negative", []) or [])
        lig_pos_groups = [g for g in ligand_charge_groups if int(g.get("charge_sign", 0) or 0) > 0]
        lig_neg_groups = [g for g in ligand_charge_groups if int(g.get("charge_sign", 0) or 0) < 0]

        if not update_coords:
            try:
                self._append_debug_log(
                    "Charge groups: "
                    f"protein_pos={len(prot_pos_groups)}, protein_neg={len(prot_neg_groups)}, "
                    f"ligand_pos={len(lig_pos_groups)}, ligand_neg={len(lig_neg_groups)}."
                )
            except Exception:
                pass

        sb_cut = float(GEOMETRY_CRITERIA["salt_bridge_dist"])
        sb_best = {}
        # Salt bridge / H-bond policy: an H-bond between an atom of a protein charge group and
        # an atom of the oppositely charged ligand group (Asp189 OD1/OD2 ... benzamidinium N1/N2)
        # is the same contact as the salt bridge, a charge-assisted H-bond. It is reported once,
        # as the Salt Bridge record, which lists the atom pairs in "hbond_pairs" and says
        # "charge-assisted" in its details. H-bonds of the same atoms to other partners (Gly219
        # O, Ser190 OG) stay separate Hydrogen Bond records.
        sb_records = []

        def _register_salt_bridge(prot_group, lig_group):
            d = float(distance(prot_group["center"], lig_group["center"]))
            if d > sb_cut:
                return
            key = (
                str(prot_group.get("chain", "") or ""),
                str(prot_group.get("resi", "") or ""),
                str(lig_group.get("group_id", "") or ""),
            )
            cur = sb_best.get(key)
            if cur is not None and d >= float(cur["distance"]):
                return
            sb_best[key] = {
                "distance": float(d),
                "prot_group": dict(prot_group),
                "lig_group": dict(lig_group),
            }

        for prot_group in prot_pos_groups:
            for lig_group in lig_neg_groups:
                _register_salt_bridge(prot_group, lig_group)
        for prot_group in prot_neg_groups:
            for lig_group in lig_pos_groups:
                _register_salt_bridge(prot_group, lig_group)

        for payload in list(sb_best.values()):
            prot_group = dict(payload["prot_group"] or {})
            lig_group = dict(payload["lig_group"] or {})
            prot_atom = _group_anchor(prot_group)
            lig_atom = _group_anchor(lig_group)
            details = (
                f"{prot_group.get('group_type', 'charge')} ↔ {lig_group.get('group_type', 'charge')} "
                f"center-center {float(payload['distance']):.1f}Å"
            )
            rec = add_interaction(
                "Salt Bridge",
                prot_atom,
                lig_atom,
                float(payload["distance"]),
                details,
                extra={
                    "prot_charge_group": dict(prot_group),
                    "lig_charge_group": dict(lig_group),
                    "charge_center_distance": float(payload["distance"]),
                    "hbond_pairs": [],
                },
                prot_coord=prot_group.get("center"),
                lig_coord=lig_group.get("center"),
            )
            if rec is not None:
                sb_records.append(
                    (
                        rec,
                        {_atom_key(a) for a in list(prot_group.get("atoms", []) or [])},
                        {_atom_key(a) for a in list(lig_group.get("atoms", []) or [])},
                    )
                )

        def _salt_bridge_of(prot_atom, lig_atom):
            pk, lk = _atom_key(prot_atom), _atom_key(lig_atom)
            for rec, prot_keys, lig_keys in sb_records:
                if pk in prot_keys and lk in lig_keys:
                    return rec
            return None

        hb_cut = float(GEOMETRY_CRITERIA["h_bond_dist"])
        hb_ha_cut = float(GEOMETRY_CRITERIA["h_bond_ha_dist"])
        hb_fallback_angle = 90.0
        hb_heavy_crit = dict(GEOMETRY_CRITERIA, h_bond_fallback_angle=hb_fallback_angle)
        lig_h_acceptors = list(features.get("ligand_h_acceptors", []) or [])
        lig_h_donors = list(features.get("ligand_h_donors", []) or [])
        if (not lig_h_acceptors) and features.get("ligand_h_donors_acceptors"):
            lig_h_acceptors = list(features["ligand_h_donors_acceptors"])
        if (not lig_h_donors) and features.get("ligand_h_donors_acceptors"):
            lig_h_donors = list(features["ligand_h_donors_acceptors"])
        grid_lig_acc = self._NeighborGrid(lig_h_acceptors, cell_size=max(hb_cut, hb_ha_cut))
        grid_prot_acc = self._NeighborGrid(features["protein_h_acceptors"], cell_size=max(hb_cut, hb_ha_cut))
        hb_stats = {"explicit_h": 0, "heavy_atom": 0, "charge_assisted": 0, "metal_bound_skipped": 0}

        # Atoms bound to a metal ion are not H-bond partners: a His N or Asp O coordinating Zn has
        # no free lone pair (and the His H, if any, sits on the other N); a ligand atom bound to the
        # metal does not accept (it may still donate, e.g. the sulfonamide NH to Thr199 in CA II).
        metal_bound_prot = set()
        metal_bound_lig = set()
        metal_list = list(features.get("metals", []) or [])
        if metal_list:
            grid_prot_any = self._NeighborGrid(features["protein_atoms"], cell_size=3.5)
            for metal in metal_list:
                m_cut = float(metal_coordination_cutoff(metal.get("element", ""), criteria=GEOMETRY_CRITERIA))
                for p_atom in grid_prot_any.query(metal["coord"], m_cut):
                    if str(p_atom.get("element", "")).upper() in ("N", "O", "S"):
                        if float(distance(p_atom["coord"], metal["coord"])) <= m_cut:
                            metal_bound_prot.add(_atom_key(p_atom))
                for l_atom in list(features.get("ligand_atoms", []) or []):
                    if str(l_atom.get("element", "")).upper() in ("N", "O", "S"):
                        if float(distance(l_atom["coord"], metal["coord"])) <= m_cut:
                            metal_bound_lig.add(_atom_key(l_atom))

        hb_best = {}

        prot_c_by_res = {}

        def _heavy_neighbors(atom):
            pool = features["ligand_atoms"] if atom.get("origin") == "ligand" else features["protein_atoms"]
            out = [n for n in self._neighbors(atom, pool) if str(n.get("element", "")).upper() != "H"]
            if atom.get("origin") == "protein" and str(atom.get("name", "")) == "N":
                # _neighbors stays inside the residue: add the peptide C of the previous residue, so
                # the backbone N-H direction (opposite C and CA) is known
                if not prot_c_by_res:
                    for p in features["protein_atoms"]:
                        if str(p.get("name", "")) == "C":
                            prot_c_by_res.setdefault(str(p.get("chain", "")), []).append(p)
                for c_atom in prot_c_by_res.get(str(atom.get("chain", "")), []):
                    if c_atom.get("resi") != atom.get("resi") and float(distance(c_atom["coord"], atom["coord"])) <= 1.5:
                        out.append(c_atom)
                        break
            return out

        def _rotatable_donor(donor, hs):
            heavy = _heavy_neighbors(donor)
            if len(heavy) != 1:
                return False                  # ring/backbone/secondary N-H: H fixed by the heavy atoms
            if str(donor.get("element", "")).upper() in ("O", "S") or len(hs) >= 3:
                return True                   # OH, SH, NH3+
            pool = features["ligand_atoms"] if donor.get("origin") == "ligand" else features["protein_atoms"]
            # NH2 on a tetrahedral atom (amine, sulfonamide) rotates; on an sp2 C (amide,
            # amidinium, aniline) it is held in the plane
            return len(self._neighbors(heavy[0], pool)) >= 4

        def _donor_h_capacity(donor, hs):
            if hs:
                return len(hs)
            if donor.get("origin") == "protein":
                return protein_donor_hydrogen_count(donor.get("resn", ""), donor.get("name", ""))
            return None

        def _consider_hbond(donor, acceptor, prot_atom, lig_atom, donor_side):
            if _atom_key(prot_atom) in metal_bound_prot:
                hb_stats["metal_bound_skipped"] += 1
                return
            if donor_side == "protein" and _atom_key(lig_atom) in metal_bound_lig:
                hb_stats["metal_bound_skipped"] += 1
                return
            hs = list(self._donor_hydrogens(donor, features) or [])
            placed = bool(hs) and all(bool(h.get("placed")) for h in hs)
            best = None
            for h in hs:
                geom = classify_hbond_geometry(donor, acceptor, hydrogen=h, criteria=GEOMETRY_CRITERIA)
                if bool(geom.get("ok", False)) and (best is None or float(geom["angle"]) > float(best[0]["angle"])):
                    best = (geom, h)
            # Hydrogens Leonardo placed are not observed. Where the chemistry fixes them (amide,
            # amidinium, aniline, ring N-H) they are trusted; a rotatable OH/SH/NH3+/SO2NH2
            # hydrogen points wherever RDKit put it, so that donor (and any donor without
            # hydrogens) is judged by the heavy-atom geometry instead.
            if best is None and (not hs or (placed and _rotatable_donor(donor, hs))):
                geom = classify_hbond_geometry(
                    donor,
                    acceptor,
                    acceptor_neighbors=_heavy_neighbors(acceptor),
                    donor_neighbors=_heavy_neighbors(donor),
                    criteria=hb_heavy_crit,
                )
                if bool(geom.get("ok", False)):
                    best = (geom, None)
            if best is None:
                return
            geom, h = best
            mode_rank = 0 if geom.get("mode") == "explicit_hydrogen" else 1
            extra = {
                "donor_side": donor_side,
                "hbond_mode": str(geom.get("mode", "")),
                "distance_kind": "D...A",
                "da_distance": float(geom["da_distance"]),
                "ha_distance": (float(geom["ha_distance"]) if geom.get("ha_distance") is not None else None),
                "hbond_angle": float(geom["angle"]),
                "hbond_geometry": dict(geom),
            }
            if h is not None:
                extra["h_coord"] = h["coord"]
                extra["h_owner"] = donor_side
                extra["h_placed"] = bool(h.get("placed"))
            # one record per protein-atom/ligand-atom pair, whichever side donates
            key = (_atom_key(prot_atom), _atom_key(lig_atom))
            _store_best(
                hb_best,
                key,
                {
                    "prot_atom": dict(prot_atom),
                    "lig_atom": dict(lig_atom),
                    "geom": dict(geom),
                    "extra": extra,
                    "donor_key": (donor_side,) + _atom_key(donor),
                    "donor_h_capacity": _donor_h_capacity(donor, hs),
                },
                (mode_rank, float(geom["da_distance"]), -float(geom["angle"])),
            )
            hb_stats["explicit_h" if mode_rank == 0 else "heavy_atom"] += 1

        for p_d in list(features.get("protein_h_donors", []) or []):
            for l_a in grid_lig_acc.query(p_d["coord"], hb_cut):
                if not bool(l_a.get("hbond_acceptor", True)):
                    continue
                _consider_hbond(p_d, l_a, p_d, l_a, "protein")

        for l_d in lig_h_donors:
            if str(l_d.get("element", "")).upper() not in ("O", "N", "S"):
                continue
            if bool(l_d.get("is_anion", False)) or not bool(l_d.get("hbond_donor", True)):
                continue
            for p_a in grid_prot_acc.query(l_d["coord"], hb_cut):
                _consider_hbond(l_d, p_a, p_a, l_d, "ligand")

        # A donor cannot make more H-bonds than it has hydrogens: without explicit H the heavy-atom
        # test lets Thr OG1 "donate" to two ring N; keep its best one(s). Explicit-H bonds are per
        # hydrogen already and a bifurcated one is kept.
        by_donor = defaultdict(list)
        for payload in list(hb_best.values()):
            by_donor[payload["candidate"]["donor_key"]].append(payload)
        hb_kept = []
        for _dkey, payloads in by_donor.items():
            payloads.sort(key=lambda p: tuple(p["score"]))
            cap = payloads[0]["candidate"].get("donor_h_capacity")
            n_heavy = 0
            for payload in payloads:
                if payload["candidate"]["extra"].get("hbond_mode") != "explicit_hydrogen":
                    if cap is not None and n_heavy >= int(cap):
                        hb_stats["capped"] = hb_stats.get("capped", 0) + 1
                        continue
                    n_heavy += 1
                hb_kept.append(payload)

        for payload in hb_kept:
            cand = dict(payload.get("candidate", {}) or {})
            geom = dict(cand.get("geom", {}) or {})
            extra = dict(cand.get("extra", {}) or {})
            sb_rec = _salt_bridge_of(cand["prot_atom"], cand["lig_atom"])
            if sb_rec is not None:
                sb_rec["hbond_pairs"].append(
                    {
                        "prot_atom": str(cand["prot_atom"].get("name", "") or ""),
                        "lig_atom": str(cand["lig_atom"].get("name", "") or ""),
                        "da_distance": float(geom["da_distance"]),
                        "donor_side": extra.get("donor_side"),
                        "hbond_mode": extra.get("hbond_mode"),
                    }
                )
                hb_stats["charge_assisted"] += 1
                continue
            add_interaction(
                "Hydrogen Bond",
                cand["prot_atom"],
                cand["lig_atom"],
                float(geom["da_distance"]),
                str(geom.get("details", "")) + (" (protein donor)" if extra.get("donor_side") == "protein" else " (ligand donor)"),
                extra=extra,
            )
        for rec, _pk, _lk in sb_records:
            pairs = sorted(rec.get("hbond_pairs", []) or [], key=lambda p: float(p["da_distance"]))
            rec["hbond_pairs"] = pairs
            if pairs:
                rec["details"] = (
                    str(rec.get("details", ""))
                    + "; charge-assisted H-bond "
                    + ", ".join(f"{p['prot_atom']}···{p['lig_atom']} {float(p['da_distance']):.1f}Å" for p in pairs)
                )

        if not update_coords:
            try:
                self._append_debug_log(
                    "H-bond engine stats: "
                    f"explicit_h={hb_stats['explicit_h']}, heavy_atom={hb_stats['heavy_atom']}, "
                    f"charge_assisted={hb_stats['charge_assisted']}, "
                    f"metal_bound_skipped={hb_stats['metal_bound_skipped']}."
                )
            except Exception:
                pass

        metal_rows = list(features.get("metals", []) or [])
        metal_scan_cut = max(
            [float(metal_coordination_cutoff(m.get("element", ""), criteria=GEOMETRY_CRITERIA)) for m in metal_rows]
            + [float(GEOMETRY_CRITERIA["metal_coordination_dist"])]
        )
        grid_lig_macc = self._NeighborGrid(features["ligand_metal_acceptors"], cell_size=metal_scan_cut)
        for metal in metal_rows:
            # every ligand donor atom inside the ion's cutoff is a coordination bond (a chelating
            # hydroxamate or carboxylate binds with two atoms; keeping only the closest lost one)
            cutoff = float(metal_coordination_cutoff(metal.get("element", ""), criteria=GEOMETRY_CRITERIA))
            for l_acc in grid_lig_macc.query(metal["coord"], cutoff):
                geom = validate_metal_coordination(metal, l_acc, criteria=GEOMETRY_CRITERIA)
                if not bool(geom.get("ok", False)):
                    continue
                add_interaction(
                    "Metal Coordination",
                    metal,
                    dict(l_acc),
                    float(geom["distance"]),
                    str(geom.get("details", "")),
                    extra={"metal_cutoff": float(cutoff)},
                )

        hal_cut = float(GEOMETRY_CRITERIA["halogen_dist"])
        hal_don_ideal = float(GEOMETRY_CRITERIA["halogen_don_angle"])
        hal_acc_ideal = float(GEOMETRY_CRITERIA["halogen_acc_angle"])
        grid_prot_acc2 = self._NeighborGrid(features["protein_h_acceptors"], cell_size=hal_cut)
        hal_best = {}
        for l_hal in list(features.get("ligand_halogens", []) or []):
            hal_key = _atom_key(l_hal)
            carbons = [n for n in self._neighbors(l_hal, features["ligand_atoms"], element_filter={"C"}) if str(n.get("element", "")).upper() == "C"]
            carbon = carbons[0] if carbons else None
            if carbon is None:
                continue
            for p_acc in grid_prot_acc2.query(l_hal["coord"], hal_cut):
                acc_neighbor = self._acceptor_heavy_neighbor(p_acc, features)
                geom = validate_halogen_bond(
                    l_hal,
                    carbon,
                    p_acc,
                    acceptor_neighbor=acc_neighbor,
                    criteria=GEOMETRY_CRITERIA,
                )
                if not bool(geom.get("ok", False)):
                    continue
                candidate = {
                    "prot_atom": dict(p_acc),
                    "lig_atom": dict(l_hal),
                    "distance": float(geom["distance"]),
                    "details": str(geom["details"]),
                }
                _store_best(
                    hal_best,
                    hal_key,
                    candidate,
                    (
                        abs(float(geom["donor_angle"]) - hal_don_ideal)
                        + abs(float(geom["acceptor_angle"]) - hal_acc_ideal),
                        float(geom["distance"]),
                    ),
                )
        for payload in list(hal_best.values()):
            cand = dict(payload.get("candidate", {}) or {})
            add_interaction("Halogen Bond", cand["prot_atom"], cand["lig_atom"], cand["distance"], cand["details"])

        pi_pair_stats = {"pairs_tested": 0, "parallel_hits": 0, "tshape_hits": 0}
        pi_residue_ring_pairs = set()

        def _ring_placeholder(ring):
            return {"resn": ring["resn"], "resi": ring["resi"], "chain": ring["chain"], "name": "Ring"}

        for l_ring in list(features.get("ligand_rings", []) or []):
            lig_ring_key = tuple(int(i) for i in list(l_ring.get("atom_indices", []) or []))
            l_placeholder = _ring_placeholder(l_ring)
            for p_ring in list(features.get("protein_rings", []) or []):
                pi_pair_stats["pairs_tested"] += 1
                p_placeholder = _ring_placeholder(p_ring)
                geom = classify_pi_ring_pair(p_ring, l_ring, criteria=GEOMETRY_CRITERIA)
                if not bool(geom.get("ok", False)):
                    continue
                itype = str(geom.get("type", "") or "")
                d = float(geom["distance"])
                offset = float(geom["offset"])
                if itype == "Pi-Pi Stacking":
                    pi_pair_stats["parallel_hits"] += 1
                    add_interaction(
                        itype,
                        p_placeholder,
                        l_placeholder,
                        d,
                        str(geom["details"]),
                        extra={"prot_ring": p_ring, "ligand_ring": l_ring, "ring_offset": offset},
                        prot_coord=p_ring["centroid"],
                        lig_coord=l_ring["centroid"],
                    )
                    pi_residue_ring_pairs.add((str(p_ring["chain"]), str(p_ring["resi"]), lig_ring_key))
                elif itype == "T-Shaped Pi-Pi":
                    pi_pair_stats["tshape_hits"] += 1
                    add_interaction(
                        itype,
                        p_placeholder,
                        l_placeholder,
                        d,
                        str(geom["details"]),
                        extra={"prot_ring": p_ring, "ligand_ring": l_ring, "ring_offset": offset},
                        prot_coord=p_ring["centroid"],
                        lig_coord=l_ring["centroid"],
                    )
                    pi_residue_ring_pairs.add((str(p_ring["chain"]), str(p_ring["resi"]), lig_ring_key))

        for p_ring in list(features.get("protein_rings", []) or []):
            p_placeholder = _ring_placeholder(p_ring)
            for lig_group in lig_pos_groups:
                geom = validate_ring_charge_interaction(
                    p_ring,
                    lig_group.get("center"),
                    criteria=GEOMETRY_CRITERIA,
                )
                if not bool(geom.get("ok", False)):
                    continue
                lig_anchor = _group_anchor(lig_group)
                add_interaction(
                    "Cation-Pi",
                    p_placeholder,
                    lig_anchor,
                    float(geom["distance"]),
                    f"{lig_group.get('group_type', 'cation')} to ring: {str(geom['details_suffix'])}",
                    extra={
                        "prot_ring": p_ring,
                        "lig_charge_group": dict(lig_group),
                        "ring_offset": float(geom["offset"]),
                        "ring_plane_distance": float(geom["plane_distance"]),
                    },
                    prot_coord=p_ring["centroid"],
                    lig_coord=lig_group["center"],
                )

        for l_ring in list(features.get("ligand_rings", []) or []):
            l_placeholder = _ring_placeholder(l_ring)
            ring_is_pi_acidic = False
            for idx in list(l_ring.get("atom_indices", []) or []):
                if 0 <= int(idx) < len(features["ligand_atoms"]):
                    atom = features["ligand_atoms"][int(idx)]
                    if str(atom.get("group_type", "") or "") == "Aromatic Cation" or int(atom.get("charge_formal", 0) or 0) > 0:
                        ring_is_pi_acidic = True
                        break
            for prot_group in prot_pos_groups:
                prot_anchor = _group_anchor(prot_group)
                geom = validate_ring_charge_interaction(
                    l_ring,
                    prot_group.get("center"),
                    criteria=GEOMETRY_CRITERIA,
                )
                if bool(geom.get("ok", False)):
                    add_interaction(
                        "Cation-Pi",
                        prot_anchor,
                        l_placeholder,
                        float(geom["distance"]),
                        f"{prot_group.get('group_type', 'cation')} to ring: {str(geom['details_suffix'])}",
                        extra={
                            "ligand_ring": l_ring,
                            "prot_charge_group": dict(prot_group),
                            "ring_offset": float(geom["offset"]),
                            "ring_plane_distance": float(geom["plane_distance"]),
                        },
                        prot_coord=prot_group["center"],
                        lig_coord=l_ring["centroid"],
                    )
            if ring_is_pi_acidic:
                for prot_group in prot_neg_groups:
                    geom = validate_ring_charge_interaction(
                        l_ring,
                        prot_group.get("center"),
                        criteria=GEOMETRY_CRITERIA,
                    )
                    if not bool(geom.get("ok", False)):
                        continue
                    prot_anchor = _group_anchor(prot_group)
                    add_interaction(
                        "Anion-Pi",
                        prot_anchor,
                        l_placeholder,
                        float(geom["distance"]),
                        f"{prot_group.get('group_type', 'anion')} to pi-acidic ring: {str(geom['details_suffix'])}",
                        extra={
                            "ligand_ring": l_ring,
                            "prot_charge_group": dict(prot_group),
                            "ring_offset": float(geom["offset"]),
                            "ring_plane_distance": float(geom["plane_distance"]),
                        },
                        prot_coord=prot_group["center"],
                        lig_coord=l_ring["centroid"],
                    )

        if not update_coords:
            try:
                self._append_debug_log(
                    "Pi-ring stats: "
                    f"pairs_tested={pi_pair_stats['pairs_tested']}, parallel_hits={pi_pair_stats['parallel_hits']}, "
                    f"tshape_hits={pi_pair_stats['tshape_hits']}."
                )
            except Exception:
                pass

        hydrophobic_pairs = []
        p_hydroph_grid = self._NeighborGrid(features["protein_hydrophobic"], cell_size=float(GEOMETRY_CRITERIA["hydrophobic_dist"]))
        for l_atom in list(features.get("ligand_hydrophobic", []) or []):
            if str(l_atom.get("element", "")).upper() == "H":
                continue
            lig_idx = int(l_atom.get("_lig_idx", -1) or -1)
            for p_atom in p_hydroph_grid.query(l_atom["coord"], float(GEOMETRY_CRITERIA["hydrophobic_dist"])):
                if str(p_atom.get("element", "")).upper() == "H":
                    continue
                d = float(distance(p_atom["coord"], l_atom["coord"]))
                if d > float(GEOMETRY_CRITERIA["hydrophobic_dist"]):
                    continue
                suppress_pair = False
                for ring_key in [rk for ch, rs, rk in pi_residue_ring_pairs if ch == str(p_atom.get("chain", "") or "") and rs == str(p_atom.get("resi", "") or "")]:
                    if lig_idx >= 0 and int(lig_idx) in set(int(x) for x in ring_key):
                        suppress_pair = True
                        break
                if suppress_pair:
                    continue
                hydrophobic_pairs.append({"prot_atom": dict(p_atom), "lig_atom": dict(l_atom), "distance": float(d)})
        hydrophobic_pairs = reduce_hydrophobic_pairs(hydrophobic_pairs)

        hydrophobic_contacts = defaultdict(
            lambda: {
                "prot_atoms": set(),
                "lig_atoms": set(),
                "min_dist": 1.0e9,
                "min_prot_atom": None,
                "min_lig_atom": None,
                "min_prot_coord": None,
                "min_lig_coord": None,
                "prot_pts": {},
                "lig_pts": {},
            }
        )
        for pair in hydrophobic_pairs:
            p_atom = dict(pair["prot_atom"])
            l_atom = dict(pair["lig_atom"])
            d = float(pair["distance"])
            prot_key = (str(p_atom.get("chain", "") or ""), str(p_atom.get("resi", "") or ""))
            rec = hydrophobic_contacts[prot_key]
            rec["prot_atoms"].add(str(p_atom.get("name", "") or ""))
            rec["lig_atoms"].add(str(l_atom.get("name", "") or ""))
            pcoord = np.array(p_atom["coord"], dtype=float)
            lcoord = np.array(l_atom["coord"], dtype=float)
            rec["prot_pts"][tuple(np.round(pcoord, 3))] = pcoord
            rec["lig_pts"][tuple(np.round(lcoord, 3))] = lcoord
            if d < rec["min_dist"]:
                rec["min_dist"] = float(d)
                rec["min_prot_atom"] = str(p_atom.get("name", "") or "")
                rec["min_lig_atom"] = str(l_atom.get("name", "") or "")
                rec["min_prot_coord"] = pcoord
                rec["min_lig_coord"] = lcoord

        for (chain, resi), data in hydrophobic_contacts.items():
            if not data["prot_atoms"]:
                continue
            try:
                resn = next(
                    a["resn"] for a in features["protein_atoms"] if str(a.get("chain", "")) == str(chain) and str(a.get("resi", "")) == str(resi)
                )
            except StopIteration:
                continue
            prot_pts = list(data.get("prot_pts", {}).values())
            lig_pts = list(data.get("lig_pts", {}).values())
            prot_com = np.mean(np.vstack(prot_pts), axis=0) if prot_pts else np.array(data["min_prot_coord"], dtype=float)
            lig_com = np.mean(np.vstack(lig_pts), axis=0) if lig_pts else np.array(data["min_lig_coord"], dtype=float)
            inter = build_interaction_record(
                "Hydrophobic",
                {"resn": resn, "resi": resi, "chain": chain, "name": str(data.get("min_prot_atom") or "")},
                {
                    "resn": lig_resn,
                    "resi": lig_resi,
                    "chain": lig_chain,
                    "name": str(data.get("min_lig_atom") or ""),
                },
                # the closest C...C distance (PLIP); the drawn line joins the cluster centres
                float(data.get("min_dist", 0.0)),
                details="Cluster",          # drawing keys on this exact text
                extra={
                    "cluster_com_distance": float(distance(prot_com, lig_com)),
                    "cluster_min_prot_atom": data.get("min_prot_atom"),
                    "cluster_min_lig_atom": data.get("min_lig_atom"),
                    "cluster_min_distance": float(data.get("min_dist", 0.0)),
                    "cluster_contact_count": int(len(data.get("prot_pts", {}))),
                    "cluster_min_prot_coord": tuple(data["min_prot_coord"]) if data.get("min_prot_coord") is not None else None,
                    "cluster_min_lig_coord": tuple(data["min_lig_coord"]) if data.get("min_lig_coord") is not None else None,
                },
                prot_coord=prot_com,
                lig_coord=lig_com,
            )
            inter["prot_atom"] = ",".join(sorted(data["prot_atoms"]))
            inter["lig_atom"] = ",".join(sorted(data["lig_atoms"]))
            inter["cluster_com_prot_coord"] = tuple(prot_com)
            inter["cluster_com_lig_coord"] = tuple(lig_com)
            key = (
                inter["type"],
                inter["prot_res"],
                inter["prot_atom"],
                inter["lig_atom"],
                _coord_key(inter.get("prot_coord")),
                _coord_key(inter.get("lig_coord")),
            )
            if key not in seen:
                seen.add(key)
                interactions.append(inter)

        specific_residues = {
            (str(i.get("prot_chain", "") or ""), str(i.get("prot_resi", "") or ""))
            for i in interactions
            if str(i.get("type", "") or "") != "Van der Waals"
        }

        vdw_contacts = {}
        vdw_scan_cut = float(GEOMETRY_CRITERIA["vdw_max_dist"])
        p_grid = self._NeighborGrid(features["protein_atoms"], cell_size=vdw_scan_cut)
        for l_atom in list(features.get("ligand_atoms", []) or []):
            if str(l_atom.get("element", "")).upper() == "H":
                continue
            for p_atom in p_grid.query(l_atom["coord"], vdw_scan_cut):
                if str(p_atom.get("element", "")).upper() == "H":
                    continue
                d = float(distance(p_atom["coord"], l_atom["coord"]))
                cutoff = float(
                    vdw_contact_cutoff(
                        p_atom,
                        l_atom,
                        padding=GEOMETRY_CRITERIA["vdw_padding"],
                        max_cutoff=GEOMETRY_CRITERIA["vdw_max_dist"],
                    )
                )
                if d > cutoff:
                    continue
                if bool(p_atom.get("element") == "C" and l_atom.get("element") == "C" and d <= float(GEOMETRY_CRITERIA["hydrophobic_dist"])):
                    continue
                res_key = (str(p_atom.get("chain", "") or ""), str(p_atom.get("resi", "") or ""))
                if res_key in specific_residues:
                    continue
                gap = float(d - (vdw_contact_cutoff(p_atom, l_atom, padding=0.0, max_cutoff=100.0)))
                cur = vdw_contacts.get(res_key)
                if cur is None or d < float(cur["distance"]):
                    vdw_contacts[res_key] = {
                        "prot_atom": dict(p_atom),
                        "lig_atom": dict(l_atom),
                        "distance": d,
                        "gap": gap,
                    }

        for (_chain, _resi), payload in list(vdw_contacts.items()):
            p_atom = dict(payload["prot_atom"] or {})
            l_atom = dict(payload["lig_atom"] or {})
            add_interaction(
                "Van der Waals",
                p_atom,
                l_atom,
                float(payload["distance"]),
                f"closest heavy-atom contact, gap {float(payload['gap']):+.2f}Å vs vdW sum",
            )

        max_by_type = {
            "Salt Bridge": float(GEOMETRY_CRITERIA["salt_bridge_dist"]) + 0.5,
            "Hydrogen Bond": float(GEOMETRY_CRITERIA["h_bond_dist"]) + 0.5,
            "Metal Coordination": float(GEOMETRY_CRITERIA["metal_coordination_dist"]) + 0.5,
            "Halogen Bond": float(GEOMETRY_CRITERIA["halogen_dist"]) + 0.5,
            "Cation-Pi": float(GEOMETRY_CRITERIA["cation_pi_dist"]) + 0.5,
            "Anion-Pi": float(GEOMETRY_CRITERIA["cation_pi_dist"]) + 0.5,
            "Pi-Pi Stacking": float(GEOMETRY_CRITERIA["pi_pi_dist"]) + 0.5,
            "T-Shaped Pi-Pi": float(GEOMETRY_CRITERIA["pi_pi_dist"]) + 0.5,
            "Hydrophobic": float(GEOMETRY_CRITERIA["hydrophobic_dist"]) + 2.5,
            "Van der Waals": float(GEOMETRY_CRITERIA["vdw_max_dist"]) + 0.5,
        }
        filtered = []
        dropped = 0
        for inter in interactions:
            try:
                d = float(inter.get("distance", 0.0))
            except Exception:
                dropped += 1
                continue
            if not np.isfinite(d) or d <= 0.0:
                dropped += 1
                continue
            if d > float(max_by_type.get(str(inter.get("type", "") or ""), 10.0)):
                dropped += 1
                continue
            filtered.append(inter)
        if dropped:
            print(f"ProtLigInteract: Dropped {dropped} outlier interactions by geometry sanity filter.")
        return sorted(filtered, key=lambda x: (str(x.get("type", "")), float(x.get("distance", 0.0))))
    def _populate_table(self):
        self.table.setRowCount(0)
        self.table.setColumnCount(6)
        self.table.setHorizontalHeaderLabels(["Type", "Prot Res", "Prot Atom", "Lig Atom", "Distance (Å)", "Details"])
        items = self._current_filtered_items()
        self._table_items = list(items)
        for i, inter in enumerate(items):
            self.table.insertRow(i)
            self.table.setItem(i, 0, QtWidgets.QTableWidgetItem(inter["type"]))
            self.table.setItem(i, 1, QtWidgets.QTableWidgetItem(inter["prot_res"]))
            self.table.setItem(i, 2, QtWidgets.QTableWidgetItem(inter["prot_atom"]))
            self.table.setItem(i, 3, QtWidgets.QTableWidgetItem(inter["lig_atom"]))
            self.table.setItem(i, 4, QtWidgets.QTableWidgetItem(f"{inter['distance']:.2f}"))
            self.table.setItem(i, 5, QtWidgets.QTableWidgetItem(inter.get("details", "")))
        self.table.resizeColumnsToContents()
    def _on_table_clicked(self, row, col):
        try:
            inter = self._table_items[row] if self._table_items else self.interactions[row]
            rid = self.interactions.index(inter)
        except Exception:
            return
        self._last_clicked_rid = rid
        self._toggle_interaction_by_id(rid)
        if rid in self._selected_ids:
            self._highlight_interaction_visual(rid, zoom_to=False)
        elif int(getattr(self, "_focused_interaction_rid", -1)) == int(rid):
            self._focused_interaction_rid = -1
    def _select_table_row_for_interaction(self, rid):
        """Select the table row matching an interaction id without toggling visuals."""
        if not hasattr(self, "table"):
            return
        try:
            rid = int(rid)
            if rid < 0 or rid >= len(self.interactions):
                return
            target = self.interactions[rid]
            row = -1
            for idx, item in enumerate(list(getattr(self, "_table_items", []) or [])):
                if item is target:
                    row = idx
                    break
            if row < 0:
                for idx, item in enumerate(list(getattr(self, "_table_items", []) or [])):
                    if item == target:
                        row = idx
                        break
            if row < 0:
                return
            try:
                self.table.blockSignals(True)
            except Exception:
                pass
            try:
                self.table.setCurrentCell(row, 0)
                self.table.selectRow(row)
                item = self.table.item(row, 0)
                if item is not None:
                    self.table.scrollToItem(item, QtWidgets.QAbstractItemView.PositionAtCenter)
            finally:
                try:
                    self.table.blockSignals(False)
                except Exception:
                    pass
        except Exception:
            pass
    def _restore_interaction_focus_style(self, rid):
        """Restore a previously focused interaction dash to its type-specific style."""
        try:
            rid = int(rid)
            if rid < 0 or rid >= len(self.interactions):
                return
            inter = self.interactions[rid]
            dash = f"int_dash_{rid}"
            color_name = self._type_color_name(str(inter.get("type", "") or ""))
            try:
                cmd.set("dash_color", color_name, dash)
                cmd.set("label_color", color_name, dash)
            except Exception:
                pass
            self._apply_dash_style(dash, str(inter.get("type", "") or ""))
        except Exception:
            pass
    def _interaction_focus_selection(self, rid):
        """Build a PyMOL selection around all visible objects for one interaction."""
        try:
            rid = int(rid)
            if rid < 0 or rid >= len(self.interactions):
                return ""
            candidates = [
                f"pseudo_p_{rid}",
                f"pseudo_l_{rid}",
                f"intRes_{rid}",
                f"intCloudProt_{rid}",
                f"intCloudLig_{rid}",
                f"intRingDiscProt_{rid}",
                f"intRingDiscLig_{rid}",
                f"int_dash_{rid}",
            ]
            valid = []
            seen = set()
            for name in candidates:
                if name in seen:
                    continue
                seen.add(name)
                try:
                    if int(cmd.count_atoms(name)) > 0:
                        valid.append(name)
                except Exception:
                    pass
            if not valid:
                try:
                    known = set(cmd.get_names("objects"))
                except Exception:
                    known = set()
                for name in candidates:
                    if name in known and name not in valid:
                        valid.append(name)
            if not valid:
                inter = self.interactions[rid]
                prot_chain = inter.get("prot_chain")
                prot_resi = inter.get("prot_resi")
                prot_resn = inter.get("prot_resn")
                if prot_chain is None or prot_resi is None:
                    toks = str(inter.get("prot_res", "") or "").split()
                    pr = toks[1] if len(toks) > 1 else ""
                    if pr:
                        prot_chain = pr[0]
                        prot_resi = pr[1:] if len(pr) > 1 else pr
                    if not prot_resn and toks:
                        prot_resn = toks[0]
                if self.loaded_object and prot_resi is not None:
                    chain_clause = 'chain ""' if str(prot_chain or "").strip() == "" else f'chain "{str(prot_chain).strip()}"'
                    prot_sel = f"{self.loaded_object} and {chain_clause} and resi {prot_resi}"
                    if prot_resn:
                        prot_sel += f" and resn {prot_resn}"
                    valid.append(prot_sel)
                if self.loaded_object and self.ligand_info:
                    l_c, l_i, l_n = self.ligand_info
                    valid.append(self._pymol_residue_selection(self.loaded_object, l_c, l_i, l_n, wrap=True))
            return " or ".join(f"({sel})" for sel in valid if str(sel).strip())
        except Exception:
            return ""
    def _highlight_interaction_visual(self, rid, zoom_to=True):
        """Emphasize one visible interaction in PyMOL and optionally move the camera to it."""
        try:
            rid = int(rid)
            if rid < 0 or rid >= len(self.interactions):
                return False
            prev = int(getattr(self, "_focused_interaction_rid", -1))
            if prev != rid:
                self._restore_interaction_focus_style(prev)
            self._focused_interaction_rid = rid
            if rid not in self._selected_ids:
                return False
            dash = f"int_dash_{rid}"
            try:
                cmd.set_color("pli_focus_interaction", [1.0, 0.86, 0.12])
                cmd.set("dash_color", "pli_focus_interaction", dash)
                cmd.set("label_color", "pli_focus_interaction", dash)
                cmd.set("dash_radius", 0.16, dash)
            except Exception:
                pass
            for obj in (
                "Interactions",
                f"Interactions.{str(self.interactions[rid].get('type', '')).replace(' ', '_')}",
                f"intRes_{rid}",
                f"intCloudProt_{rid}",
                f"intCloudLig_{rid}",
                f"intRingDiscProt_{rid}",
                f"intRingDiscLig_{rid}",
                dash,
                f"pseudo_p_{rid}",
                f"pseudo_l_{rid}",
            ):
                try:
                    cmd.enable(obj)
                except Exception:
                    pass
            focus_sel = self._interaction_focus_selection(rid)
            if zoom_to and focus_sel:
                try:
                    cmd.center(focus_sel)
                except Exception:
                    pass
                try:
                    cmd.zoom(focus_sel, 5)
                except TypeError:
                    try:
                        cmd.zoom(focus_sel)
                    except Exception:
                        pass
                except Exception:
                    pass
            return True
        except Exception:
            return False
    def _focus_interaction_by_id(self, rid, ensure_visible=True, update_table=True, zoom_to=True):
        """Focus an interaction from non-table UI, such as the 2D interaction map."""
        try:
            rid = int(rid)
            if rid < 0 or rid >= len(self.interactions):
                return False
            self._last_clicked_rid = rid
            if ensure_visible and rid not in self._selected_ids:
                self._toggle_interaction_by_id(rid)
            if update_table:
                self._select_table_row_for_interaction(rid)
            return self._highlight_interaction_visual(rid, zoom_to=zoom_to)
        except Exception:
            return False
    def _toggle_interaction_by_id(self, rid):
        inter = self.interactions[rid]
        res_name = f"intRes_{rid}"
        dash_name = f"int_dash_{rid}"
        cloud_prot_name = f"intCloudProt_{rid}"
        cloud_lig_name = f"intCloudLig_{rid}"
        disc_prot_name = f"intRingDiscProt_{rid}"
        disc_lig_name = f"intRingDiscLig_{rid}"
        if rid in self._selected_ids:
            try:
                cmd.delete(res_name)
                cmd.delete(dash_name)
                cmd.delete(cloud_prot_name)
                cmd.delete(cloud_lig_name)
                cmd.delete(disc_prot_name)
                cmd.delete(disc_lig_name)
                cmd.delete(f"pseudo_p_{rid}")
                cmd.delete(f"pseudo_l_{rid}")
                # Cleanup labels
                cmd.delete(f"lbl_prot_{rid}")
                cmd.delete(f"lbl_lig_{rid}")
                cmd.delete(f"lbl_dist_{rid}")
                cmd.delete(f"angle_label_{rid}")
            except Exception:
                pass
            self._selected_ids.remove(rid)
            self._last_live_state = -1
            return
        else:
            prot_chain = inter.get("prot_chain")
            prot_resi = inter.get("prot_resi")
            prot_resn = inter.get("prot_resn")
            if prot_chain is None or prot_resi is None:
                # Backward compatibility for older interaction records.
                try:
                    toks = str(inter.get("prot_res", "")).split()
                    pr = toks[1] if len(toks) > 1 else ""
                    if pr:
                        prot_chain = pr[0]
                        prot_resi = pr[1:] if len(pr) > 1 else pr
                    if not prot_resn and toks:
                        prot_resn = toks[0]
                except Exception:
                    prot_chain = ""
                    prot_resi = ""
            prot_atom_names = inter["prot_atom"]
            lig_chain, lig_resi, lig_resn = self.ligand_info
            lig_atom_names = inter["lig_atom"]
            chain_clause = 'chain ""' if str(prot_chain).strip() == "" else f'chain "{str(prot_chain).strip()}"'
            prot_res_sel = f"{self.loaded_object} and {chain_clause} and resi {prot_resi}"
            if prot_resn:
                prot_res_sel += f" and resn {prot_resn}"
            inter_type_group = f"Interactions.{inter['type'].replace(' ', '_')}"
            # Visualization logic
            if inter.get("details") == "Cluster":
                # Use robust atom parsing and a representative nearest-contact pair.
                prot_atom_list = [a.strip() for a in str(prot_atom_names).split(",") if a.strip()]
                lig_atom_list = [a.strip() for a in str(lig_atom_names).split(",") if a.strip()]
                rep_prot_atom = str(inter.get("cluster_min_prot_atom") or "").strip()
                rep_lig_atom = str(inter.get("cluster_min_lig_atom") or "").strip()
                if not rep_prot_atom and prot_atom_list:
                    rep_prot_atom = prot_atom_list[0]
                if not rep_lig_atom and lig_atom_list:
                    rep_lig_atom = lig_atom_list[0]
                res_display_sel = prot_res_sel
                lig_res_sel = self._pymol_residue_selection(self.loaded_object, lig_chain, lig_resi, lig_resn)
                try:
                    if cmd.count_atoms(res_display_sel) == 0:
                        # Fallback without resn constraint for edge naming/insertion cases.
                        res_display_sel = f"{self.loaded_object} and {chain_clause} and resi {prot_resi}"
                except Exception:
                    pass
                rep_prot_sel = f"{res_display_sel} and name {rep_prot_atom}" if rep_prot_atom else None
                rep_lig_sel = (
                    self._pymol_residue_selection(self.loaded_object, lig_chain, lig_resi, lig_resn)
                    + f" and name {rep_lig_atom}"
                    if rep_lig_atom
                    else None
                )
                try:
                    # Show the full residue so the interacting amino acid is always visible.
                    cmd.select(res_name, res_display_sel)
                    cmd.show("sticks", res_name)
                    cmd.show("spheres", res_name)
                    cmd.set("sphere_scale", 0.22, res_name)
                    cmd.set("stick_radius", 0.15, res_name)
                    cmd.util.cbao(res_name)
                    cmd.group(inter_type_group, res_name)
                    # Stable cloud selections: localize by stored min-contact coordinates.
                    # This avoids wrong-side surfaces when atom names are duplicated (e.g. docking UNL C/N/O names).
                    prot_base_sel = None
                    lig_base_sel = None
                    if prot_atom_list:
                        prot_base_sel = f"({res_display_sel}) and name " + "+".join(prot_atom_list)
                    elif rep_prot_atom:
                        prot_base_sel = f"({res_display_sel}) and name {rep_prot_atom}"
                    if lig_atom_list:
                        lig_base_sel = f"({lig_res_sel}) and name " + "+".join(lig_atom_list)
                    elif rep_lig_atom:
                        lig_base_sel = f"({lig_res_sel}) and name {rep_lig_atom}"
                    cutoff = (
                        GEOMETRY_CRITERIA["hydrophobic_dist"]
                        if inter["type"] == "Hydrophobic"
                        else GEOMETRY_CRITERIA["vdw_max_dist"]
                    )
                    contact_cut = float(cutoff) + 0.3
                    prot_cloud_sel = None
                    lig_cloud_sel = None
                    pmin = inter.get("cluster_min_prot_coord")
                    lmin = inter.get("cluster_min_lig_coord")
                    tmp_pm = f"tmp_cloud_pm_{rid}"
                    tmp_lm = f"tmp_cloud_lm_{rid}"
                    if pmin is not None and lmin is not None:
                        cmd.delete(tmp_pm)
                        cmd.delete(tmp_lm)
                        cmd.pseudoatom(tmp_pm, pos=list(pmin))
                        cmd.pseudoatom(tmp_lm, pos=list(lmin))
                        prot_cloud_sel = f"({res_display_sel}) within {contact_cut:.2f} of ({tmp_lm})"
                        lig_cloud_sel = f"({lig_res_sel}) within {contact_cut:.2f} of ({tmp_pm})"
                    elif prot_base_sel and lig_base_sel:
                        prot_cloud_sel = f"({prot_base_sel}) within {contact_cut:.2f} of ({lig_base_sel})"
                        lig_cloud_sel = f"({lig_base_sel}) within {contact_cut:.2f} of ({prot_base_sel})"
                    else:
                        prot_cloud_sel = prot_base_sel
                        lig_cloud_sel = lig_base_sel
                    if prot_cloud_sel:
                        cmd.select(cloud_prot_name, prot_cloud_sel)
                        if cmd.count_atoms(cloud_prot_name) == 0 and prot_base_sel:
                            cmd.select(cloud_prot_name, prot_base_sel)
                        if cmd.count_atoms(cloud_prot_name) == 0 and rep_prot_sel:
                            cmd.select(cloud_prot_name, rep_prot_sel)
                        cmd.show("surface", cloud_prot_name)
                        cmd.show("spheres", cloud_prot_name)
                        cmd.set("sphere_scale", 0.18, cloud_prot_name)
                        cmd.group(inter_type_group, cloud_prot_name)
                    if lig_cloud_sel:
                        cmd.select(cloud_lig_name, lig_cloud_sel)
                        if cmd.count_atoms(cloud_lig_name) == 0 and lig_base_sel:
                            cmd.select(cloud_lig_name, lig_base_sel)
                        if cmd.count_atoms(cloud_lig_name) == 0 and rep_lig_sel:
                            cmd.select(cloud_lig_name, rep_lig_sel)
                        cmd.show("surface", cloud_lig_name)
                        cmd.show("spheres", cloud_lig_name)
                        cmd.set("sphere_scale", 0.18, cloud_lig_name)
                        cmd.group(inter_type_group, cloud_lig_name)
                    cmd.delete(tmp_pm)
                    cmd.delete(tmp_lm)
                    ctype = self._type_color_name(inter["type"])
                    cov = (
                        self._settings.get("style_overrides", {}).get(inter["type"], {}).get("cloud_opacity")
                        if hasattr(self, "_settings")
                        else None
                    )
                    trans = 1.0 - float(cov) if cov is not None else 0.6
                    for obj in (cloud_prot_name, cloud_lig_name):
                        if cmd.count_atoms(obj) > 0:
                            cmd.color(ctype, obj)
                            cmd.set("transparency", trans, obj)
                            cmd.set("sphere_transparency", trans, obj)
                except Exception:
                    pass
                # Distances use stored computed coordinates first (stable and exact).
                try:
                    cmd.delete(f"pseudo_p_{rid}")
                    cmd.delete(f"pseudo_l_{rid}")
                except Exception:
                    pass
                try:
                    p1_sel = None
                    p2_sel = None
                    p1c = inter.get("prot_coord")
                    p2c = inter.get("lig_coord")
                    if p1c is not None and p2c is not None:
                        p1_name = f"pseudo_p_{rid}"
                        p2_name = f"pseudo_l_{rid}"
                        cmd.pseudoatom(p1_name, pos=list(p1c))
                        cmd.pseudoatom(p2_name, pos=list(p2c))
                        p1_sel = p1_name
                        p2_sel = p2_name
                    elif rep_prot_sel and rep_lig_sel and cmd.count_atoms(rep_prot_sel) > 0 and cmd.count_atoms(rep_lig_sel) > 0:
                        p1_sel = rep_prot_sel
                        p2_sel = rep_lig_sel
                    if p1_sel and p2_sel:
                        cmd.distance(dash_name, p1_sel, p2_sel)
                    c_name = f"c_{inter['type'].replace(' ', '_')}"
                    c_rgb = _hex_to_rgb(COLOR_MAP.get(inter["type"], "#FFFFFF"))
                    if c_rgb:
                        cmd.set_color(c_name, list(c_rgb))
                        cmd.set("dash_color", c_name, dash_name)
                    style = STYLE_MAP.get(inter["type"], {})
                    cmd.set("dash_radius", style.get("dash_radius", 0.05), dash_name)
                    cmd.set("dash_gap", style.get("dash_gap", 0.2), dash_name)
                    cmd.set("dash_length", style.get("dash_length", 0.3), dash_name)
                    cmd.group(inter_type_group, dash_name)
                except Exception:
                    pass
            else:
                # Show full interacting residue for atom/ring interactions.
                try:
                    cmd.select(res_name, prot_res_sel)
                    cmd.show("sticks", res_name)
                    cmd.show("spheres", res_name)
                    cmd.set("sphere_scale", 0.25, res_name)
                    cmd.set("stick_radius", 0.15, res_name)
                    cmd.util.cbao(res_name)
                    cmd.group(inter_type_group, res_name)
                except Exception:
                    pass
                # Visualization logic
                # Distances use stored computed coordinates first (stable and exact).
                try:
                    cmd.delete(f"pseudo_p_{rid}")
                    cmd.delete(f"pseudo_l_{rid}")
                except Exception:
                    pass
                p1_sel = None
                p2_sel = None
                p1_coord = inter.get("prot_coord")
                p2_coord = inter.get("lig_coord")
                if p1_coord is not None and p2_coord is not None:
                    p1_name = f"pseudo_p_{rid}"
                    p2_name = f"pseudo_l_{rid}"
                    cmd.pseudoatom(p1_name, pos=list(p1_coord))
                    cmd.pseudoatom(p2_name, pos=list(p2_coord))
                    p1_sel = p1_name
                    p2_sel = p2_name
                else:
                    # Fallback to atom selectors if coordinates are missing.
                    if inter["prot_atom"] == "Ring":
                        if p1_coord is not None:
                            p1_name = f"pseudo_p_{rid}"
                            cmd.pseudoatom(p1_name, pos=list(p1_coord))
                            p1_sel = p1_name
                    else:
                        p1_sel = f"({prot_res_sel} and name {prot_atom_names})"
                    if inter["lig_atom"] == "Ring":
                        if p2_coord is not None:
                            p2_name = f"pseudo_l_{rid}"
                            cmd.pseudoatom(p2_name, pos=list(p2_coord))
                            p2_sel = p2_name
                    else:
                        p2_sel = (
                            "("
                            + self._pymol_residue_selection(self.loaded_object, lig_chain, lig_resi, lig_resn)
                            + f" and name {lig_atom_names})"
                        )
                if p1_sel and p2_sel:
                    try:
                        cmd.distance(dash_name, p1_sel, p2_sel)
                        c_name = f"c_{inter['type'].replace(' ', '_')}"
                        c_rgb = _hex_to_rgb(COLOR_MAP.get(inter["type"], "#FFFFFF"))
                        if c_rgb:
                            cmd.set_color(c_name, list(c_rgb))
                            cmd.set("dash_color", c_name, dash_name)
                        style = STYLE_MAP.get(inter["type"], {})
                        radius = style.get("dash_radius", 0.05)
                        cmd.set("dash_radius", radius, dash_name)
                        cmd.set("dash_gap", style.get("dash_gap", 0.2), dash_name)
                        cmd.set("dash_length", style.get("dash_length", 0.3), dash_name)
                        cmd.set("dash_round_ends", 1, dash_name)
                        cmd.set("label_color", c_name, dash_name)
                        cmd.set("label_size", 20, dash_name)
                    except Exception as e:
                        print(f"Viz Error {rid}: {e}")
                cmd.group(inter_type_group, dash_name)
                    
                # --- Interactive Dynamic Labels (Restored) ---
                # Labels: Bold, Green, No Outline
                
                lbl_prot_name = f"lbl_prot_{rid}"
                lbl_lig_name = f"lbl_lig_{rid}"
                
                # Label Protein Atom: "Resn Resi Atom" e.g. "ASN 123 OD1"
                # Need p1 coordinate if it was a Ring
                if inter["prot_atom"] == "Ring" and "prot_coord" in inter:
                     p1_c = inter["prot_coord"]
                     cmd.pseudoatom(lbl_prot_name, pos=list(p1_c))
                     p_resn = str(inter.get("prot_resn") or "").strip()
                     p_resi = inter.get("prot_resi")
                     if not p_resn or p_resi is None:
                         toks = str(inter.get("prot_res", "")).split()
                         if toks and not p_resn:
                             p_resn = toks[0]
                         if p_resi is None and len(toks) > 1:
                             p_resi = toks[1]
                     cmd.label(lbl_prot_name, f'"{p_resn} {p_resi} Ring"')
                else:
                     prot_atom_sel = f"({prot_res_sel} and name {prot_atom_names})"
                     cmd.select(lbl_prot_name, prot_atom_sel)
                     cmd.label(lbl_prot_name, '"%s %s %s" % (resn, resi, name)')
                cmd.set("label_color", "green", lbl_prot_name)
                # cmd.set("label_outline_color", "black", lbl_prot_name) # Removed borders per request
                cmd.set("label_font_id", 2, lbl_prot_name) # 2 = Sans Bold
                
                # Label Ligand Atom: "Atom" e.g. "N1"
                if inter["lig_atom"] == "Ring" and "lig_coord" in inter:
                     p2_c = inter["lig_coord"]
                     cmd.pseudoatom(lbl_lig_name, pos=list(p2_c))
                     cmd.label(lbl_lig_name, '"Ring"')
                else:
                     # Re-derive selector if needed, or assume it's valid
                     lig_atom_sel = (
                         "("
                         + self._pymol_residue_selection(self.loaded_object, lig_chain, lig_resi, lig_resn)
                         + f" and name {lig_atom_names})"
                     )
                     cmd.select(lbl_lig_name, lig_atom_sel) 
                     cmd.label(lbl_lig_name, '"%s" % (name)') 
                cmd.set("label_color", "green", lbl_lig_name)
                # cmd.set("label_outline_color", "black", lbl_lig_name) # Removed borders per request
                cmd.set("label_font_id", 2, lbl_lig_name) # 2 = Sans Bold
                
                cmd.group(inter_type_group, lbl_prot_name)
                cmd.group(inter_type_group, lbl_lig_name)
                
                # Distance Label is handled by cmd.distance object itself (dash_name)
                # So we don't need manual pseudoatom for it regarding 'p1'/'p2'
                pass
                    # Optional angle label - REMOVED per user request for cleaner look
                    # if bool(self._settings.get("show_angle_labels", False)) ...
            # --- Ring plane discs for pi interactions ---
            try:
                ring_color = inter["type"]
                if "prot_ring" in inter:
                    r = inter["prot_ring"]
                    self._make_ring_disc(disc_prot_name, r["centroid"], r["normal"], r.get("radius", 1.8), ring_color)
                    cmd.group(inter_type_group, disc_prot_name)
                if "ligand_ring" in inter:
                    r = inter["ligand_ring"]
                    self._make_ring_disc(disc_lig_name, r["centroid"], r["normal"], r.get("radius", 1.8), ring_color)
                    cmd.group(inter_type_group, disc_lig_name)
            except Exception:
                pass
            self._selected_ids.add(rid)
            self._last_live_state = -1
    def _apply_publication_view(self):
        """Publication-style scene of the current interactions (white background, one label per residue,
        dashes by type, camera into the pocket). Off with settings['publication_view'] = False."""
        try:
            if hasattr(self, "_settings") and not bool(self._settings.get("publication_view", True)):
                return None
            if not self.interactions or not self.ligand_info or not self.loaded_object:
                return None
            from leonardo import interaction_view
            c, i, r = self.ligand_info
            lig = self._pymol_residue_selection(self.loaded_object, c, i, r)
            for name in cmd.get_names("objects"):
                if name.startswith(("int_dash_", "intRes_", "intCloud", "intRingDisc", "lbl_")):
                    cmd.disable(name)
            return interaction_view.build_scene(self.loaded_object, lig, list(self.interactions))
        except Exception as exc:
            try:
                self._append_debug_log(f"publication view: {exc}")
            except Exception:
                pass
            return None
    def _beautify_scene(self):
        """Sets up a nice, clean visualization scene."""
        self._ensure_valid_analysis_context()
        if not self.loaded_object:
            return
        try:
            topo_obj = getattr(self, "_traj_topology_object", None)
            if topo_obj and cmd.count_atoms(topo_obj) > 0:
                curr_poly = cmd.count_atoms(f"({self.loaded_object}) and polymer")
                topo_poly = cmd.count_atoms(f"({topo_obj}) and polymer")
                if curr_poly <= 0 and topo_poly > 0:
                    self.loaded_object = topo_obj
                    if hasattr(self, "structure_combo"):
                        idx = self.structure_combo.findText(topo_obj)
                        if idx >= 0:
                            self.structure_combo.setCurrentIndex(idx)
        except Exception:
            pass
        # Keep existing object visibility; only ensure the active object is enabled.
        try:
            self._redock_apply_scene_actions(
                [{"action": "enable", "object": str(self.loaded_object)}],
                known_objects=None,
                default_action="disable",
            )
        except Exception:
            pass
        # Set a nice dark grey background
        cmd.bg_color("grey20")
        # Better lighting
        cmd.set("ray_trace_mode", 1)
        cmd.set("specular", 0.4)
        cmd.set("shininess", 50)
        cmd.set("ambient", 0.3)
        # Show polymer (protein/nucleic acids) as clean white cartoon, excluding selected ligand residue
        prot_sel = f"{self.loaded_object} and polymer"
        if self.ligand_info:
            c, i, r = self.ligand_info
            lig_excl = " and not (" + self._pymol_residue_selection(self.loaded_object, c, i, r) + ")"
            prot_sel += lig_excl
        try:
            if cmd.count_atoms(prot_sel) > 0:
                cmd.show("cartoon", prot_sel)
                cmd.set("cartoon_color", "white", prot_sel)
                cmd.set("cartoon_transparency", 0.0, prot_sel)
                cmd.set("transparency", 0.0, prot_sel)
                # Fallback rendering path for cases where cartoon display is not obvious.
                if cmd.count_atoms(f"({prot_sel}) and rep cartoon") <= 0:
                    cmd.show("lines", prot_sel)
                    cmd.color("gray80", prot_sel)
            else:
                # Fallback for non-polymer topologies: at least keep the full object visible.
                cmd.show("lines", self.loaded_object)
                cmd.color("gray80", self.loaded_object)
        except Exception:
            pass
        # Show ligand in licorice/ball-and-stick, colored by element
        lig_sel = None
        if self.ligand_info:
            c, i, r = self.ligand_info
            lig_sel = self._pymol_residue_selection(self.loaded_object, c, i, r)
            try:
                self._apply_ball_and_stick_style(lig_sel, sphere_scale=0.22, stick_radius=0.16)
                self._apply_element_colors(lig_sel)
            except Exception:
                pass
        # Camera behavior: avoid zooming to ligand-only when ligand is far from protein.
        try:
            auto_zoom = bool(self._settings.get("auto_zoom", True)) if hasattr(self, "_settings") else True
            if auto_zoom:
                did_lig_zoom = False
                if lig_sel:
                    near_poly = cmd.count_atoms(f"({self.loaded_object}) and polymer within 6.0 of ({lig_sel})")
                    if near_poly > 0:
                        cmd.zoom(lig_sel, 6)
                        did_lig_zoom = True
                if not did_lig_zoom:
                    poly_count = cmd.count_atoms(f"({self.loaded_object}) and polymer")
                    if poly_count > 0:
                        cmd.zoom(f"({self.loaded_object}) and polymer", 8)
                    else:
                        cmd.zoom(self.loaded_object, 4)
        except Exception:
            pass
        # General settings for a clean look
        cmd.set("antialias", 2)
        # Dash settings serve as backup if CGO fails
        cmd.set("dash_gap", 0.0) 
        cmd.set("dash_radius", 0.1)
        cmd.set("ray_trace_fog", 0)  # No fog
        cmd.set("depth_cue", 0)  # No depth cueing
        # Legend overlay refresh
        try:
            self._update_legend()
        except Exception:
            pass
    def _apply_dash_style(self, obj_name, itype):
        style = STYLE_MAP.get(itype, {}).copy()
        # apply overrides
        try:
            o = self._settings.get("style_overrides", {}).get(itype, {}) if hasattr(self, "_settings") else {}
            style.update({k: v for k, v in o.items() if k in ("dash_radius", "dash_length", "dash_gap")})
        except Exception:
            pass
        if not style:
            return
        try:
            if "dash_radius" in style:
                cmd.set("dash_radius", style["dash_radius"], obj_name)
            if "dash_length" in style:
                cmd.set("dash_length", style["dash_length"], obj_name)
            if "dash_gap" in style:
                cmd.set("dash_gap", style["dash_gap"], obj_name)
        except Exception:
            pass
    def _type_color_name(self, itype):
        # Resolve color name for type considering overrides
        base = COLOR_MAP.get(itype, "yellow")
        try:
            o = self._settings.get("style_overrides", {}).get(itype, {}) if hasattr(self, "_settings") else {}
            hexc = o.get("color")
            if hexc:
                rgb = _hex_to_rgb(hexc)
                if rgb:
                    cname = f"pli_color_{itype.replace(' ','_')}"
                    if _COLOR_CACHE.get(cname) != rgb:
                        cmd.set_color(cname, list(rgb))
                        _COLOR_CACHE[cname] = rgb
                    return cname
        except Exception:
            pass
        return base
    def _make_ring_disc(self, name, centroid, normal, radius, color_or_type):
        thickness = 0.10
        # per-type override thickness
        if isinstance(color_or_type, str) and color_or_type in COLOR_MAP:
            try:
                ov = (
                    self._settings.get("style_overrides", {}).get(color_or_type, {})
                    if hasattr(self, "_settings")
                    else {}
                )
                tval = ov.get("disc_thickness")
                if tval is not None:
                    thickness = float(tval)
            except Exception:
                pass
        # fallback to global control
        if hasattr(self, "disc_thickness_spin"):
            try:
                if thickness == 0.10:  # only if not overridden
                    thickness = float(self.disc_thickness_spin.value())
            except Exception:
                pass
        c = np.array(centroid)
        n = np.array(normal)
        if np.linalg.norm(n) == 0:
            n = np.array([0.0, 0.0, 1.0])
        n = n / np.linalg.norm(n)
        p1 = (c - n * (thickness / 2.0)).tolist()
        p2 = (c + n * (thickness / 2.0)).tolist()
        # Resolve color from type overrides or color name
        if isinstance(color_or_type, str) and color_or_type in COLOR_MAP:
            cname = self._type_color_name(color_or_type)
        else:
            cname = color_or_type if isinstance(color_or_type, str) else None
        if cname and str(cname).startswith("#"):
            # COLOR_MAP holds "#RRGGBB" values (not PyMOL color names: "Unknown color", then yellow)
            rgb = _hex_to_rgb(cname)
        else:
            rgb = cmd.get_color_tuple(cname) if cname else color_or_type
        if not rgb:
            rgb = (1.0, 1.0, 0.0)
        obj = [
            cgo.CYLINDER,
            p1[0],
            p1[1],
            p1[2],
            p2[0],
            p2[1],
            p2[2],
            float(radius),
            rgb[0],
            rgb[1],
            rgb[2],
            rgb[0],
            rgb[1],
            rgb[2],
        ]
        cmd.load_cgo(obj, name)
        try:
            # per-type disc opacity
            if isinstance(color_or_type, str) and color_or_type in COLOR_MAP:
                ov = (
                    self._settings.get("style_overrides", {}).get(color_or_type, {})
                    if hasattr(self, "_settings")
                    else {}
                )
                op = ov.get("disc_opacity")
                trans = 1.0 - float(op) if op is not None else 0.5
            else:
                trans = 0.5
            cmd.set("transparency", trans, name)
        except Exception:
            pass
    def _on_render_export(self):
        out = self.png_path_edit.text().strip() or "output.png"
        cmd.set("ray_trace_mode", 1)
        # place export-safe legend
        try:
            include = True
            if hasattr(self, "legend_export_cb"):
                include = self.legend_export_cb.isChecked()
            if include:
                self._update_legend(for_export=True, anchor=self._legend_anchor())
            else:
                cmd.delete("Interactions.Legend")
            # Scale bar and title
            if bool(self._settings.get("include_scale", True)) if hasattr(self, "_settings") else True:
                self._update_scale_bar_for_export()
            else:
                cmd.delete("Interactions.ScaleBar")
            if bool(self._settings.get("include_title", False)) if hasattr(self, "_settings") else False:
                self._update_title_for_export()
            else:
                cmd.delete("Interactions.Title")
        except Exception:
            pass
        cmd.png(out, width=2000, height=2000, dpi=300, ray=1)
        QtWidgets.QMessageBox.information(self, "Exported", f"Image saved to {out}")
    def _update_scale_bar_for_export(self):
        # remove previous
        try:
            cmd.delete("Interactions.ScaleBar")
        except Exception:
            pass
        try:
            L = float(self._settings.get("scale_length", 10)) if hasattr(self, "_settings") else 10.0
        except Exception:
            L = 10.0
        view = cmd.get_view()
        try:
            minv, maxv = cmd.get_extent(self.loaded_object)
            minv = np.array(minv)
            maxv = np.array(maxv)
            center = (minv + maxv) / 2.0
            diag = float(np.linalg.norm(maxv - minv)) or 10.0
        except Exception:
            center = np.array([view[12], view[13], view[14]])
            diag = 10.0
        right = np.array(view[0:3])
        up = np.array(view[3:6])
        right = right / (np.linalg.norm(right) or 1.0)
        up = up / (np.linalg.norm(up) or 1.0)
        # place near bottom-left by default; reuse legend anchor
        anchor = self._legend_anchor()
        frac = 0.35
        off_r = frac * diag
        off_u = frac * diag
        if anchor == "top_left":
            off_r = -off_r
        if anchor in ("bottom_left", "bottom_right"):
            off_u = -off_u
        base = np.array(center) + right * off_r + up * (off_u - 0.15 * diag)
        p1 = base
        p2 = base + right * L
        rgb = cmd.get_color_tuple("white") or (1.0, 1.0, 1.0)
        obj = [
            cgo.CYLINDER,
            float(p1[0]),
            float(p1[1]),
            float(p1[2]),
            float(p2[0]),
            float(p2[1]),
            float(p2[2]),
            0.1,
            rgb[0],
            rgb[1],
            rgb[2],
            rgb[0],
            rgb[1],
            rgb[2],
        ]
        cmd.load_cgo(obj, "Interactions.ScaleBar")
        # label
        try:
            lab = "scale_label"
            pos = p2 + up * (0.08 * diag)
            cmd.pseudoatom(lab, pos=[float(pos[0]), float(pos[1]), float(pos[2])])
            cmd.label(lab, f'"{int(round(L))} Å"')
            cmd.set("label_color", "white", lab)
            cmd.set("label_outline_color", "black", lab)
            cmd.group("Interactions.ScaleBar", lab)
        except Exception:
            pass
    def _update_title_for_export(self):
        try:
            cmd.delete("Interactions.Title")
        except Exception:
            pass
        text = ""
        try:
            text = str(self._settings.get("title_text", "")) if hasattr(self, "_settings") else ""
        except Exception:
            text = ""
        if not text:
            return
        view = cmd.get_view()
        try:
            minv, maxv = cmd.get_extent(self.loaded_object)
            minv = np.array(minv)
            maxv = np.array(maxv)
            center = (minv + maxv) / 2.0
            diag = float(np.linalg.norm(maxv - minv)) or 10.0
        except Exception:
            center = np.array([view[12], view[13], view[14]])
            diag = 10.0
        up = np.array(view[3:6])
        up = up / (np.linalg.norm(up) or 1.0)
        pos = center + up * (0.45 * diag)
        name = "title_label"
        cmd.pseudoatom(name, pos=[float(pos[0]), float(pos[1]), float(pos[2])])
        cmd.label(name, f'"{text}"')
        cmd.set("label_color", "white", name)
        cmd.set("label_outline_color", "black", name)
        cmd.group("Interactions.Title", name)
    def _on_show_hist(self):
        # Simple histogram dialog for distances
        try:
            from PySide2.QtWidgets import QDialog, QPlainTextEdit, QPushButton, QVBoxLayout
        except Exception:
            QDialog = QtWidgets.QDialog
            QVBoxLayout = QtWidgets.QVBoxLayout
            QPlainTextEdit = QtWidgets.QPlainTextEdit
            QPushButton = QtWidgets.QPushButton
        dlg = QDialog(self)
        dlg.setWindowTitle("Distance Histogram")
        layout = QVBoxLayout(dlg)
        txt = QPlainTextEdit(dlg)
        txt.setReadOnly(True)
        layout.addWidget(txt)
        close_btn = QPushButton("Close", dlg)
        close_btn.clicked.connect(dlg.accept)
        layout.addWidget(close_btn)
        # build bins 0-2,...,18-20
        bins = [(i, i + 2) for i in range(0, 20, 2)]
        counts = [0] * len(bins)
        dists = [i.get("distance", 0.0) for i in self._current_filtered_items()]
        for d in dists:
            for idx, (a, b) in enumerate(bins):
                if a <= d < b or (b == 20 and d <= 20):
                    counts[idx] += 1
                    break
        lines = []
        for (a, b), c in zip(bins, counts):
            bar = "▇" * min(c, 50)
            lines.append(f"{a:2d}-{b:2d}: {c:4d} {bar}")
        txt.setPlainText("\n".join(lines))
        dlg.resize(400, 300)
        dlg.exec_()
    def _on_edit_styles(self):
        # Dialog to edit per-type color and dash styles
        dlg = QtWidgets.QDialog(self)
        dlg.setWindowTitle("Edit Styles")
        layout = QtWidgets.QVBoxLayout(dlg)
        table = QtWidgets.QTableWidget(dlg)
        types = sorted(COLOR_MAP.keys())
        table.setColumnCount(8)
        table.setHorizontalHeaderLabels(
            [
                "Type",
                "Color",
                "#Dash Radius",
                "#Dash Length",
                "#Dash Gap",
                "Disc Thickness",
                "Disc Opacity",
                "Cloud Opacity",
            ]
        )
        table.setRowCount(len(types))
        overrides = dict(self._settings.get("style_overrides", {})) if hasattr(self, "_settings") else {}
        def make_color_btn(color_hex):
            btn = QtWidgets.QPushButton()
            btn.setText(color_hex or "")
            if color_hex:
                btn.setStyleSheet(f"background:{color_hex};")
            def choose():
                col = QtWidgets.QColorDialog.getColor()
                if col.isValid():
                    hx = col.name()
                    btn.setText(hx)
                    btn.setStyleSheet(f"background:{hx};")
            btn.clicked.connect(choose)
            return btn
        for row, t in enumerate(types):
            table.setItem(row, 0, QtWidgets.QTableWidgetItem(t))
            table.item(row, 0).setFlags(table.item(row, 0).flags() & ~QtCore.Qt.ItemIsEditable)
            ov = overrides.get(t, {})
            color_btn = make_color_btn(ov.get("color"))
            table.setCellWidget(row, 1, color_btn)
            for col, key, default in [
                (2, "dash_radius", STYLE_MAP.get(t, {}).get("dash_radius", 0.08)),
                (3, "dash_length", STYLE_MAP.get(t, {}).get("dash_length", 0.4)),
                (4, "dash_gap", STYLE_MAP.get(t, {}).get("dash_gap", 0.2)),
            ]:
                spin = QtWidgets.QDoubleSpinBox()
                spin.setDecimals(3)
                spin.setRange(0.01, 2.0)
                spin.setSingleStep(0.01)
                spin.setValue(float(ov.get(key, default)))
                table.setCellWidget(row, col, spin)
            # Disc thickness per type (Å)
            thick_spin = QtWidgets.QDoubleSpinBox()
            thick_spin.setDecimals(2)
            thick_spin.setRange(0.02, 0.50)
            thick_spin.setSingleStep(0.01)
            default_thick = float(
                ov.get(
                    "disc_thickness", self.disc_thickness_spin.value() if hasattr(self, "disc_thickness_spin") else 0.10
                )
            )
            thick_spin.setValue(default_thick)
            table.setCellWidget(row, 5, thick_spin)
            # Disc opacity (0-1)
            disc_spin = QtWidgets.QDoubleSpinBox()
            disc_spin.setDecimals(2)
            disc_spin.setRange(0.0, 1.0)
            disc_spin.setSingleStep(0.05)
            disc_spin.setValue(float(ov.get("disc_opacity", 0.5)))
            table.setCellWidget(row, 6, disc_spin)
            # Cloud opacity (0-1)
            cloud_spin = QtWidgets.QDoubleSpinBox()
            cloud_spin.setDecimals(2)
            cloud_spin.setRange(0.0, 1.0)
            cloud_spin.setSingleStep(0.05)
            cloud_spin.setValue(float(ov.get("cloud_opacity", 0.4)))
            table.setCellWidget(row, 7, cloud_spin)
        layout.addWidget(table)
        btns = QtWidgets.QHBoxLayout()
        save_btn = QtWidgets.QPushButton("Save")
        cancel_btn = QtWidgets.QPushButton("Cancel")
        btns.addWidget(save_btn)
        btns.addWidget(cancel_btn)
        layout.addLayout(btns)
        def on_save():
            new_ov = {}
            for row, t in enumerate(types):
                color_w = table.cellWidget(row, 1)
                dr = table.cellWidget(row, 2).value()
                dl = table.cellWidget(row, 3).value()
                dg = table.cellWidget(row, 4).value()
                thick = table.cellWidget(row, 5).value()
                disc = table.cellWidget(row, 6).value()
                cloud = table.cellWidget(row, 7).value()
                rec = {
                    "dash_radius": dr,
                    "dash_length": dl,
                    "dash_gap": dg,
                    "disc_thickness": thick,
                    "disc_opacity": disc,
                    "cloud_opacity": cloud,
                }
                color_hex = color_w.text().strip()
                if color_hex:
                    rec["color"] = color_hex
                new_ov[t] = rec
            self._settings["style_overrides"] = new_ov
            self._save_settings()
            # Apply to currently visible dashes by reapplying style
            try:
                for rid in list(self._selected_ids):
                    obj = f"int_dash_{rid}"
                    if cmd.count_atoms(obj) >= 0:
                        self._apply_dash_style(obj, self.interactions[rid]["type"])
                # Update legend colors
                self._update_legend(for_export=False, anchor=self._legend_anchor())
            except Exception:
                pass
            dlg.accept()
        save_btn.clicked.connect(on_save)
        cancel_btn.clicked.connect(dlg.reject)
        dlg.resize(700, 400)
        dlg.exec_()
    # --- Enhancements: legend, clear, csv export, filtering ---
    def showEvent(self, event):
        super().showEvent(event)
        # Build legend dynamically once widgets exist
        try:
            self._load_settings()
            self._build_legend()
            self._init_filter()
            self._init_type_toggles()
            self._init_settings()
            self._apply_settings_to_ui()
            loaded_project = False
            if not bool(getattr(self, "_project_autoload_done", False)):
                self._project_autoload_done = True
                loaded_project = bool(self._project_try_autoload_from_settings())
            if not loaded_project:
                self._restore_last_session()
        except Exception:
            pass
    def closeEvent(self, event):
        try:
            self._project_save_state(silent=True)
        except Exception:
            pass
        super().closeEvent(event)
    def _build_legend(self):
        # Legend removed per user request
        # If UI element exists, clear it
        try:
            legend_container = getattr(self, "legend_grid", None) or self.findChild(QtWidgets.QGridLayout, "legend_grid")
            if legend_container:
                while legend_container.count():
                    item = legend_container.takeAt(0)
                    if item.widget():
                        item.widget().deleteLater()
        except Exception:
            pass
    def _init_filter(self):
        combo = getattr(self, "filter_combo", None)
        if not combo:
            return
        combo.blockSignals(True)
        combo.clear()
        combo.addItem("All")
        for t in sorted(set(COLOR_MAP.keys())):
            combo.addItem(t)
        combo.blockSignals(False)
        combo.currentTextChanged.connect(lambda _t: (self._apply_filter(_t), self._save_settings()))
        # Max distance control
        if hasattr(self, "max_distance_spin"):
            try:
                self.max_distance_spin.setValue(0.00)
                self.max_distance_spin.valueChanged.connect(lambda _v: (self._populate_table(), self._save_settings()))
            except Exception:
                pass
        # Sync slider and spin
        if hasattr(self, "max_distance_slider") and hasattr(self, "max_distance_spin"):
            def slider_to_spin(val):
                try:
                    self.max_distance_spin.blockSignals(True)
                    self.max_distance_spin.setValue(val / 100.0)
                    self.max_distance_spin.blockSignals(False)
                    self._populate_table()
                    self._save_settings()
                except Exception:
                    pass
            def spin_to_slider(val):
                try:
                    self.max_distance_slider.blockSignals(True)
                    self.max_distance_slider.setValue(int(round(val * 100)))
                    self.max_distance_slider.blockSignals(False)
                except Exception:
                    pass
            self.max_distance_slider.valueChanged.connect(slider_to_spin)
            self.max_distance_spin.valueChanged.connect(spin_to_slider)
    def _init_type_toggles(self):
        # Prefer Trajectory UI layout if setup
        layout = getattr(self, "traj_types_layout", None)
        if not layout:
             layout = getattr(self, "types_layout", None) or self.findChild(QtWidgets.QVBoxLayout, "types_layout")
        if not layout:
            return
        # Clear any existing
        while layout.count():
            item = layout.takeAt(0)
            w = item.widget()
            if w:
                w.deleteLater()
        self._type_checkboxes = {}
        types = sorted(COLOR_MAP.keys())
        saved = {}
        try:
            saved = self._settings.get("types_enabled", {}) if hasattr(self, "_settings") else {}
        except Exception:
            saved = {}
        for t in types:
            cb = QtWidgets.QCheckBox(t)
            checked = bool(saved.get(t, True))
            cb.setChecked(checked)
            cb.toggled.connect(lambda checked, tt=t: (self._on_type_toggle(tt, checked), self._save_settings()))
            layout.addWidget(cb)
            self._type_checkboxes[t] = cb
        spacer = QtWidgets.QSpacerItem(20, 10, QtWidgets.QSizePolicy.Minimum, QtWidgets.QSizePolicy.Expanding)
        layout.addItem(spacer)
    def _on_type_toggle(self, itype, checked):
        group = f"Interactions.{itype.replace(' ', '_')}"
        try:
            self._redock_apply_scene_actions(
                [{"action": ("enable" if bool(checked) else "disable"), "object": str(group)}],
                known_objects=None,
                default_action="disable",
            )
        except Exception:
            pass
    def _apply_filter(self, text):
        # Rebuild table using current combined filters
        self._populate_table()
    def _init_settings(self):
        # Legend corner options
        if hasattr(self, "legend_corner_combo"):
            combo = self.legend_corner_combo
            if combo.count() == 0:
                combo.addItems(["Top Right", "Top Left", "Bottom Right", "Bottom Left"])
            combo.setCurrentText("Top Right")
            combo.currentTextChanged.connect(
                lambda _: (self._update_legend(for_export=False, anchor=self._legend_anchor()), self._save_settings())
            )
        # Legend export
        if hasattr(self, "legend_export_cb"):
            self.legend_export_cb.setChecked(True)
            self.legend_export_cb.toggled.connect(lambda _v: self._save_settings())
        # Disc thickness
        if hasattr(self, "disc_thickness_spin"):
            self.disc_thickness_spin.setValue(0.10)
            self.disc_thickness_spin.valueChanged.connect(
                lambda _v: (self._refresh_ring_discs(), self._save_settings())
            )
        # Distance labels
        if hasattr(self, "show_labels_cb"):
            self.show_labels_cb.setChecked(True)
            self.show_labels_cb.toggled.connect(lambda _v: (self._apply_labels_visibility(), self._save_settings()))
        # Compute on load
        if hasattr(self, "compute_on_load_cb"):
            self.compute_on_load_cb.setChecked(False)
            self.compute_on_load_cb.toggled.connect(lambda _v: self._save_settings())
        # Auto-zoom
        if hasattr(self, "auto_zoom_cb"):
            self.auto_zoom_cb.setChecked(True)
            self.auto_zoom_cb.toggled.connect(lambda _v: self._save_settings())
        # Max distance slider init
        if hasattr(self, "max_distance_slider") and hasattr(self, "max_distance_spin"):
            try:
                self.max_distance_slider.setValue(int(round(self.max_distance_spin.value() * 100)))
            except Exception:
                pass
        # Angle labels
        if hasattr(self, "show_angle_labels_cb"):
            self.show_angle_labels_cb.setChecked(False)
            self.show_angle_labels_cb.toggled.connect(lambda _v: self._save_settings())
        # Scale bar & title
        if hasattr(self, "include_scale_cb"):
            self.include_scale_cb.setChecked(True)
            self.include_scale_cb.toggled.connect(lambda _v: self._save_settings())
        if hasattr(self, "scale_length_spin"):
            self.scale_length_spin.setValue(10)
            self.scale_length_spin.valueChanged.connect(lambda _v: self._save_settings())
        if hasattr(self, "include_title_cb"):
            self.include_title_cb.setChecked(False)
            self.include_title_cb.toggled.connect(lambda _v: self._save_settings())
        if hasattr(self, "title_line"):
            self.title_line.textChanged.connect(lambda _v: self._save_settings())
    def _legend_anchor(self):
        txt = (
            getattr(self, "legend_corner_combo", None).currentText()
            if hasattr(self, "legend_corner_combo")
            else "Top Right"
        )
        mapping = {
            "Top Right": "top_right",
            "Top Left": "top_left",
            "Bottom Right": "bottom_right",
            "Bottom Left": "bottom_left",
        }
        return mapping.get(txt, "top_right")
    def _apply_labels_visibility(self):
        show = True
        if hasattr(self, "show_labels_cb"):
            show = self.show_labels_cb.isChecked()
        # Toggle labels on all interaction groups
        try:
            if show:
                cmd.show("labels", "Interactions")
            else:
                cmd.hide("labels", "Interactions")
        except Exception:
            pass
    def _refresh_ring_discs(self):
        # Recreate ring discs with new thickness for selected interactions
        try:
            for rid in list(self._selected_ids):
                try:
                    cmd.delete(f"intRingDiscProt_{rid}")
                    cmd.delete(f"intRingDiscLig_{rid}")
                except Exception:
                    pass
                # Recreate discs if interaction has ring info
                inter = self.interactions[rid]
                inter_type_group = f"Interactions.{inter['type'].replace(' ', '_')}"
                # the type, as when the discs are first drawn: _make_ring_disc resolves its (overridden)
                # color; a "#RRGGBB" string is no PyMOL color name and fell back to yellow
                ring_color = inter["type"] if inter.get("type") in COLOR_MAP else "yellow"
                if "prot_ring" in inter:
                    r = inter["prot_ring"]
                    self._make_ring_disc(
                        f"intRingDiscProt_{rid}", r["centroid"], r["normal"], r.get("radius", 1.8), ring_color
                    )
                    cmd.group(inter_type_group, f"intRingDiscProt_{rid}")
                if "ligand_ring" in inter:
                    r = inter["ligand_ring"]
                    self._make_ring_disc(
                        f"intRingDiscLig_{rid}", r["centroid"], r["normal"], r.get("radius", 1.8), ring_color
                    )
                    cmd.group(inter_type_group, f"intRingDiscLig_{rid}")
        except Exception:
            pass
    # --- Settings persistence ---
    def _settings_path(self):
        return os.path.join(os.path.dirname(__file__), "settings.json")
    def _load_settings(self):
        self._settings = {
            "legend_corner": "Top Right",
            "legend_export": True,
            "disc_thickness": 0.10,
            "show_labels": True,
            "max_distance": 0.0,
            "filter_selection": "All",
            "types_enabled": {},
            "compute_on_load": False,
            "auto_zoom": True,
            "confirm_remove_all": True,
            # chooser defaults
            "chooser_show": "All",
            "chooser_near": False,
            "chooser_near_dist": 6.0,
            "chooser_ref": "Protein",
            "chooser_ref_chain": "",
            "chooser_search": "",
            "last_project_root": "",
            "last_project_parent": os.path.expanduser("~"),
            "abfe_keep_scene_visible": False,
            "abfe_surface_transparency": 0.55,
            "abfe_surface_color_mode": "rainbow_resi",
            "abfe_steering_mode": "pull_hold_return",
            "abfe_steering_cycles": 3,
            "abfe_policy_mode": "heuristic",
            "abfe_guide_tunnel_enabled": True,
            "abfe_guide_tunnel_radius_a": 3.5,
            "abfe_guide_tunnel_shape": "funnel",
            "abfe_replica_count": 3,
            "abfe_replica_seed0": 20260311,
        }
        try:
            p = self._settings_path()
            if os.path.exists(p):
                import json
                with open(p, "r") as f:
                    data = json.load(f)
                    if isinstance(data, dict):
                        self._settings.update(data)
        except Exception:
            pass
    def _save_settings(self):
        try:
            # Start from current settings to preserve non-UI flags
            data = dict(getattr(self, "_settings", {}))
            data.update(self._collect_settings_from_ui())
            try:
                proj_root = str(getattr(self, "_project_root", "") or "").strip()
                if proj_root:
                    data["last_project_root"] = proj_root
                    data["last_project_parent"] = str(os.path.dirname(proj_root) or proj_root)
            except Exception:
                pass
            import json
            with open(self._settings_path(), "w") as f:
                json.dump(data, f, indent=2)
        except Exception:
            pass
    def _apply_settings_to_ui(self):
        s = getattr(self, "_settings", {})
        try:
            if hasattr(self, "legend_corner_combo"):
                self.legend_corner_combo.blockSignals(True)
                self.legend_corner_combo.setCurrentText(s.get("legend_corner", "Top Right"))
                self.legend_corner_combo.blockSignals(False)
            if hasattr(self, "legend_export_cb"):
                self.legend_export_cb.blockSignals(True)
                self.legend_export_cb.setChecked(bool(s.get("legend_export", True)))
                self.legend_export_cb.blockSignals(False)
            if hasattr(self, "disc_thickness_spin"):
                self.disc_thickness_spin.blockSignals(True)
                self.disc_thickness_spin.setValue(float(s.get("disc_thickness", 0.10)))
                self.disc_thickness_spin.blockSignals(False)
            if hasattr(self, "show_labels_cb"):
                self.show_labels_cb.blockSignals(True)
                self.show_labels_cb.setChecked(bool(s.get("show_labels", True)))
                self.show_labels_cb.blockSignals(False)
            if hasattr(self, "max_distance_spin"):
                self.max_distance_spin.blockSignals(True)
                self.max_distance_spin.setValue(float(s.get("max_distance", 0.0)))
                self.max_distance_spin.blockSignals(False)
            if hasattr(self, "filter_combo"):
                self.filter_combo.blockSignals(True)
                self.filter_combo.setCurrentText(s.get("filter_selection", "All"))
                self.filter_combo.blockSignals(False)
            if hasattr(self, "legend_export_cb") and hasattr(self, "legend_corner_combo"):
                pass
            # Restore per-type toggles if present
            if hasattr(self, "_type_checkboxes"):
                for t, cb in self._type_checkboxes.items():
                    cb.blockSignals(True)
                    cb.setChecked(bool(s.get("types_enabled", {}).get(t, True)))
                    cb.blockSignals(False)
            # compute on load
            if hasattr(self, "compute_on_load_cb"):
                self.compute_on_load_cb.blockSignals(True)
                self.compute_on_load_cb.setChecked(bool(s.get("compute_on_load", False)))
                self.compute_on_load_cb.blockSignals(False)
            # auto zoom
            if hasattr(self, "auto_zoom_cb"):
                self.auto_zoom_cb.blockSignals(True)
                self.auto_zoom_cb.setChecked(bool(s.get("auto_zoom", True)))
                self.auto_zoom_cb.blockSignals(False)
            self._set_abfe_keep_scene_visible(bool(s.get("abfe_keep_scene_visible", False)))
            self._set_abfe_surface_alpha(float(s.get("abfe_surface_transparency", 0.55)))
            self._set_abfe_surface_color_mode(str(s.get("abfe_surface_color_mode", "rainbow_resi")))
            # settings saved before exit/re-entry cycles existed carry "pull_hold" only because it was the
            # default then; they move to the new default once (the cycles key marks newer settings)
            saved_mode = str(s.get("abfe_steering_mode", "pull_hold_return"))
            if "abfe_steering_cycles" not in s:
                saved_mode = "pull_hold_return"
            self._set_abfe_steering_mode(saved_mode)
            self._set_abfe_steering_cycles(int(s.get("abfe_steering_cycles", 3) or 3))
            self._set_abfe_policy_mode(str(s.get("abfe_policy_mode", "heuristic")))
            self._set_abfe_guide_tunnel_enabled(bool(s.get("abfe_guide_tunnel_enabled", True)))
            self._set_abfe_guide_tunnel_radius_a(float(s.get("abfe_guide_tunnel_radius_a", 3.5)))
            self._set_abfe_guide_tunnel_shape(str(s.get("abfe_guide_tunnel_shape", "funnel") or "funnel"))
            if hasattr(self, "show_angle_labels_cb"):
                self.show_angle_labels_cb.blockSignals(True)
                self.show_angle_labels_cb.setChecked(bool(s.get("show_angle_labels", False)))
                self.show_angle_labels_cb.blockSignals(False)
            if hasattr(self, "include_scale_cb"):
                self.include_scale_cb.blockSignals(True)
                self.include_scale_cb.setChecked(bool(s.get("include_scale", True)))
                self.include_scale_cb.blockSignals(False)
            if hasattr(self, "scale_length_spin"):
                self.scale_length_spin.blockSignals(True)
                self.scale_length_spin.setValue(int(s.get("scale_length", 10)))
                self.scale_length_spin.blockSignals(False)
            if hasattr(self, "include_title_cb"):
                self.include_title_cb.blockSignals(True)
                self.include_title_cb.setChecked(bool(s.get("include_title", False)))
                self.include_title_cb.blockSignals(False)
            if hasattr(self, "title_line"):
                self.title_line.blockSignals(True)
                self.title_line.setText(s.get("title_text", ""))
                self.title_line.blockSignals(False)
            # Apply side effects
            self._apply_labels_visibility()
            self._update_legend(for_export=False, anchor=self._legend_anchor())
            # Rebuild table with filters
            self._populate_table()
        except Exception:
            pass
    def _restore_last_session(self):
        s = getattr(self, "_settings", {})
        path = s.get("last_file")
        try:
            if path and os.path.isfile(path):
                # avoid file dialog; directly load
                self.pdb_path = path
                if hasattr(self, "file_edit"):
                    self.file_edit.setText(path)
                self._load_structure(path)
                base = os.path.splitext(os.path.basename(path))[0]
                cmd.reinitialize()
                self.loaded_object = base
                cmd.load(path, base)
                # Restore ligand fields if present
                lc = s.get("last_ligand_chain")
                lr = s.get("last_ligand_resi")
                ln = s.get("last_ligand_resn")
                if lc and lr and ln:
                    self.ligand_info = (lc, int(lr), ln)
                    self.ligand_chain.setText(lc)
                    self.ligand_resi.setText(str(lr))
                    self.ligand_resn.setText(ln)
                self._beautify_scene()
                # optionally auto-compute
                if bool(s.get("compute_on_load", False)) and self.ligand_info:
                    self._on_calc_interactions()
        except Exception:
            pass
    def _on_redraw_visible_types(self):
        try:
            for rid, inter in enumerate(self.interactions):
                itype = inter["type"]
                enabled = True
                if hasattr(self, "_type_checkboxes") and itype in self._type_checkboxes:
                    enabled = self._type_checkboxes[itype].isChecked()
                if enabled:
                    if rid in self._selected_ids:
                        # rebuild
                        self._toggle_interaction_by_id(rid)
                        self._toggle_interaction_by_id(rid)
                    else:
                        # create visuals
                        self._toggle_interaction_by_id(rid)
                else:
                    if rid in self._selected_ids:
                        # remove visuals
                        self._toggle_interaction_by_id(rid)
            self._apply_labels_visibility()
            self._update_legend(for_export=False, anchor=self._legend_anchor())
        except Exception:
            pass
    def _on_reset_defaults(self):
        try:
            if hasattr(self, "legend_corner_combo"):
                self.legend_corner_combo.setCurrentText("Top Right")
            if hasattr(self, "legend_export_cb"):
                self.legend_export_cb.setChecked(True)
            if hasattr(self, "disc_thickness_spin"):
                self.disc_thickness_spin.setValue(0.10)
            if hasattr(self, "show_labels_cb"):
                self.show_labels_cb.setChecked(True)
            self._save_settings()
            self._apply_labels_visibility()
            self._update_legend(for_export=False, anchor=self._legend_anchor())
            self._refresh_ring_discs()
        except Exception:
            pass
    def _collect_settings_from_ui(self):
        data = {}
        try:
            data["legend_corner"] = (
                self.legend_corner_combo.currentText() if hasattr(self, "legend_corner_combo") else "Top Right"
            )
            data["legend_export"] = (
                bool(self.legend_export_cb.isChecked()) if hasattr(self, "legend_export_cb") else True
            )
            data["disc_thickness"] = (
                float(self.disc_thickness_spin.value()) if hasattr(self, "disc_thickness_spin") else 0.10
            )
            data["show_labels"] = bool(self.show_labels_cb.isChecked()) if hasattr(self, "show_labels_cb") else True
            data["max_distance"] = float(self.max_distance_spin.value()) if hasattr(self, "max_distance_spin") else 0.0
            data["filter_selection"] = self.filter_combo.currentText() if hasattr(self, "filter_combo") else "All"
            # per-type toggles
            if hasattr(self, "_type_checkboxes"):
                data["types_enabled"] = {t: bool(cb.isChecked()) for t, cb in self._type_checkboxes.items()}
            # compute on load
            data["compute_on_load"] = (
                bool(self.compute_on_load_cb.isChecked()) if hasattr(self, "compute_on_load_cb") else False
            )
            data["auto_zoom"] = bool(self.auto_zoom_cb.isChecked()) if hasattr(self, "auto_zoom_cb") else True
            if hasattr(self, "cb_abfe_keep_scene"):
                data["abfe_keep_scene_visible"] = bool(self.cb_abfe_keep_scene.isChecked())
            elif hasattr(self, "cb_pose_abfe_keep_scene"):
                data["abfe_keep_scene_visible"] = bool(self.cb_pose_abfe_keep_scene.isChecked())
            else:
                data["abfe_keep_scene_visible"] = bool(getattr(self, "_settings", {}).get("abfe_keep_scene_visible", False))
            if hasattr(self, "spin_abfe_surface_alpha"):
                data["abfe_surface_transparency"] = float(self.spin_abfe_surface_alpha.value())
            elif hasattr(self, "spin_pose_abfe_surface_alpha"):
                data["abfe_surface_transparency"] = float(self.spin_pose_abfe_surface_alpha.value())
            else:
                data["abfe_surface_transparency"] = float(
                    getattr(self, "_settings", {}).get("abfe_surface_transparency", 0.55)
                )
            if hasattr(self, "cmb_abfe_surface_color"):
                data["abfe_surface_color_mode"] = str(self.cmb_abfe_surface_color.currentData() or "rainbow_resi")
            elif hasattr(self, "cmb_pose_abfe_surface_color"):
                data["abfe_surface_color_mode"] = str(
                    self.cmb_pose_abfe_surface_color.currentData() or "rainbow_resi"
                )
            else:
                data["abfe_surface_color_mode"] = str(
                    getattr(self, "_settings", {}).get("abfe_surface_color_mode", "rainbow_resi")
                )
            if hasattr(self, "cmb_abfe_steering_mode"):
                data["abfe_steering_mode"] = str(self.cmb_abfe_steering_mode.currentData() or "pull_hold")
            elif hasattr(self, "cmb_pose_abfe_steering_mode"):
                data["abfe_steering_mode"] = str(
                    self.cmb_pose_abfe_steering_mode.currentData() or "pull_hold"
                )
            else:
                data["abfe_steering_mode"] = str(
                    getattr(self, "_settings", {}).get("abfe_steering_mode", "pull_hold")
                )
            if hasattr(self, "cmb_abfe_policy_mode"):
                data["abfe_policy_mode"] = str(self.cmb_abfe_policy_mode.currentData() or "heuristic")
            elif hasattr(self, "cmb_pose_abfe_policy_mode"):
                data["abfe_policy_mode"] = str(
                    self.cmb_pose_abfe_policy_mode.currentData() or "heuristic"
                )
            else:
                data["abfe_policy_mode"] = str(
                    getattr(self, "_settings", {}).get("abfe_policy_mode", "heuristic")
                )
            if hasattr(self, "cb_abfe_guide_tunnel"):
                data["abfe_guide_tunnel_enabled"] = bool(self.cb_abfe_guide_tunnel.isChecked())
            elif hasattr(self, "cb_pose_abfe_guide_tunnel"):
                data["abfe_guide_tunnel_enabled"] = bool(self.cb_pose_abfe_guide_tunnel.isChecked())
            else:
                data["abfe_guide_tunnel_enabled"] = bool(
                    getattr(self, "_settings", {}).get("abfe_guide_tunnel_enabled", True)
                )
            if hasattr(self, "spin_abfe_guide_tunnel_radius"):
                data["abfe_guide_tunnel_radius_a"] = float(self.spin_abfe_guide_tunnel_radius.value())
            elif hasattr(self, "spin_pose_abfe_guide_tunnel_radius"):
                data["abfe_guide_tunnel_radius_a"] = float(self.spin_pose_abfe_guide_tunnel_radius.value())
            else:
                data["abfe_guide_tunnel_radius_a"] = float(
                    getattr(self, "_settings", {}).get("abfe_guide_tunnel_radius_a", 3.5)
                )
            data["abfe_steering_cycles"] = int(self._abfe_steering_cycles())
            data["style_overrides"] = self._settings.get("style_overrides", {}) if hasattr(self, "_settings") else {}
            data["show_angle_labels"] = (
                bool(self.show_angle_labels_cb.isChecked()) if hasattr(self, "show_angle_labels_cb") else False
            )
            data["include_scale"] = (
                bool(self.include_scale_cb.isChecked()) if hasattr(self, "include_scale_cb") else True
            )
            data["scale_length"] = int(self.scale_length_spin.value()) if hasattr(self, "scale_length_spin") else 10
            data["include_title"] = (
                bool(self.include_title_cb.isChecked()) if hasattr(self, "include_title_cb") else False
            )
            data["title_text"] = self.title_line.text() if hasattr(self, "title_line") else ""
            data["confirm_remove_all"] = (
                bool(self._settings.get("confirm_remove_all", True)) if hasattr(self, "_settings") else True
            )
        except Exception:
            pass
        return data
    def _on_redraw_all(self):
        # Recreate visuals for all currently selected interactions
        try:
            for rid in list(self._selected_ids):
                # toggle off then on to fully rebuild visuals and apply per-type styles
                self._toggle_interaction_by_id(rid)
                self._toggle_interaction_by_id(rid)
            self._apply_labels_visibility()
            self._update_legend(for_export=False, anchor=self._legend_anchor())
        except Exception:
            pass
    def _on_apply_styles_now(self):
        # Apply color/style/opacity changes to all existing visuals without toggling selection state
        try:
            # Update legend to reflect colors first
            self._update_legend(for_export=False, anchor=self._legend_anchor())
            for rid, inter in enumerate(self.interactions):
                itype = inter["type"]
                color_name = self._type_color_name(itype)
                # Distance dashes
                dash = f"int_dash_{rid}"
                try:
                    cmd.set("dash_color", color_name, dash)
                    self._apply_dash_style(dash, itype)
                except Exception:
                    pass
                # Clouds
                for obj in (f"intCloudProt_{rid}", f"intCloudLig_{rid}"):
                    try:
                        cmd.color(color_name, obj)
                        ov = (
                            self._settings.get("style_overrides", {}).get(itype, {})
                            if hasattr(self, "_settings")
                            else {}
                        )
                        cov = ov.get("cloud_opacity")
                        trans = 1.0 - float(cov) if cov is not None else 0.6
                        cmd.set("transparency", trans, obj)
                        cmd.set("sphere_transparency", trans, obj)
                    except Exception:
                        pass
                # Ring discs: rebuild with new thickness/opacity/colors if present
                for which, key, obj in (
                    ("prot", "prot_ring", f"intRingDiscProt_{rid}"),
                    ("lig", "ligand_ring", f"intRingDiscLig_{rid}"),
                ):
                    try:
                        cmd.delete(obj)
                    except Exception:
                        pass
                    try:
                        if key in inter:
                            r = inter[key]
                            self._make_ring_disc(obj, r["centroid"], r["normal"], r.get("radius", 1.8), itype)
                            group = f"Interactions.{itype.replace(' ', '_')}"
                            cmd.group(group, obj)
                    except Exception:
                        pass
                # Angle labels visibility toggling
                try:
                    lab = f"angle_label_{rid}"
                    if bool(self._settings.get("show_angle_labels", False)) if hasattr(self, "_settings") else False:
                        # Recreate at midpoint if dash exists
                        cmd.delete(lab)
                        detail = inter.get("details")
                        if detail and inter.get("prot_atom") and inter.get("lig_atom"):
                            p_atom = str(inter.get("prot_atom", "")).strip()
                            l_atom = str(inter.get("lig_atom", "")).strip()
                            # Skip labels for cluster/ring/multi-atom interactions.
                            if (
                                str(inter.get("details", "")) == "Cluster"
                                or p_atom == "Ring"
                                or l_atom == "Ring"
                                or "," in p_atom
                                or "," in l_atom
                            ):
                                continue
                            prot_chain = inter.get("prot_chain")
                            prot_resi = inter.get("prot_resi")
                            prot_resn = inter.get("prot_resn")
                            if prot_chain is None or prot_resi is None:
                                toks = str(inter.get("prot_res", "")).split()
                                pr = toks[1] if len(toks) > 1 else ""
                                if pr:
                                    prot_chain = pr[0]
                                    prot_resi = pr[1:] if len(pr) > 1 else pr
                                if not prot_resn and toks:
                                    prot_resn = toks[0]
                            chain_clause = 'chain ""' if str(prot_chain).strip() == "" else f'chain "{str(prot_chain).strip()}"'
                            prot_res_sel = (
                                f"{self.loaded_object} and {chain_clause} and resi {prot_resi} and name {p_atom}"
                            )
                            if prot_resn:
                                prot_res_sel += f" and resn {prot_resn}"
                            lig_chain, lig_resi, lig_resn = self.ligand_info
                            lig_atom_sel = (
                                self._pymol_residue_selection(self.loaded_object, lig_chain, lig_resi, lig_resn)
                                + f" and name {l_atom}"
                            )
                            pm = cmd.get_model(prot_res_sel)
                            lm = cmd.get_model(lig_atom_sel)
                            if pm.atom and lm.atom:
                                p = np.array(pm.atom[0].coord)
                                q = np.array(lm.atom[0].coord)
                                mid = (p + q) / 2.0
                                cmd.pseudoatom(lab, pos=[float(mid[0]), float(mid[1]), float(mid[2])])
                                cmd.label(lab, f'"{detail}"')
                                cmd.set("label_color", "white", lab)
                                cmd.set("label_outline_color", "black", lab)
                                cmd.group(f"Interactions.{itype.replace(' ', '_')}", lab)
                    else:
                        cmd.delete(lab)
                except Exception:
                    pass
        except Exception:
            pass
    def _populate_table_from(self, items):
        self.table.setRowCount(0)
        self.table.setColumnCount(6)
        self.table.setHorizontalHeaderLabels(["Type", "Prot Res", "Prot Atom", "Lig Atom", "Distance (Å)", "Details"])
        self._table_items = list(items)
        for i, inter in enumerate(items):
            self.table.insertRow(i)
            self.table.setItem(i, 0, QtWidgets.QTableWidgetItem(inter["type"]))
            self.table.setItem(i, 1, QtWidgets.QTableWidgetItem(inter["prot_res"]))
            self.table.setItem(i, 2, QtWidgets.QTableWidgetItem(inter["prot_atom"]))
            self.table.setItem(i, 3, QtWidgets.QTableWidgetItem(inter["lig_atom"]))
            self.table.setItem(i, 4, QtWidgets.QTableWidgetItem(f"{inter['distance']:.2f}"))
            self.table.setItem(i, 5, QtWidgets.QTableWidgetItem(inter.get("details", "")))
        self.table.resizeColumnsToContents()
    def _current_filtered_items(self):
        items = self.interactions
        # Type filter
        try:
            if hasattr(self, "filter_combo"):
                t = self.filter_combo.currentText()
                if t and t != "All":
                    items = [i for i in items if i["type"] == t]
        except Exception:
            pass
        # Distance filter
        try:
            if hasattr(self, "max_distance_spin"):
                md = float(self.max_distance_spin.value())
                if md > 0:
                    items = [i for i in items if i.get("distance", 0.0) <= md]
        except Exception:
            pass
        return items
    def _on_clear(self):
        # Remove all interaction visuals created by this session
        try:
            for rid in list(self._selected_ids):
                for prefix in (
                    "intRes_",
                    "int_dash_",
                    "intCloudProt_",
                    "intCloudLig_",
                    "intRingDiscProt_",
                    "intRingDiscLig_",
                    "pseudo_p_",
                    "pseudo_l_",
                    "lbl_prot_",
                    "lbl_lig_",
                    "lbl_dist_",
                    "angle_label_",
                    "tmp_cloud_pm_",
                    "tmp_cloud_lm_",
                ):
                    try:
                        cmd.delete(f"{prefix}{rid}")
                    except Exception:
                        pass
            self._selected_ids.clear()
            self._last_live_state = -1
        finally:
            pass
    def _on_remove_all_visuals(self):
        # Remove all Interactions.* groups and any int* objects, independent of selection
        try:
            if not self._confirm_remove_all():
                return
            # Delete group trees if present
            for grp in ("Interactions", "Interactions.Legend", "Interactions.ScaleBar", "Interactions.Title"):
                try:
                    cmd.delete(grp)
                except Exception:
                    pass
            # Wildcard cleanup for any leftover objects
            for pat in (
                "intRes_*",
                "int_dash_*",
                "intCloudProt_*",
                "intCloudLig_*",
                "intRingDiscProt_*",
                "intRingDiscLig_*",
                "pseudo_p_*",
                "pseudo_l_*",
                "lbl_prot_*",
                "lbl_lig_*",
                "lbl_dist_*",
                "tmp_cloud_pm_*",
                "tmp_cloud_lm_*",
                "legend_*",
                "angle_label_*",
                "scale_label",
                "title_label",
            ):
                try:
                    cmd.delete(pat)
                except Exception:
                    pass
            self._selected_ids.clear()
            self._last_live_state = -1
        except Exception:
            pass
    def _confirm_remove_all(self):
        # Show a confirmation dialog with "Don't ask again"
        try:
            if not bool(self._settings.get("confirm_remove_all", True)):
                return True
        except Exception:
            return True
        mbox = QtWidgets.QMessageBox(self)
        mbox.setIcon(QtWidgets.QMessageBox.Warning)
        mbox.setWindowTitle("Remove All Visuals")
        mbox.setText("Remove all plugin-generated visuals?")
        mbox.setInformativeText("This will delete all Interactions.* groups and int* objects. This cannot be undone.")
        mbox.setStandardButtons(QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.No)
        mbox.setDefaultButton(QtWidgets.QMessageBox.No)
        chk = QtWidgets.QCheckBox("Don't ask again")
        mbox.setCheckBox(chk)
        ret = mbox.exec_()
        if ret == QtWidgets.QMessageBox.Yes:
            if chk.isChecked():
                try:
                    self._settings["confirm_remove_all"] = False
                    self._save_settings()
                except Exception:
                    pass
            return True
        return False
    def _on_export_csv(self):
        out, _ = QtWidgets.QFileDialog.getSaveFileName(self, "Export CSV", "interactions.csv", "CSV (*.csv)")
        if not out:
            return
        try:
            import csv
            with open(out, "w", newline="") as f:
                w = csv.writer(f)
                w.writerow(["Type", "Prot Res", "Prot Atom", "Lig Atom", "Distance (Å)", "Details"])
                for i in self.interactions:
                    w.writerow(
                        [
                            i["type"],
                            i["prot_res"],
                            i["prot_atom"],
                            i["lig_atom"],
                            f"{i['distance']:.2f}",
                            i.get("details", ""),
                        ]
                    )
            QtWidgets.QMessageBox.information(self, "Exported", f"CSV saved to {out}")
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "Error", f"Failed to export CSV: {e}")
    def _update_legend(self, for_export=False, anchor="top_right"):
        # Explicit request to remove all legend objects: "legend_0" to "legend_9"
        try:
            cmd.delete("Interactions.Legend")
            # Loop arbitrary range to be safe
            for i in range(20):
                 cmd.delete(f"legend_{i}")
        except Exception:
            pass
